-- Restores the old site's article archive (backup from 2026-11-09) with the
-- original sections, authors, dates, views and clicks. Images still point at the
-- old Blob store; POST /api/cron/migrate-covers copies them into the new one.

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Trump Tells His Aides That He Wants to End the War With Iran Quickly', 'ترامب يبلغ مساعديه أنه يريد إنهاء الحرب على إيران بسرعة', 'trump-aides-endwar', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أفادت تقارير إعلامية أميركية بأن الرئيس دونالد ترامب عبّر لمقربين منه عن رغبته في تجنب الانخراط في حرب طويلة الأمد مع إيران، في ظل مخاوف من ارتفاع الخسائر البشرية في صفوف القوات الأميركية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ونقلت صحيفة «وول ستريت جورنال» عن مسؤولين أميركيين قولهم إن ترامب أبدى قلقه من تزايد عدد القتلى والجرحى إذا استمر النزاع، معتبراً أن الصراع دخل مراحله الأخيرة. كما شدد أمام مستشاريه على ضرورة الالتزام بالجدول الزمني المحدد للتعامل مع الملف الإيراني، والذي يمتد بين أربعة وستة أسابيع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي سياق متصل، كشفت المصادر أن الولايات المتحدة وإسرائيل قررتا تعليق استهداف مسؤولين إيرانيين، هما علي عراقجي ومحمد قاليباف، بشكل مؤقت. في المقابل، أكد عراقجي أن طهران لا تجري مفاوضات مباشرة مع واشنطن، مشيراً إلى أن التواصل يتم عبر وسطاء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وخلال عشاء جمعه بأعضاء في الكونغرس من الحزب الجمهوري، قال ترامب إن إيران تسعى إلى التوصل لاتفاق مع الولايات المتحدة لكنها تتجنب الإعلان عن ذلك، مضيفاً أن المفاوضين الإيرانيين يخشون التعرض للقتل من قبل شعبهم إذا كشفوا عن هذه المحادثات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار ترامب إلى أن القيادة في إيران تواجه ظروفاً صعبة، قائلاً إن لا أحد يرغب في تولي المسؤولية في ظل الوضع الراهن. كما جدّد تأكيده أن الولايات المتحدة «دمرت كل شيء في إيران»، بما في ذلك القدرات العسكرية والبحرية والبرنامج النووي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن التدخل العسكري كان ضرورياً، معتبراً أنه لم يكن هناك خيار آخر «لاستئصال السرطان النووي الإيراني»، لافتاً إلى أن الولايات المتحدة حققت تقدماً في هذا الصراع. كما رأى أن تداعيات الحرب على أسعار النفط والأسواق المالية كانت أقل حدة مما كان متوقعاً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التصريحات بعد إعلان وزير الخارجية الإيراني عباس عراقجي عدم وجود نية لدى بلاده للدخول في مفاوضات مع الولايات المتحدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي انتقاد لاذع لخصومه السياسيين، اتهم ترامب الديمقراطيين بمحاولة صرف الأنظار عن ما وصفه بـ«النجاح الكبير» للعملية العسكرية، ساخراً من مطالبهم بالحصول على موافقة الكونغرس، ومشيراً إلى أنه يفضل وصف ما يجري بـ«عملية عسكرية» بدلاً من «حرب»", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "U.S. media reports said that President Donald Trump expressed to close associates his desire to avoid getting involved in a prolonged war with Iran, amid concerns over rising casualties among U.S. forces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Wall Street Journal, citing U.S. officials, reported that Trump voiced concern about increasing numbers of dead and wounded if the conflict continues, considering that the war has entered its final stages. He also stressed to his advisers the need to adhere to the set timeline for handling the Iranian file, which ranges between four to six weeks.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a related context, sources revealed that the United States and Israel have decided to temporarily suspend targeting two Iranian officials, Ali Araghchi and Mohammad Qalibaf. Meanwhile, Araghchi confirmed that Tehran is not engaged in direct negotiations with Washington, noting that communication is taking place through intermediaries.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "During a dinner with Republican members of Congress, Trump said that Iran is seeking to reach an agreement with the United States but is avoiding announcing it publicly, adding that Iranian negotiators fear being killed by their own people if such talks are revealed.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trump also indicated that Iran’s leadership is facing difficult conditions, saying that no one wants to assume responsibility under the current situation. He reiterated that the United States has “destroyed everything in Iran,” including military and naval capabilities as well as the nuclear program.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added that military intervention was necessary, arguing there was no other option to “eradicate the Iranian nuclear cancer,” noting that the United States has made progress in this conflict. He also said the war’s impact on oil prices and financial markets was less severe than expected.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These remarks come after Iranian Foreign Minister Abbas Araghchi announced that his country has no intention of entering negotiations with the United States.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In sharp criticism of his political opponents, Trump accused Democrats of trying to divert attention from what he described as the “great success” of the military operation, mocking their demands for congressional approval and stating that he prefers to describe what is happening as a “military operation” rather than a “war.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Trump_final_1.jpg-gnYDVtZo3dqzgeAzcoUBLSnqEtPyOf.webp', false, false, 386, 1190, TIMESTAMP '2026-03-26 10:24:56.860', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Lebanese Minister Fadi Makki: I participated in the Cabinet session despite opposing the decision to expel the Iranian ambassador', '‏الوزير اللبناني فادي مكي: شاركت في جلسة الحكومة رغم معارضتي قرار طرد السفير الإيراني', 'makki-statement', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "شدد وزير الدولة لشؤون التنمية الإدارية الدكتور فادي مكي على ضرورة تعزيز دور الدولة اللبنانية في ظل ما وصفه بـ«الأزمة الوجودية» التي يمر بها البلد، داعياً إلى تغليب منطق المسؤولية الوطنية وتفعيل عمل المؤسسات الدستورية، وعلى رأسها مجلس الوزراء، باعتباره الإطار الأساسي لاتخاذ القرارات الوطنية، لا سيما في أوقات الأزمات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي تصريح له، أوضح مكي أنه شارك في اجتماع مجلس الوزراء رغم معارضته للإجراء الذي اتخذته وزارة الخارجية، مؤكداً أن المشاركة الفاعلة تبقى ضرورة وطنية لضمان انتظام العمل العام ومواجهة التحديات المتصاعدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد أن الأولوية في المرحلة الراهنة يجب أن تنصب على التصدي لما يتعرض له لبنان من «عدوان إسرائيلي مستمر»، مشيراً إلى أن هذا العدوان يتجلى في تدمير ممنهج واستهداف للمدنيين والطواقم الطبية والبنى التحتية والخدمات الأساسية، في ما اعتبره انتهاكاً واضحاً للقانون الدولي الإنساني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، عرض مكي مجموعة من الثوابت التي ينبغي أن توجه عمل الحكومة في المرحلة المقبلة، أبرزها إعطاء الأولوية المطلقة لاستقبال النازحين وتأمين احتضانهم، إلى جانب تكثيف الجهود السياسية والدبلوماسية لوقف العدوان، خصوصاً على القرى الجنوبية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما دعا إلى تفعيل الدبلوماسية اللبنانية بشكل عاجل لمواجهة ما وصفه بالتصريحات والممارسات الإسرائيلية الخطيرة المرتبطة بنوايا التوسع والاحتلال، لا سيما في منطقة جنوب الليطاني، والعمل على حشد دعم دولي لوقف الحرب على لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وشدد أيضاً على أهمية الحفاظ على السلم الأهلي وتعزيز الحوار الداخلي، معتبراً أنهما الخيار الوحيد لحماية البلاد ومنع الانزلاق نحو مزيد من الانقسام والتوتر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم مكي بالتأكيد على أن لبنان يحتاج في هذه المرحلة إلى قرارات توحد ولا تفرق، وإلى مقاربات تعزز حضور الدولة بدل إضعافها، قائلاً: «لا خيار لنا إلا الدولة».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Minister of State for Administrative Development Dr. Fadi Makki stressed the need to strengthen the role of the Lebanese state amid what he described as an “existential crisis” facing the country, calling for prioritizing national responsibility and activating constitutional institutions, foremost among them the Council of Ministers, as the primary framework for making national decisions, especially in times of crisis.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement, Makki explained that he participated in the Cabinet meeting despite opposing the measure taken by the Ministry of Foreign Affairs, emphasizing that active participation remains a national necessity to ensure the proper functioning of public affairs and to confront escalating challenges.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He affirmed that the priority at the current stage should be focused on confronting what Lebanon is facing from “ongoing Israeli aggression,” noting that this aggression is reflected in systematic destruction and the targeting of civilians, medical teams, infrastructure, and essential services, which he described as a clear violation of international humanitarian law.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Makki outlined a set of principles that should guide the government’s work in the coming phase, foremost among them giving absolute priority to receiving and accommodating displaced persons, alongside intensifying political and diplomatic efforts to halt the aggression, particularly on southern villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also called for urgently activating Lebanese diplomacy to confront what he described as dangerous Israeli statements and practices linked to expansion and occupation intentions, particularly in the area south of the Litani River, and to mobilize international support to stop the war on Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Makki further stressed the importance of preserving civil peace and strengthening internal dialogue, considering them the only option to protect the country and prevent further division and tension.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He concluded by emphasizing that Lebanon, at this stage, needs decisions that unite rather than divide, and approaches that strengthen the role of the state rather than weaken it, saying: “We have no choice but the state.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-Trc3L8IUBaFygvub1Z1gV1unwtslJ7', false, false, 233, 650, TIMESTAMP '2026-03-26 14:24:18.897', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Salam reveals new security measures in Beirut', 'سلام يكشف عن إجراءات أمنية جديدة في بيروت', 'salam-security-bei', $c${"type": "doc", "content": [{"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "حذّر رئيس الحكومة نواف سلام من تصاعد المخاطر المرتبطة بالتطورات الميدانية جنوب نهر الليطاني، في ظل استمرار الاعتداءات الإسرائيلية، كاشفًا عن مؤشرات خطيرة توحي بمحاولات عزل المنطقة وفرض واقع جديد، بالتوازي مع تفاقم أزمة النزوح وتداعياتها على مختلف المستويات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وجاءت مواقف سلام في تصريح نقله وزير الإعلام بول مرقص عقب جلسة مجلس الوزراء، التي خُصصت لبحث انعكاسات الحرب، لا سيما في ما يتعلق بالأوضاع الإيوائية والإغاثية والاجتماعية والاقتصادية والمالية، إلى جانب الشق العسكري الذي أكد أنه يحظى بالأولوية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، أشار سلام إلى تهديدات متكررة صادرة عن وزير الدفاع الإسرائيلي بشأن نية احتلال المنطقة الواقعة جنوب الليطاني، لافتًا إلى أن إسرائيل أقدمت على تفجير معظم الجسور في تلك المنطقة في مسعى لعزلها عن باقي الأراضي اللبنانية، بالتوازي مع عمليات تهجير جماعي واستمرار تدمير المنازل وتجريف الأراضي، في ما يعكس توجهاً يمنع عودة السكان في المدى القريب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم سلام بالإعلان عن إجراءات أمنية جديدة لتعزيز الاستقرار في بيروت، تشمل تكثيف انتشار الجيش وقوى الأمن الداخلي، بهدف طمأنة المواطنين وتعزيز الشعور بالأمان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lebanese Prime Minister Nawaf Salam warned of escalating risks linked to developments south of the Litani River amid ongoing Israeli attacks, revealing dangerous indicators suggesting attempts to isolate the area and impose a new reality, alongside a worsening displacement crisis and its repercussions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "His remarks were conveyed by Information Minister Paul Morcos following a Cabinet session dedicated to discussing the war’s impact, particularly regarding shelter, relief, social, economic, and financial conditions, in addition to the military aspect, which he said remains the priority.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Salam pointed to repeated threats by the Israeli Defense Minister regarding intentions to occupy the area south of the Litani, noting that Israel has blown up most of the bridges in the region in an effort to isolate it from the rest of Lebanon, alongside mass displacement, continued destruction of homes, and land bulldozing—reflecting a direction aimed at preventing residents from returning in the near future.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He concluded by announcing new security measures to enhance stability in Beirut, including increased deployment of the army and Internal Security Forces to reassure citizens and strengthen the sense of safety", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/WhatsAppImage2025-01-14at12918PM_925138-ibMSoyWBa72l9FotfPehSf9XR9Rx74.jpeg', false, false, 307, 660, TIMESTAMP '2026-03-26 16:19:41.097', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Contract teachers’ union warns of deadlock with Education Ministry', 'رابطة الأساتذة المتعاقدين تحذّر من وصول التواصل مع وزارة التربية إلى طريق مسدود', 'contract-teachers-challenges', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت «رابطة الأساتذة المتعاقدين» في التعليم الأساسي الرسمي في لبنان وصولها إلى طريق مسدود في التواصل مع وزيرة التربية ريما كرامي، في ظل استمرار التحديات المرتبطة بالتعليم عن بُعد خلال فترة الحرب، وانتقادها لعدم الاستجابة لمطالب الأساتذة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي بيان صادر اليوم، اعتبرت الرابطة أنه رغم مرور نحو شهر على اندلاع الحرب، لا تزال أبواب الوزارة مقفلة أمام ممثلي شريحة واسعة من الأساتذة المتعاقدين، الذين يشكلون نحو 80% من الكادر التعليمي في المدارس الرسمية، ما حال دون نقل المشاكل التي يواجهونها ومعالجتها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت إلى أن رئيسة الرابطة، الدكتورة نسرين شاهين، تواصلت مع الجهات المعنية لعرض التحديات، إلا أن الأمور استمرت في التفاقم، ما انعكس سلباً على سير العملية التعليمية، وظهر في شكل نزاعات بين بعض الإدارات والأساتذة، إضافة إلى حالة من التخبط التنظيمي وصعوبة متابعة الدروس بشكل منتظم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولفتت الرابطة إلى أن الأوضاع المعيشية للأساتذة المتعاقدين لا تقل صعوبة، في ظل عدم تنفيذ قانون العقد الكامل لدفع مستحقاتهم، وغياب أي مساعدة اجتماعية تخفف من وطأة الأزمة عليهم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما عرضت أبرز التحديات التي تواجه الأساتذة، من بينها وجود عدد كبير منهم في مناطق نازحة أو غير آمنة، وضعف خدمات الإنترنت، وعدم الاستفادة الفعلية من باقات الإنترنت المخصصة، إضافة إلى الأعباء التقنية المرتبطة باستخدام منصات التعليم، ولا سيما «Teams»، في ظل محدودية الأجهزة، خصوصاً أن العديد من الأساتذة لديهم أبناء يتابعون التعليم عن بُعد أيضاً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبناءً على هذه المعطيات، أعلنت الرابطة أنه في موازاة موقف وزيرة التربية القائل «من يستطيع أن يتعلم فليتعلم»، فإنها تعتمد مبدأ مماثلاً للأساتذة المتعاقدين، بحيث «من يستطيع أن يعلّم فليعلّم، ومن لا يستطيع فلا يعلّم».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ودعت الرابطة وزيرة التربية إلى متابعة الملف مع المناطق التربوية والمدراء لتفادي أي تصادم داخل المؤسسات التعليمية، كما طالبت بإقرار مساعدة اجتماعية للأساتذة، والعمل على تنفيذ قانون العقد الكامل بما يضمن حقوقهم في هذه الظروف الاستثنائية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Union of Contract Teachers in Lebanon’s public basic education sector announced it has reached a dead end in communication with Education Minister Rima Karami, amid ongoing challenges related to remote learning during the war and a lack of response to teachers’ demands.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement issued today, the union said that nearly a month into the war, the ministry’s doors remain closed to representatives of contract teachers—who make up around 80% of public school staff—preventing them from conveying and addressing the issues they face.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It noted that union president Dr. Nisreen Shaheen had contacted relevant parties to present these challenges, but the situation continued to deteriorate, negatively affecting the educational process. This has led to disputes between some school administrations and teachers, organizational confusion, and difficulties in maintaining regular lessons.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The union also highlighted the difficult living conditions of contract teachers, pointing to the failure to implement the full-contract law for payment of dues, and the absence of any social assistance to ease their burden.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It outlined key challenges facing teachers, including many being in displaced or unsafe areas, weak internet services, limited benefit from allocated internet packages, and technical burdens related to using educational platforms—especially Teams—amid a shortage of devices, particularly as many teachers also have children studying remotely.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Based on these conditions, the union said that alongside the minister’s stance that “those who can learn should learn,” it adopts a similar approach for teachers: “those who can teach should teach, and those who cannot should not.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The union called on the Education Minister to follow up on the issue with regional education authorities and school principals to avoid conflict within institutions, and demanded social assistance for teachers as well as the implementation of the full-contract law to guarantee their rights under these exceptional circumstances.", "type": "text"}]}]}$c$::jsonb, 'https://thisisbeirut.com.lb/images/bibli/1920/1280/2/education-ministry-markazia.jpeg', false, false, 76, 270, TIMESTAMP '2026-03-26 19:51:36.141', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Internal attempts to deny the achievements of the resistance', 'محاولات داخلية للتشكيك في عمليات المقاومة', 'hezeb-israel-achievements-denial', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في ظل التصعيد المستمر والتطورات الميدانية الأخيرة، برزت قضية تدمير عدد كبير من الدبابات الإسرائيلية كأحد أبرز الأحداث التي يتم تداولها على نطاق واسع. فقد أعلنت المقاومة عن تدمير 86 دبابة إسرائيلية، وهو رقم لافت يعكس حجم المواجهة وشدتها. ورغم انتشار هذه الأخبار عبر قنوات متعددة، لا يزال جزء من اللبنانيين يشكك في صحتها، متذرعًا بعدم وجود تغطية مرئية كافية أو تقارير موثقة من وجهة نظره.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "هذا التشكيك لا يمكن فصله عن حالة الانقسام الداخلي، حيث يبدو أن البعض يتعامل مع هذه الأخبار من منطلق عاطفي أو سياسي أكثر منه موضوعي. فبدلًا من تقييم المعطيات كما هي، يتم رفضها بشكل مسبق، وكأن الاعتراف بها يتعارض مع مواقفهم الشخصية أو قناعاتهم المسبقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وعند المقارنة بما حدث خلال حرب الأيام الـ12، يتضح التناقض في طريقة التعاطي مع الأخبار. حينها، انتشرت معلومات غير مؤكدة عن إسقاط أربع طائرات إسرائيلية، لكنها لم تصدر عن أي جهة رسمية، بل تداولتها حسابات عشوائية على وسائل التواصل الاجتماعي. وقد سارعت الجهات الإسرائيلية الرسمية إلى نفي تلك الادعاءات بشكل واضح وصريح، ما ساهم في تقويض مصداقيتها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما اليوم، فالوضع مختلف. الحديث عن تدمير الدبابات لا يقتصر على مصادر غير موثوقة، بل يتم تداوله عبر قنوات إعلامية متعددة، بما في ذلك منصات رسمية. والأهم من ذلك، أن الجانب الإسرائيلي لم يصدر نفيًا واضحًا كما حدث سابقًا، وهو ما يطرح تساؤلات مشروعة حول أسباب هذا الصمت.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم ذلك، يصر بعض المشككين على رفض هذه المعطيات، متجاهلين السياق العام واختلاف الظروف بين الحالتين. هذا الرفض لا يبدو قائمًا على تحليل موضوعي بقدر ما يعكس حالة من الرفض النفسي أو السياسي للاعتراف بأي إنجاز يُنسب إلى المقاومة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المطلوب اليوم هو قراءة الأحداث بعين نقدية متوازنة، بعيدًا عن التحيز والانفعال، للوصول إلى تقييم أكثر دقة وموضوعية لما يجري على الأرض.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Amid ongoing escalation and recent field developments, the reported destruction of a large number of Israeli tanks has emerged as one of the most widely discussed issues. The resistance has announced the destruction of 86 Israeli tanks—a notable figure reflecting the scale and intensity of the confrontation. Despite the spread of this information across multiple channels, a segment of Lebanese society continues to question its accuracy, citing a lack of sufficient visual coverage or documented reports.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This skepticism cannot be separated from the internal divisions, as some appear to approach such news from an emotional or political standpoint rather than an objective one. Instead of assessing the information on its merits, it is dismissed outright, as if acknowledging it would contradict personal beliefs or prior positions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A comparison with the events of the 12-day war highlights the inconsistency in how such reports are treated. At that time, unverified claims about downing four Israeli aircraft circulated widely, yet they did not originate from any official source, but rather from random social media accounts. Israeli authorities quickly issued clear denials, undermining the credibility of those claims.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Today, however, the situation differs. Reports about tank destruction are not confined to unreliable sources but are being circulated by multiple media outlets, including official platforms. More notably, the Israeli side has not issued a clear denial as it did previously, raising legitimate questions about this silence.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite this, some skeptics continue to reject these claims, disregarding the broader context and differences between the two cases. This rejection appears less rooted in objective analysis and more reflective of a psychological or political unwillingness to acknowledge any achievement attributed to the resistance.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What is needed today is a balanced and critical reading of events, free from bias and emotional reactions, to arrive at a more accurate and objective understanding of what is happening on the ground.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Fajr-5-Getty-woO5fQYGt3jsyoeuSogXCVtec6zL4o.jpg', false, false, 133, 580, TIMESTAMP '2026-03-27 10:37:25.657', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The Minister of Health proposes an emergency plan to enhance the readiness of the health sector during the war.', 'وزير الصحة يطرح خطة طوارئ لتعزيز جاهزية القطاع الصحي خلال الحرب', 'health-emergency-plan', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "عرض وزير الصحة العامة ركان ناصر الدين خطة الطوارئ التي تعتمدها الوزارة لمواجهة التداعيات الصحية الناتجة عن العدوان الإسرائيلي على لبنان، مؤكداً أن الخطة ترتكز على تعزيز جاهزية المستشفيات والكوادر الصحية، إلى جانب تطوير آليات التنسيق لضمان الاستجابة السريعة وتلبية احتياجات النازحين المتزايدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وجاء ذلك خلال مؤتمر حول «جاهزية المستشفيات للطوارئ في خلال الحرب والنزاعات المسلحة» نظمته الجامعة الأميركية في بيروت بدعم من الجمعية اللبنانية لطب الطوارئ ونقابة الممرضات والممرضين، بمشاركة اختصاصيين في القطاع الصحي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح ناصر الدين أن الوزارة عملت ضمن خطة وطنية شاملة لتعزيز صمود النظام الصحي، من خلال بناء القدرات وتطوير الشراكات وتعزيز الاستعداد المسبق لمواجهة الأزمات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار إلى أن الخطة تقوم على خمس ركائز أساسية، أولها تأمين الأدوية والمستلزمات الطبية ومعدات الطوارئ بشكل استباقي، تحسباً لأي اضطراب في سلاسل الإمداد، وضمان تلبية الطلب المتزايد في ظل الضغوط على المستشفيات، بما يشمل دعم العمليات الجراحية والعناية المركزة والعلاجات الحيوية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما الركيزة الثانية، فتتمثل في رفع جاهزية الكوادر الصحية عبر تدريبات متخصصة في إدارة الإصابات الجماعية، وفرز الحالات، ومكافحة العدوى، والتعامل مع الحالات الحرجة، إضافة إلى تنفيذ تمارين محاكاة لتعزيز الجهوزية العملية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الركيزة الثالثة، لفت إلى العمل على حشد فرق الطوارئ الطبية بالتعاون مع شركاء محليين ودوليين، بما يتيح الاستجابة للارتفاع المفاجئ في أعداد المرضى وضمان استمرارية الخدمات الحيوية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تشمل الخطة، بحسب ناصر الدين، تعزيز أنظمة الإحالة والتنسيق والتواصل بين المستشفيات وجهات الاستجابة، بما يضمن توزيع الحالات بكفاءة وتفادي الفوضى التي قد تؤدي إلى خسائر في الأرواح، مشيراً إلى الدور المحوري الذي يؤديه مركز عمليات طوارئ الصحة العامة في هذا المجال.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما الركيزة الخامسة، فتتعلق بضمان تغطية تكاليف الرعاية الأساسية للجرحى والنازحين، بهدف تخفيف الأعباء المالية عن الأسر المتضررة وتأمين الوصول إلى الخدمات الصحية المنقذة للحياة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم هذه الإجراءات، أقر الوزير بأن التحديات لا تزال كبيرة، في ظل محدودية الموارد وتزايد الاحتياجات، إضافة إلى الأضرار التي تطال البنية التحتية الصحية والتهديدات التي يتعرض لها العاملون في القطاع، مشدداً على ضرورة حماية المستشفيات وضمان سلامة الطواقم الطبية وفقاً للقانون الدولي الإنساني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد أن الجاهزية للطوارئ تمثل استثماراً وطنياً مستمراً يتطلب تمويلاً مستداماً وتنسيقاً مؤسسياً ودعماً دائماً للمستشفيات والعاملين في الخطوط الأمامية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم بتوجيه الشكر إلى الكوادر الصحية وفرق الطوارئ على جهودهم، مجدداً التزام الوزارة بتعزيز الجهوزية وترسيخ التنسيق بين مختلف مكونات النظام الصحي، بما يساهم في الحد من الخسائر وإنقاذ الأرواح.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "The Lebanese Minister of Public Health, Rakan Nassereddine, presented the ministry’s emergency plan to address the health consequences resulting from the Israeli aggression on Lebanon. He emphasized that the plan focuses on strengthening hospital readiness and healthcare personnel, as well as improving coordination mechanisms to ensure rapid response and meet the growing needs of displaced people.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This came during a conference on “Hospital Emergency Preparedness during War and Armed Conflicts,” organized by the American University of Beirut with support from the Lebanese Society of Emergency Medicine and the Order of Nurses, with participation from healthcare specialists.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nassereddine explained that the ministry has been working ضمن a comprehensive national plan to enhance the resilience of the healthcare system by building capacities, developing partnerships, and improving preparedness for crises.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He noted that the plan is based on five main pillars:", "type": "text"}]}, {"type": "orderedList", "attrs": {"type": null, "start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Securing medications, medical supplies, and emergency equipment in advance", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", anticipating disruptions in supply chains and ensuring the ability to meet rising demand, including support for surgeries, intensive care, and critical treatments.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Enhancing the readiness of healthcare workers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " through specialized training in mass casualty management, triage, infection control, and handling critical cases, along with simulation exercises to improve practical preparedness.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mobilizing emergency medical teams", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in cooperation with local and international partners to respond to sudden increases in patient numbers and ensure continuity of essential services.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Strengthening referral systems, coordination, and communication", "type": "text", "marks": [{"type": "bold"}]}, {"text": " between hospitals and response entities to ensure efficient case distribution and prevent chaos that could lead to loss of life, highlighting the central role of the Public Health Emergency Operations Center.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ensuring coverage of basic healthcare costs for the injured and displaced", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in order to reduce financial burdens on affected families and guarantee access to life-saving services.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Despite these measures, the minister acknowledged ongoing challenges, including limited resources, increasing needs, damage to healthcare infrastructure, and threats faced by healthcare workers. He stressed the importance of protecting hospitals and ensuring the safety of medical staff in accordance with international humanitarian law.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He concluded by affirming that emergency preparedness is a continuous national investment requiring sustainable funding, institutional coordination, and ongoing support for hospitals and frontline workers, thanking healthcare teams and emergency responders for their efforts and reaffirming the ministry’s commitment to saving lives and reducing losses.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/HA8eSjUbwAAghe2-NSDUfJyZ48W2PBxsZSFsWeLCOUOxVB.jpg', false, false, 55, 283, TIMESTAMP '2026-03-28 11:47:09.682', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'From the Battlefield to the Economy: War Is Driving Inflation and Market Turmoil in the U.S.', 'من ساحة المعركة إلى الاقتصاد: الحرب تدفع التضخم واضطرابات السوق في الولايات المتحدة', 'usa-economy-war', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "مع تصاعد الحرب بين الولايات المتحدة وإسرائيل من جهة وإيران من جهة أخرى، تتكشّف تداعيات اقتصادية متسارعة داخل الولايات المتحدة، حيث تتقاطع كلفة العمليات العسكرية مع صدمة أسعار الطاقة لتزيد الضغوط على الاقتصاد وتعيد طرح مخاطر التضخم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، يشكّل ارتفاع أسعار النفط العامل الأكثر تأثيراً، إذ تجاوز سعر البرميل حاجز 100 دولار في بعض الفترات، في ظل التوترات في مضيق هرمز الذي يمر عبره نحو 20% من الإمدادات العالمية. وعلى الرغم من ارتفاع إنتاج الولايات المتحدة، إلا أن ترابط الأسواق العالمية انعكس مباشرة على الأسعار المحلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووفق تقارير نقلتها «فوكس بيزنس»، ارتفع متوسط سعر البنزين من نحو 2.9 دولار إلى أكثر من 3.9 دولارات للغالون خلال فترة قصيرة، ما أدى إلى زيادة كلفة النقل والشحن، وبالتالي ارتفاع أسعار السلع والخدمات. وتشير تحليلات نشرتها شبكة «PBS» إلى أن الوقود قد يشكّل نحو نصف كلفة النقل البحري، ما يسرّع انتقال أثر الأسعار إلى الأسواق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بالتوازي، تتزايد المخاوف من عودة التضخم، إذ تقدّر «باركليز» أن ارتفاع أسعار النفط بنسبة 10% قد يرفع معدلات التضخم بنحو 0.2% خلال فترة قصيرة، فيما قد يصل إلى 3.5% سنوياً إذا استمرت الأسعار المرتفعة، مقارنة بتوقعات سابقة عند 2.7%. وهو ما يضع الاحتياطي الفدرالي أمام معادلة معقدة بين كبح التضخم والحفاظ على النمو.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وعلى صعيد الأسواق، تراجع مؤشر «S&P500» بنحو 4.2% منذ بداية الحرب، فيما تضررت قطاعات النقل والصناعات المعتمدة على الطاقة، مقابل مكاسب لشركات النفط والصناعات العسكرية، بحسب تقارير «الغارديان».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تواصل الكلفة العسكرية المباشرة الارتفاع، إذ أفادت وكالة «رويترز» نقلاً عن مسؤولين أميركيين أن الإنفاق بلغ نحو 11 مليار دولار في الأيام الأولى، مع إمكانية وصوله إلى نحو مليار دولار يومياً. كما ذكرت «واشنطن بوست» أن نحو 5.6 مليارات دولار صُرفت على الذخائر خلال الفترة نفسها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتبقى هذه الكلفة مرشحة للتصاعد في حال استمرار الحرب، ما قد يدفع الإدارة الأميركية إلى طلب تمويل إضافي من الكونغرس، في وقت بلغ فيه الدين العام نحو 38.8 تريليون دولار، أي ما يعادل 125% من الناتج المحلي الإجمالي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ظل هذه المعطيات، يحذّر اقتصاديون، وفق «الغارديان»، من أن استمرار الحرب وارتفاع أسعار الطاقة قد يؤديان إلى تباطؤ النمو الاقتصادي، مع تراجع القدرة الشرائية وارتفاع كلفة الإنتاج، ما يضع الاقتصاد الأميركي أمام مرحلة دقيقة تتداخل فيها الضغوط العسكرية والاقتصادية.", "type": "text"}, {"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "As the war between the United States and Israel on one side and Iran on the other escalates, rapidly unfolding economic repercussions are emerging ", "type": "text"}, {"text": "within", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the United States. The cost of military operations is intersecting with rising energy prices, increasing pressure on the economy and reviving concerns about inflation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, rising oil prices are the most significant factor. The price of a barrel has exceeded $100 at times amid tensions in the Strait of Hormuz, through which about 20% of global supplies pass. Despite increased U.S. production, the interconnected nature of global markets has directly impacted domestic prices.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to reports cited by ", "type": "text"}, {"text": "Fox Business", "type": "text", "marks": [{"type": "italic"}]}, {"text": ", the average price of gasoline rose from around $2.90 to over $3.90 per gallon in a short period. This has increased transportation and shipping costs, leading to higher prices for goods and services. Analyses published by ", "type": "text"}, {"text": "PBS", "type": "text", "marks": [{"type": "italic"}]}, {"text": " indicate that fuel can account for about half of maritime shipping costs, accelerating the transmission of price increases to markets.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, concerns about inflation are growing. ", "type": "text"}, {"text": "Barclays", "type": "text", "marks": [{"type": "italic"}]}, {"text": " estimates that a 10% increase in oil prices could raise inflation by about 0.2% in the short term, potentially reaching 3.5% annually if high prices persist, compared to earlier expectations of 2.7%. This places the Federal Reserve in a difficult position between controlling inflation and sustaining economic growth.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In financial markets, the S&P 500 index has declined by ", "type": "text"}, {"text": "about", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 4.2% since the beginning of the war. Transportation and energy-dependent industries have been negatively affected, while oil companies and defense industries have seen gains, according to ", "type": "text"}, {"text": "The Guardian", "type": "text", "marks": [{"type": "italic"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, direct military costs continue to rise. ", "type": "text"}, {"text": "Reuters", "type": "text", "marks": [{"type": "italic"}]}, {"text": ", citing U.S. officials, reported that spending reached about $11 billion in the early days, with the potential to reach around $1 billion per day. ", "type": "text"}, {"text": "The Washington Post", "type": "text", "marks": [{"type": "italic"}]}, {"text": " also noted that approximately $5.6 billion was spent on munitions ", "type": "text"}, {"text": "during", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the same period.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These costs are expected to increase further if the war continues, potentially prompting the U.S. administration to request additional funding from Congress. This comes at a time when public debt has reached ", "type": "text"}, {"text": "about", "type": "text", "marks": [{"type": "bold"}]}, {"text": " $38.8 trillion, equivalent to about 125% of GDP.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In light of these factors, economists—according to ", "type": "text"}, {"text": "The Guardian", "type": "text", "marks": [{"type": "italic"}]}, {"text": "—warn that the continuation of the war and rising energy prices could slow economic growth, reduce purchasing power, and increase production costs, placing the U.S. economy in a delicate phase shaped by overlapping military and economic pressures.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/4491769-rms-peregrine-product-page-feature-albrecht-1568906438-doumYEe49zmI3GAPRX6LQDRYgjo1K4.jpg', false, false, 29, 144, TIMESTAMP '2026-03-28 17:48:15.046', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Southern media bids farewell to the martyrs of the word: emotional messages reveal a journey of sacrifice and steadfastness', 'الإعلام الجنوبي يودّع شهداء الكلمة: رسائل مؤثرة تكشف مسيرة التضحية والثبات', 'choeib-ftouni-farewell', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كتب الزميل الإعلامي طارق مروة، مدير “قناة النبطية”، كلمات مؤثرة في وداع زملائه الشهداء، مستذكراً مسيرتهم المهنية والإنسانية في ميادين العمل الإعلامي، ولا سيما في مناطق الخطر جنوب لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار مروة في رسالته إلى الشهيد الحاج علي، مؤكداً أنه لم يكن مجرد زميل، بل شكّل مدرسة إعلامية وإنسانية متكاملة، جمع بين دور الأب والأخ والصديق والمعلم، وكان سنداً ثابتاً في أصعب الظروف. ولفت إلى أن الشهيد لطالما عبّر عن رغبته في أن يختتم حياته بالشهادة، بعد سنوات من العمل في “الإعلام المقاوم” ونقل الحقيقة من قلب الميدان، حيث كان حاضراً دائماً في خطوط المواجهة غير آبه بالمخاطر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما استعاد مروة محطات من عمله إلى جانب الشهيدة فاطمة، مشيراً إلى مشاركتهما في تغطيات ميدانية خلال حرب الإسناد، حيث برزت شجاعتها وإيمانها بالقضية. وأوضح أنها تأثرت باستشهاد زميلتها فرح، وأصرّت على استكمال مسيرتها الإعلامية، رغم محاولات إبعادها عن مناطق التوتر، مؤكداً أنها بقيت صوتاً معبّراً عن أبناء الجنوب الذين واجهوا التحديات بثبات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم مروة رسالته بالتأكيد على أن وداع الشهداء سيكون مفعماً بالفخر، حيث سيُشيّعون على الأكتاف، “أحياءً عند ربهم يُرزقون”، في مشهد يجسّد تضحيات الإعلاميين الذين دفعوا حياتهم ثمناً لنقل الحقيقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الصورة من صحيفة الأخبار", "type": "text", "marks": [{"type": "italic"}]}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Journalist Tarek Marwa, director of “Nabatieh Channel,” wrote a moving tribute in farewell to his martyred colleagues, recalling their professional and human journey in the field of media—especially in the dangerous ", "type": "text"}, {"text": "areas", "type": "text", "marks": [{"type": "bold"}]}, {"text": " of southern Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In his message, Marwa spoke about the late Hajj Ali, emphasizing that he was not just a colleague but a complete school in both media and humanity. He combined the roles of father, brother, friend, and mentor, and was a constant source of support in the most difficult ", "type": "text"}, {"text": "circumstances", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Marwa noted that the martyr had long expressed his wish to end his life in martyrdom, after years of work in “resistance media,” conveying the truth from the heart of the field, always present on the front lines despite the risks.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also recalled moments of working alongside the late Fatima, highlighting their joint field coverage during the support war, where her courage and belief in the cause stood out. He explained that she was deeply affected by the martyrdom of her colleague Farah, yet insisted on continuing her media path despite attempts to keep her away from ", "type": "text"}, {"text": "areas of tension", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", remaining a voice representing the people of the south who faced challenges with resilience.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Marwa concluded his message by affirming that the farewell to the martyrs would be filled with pride, as they would be carried on shoulders, “alive with their Lord, provided for,” in a scene that embodies the sacrifices of journalists who gave their lives to convey the truth.", "type": "text"}]}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2-QNd4opkYNxxVt08Ld5WS8YCweQx0Ug.png', false, false, 363, 1290, TIMESTAMP '2026-03-28 18:37:49.754', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Weak digital infrastructure is hindering distance learning', 'ضعف البنية الرقمية يعثر التعليم عن بعد', 'digital-learning-issues', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يواجه التعليم الرسمي عن بعد تحديات تقنية جدية تهدد استمراريته، في ظل ضعف البنية التحتية الرقمية وعدم قدرة عدد كبير من الأساتذة والتلامذة على استخدام منصة «مايكروسوفت تيمز» المعتمدة رسمياً، نتيجة بطء الإنترنت والضغط على الشبكة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأدى هذا الواقع إلى لجوء العديد من المدارس إلى حلول بديلة غير رسمية، أبرزها «واتساب»، إلى جانب «زووم» و«غوغل ميت»، رغم محدوديتها وعدم قدرتها على تأمين التفاعل الكامل أو توثيق الحصص وضمان حقوق الأساتذة، لا سيما المتعاقدين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "مديرو المدارس انتقدوا فرض استخدام منصة غير متاحة فعلياً، مطالبين بمرونة أكبر في اعتماد أدوات تتناسب مع الواقع التقني، فيما أكدت وزارة التربية أنها تعمل على معالجة العقبات وتوفير تسهيلات، مشيرة إلى اعتماد نهج مرن بالتنسيق مع الإدارات التربوية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي حادثة أثارت تساؤلات، ظهرت اللغة العبرية على المنصة لدى بعض المستخدمين، قبل أن توضح الوزارة أن الأمر ناتج عن خلل تقني تمّت معالجته، نافية أي اختراق أمني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويعيد هذا المشهد طرح تساؤلات حول غياب التخطيط المسبق، إذ يرى تربويون أن الاعتماد على الحلول الرقمية لا يزال يتم عند الأزمات فقط، من دون تجهيز البنية التحتية أو تدريب الكوادر مسبقاً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تعتمد المدارس حالياً نماذج تعليمية مختلفة بين الحضور الجزئي والتعليم عن بعد، وفقاً للوضع الأمني في المناطق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بتصرّف عن جريدة الأخبار", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Public remote education is facing serious technical challenges that threaten its continuity, amid weak digital infrastructure and the inability of many teachers and students to effectively use the officially adopted Microsoft Teams platform, due to slow internet speeds and network congestion.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This situation has led many schools to resort to unofficial alternative solutions, most notably WhatsApp, as well as Zoom and Google Meet, despite their limitations and inability to ", "type": "text"}, {"text": "provide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " full interaction, document sessions, or guarantee teachers’ rights—especially for contract-based instructors.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "School principals criticized the imposition of a platform that is not practically accessible, calling for greater flexibility in adopting tools suited to the technical reality. Meanwhile, the Ministry of Education stated that it is working to address obstacles and provide facilitation, noting that it is adopting a flexible approach in coordination with educational administrations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In an incident that raised questions, Hebrew appeared on the platform for some users. The ministry later clarified that this was due to a technical glitch that has since been resolved, denying any security breach.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This situation once again raises questions about the lack of prior planning, as educators point out that reliance on digital solutions still occurs only during crises, without prior infrastructure preparation or staff training.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, schools are currently adopting various models, combining partial in-person attendance with remote learning, depending on the security situation in different areas.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/annie-spratt-V_yEK9wOuPw-unsplash-f4HiChDqraDiSx5D5isQ0dQVaqHzT5.jpg', false, false, 135, 525, TIMESTAMP '2026-03-30 11:33:09.351', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'New challenges are imposing themselves at the World Cup', 'تحديات جديدة تفرض نفسها في المونديال', 'worldcup-challenges', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "تتجه الأنظار إلى كأس العالم 2026، المقررة بين 11 حزيران و19 تموز، والتي ستُقام للمرة الأولى في ثلاث دول هي الولايات المتحدة وكندا والمكسيك، في نسخة مختلفة عن البطولات السابقة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أبرز التغييرات هو رفع عدد المنتخبات إلى 48 منتخباً، ما يتيح الفرصة لمنتخبات جديدة من إفريقيا وآسيا وأوقيانوسيا للمشاركة. هذا التوسع يعزز انتشار اللعبة، لكنه يطرح تساؤلات حول تأثيره على مستوى بعض المباريات، رغم أن نظام التأهل الجديد يحافظ على المنافسة حتى النهاية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "التحدي الأكبر لا يقتصر على المباريات فقط، بل يشمل أيضاً المسافات الطويلة بين المدن. فقد يلعب منتخب في أجواء رطبة مثل ميامي، ثم ينتقل سريعاً إلى طقس بارد مثل فانكوفر، ما يشكل ضغطاً على اللاعبين والأجهزة الطبية، خصوصاً من ناحية اللياقة والاستشفاء", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم اعتماد توزيع جغرافي للمجموعات في البداية لتخفيف السفر، فإن الأدوار الإقصائية ستفرض تنقلاً أكبر بين الدول الثلاث، ما قد يؤثر على أداء المنتخبات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "على الصعيد الفني، قد تكون هذه البطولة الأخيرة لنجوم كبار مثل ليونيل ميسي وكريستيانو رونالدو، في وقت يبرز فيه جيل جديد يعتمد على السرعة والقوة البدنية، ما يعكس تحولاً نحو كرة جماعية أكثر تنظيماً", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما من الناحية التقنية، فمن المتوقع استخدام نسخ أكثر تطوراً من تقنيات التسلل وتتبع اللاعبين، بهدف تسريع القرارات وتقليل توقف اللعب", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بذلك، لا يُعد مونديال 2026 مجرد بطولة أكبر حجماً، بل تجربة جديدة تختبر قدرة كرة القدم على التطور دون أن تفقد هويتها", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Attention is turning to the 2026 World Cup, scheduled from June 11 to July 19, which will be hosted for the first time by three countries: the United States, Canada, and Mexico—marking a departure from previous tournaments.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The most notable change is the expansion to 48 teams, giving new opportunities to nations from Africa, Asia, and Oceania to participate. While this expansion promotes the global reach of the sport, it also raises questions about its impact on the quality of some matches, even though the new qualification system aims to maintain competitiveness until the end.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The biggest challenge goes beyond the matches themselves and includes the long distances between host cities. A team might play in humid conditions like Miami, then quickly move to a colder climate like Vancouver, creating pressure on players and medical staff, especially in terms of fitness and recovery.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although a geographic distribution of groups will initially help reduce travel, the knockout stages will require more movement between the three countries, which could affect team performance.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From a technical standpoint, this tournament may be the last for major stars like Lionel Messi and Cristiano Ronaldo, while a new generation—relying on speed and physical strength—is emerging, reflecting a shift toward more organized, team-oriented football.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Technologically, more advanced versions of offside detection and player tracking systems are expected to be used, aiming to speed up decisions and reduce interruptions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Thus, the 2026 World Cup is not just a larger tournament, but a new experience testing football’s ability to evolve without losing its identity.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/a9b11802a1ff6530fbdbfed0d2ab8eef53c664f72c1cc78060533f956010de59-1200-675-vLbZQEowCrottrpdi7397nMBH60S64.png', false, false, 71, 209, TIMESTAMP '2026-03-31 13:13:34.038', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'sport'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The Directorate of Intelligence arrests one of the most prominent drug traffickers', 'مديرية المخابرات توقف أحد أبرز تجار المخدرات', 'intelligence-drug-arrest', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "مديرية المخابرات توقف أحد أبرز تجّار المخدرات (ح.ج.) بعد تحديد مكان وجوده خارج البلاد، وقد جرى تسلّمه ونقله إلى لبنان عبر المطار، وهو مطلوب بجرائم عدّة أبرزها إطلاق النار باتجاه مراكز الجيش ما أدى إلى استشـهاد عسكريين، إضافة إلى تورّطه في عمليات خطف مقابل فدية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Directorate of Intelligence arrests one of the most prominent drug traffickers (H.J.) after locating him abroad. He was handed over and transferred to Lebanon via the airport. He is wanted for several crimes, most notably opening fire on army positions, which led to the killing of soldiers, in addition to his involvement in kidnapping-for-ransom operations", "type": "text", "marks": [{"type": "italic"}]}]}, {"type": "paragraph"}, {"type": "paragraph"}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/AFP__20221103__32KW7GX__v1__HighRes__LebanonSyriaConflictCorruptionCrimeDrugsCaptago-1763688701-WrlFPGrUE1jZVemrJr8dB1XFrFCJXW.jpg', false, false, 121, 363, TIMESTAMP '2026-04-01 18:20:30.515', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Attention turns to Trump’s speech — what do we know so far?', 'الأنظار تتجه إلى خطاب ترامب، ماذا نعرف عنه حتى الآن؟', 'trump-state-speech', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "تتجه الأنظار إلى خطاب «الأمة» المرتقب للرئيس الأميركي دونالد ترمب، في ظل تضارب التقديرات بشأن مضمونه، بين توجه نحو تهدئة شاملة أو تصعيد ميداني إضافي في الملف الإيراني، ما يضع الساحة السياسية والإعلامية في حالة ترقب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، أفاد موقع «أكسيوس» بأن تصريحات ترمب غير المنسقة تسببت في حالة من «الارتباك الشديد» داخل فريقه وفي الأسواق، في وقت نقل عن مستشارين قولهم إن «لا أحد يعرف فعلياً ما الذي يفكر فيه الرئيس».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بدوره، اعتبر السيناتور ليندسي غراهام أن هذا الغموض مقصود، مشيراً إلى أن الهدف هو إبقاء الجميع في حالة عدم يقين حيال الخطوات المقبلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، ذكرت صحيفة «إندبندنت» أن ترمب بدأ يشعر بـ«السأم» من الحرب مع إيران، ويسعى إلى إنهاء هذا الملف للتركيز على معركته السياسية المرتبطة بانتخابات تشرين الثاني المقبلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتزايد التوقعات بإمكانية أن يتضمن الخطاب إعلاناً عن «نصر» خلال فترة قصيرة، قد لا تتجاوز أسبوعين، في خطوة تهدف إلى احتواء تداعيات الحرب، ولا سيما على صعيد أسعار الوقود، إضافة إلى تعزيز موقعه الشعبي داخلياً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبين سيناريوهات التهدئة والتصعيد، يبقى خطاب ترمب المنتظر محور الاهتمام، في محاولة لفهم الاتجاه الذي ستسلكه السياسة الأميركية في المرحلة المقبلة.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Attention is turning to the anticipated “State of the Nation” address by U.S. President Donald Trump, amid conflicting assessments about its content—ranging between a move toward broad de-escalation or further military escalation in the Iran file—placing the political and media landscape in a state of anticipation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Axios reported that Trump’s uncoordinated statements have caused “significant confusion” within his team and in the markets, with advisers saying that “no one really knows what the president is thinking.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For his part, Senator Lindsey Graham considered this ambiguity intentional, noting that the aim is to keep everyone uncertain about the next steps.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, The Independent reported that Trump has begun to feel “weary” of the war with Iran and is seeking to end the issue in order to focus on his political battle tied to the upcoming November elections.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Expectations are growing that the speech may include an announcement of a “victory” within a short timeframe—possibly not exceeding two weeks—in a move aimed at containing the repercussions of the war, particularly on fuel prices, as well as strengthening his domestic standing.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Between scenarios of de-escalation and escalation, Trump’s anticipated speech remains the center of attention, as observers try to understand the direction U.S. policy will take in the coming phase.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/0F050D70-9E2B-4253-BC4F518E7EF1346C_source-91FOyit9HXR41l8XuY9ouZqhilfoir.jpg', false, false, 894, 2244, TIMESTAMP '2026-04-01 21:00:36.830', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Public Works accelerates steps to rehabilitate Qlayaat Airport', 'الأشغال تسرّع خطوات تأهيل مطار القليعات', 'qlayaat-airport-acceleration', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت وزارة الأشغال العامة والنقل المباشرة بخطوات عملية لتسريع تنفيذ مشروع تأهيل وتشغيل مطار رينه معوّض في القليعات، مؤكدة وضع هذا المشروع في صدارة أولوياتها الوطنية نظراً لأهميته الاستراتيجية في ظل الظروف التي يمر بها لبنان", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت الوزارة، في بيان، أنها أطلقت مزايدة للشراء العام وفق الأصول القانونية المعتمدة، بما يضمن الشفافية ويعزز معايير التنافس، وذلك في إطار سعيها إلى تطوير قطاع النقل الجوي وتوسيع الخيارات أمام المواطنين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار البيان إلى أن المشروع لقي اهتماماً ملحوظاً، حيث بلغ عدد الجهات التي حصلت على دفتر الشروط وأبدت رغبتها بالمشاركة 18 جهة، ما يعكس ثقة متزايدة بجدواه على الصعيدين الوطني والاقتصادي", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت الوزارة التزامها متابعة تنفيذ المشروع ضمن المهلة الممكنة، بما يخدم المصلحة العامة ويسهم في تعزيز قدرات لبنان، على أن يتم الإعلان عن أي مستجدات وفق الأصول المعتمدة", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "The Ministry of Public Works and Transport has announced the start of practical steps to accelerate the implementation of the rehabilitation and operation project of Rene Mouawad Airport in Qlayaat, مؤكدة that the project is at the top of its national priorities due to its strategic importance amid the current situation in Lebanon", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement, the ministry said it has launched a public procurement tender in accordance with the applicable legal procedures, ensuring transparency and strengthening competition standards, as part of its efforts to develop the aviation sector and expand options for citizens", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The statement noted that the project has attracted significant interest, with 18 الجهات (entities) obtaining the tender documents and expressing willingness to participate, reflecting growing confidence in its national and economic feasibility", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry also affirmed its commitment to following up on the project’s implementation within the shortest possible timeframe, in a way that serves the public interest and enhances Lebanon’s capabilities, with any updates to be announced according to official procedures", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/AeroportmilitairedeKleiate-3-phMichelHallak_337548copy_924216-30tz1Krzk6JLljvE7GQ9Q2t3JWCy0D.jpg', false, false, 188, 764, TIMESTAMP '2026-04-02 08:55:41.300', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The A-10 aircraft enters the Middle East theater… what do we know about it?', 'طائرة الـA10 تدخل ميدان الشرق الأوسط... ماذا نعرف عنها؟', 'a10-warcraft-mea', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "تتجه عشرات الطائرات الهجومية الأميركية من طراز «A-10 Thunderbolt II» نحو الشرق الأوسط، في خطوة تعكس تعزيز الحضور العسكري الأميركي في ظل التصعيد الإقليمي المستمر", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتُعرف هذه الطائرة بلقب «Warthog»، كما تُوصف عسكرياً بـ«طائرة الأرض المحروقة»، نظراً لقدرتها على تقديم دعم جوي مباشر للقوات البرية واستهداف الدبابات والمدرعات بدقة عالية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتُعد A-10 من أبرز الطائرات الهجومية المتخصصة، إذ صُممت لدعم القوات على الأرض، وتمتاز بقدرتها على التحليق على ارتفاعات منخفضة وتنفيذ ضربات دقيقة في بيئات قتالية معقدة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومن أبرز ما يميزها مدفعها من طراز GAU-8 Avenger، أحد أقوى المدافع الجوية، إلى جانب قدرتها العالية على التحمل والاستمرار في تنفيذ المهام حتى بعد تعرضها لأضرار مباشرة، إضافة إلى تصميمها الذي يمنحها فعالية خاصة في ساحات القتال", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم التطور الكبير في الطائرات الحديثة، لا تزال A-10 تحتفظ بدورها كعنصر أساسي في دعم القوات البرية، ما يعزز أهميتها في أي تصعيد ميداني محتمل في المنطقة", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Dozens of U.S. A-10 Thunderbolt II attack aircraft are heading toward the Middle East, in a move that reflects a strengthening of the American military presence amid ongoing regional escalation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This aircraft is known by the nickname “Warthog” and is also described militarily as a “scorched earth aircraft,” due to its ability to provide close air support to ground forces and accurately target tanks and armored vehicles", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The A-10 is considered one of the most prominent specialized attack aircraft, designed specifically to support troops on the ground. It is capable of flying at low altitudes and carrying out precise strikes in complex combat environments", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "One of its most notable features is the GAU-8 Avenger cannon, one of the most powerful airborne cannons, in addition to its high durability and ability to continue missions even after sustaining direct damage. Its design also gives it unique effectiveness on the battlefield", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite the significant advancement in modern aircraft, the A-10 continues to maintain its role as a key asset in supporting ground forces, reinforcing its importance in any potential escalation on the ground in the region", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/1280px-Fairchild_Republic_A-10_Thunderbolt_II_-_32156159151-auphJucZ3XAbpYzQUCiPRk6RkSmdyL.jpg', false, false, 187, 481, TIMESTAMP '2026-04-02 09:19:13.356', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'After his latest speech, a poll shows a decline in Trump’s popularity', 'بعد خطابه الأخير، استطلاع يظهر تدهور شعبية ترامب', 'trump-popularity-decline', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أظهر استطلاع حديث لشبكة «CNN» تصاعد القلق داخل الولايات المتحدة حيال الانخراط العسكري في إيران، مع معارضة أكثر من 70% من الأميركيين إرسال قوات برية، في مؤشر واضح على رفض توسيع التدخل الميداني", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبيّن الاستطلاع أن 63% من الأميركيين يعتقدون أن الحرب قد تتحول إلى صراع طويل الأمد، ما يعكس مخاوف متزايدة من تداعيات التصعيد واستمراريته", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي السياق ذاته، تراجعت نسبة التأييد لأداء الرئيس دونالد ترامب في إدارة الملف الاقتصادي إلى 31%، وهو أدنى مستوى له، في ظل ضغوط اقتصادية وارتفاع أسعار الوقود المرتبطة بالحرب", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أظهر الاستطلاع تراجع الدعم للعملية العسكرية في إيران إلى 34%، مقابل ارتفاع نسبة المعارضة القوية إلى 43%، إلى جانب شكوك واسعة حول قدرة ترامب على إدارة هذا الملف، وذلك قبيل خطابه المرتقب في البيت الأبيض", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولم يقتصر التباين على الانقسام الحزبي التقليدي، إذ برزت تحفظات حتى داخل بعض الأوساط الجمهورية، بما فيها مؤيدو «Make America Great Again»، فيما استمر الديمقراطيون والمستقلون في معارضة التدخل العسكري بشكل واضح", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "A recent CNN poll shows rising concern within the United States over military involvement in Iran, with more than 70% of Americans opposing the deployment of ground troops—clearly indicating rejection of expanding direct military intervention", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The poll found that 63% of Americans believe the war could turn into a long-term conflict, reflecting growing fears about the continuation and consequences of escalation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the same context, approval of President Donald Trump’s handling of the economy has dropped to 31%, its lowest level, amid economic pressures and rising fuel prices linked to the war", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Support for the military operation in Iran has also declined to 34%, while strong opposition has risen to 43%, alongside widespread doubts about Trump’s ability to manage this issue, just ahead of his anticipated White House speech", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The divide is not limited to traditional partisan lines, as reservations have also emerged within some Republican circles, including among “Make America Great Again” supporters, while Democrats and independents continue to clearly oppose military intervention", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/AP25211759325751-1753921070-tCPPndM4oRmAm1hLOkBvBYYl9lflNF.jpg', false, false, 117, 333, TIMESTAMP '2026-04-02 10:06:24.902', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A new drone enters Hezbollah’s balance of power… here are its features', 'طائرة جديدة تدخل في موازين قوة حزب الله... وهذه مميزاتها', 'hezb-new-drone', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كشف تقرير صادر عن مؤسسة «الدفاع عن الديمقراطيات» (FDD) أن «حزب الله» يُرجّح أنه بدأ باستخدام طائرات مسيّرة مزودة بتقنية الرؤية من منظور الشخص الأول (FPV) في عملياته ضد الجيش الإسرائيلي، في تطور ميداني لافت في أساليب القتال.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب التقرير، نشر الحزب مؤخراً مقاطع فيديو تُظهر استهداف ناقلتي جند مدرعتين من طراز «نامر» وشاحنة عسكرية إسرائيلية باستخدام هذا النوع من الطائرات، وذلك بعد أيام من عرض لقطات لهجوم سابق على دبابة «ميركافا» بالتقنية نفسها في 26 آذار الماضي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار التقرير إلى أن هذه العمليات قد تكون من أوائل استخدامات «حزب الله» لتقنية FPV في المواجهة الحالية، رغم ظهوره السابق في لقطات تعود إلى عام 2024، ما يعكس انتقالاً تدريجياً نحو توظيف هذه الوسائل بشكل أوسع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتُعد طائرات FPV من الطائرات الصغيرة منخفضة الكلفة، والقادرة على حمل شحنات متفجرة مثل قذائف «آر بي جي»، إضافة إلى صعوبة رصدها واعتراضها. كما تتيح للمشغّل تنفيذ الاستطلاع وتحديد الأهداف ثم ضربها بسرعة ضمن منصة واحدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويأتي هذا التطور في وقت أعلن فيه الجيش الإسرائيلي انتشار أربع فرق في جنوب لبنان ضمن حملة بدأت في 2 آذار، وتهدف إلى منع تسلل «حزب الله» أو تنفيذ هجمات على مناطق في شمال إسرائيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولفت التقرير إلى أن التجارب في أوكرانيا أظهرت فعالية كبيرة لهذا النوع من الطائرات، حيث تُنسب إليها نسبة تتراوح بين 70 و80% من الإصابات، كما استخدمت في إسقاط مروحية هجومية روسية من طراز «كا-52»، ما يعزز احتمال اعتماد تكتيكات مشابهة في ساحات أخرى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، رجّح التقرير أن يسعى «حزب الله» إلى استهداف المروحيات الإسرائيلية التي تُستخدم لاعتراض طائراته المسيّرة، مستفيداً من الخبرات المتراكمة في هذا المجال، خاصة مع استخدام فصائل مدعومة من إيران للطائرات المسيّرة في هجمات واستطلاع خلال الفترة الماضية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، أشار التقرير إلى أن القوات الإسرائيلية تمتلك وسائل دفاعية، أبرزها نظام «تروفي» للحماية النشطة، القادر على رصد المقذوفات والطائرات المسيّرة واعتراضها، وقد أظهرت بعض المقاطع استخدامه في مواجهة هجمات مشابهة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم التقرير بالتأكيد على أهمية تطوير وسائل مضادة إضافية، داعياً إلى تعزيز التعاون بين إسرائيل وأوكرانيا للاستفادة من الخبرات الميدانية، بما يشمل استخدام رادارات متنقلة واعتراض الطائرات المسيّرة عبر وسائل مماثلة، مع دور محتمل للولايات المتحدة في تنسيق هذا التعاون.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "A report by the Foundation for Defense of Democracies (FDD) revealed that Hezbollah is likely beginning to use drones equipped with first-person view (FPV) technology in its operations against the Israeli army, marking a notable battlefield development in combat tactics.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the report, the group recently published videos showing the targeting of two Namer armored personnel carriers and an Israeli military truck using this type of drone, just days after releasing footage of a previous attack on a Merkava tank using the same technology on March 26.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report noted that these operations may be among Hezbollah’s first uses of FPV technology in the current confrontation, despite its earlier appearance in footage dating back to 2024, reflecting a gradual shift toward broader deployment of such tools.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "FPV drones are small, low-cost aircraft capable of carrying explosive payloads such as RPG rounds, and are difficult to detect and intercept. They also allow operators to conduct reconnaissance, identify targets, and strike them quickly within a single platform.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This development comes as the Israeli army announced the deployment of four divisions in southern Lebanon as part of a campaign launched on March 2, aimed at preventing Hezbollah infiltration or attacks on northern Israel.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report highlighted that experiences in Ukraine have demonstrated the high effectiveness of this type of drone, attributing 70–80% of casualties to them, and noting their use in downing a Russian Ka-52 attack helicopter, reinforcing the likelihood of similar tactics being adopted in other arenas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, the report suggested that Hezbollah may seek to target Israeli helicopters used to intercept its drones, leveraging accumulated expertise, particularly as Iran-backed factions have increasingly used drones in both attacks and reconnaissance in recent periods.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, the report pointed out that Israeli forces possess defensive systems, most notably the Trophy active protection system, capable of detecting and intercepting projectiles and drones, with some footage showing its use against similar attacks.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report concluded by emphasizing the importance of developing additional countermeasures, calling for enhanced cooperation between Israel and Ukraine to benefit from battlefield experience, including the use of mobile radars and drone interception through similar means, with a potential role for the United States in coordinating such cooperation.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/thumbs_b_c_4119a0591eb773b5889a1772b64d0f0a-53kxriyRfbuqqkIAspe81iIWiOZIh3.jpg', false, false, 2667, 6287, TIMESTAMP '2026-04-03 21:01:54.158', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Egyptian proposals and French signals… and the party has made its decision', 'طروحات مصرية وتلميحات فرنسية.. والحزب حسم خياره', 'egypt-isra-hezb-deal', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كشف مصدر سياسي كشف لـجريدة \"المدن\" أن الأفكار المصرية المقدمة إلى الحزب تراوحت بين إعادة إحياء نموذج احتواء السلاح، والتوصل إلى صيغة تمنع استخدامه لفترة محددة، وصولاً إلى وضعه تحت سلطة الدولة وفق آلية تطبيقية يتفق عليها، على أن يترافق ذلك مع إلزام إسرائيل بتنفيذ ما عليها من بنود، وفي مقدمتها الانسحاب إلى الخط الأزرق وتسليم جميع الأسرى المدنيين والعسكريين. غير أن الإشكالية الأساسية، بحسب المصدر، تمثلت في غياب آلية واضحة لكيفية إلزام إسرائيل بتطبيق البنود، فضلاً عن عدم توضيح ما إذا كانت القاهرة قد نسّقت هذه الأفكار مع تل أبيب أو مع الأميركيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما العقدة الأكبر، فتتمثل في استمرار وجود جيش الاحتلال على الأراضي اللبنانية، مع تهديداته باستئناف العمليات العدوانية. وفي المحصلة، ردّ الحزب على الطرح المصري بأسلوب دبلوماسي، مشيراً إلى ربط الملف اللبناني بالملف الإيراني، وانتظار ما ستؤول إليه التطورات الميدانية، على أن يجري التفاوض لاحقاً مع رئيس مجلس النواب نبيه بري.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "A political source told Al-Modon newspaper that the Egyptian proposals presented to the party ranged from reviving a model of containing weapons, to reaching a formula that would prevent their use for a specified period, and ultimately placing them under state authority through an agreed implementation mechanism. This would be accompanied by obligating Israel to fulfill its commitments, foremost among them withdrawing to the Blue Line and handing over all civilian and military detainees.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "However, according to the source, the main issue lies in the absence of a clear mechanism to compel Israel to implement these terms, in addition to the lack of clarity on whether Cairo coordinated these proposals with Tel Aviv or the United States.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The biggest obstacle, however, remains the continued presence of Israeli forces on Lebanese territory, along with threats to resume military operations. In response, the party addressed the Egyptian proposal in a diplomatic manner, indicating a linkage between the Lebanese file and the Iranian file, and awaiting the outcome of field developments before entering negotiations later with Parliament Speaker Nabih Berri.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/3K4EPVF5SVLEZLSQEE3CPG6XNE-gJARGywcVYSqNDiEAlnhiPu5501Wa3.jpg', false, false, 1915, 4107, TIMESTAMP '2026-04-04 10:50:44.982', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT ' Islamabad Accord: U.S. and Iran consider a ceasefire plan proposed by Pakistan', 'اتفاق إسلام آباد: أمريكا وإيران تدرسان خطة وقف إطلاق نار اقترحتها باكستان ', 'islamabad-accord', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "برز مقترح دبلوماسي بوساطة باكستان لوقف الحرب بين الولايات المتحدة وإيران، يقوم على وقف فوري لإطلاق النار وإعادة فتح مضيق هرمز، مع التوصل إلى اتفاق أشمل خلال 15 إلى 20 يومًا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الخطة تقترح توقيع مذكرة تفاهم إلكترونيًا، مع قيام باكستان بدور قناة الاتصال الرئيسية بين الأطراف. وذكرت مصادر أن قائد الجيش الباكستاني عاصم منير تواصل طوال الليل مع مسؤولين أمريكيين وإيرانيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما نقلت باكستان وتركيا ومصر مقترحات إلى طهران، بينما تدعم الصين جهود التهدئة. وأكد مسؤول إيراني لوكالة رويترز أن طهران تدرس المقترح لكنها لن تقبل مواعيد نهائية أو ضغوطًا سياسية، كما ترفض إعادة فتح مضيق هرمز مقابل وقف مؤقت لإطلاق النار.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "الصفقة المقترحة من باكستان تقوم على مرحلتين:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المرحلة الفورية", "type": "text"}, {"type": "hardBreak"}, {"text": "• يبدأ وقف إطلاق النار فورًا.", "type": "text"}, {"type": "hardBreak"}, {"text": "• إعادة فتح مضيق هرمز مباشرة (مهم لإمدادات النفط العالمية).", "type": "text"}]}, {"type": "orderedList", "attrs": {"type": null, "start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "المرحلة اللاحقة (15–20 يومًا)", "type": "text"}, {"type": "hardBreak"}, {"text": "• التفاوض على اتفاق سلام شامل.", "type": "text"}, {"type": "hardBreak"}, {"text": "• يُطلق عليه مبدئيًا “اتفاق إسلام آباد”.", "type": "text"}]}]}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "قد يشمل الاتفاق النهائي:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• موافقة إيران على قيود في برنامجها النووي (من دون أسلحة).", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "في المقابل:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• تخفيف العقوبات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الإفراج عن الأصول المجمدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• إطار إقليمي أوسع لأمن مضيق هرمز.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "المصدر: رويترز", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "A Pakistan-mediated diplomatic proposal has emerged to halt the U.S.–Iran war, linking an immediate ceasefire to the reopening of the Strait of Hormuz and a broader agreement within 15–20 days.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "The plan suggests signing a memorandum of understanding electronically, with Pakistan acting as the main communication channel. Sources say Pakistan’s army chief Asim Munir held overnight contacts with U.S. and Iranian officials.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Pakistan, Türkiye, and Egypt have delivered proposals to Tehran, while China supports the de-escalation effort. An Iranian official told Reuters that Tehran is reviewing the proposal but will not accept deadlines or decisions made under pressure, and rejects reopening the Strait of Hormuz in exchange for a temporary ceasefire.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Pakistan’s proposed two-phase deal:", "type": "text"}]}, {"type": "orderedList", "attrs": {"type": null, "start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Immediate Phase", "type": "text"}, {"type": "hardBreak"}, {"text": "• Ceasefire starts right away.", "type": "text"}, {"type": "hardBreak"}, {"text": "• Strait of Hormuz reopens immediately (key for global oil).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Follow-up Phase (15–20 days)", "type": "text"}, {"type": "hardBreak"}, {"text": "• Final comprehensive peace deal negotiated.", "type": "text"}, {"type": "hardBreak"}, {"text": "• Tentatively called the “Islamabad Accord”.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The final deal may include:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Iran agrees to limits on nuclear program (no weapons).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In return:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Sanctions relief.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Release of frozen assets.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Broader regional framework for Hormuz security.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Source: Reuters", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/pak-iran-us-BHeRfdLA3C6y2HJ2TPj28HRUW1FVjg.jpg', false, false, 81, 204, TIMESTAMP '2026-04-06 10:36:22.859', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT ' Doctors Warn Israel Is Destroying Lebanon’s Health System Using Gaza-Style Tactics', 'أطباء يحذرون: إسرائيل تدمر النظام الصحي في لبنان', 'lebanon-health', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "ضربات إسرائيلية في لبنان تستهدف القطاع الصحي وتثير تحذيرات من تكرار سيناريو غزة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "حذّر أطباء ومنظمات إنسانية من أن الضربات الإسرائيلية في لبنان بدأت تستهدف البنية الصحية، في نمط يشبه ما حدث في غزة، مما يضع النظام الصحي الهش تحت ضغط شديد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "منذ تجدد القتال في 2 مارس، قُتل ما لا يقل عن 56 من العاملين في المجال الصحي، وتعرض أكثر من 150 سيارة إسعاف وفرق طوارئ لهجمات، بحسب وزارة الصحة اللبنانية. كما أُجبرت 6 مستشفيات و49 عيادة على الإغلاق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقالت منظمة العفو الدولية إن إسرائيل تستخدم في لبنان نفس الأسلوب الذي استخدمته في غزة عام 2024، والذي أدى إلى مقتل عشرات العاملين في المجال الطبي وتدمير خدمات الرعاية الصحية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من جهته، يقول الجيش الإسرائيلي إن حزب الله يستخدم منشآت مدنية مثل المستشفيات، ما يجعلها أهدافًا عسكرية، وهو ما ينفيه حزب الله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "منظمة هيومن رايتس ووتش قالت إن حجم العمليات يشير إلى تصعيد واضح، بينما أعلن وزير الدفاع الإسرائيلي أن العمليات في جنوب لبنان ستتبع نموذج العمليات في مدن غزة مثل رفح وبيت حانون.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووفق منظمة الصحة العالمية، قُتل 9 مسعفين في يوم واحد أواخر مارس، ما رفع عدد القتلى بين الطواقم الطبية خلال الشهر إلى 51.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الحرب أدت إلى مقتل 1,461 شخصًا وإصابة 4,430، مع نزوح أكثر من مليون مدني. المستشفيات، مثل مستشفى صيدا الحكومي، تعاني من نقص في الطواقم والأسرة والإمدادات.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "مصادر: أسوشيتد برس", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "———", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli strikes in Lebanon target healthcare system, raising Gaza-style tactic fears", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Doctors and humanitarian groups warn that Israeli strikes in Lebanon are increasingly hitting healthcare infrastructure, raising concerns of a pattern similar to what occurred in Gaza.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Since fighting resumed on March 2, at least 56 health workers have been killed and more than 150 ambulances and emergency teams have been targeted, according to Lebanon’s Health Ministry. The attacks have forced 6 hospitals and 49 clinics to close.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Amnesty International said Israel is using the same tactics seen in Gaza in 2024 that led to the deaths of dozens of medical workers and the destruction of healthcare services.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Israeli military says Hezbollah operates within civilian infrastructure, including hospitals, making them legitimate targets. Hezbollah denies the claims.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Human Rights Watch said the scale of operations signals a significant escalation. Israel’s defense minister said operations in southern Lebanon will follow the model used in Gaza cities such as Rafah and Beit Hanoun.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The World Health Organization said 9 paramedics were killed in one day in late March, raising the monthly toll of medical workers killed to 51.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The war has killed 1,461 people and wounded 4,430, while more than one million civilians have been displaced. Hospitals such as Sidon Government Hospital are overwhelmed and facing shortages of staff, beds, and supplies.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Sources: Associated Press", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/w%3D1080%2Cq%3D80-YdL8Vyjlre5hCSAN7CQAAwQYi8aRQ2', false, false, 324, 1307, TIMESTAMP '2026-04-06 16:59:13.804', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Under the title ‘In defense of Lebanon and its people,’ Hezbollah announces the execution of 52 military operations today', 'بعنوان دفاعاً عن لبنان وشعبه.. حزب الله يعلن تنفيذ 52 عملية عسكرية اليوم', 'hezb-april6-stat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "حزب الله يعلن سلسلة عمليات استهداف واسعة يوم الإثنين 06-04-2026 شملت مستوطنات ومواقع على الحدود والشمال", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أعلن حزب الله أنّ مجاهدي المقاومة الإسلامية نفّذوا سلسلة من العمليات العسكرية منذ فجر الإثنين 06-04-2026، استهدفت مواقع عسكرية وتجمعات لجيش العدو الإسرائيلي، إضافة إلى عدد من المستوطنات في شمال فلسطين المحتلة، باستخدام صليات صاروخية ومسيّرات انقضاضية وقذائف مدفعية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح الحزب أنّ العمليات بدأت عند الساعة 00:30 باستهداف مستوطنة حورفيش، تلاها عند الساعة 02:20 استهداف بنى تحتية في مستوطنة معالوت ترشيحا، ثم عند الساعة 02:25 مستوطنة ليمان، وعند الساعة 02:30 مستوطنة شلومي، وجميعها بصليات صاروخية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الساعة 03:10، تم استهداف مستوطنة نهاريا، فيما استُهدفت عند الساعة 05:00 دبابة ميركافا في بلدة رشاف بصاروخ مباشر، محققين إصابة مؤكدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشار البيان إلى استهداف مستوطنة كريات شمونة عند الساعة 10:00، وفي الساعة 11:20 تم تنفيذ عدة عمليات متزامنة استهدفت تجمعات لجنود وآليات الجيش الإسرائيلي عند بوابة فاطمة، وفي موقع إبل القمح، إضافة إلى استهداف مستوطنتي كريات شمونة والمطلة للمرة الثانية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وعند الساعة 12:45، استُهدفت مستوطنة نهاريا مجددًا، فيما تواصلت العمليات عند الساعة 13:30 و13:45 باستهداف تجمعات في حولاتا والمالكية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ساعات بعد الظهر، أعلن الحزب تنفيذ هجوم عند الساعة 14:30 استهدف قاعدة غفعات أولغا التابعة لقيادة المنطقة الشمالية بصاروخ نوعي وسرب من المسيّرات، إلى جانب استهداف تجمعات شرق معتقل الخيام وثكنة هونين وموقع المرج.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما شهدت الفترة بين الساعة 14:10 و15:50 و16:10 عمليات متتالية استهدفت تجمعات ودبابات ميركافا في بلدات عيناتا ورشاف باستخدام صواريخ ومسيّرات انقضاضية، محققة إصابات مباشرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتابع الحزب أنّه عند الساعة 16:00 و16:40، تم استهداف تجمعات في بلدتي البياضة ورشاف وتلة الحمامص بصليات صاروخية وقذائف مدفعية، كما استهدفت قواعد لوجستية في الجولان المحتل ومستوطنة كرم بن زمرة عند الساعة 16:50.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الفترة المسائية، تصاعدت العمليات، حيث استُهدفت مستوطنات كريات شمونة ومرغليوت والمطلة بين الساعة 17:00 و17:40، إضافة إلى تنفيذ هجمات بمسيّرات على مواقع المالكية وهضبة العجل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أعلن الحزب عن استهداف مستوطنة يرؤون عند الساعة 18:30، إلى جانب تجمعات في شلومي، وحانيتا، وكريات شمونة بعدة هجمات بمسيّرات حتى الساعة 19:20.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار إلى استهداف مرابض مدفعية شرق مستوطنة سعسع عند الساعة 20:00، ثم إعادة استهداف ثكنة هونين وموقع المرج عند الساعة 20:30.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واختُتمت العمليات عند الساعة 21:30 باستهداف تجمعات للجيش الإسرائيلي في تلة فريز في بلدة عيناتا بصليّة صاروخية كبيرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أكد الحزب أنه منذ فجر الإثنين وحتى الساعة 12:00، تم استهداف تجمعات لجنود وآليات الجيش الإسرائيلي في بلدة مارون الراس بصليات صاروخية، إلى جانب عمليات أخرى متفرقة خلال اليوم في المنطقة نفسها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hezbollah announced a series of large-scale military operations on Monday, April 6, 2026, stating that its fighters carried out multiple attacks since dawn targeting Israeli military positions, troop gatherings, and settlements in northern occupied Palestine using rocket barrages, attack drones, and artillery shells.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the statement, operations began at 00:30 with rockets targeting Hurfeish, followed by strikes on Ma’alot-Tarshiha, Liman, and Shlomi between 02:20 and 02:30. Nahariya was targeted at 03:10, and at 05:00 a Merkava tank in Rashaf was hit with a direct missile strike.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The operations continued throughout the day, including strikes on Kiryat Shmona at 10:00, and multiple simultaneous attacks at 11:20 targeting Israeli troops and vehicles at Fatima Gate, Ibl al-Qamh, and again Kiryat Shmona and Metula.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Further strikes hit Nahariya again at 12:45, and troop positions in Houla and al-Malkiya at 13:30 and 13:45. At 14:30, Hezbollah launched a combined attack with a precision missile and drones on the Givat Olga base التابعة (affiliated with) the Northern Command.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Additional operations targeted troop gatherings and Merkava tanks in Aita al-Shaab and Rashaf between 14:10 and 16:10, achieving direct hits, alongside rocket and artillery strikes on multiple مواقع (positions), including Bayyada, Talat al-Hamamess, and logistical bases in the occupied Golan.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Evening operations intensified, with repeated strikes on Kiryat Shmona, Margaliot, Metula, Yaroun, Shlomi, Hanita, and other positions using rockets and drones until 19:20.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At 20:00, artillery positions east of Sa’sa were targeted, followed by renewed strikes on Honin barracks and Marj site at 20:30. The operations concluded at 21:30 with a heavy rocket barrage targeting Israeli forces at Talat Friz in Aita al-Shaab.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hezbollah also confirmed ongoing attacks since dawn on Israeli troop concentrations in Maroun al-Ras using rocket fire, alongside additional operations throughout the day in the same area", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2023_Hezbollah_drill_in_Aaramta_03-XvV5UbcmmoZ98pmR4IEN69s21LM75O.jpg', false, false, 72, 262, TIMESTAMP '2026-04-06 20:57:32.498', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A bloody Wednesday faced Lebanon, and the detached and implicit pronouns will negotiate with the killer... under fire', 'أربعاء دموي واجهه لبنان، والضميرين المنفصل والمستتر سيفاوضان القاتل... تحت النار', 'lebanon-bloody-wednesday', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في لحظة إقليمية نادرة، حيث تتقاطع المصالح وتُعاد صياغة موازين القوى على مستوى المنطقة، لم يكن ينقص لبنان سوى قرار سياسي يلتقط الفرصة. غير أن ما حصل كان العكس تمامًا: دولة تمتلك أوراق ضغط فعلية، لكنها تختار طوعًا التخلي عنها، وتذهب إلى التفاوض من موقع الضعف، حتى وهي تحت النار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لم تكن التطورات مجرد تفصيل عابر. إغلاق مضيق هرمز، الشريان الحيوي للطاقة عالميًا، لم يكن حدثًا تقنيًا بل تحوّلًا استراتيجيًا وضع الولايات المتحدة أمام اختبار حقيقي، خصوصًا في ظل الفجوة بين إنتاجها النفطي واستهلاكها، واعتمادها الجزئي على الإمدادات التي تمر عبر هذا الممر. ومع محدودية قدرتها على الصمود لفترة طويلة، كان من الطبيعي أن تتجه نحو تفاهم مع إيران، تفاهم لم يكن لبنان خارجه، بل كان أحد عناوينه المباشرة من خلال بند وقف العدوان عليه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في تلك اللحظة تحديدًا، لم يكن لبنان خارج اللعبة، بل في قلبها. كان يملك، موضوعيًا، فرصة للانتقال من موقع المتلقي إلى موقع الفاعل، مستفيدًا من تلاقي الضغط الإقليمي مع الواقع الميداني. لكن الدولة اللبنانية قررت، مرة جديدة، أن تتصرف وكأنها غير معنية، أو عاجزة عن ترجمة هذه المعطيات إلى مكاسب سياسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تحت عنوان “استقلالية القرار”، تحدث نواف سلام عن أولوية الدبلوماسية، وكأن 15 شهرًا من هذا النهج لم تكن كافية لإثبات فشله. لم تكن المشكلة في المبدأ بحد ذاته، بل في التمسك به كخيار وحيد، حتى في لحظة كانت تفرض مقاربة مختلفة، أكثر توازنًا بين الدبلوماسية وعناصر القوة. إلا أن القرار كان واضحًا: تفادي أي تصعيد، ولو كان ذلك على حساب القدرة على فرض شروط أفضل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومع خرق إسرائيل للتفاهم واستئنافها العدوان، عاد المشهد إلى نقطة أكثر حدة، مع إعادة إغلاق مضيق هرمز وعودة الضغط الإقليمي إلى الواجهة. لكن بدل أن يشكّل ذلك فرصة إضافية للبنان، بدا وكأنه عامل لا يعنيه، أو على الأقل لا يستحق أن يُستثمر. هنا تحديدًا، تتجلى المفارقة: كلما ارتفعت كلفة المواجهة على المستوى الإقليمي، انخفض سقف الموقف اللبناني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لم يكن غياب الفرصة هو المشكلة، بل غياب الإرادة في استغلالها. فالدولة، بدل أن توظّف عناصر القوة المتاحة، من الضغط الإقليمي إلى المعطيات الميدانية، اختارت أن تتصرف كطرف مهزوم سلفًا، يسعى إلى تقليل خسائره لا إلى تحسين موقعه. وهكذا، تحوّل التفاوض من أداة لفرض الشروط إلى وسيلة لتكريس الضعف.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المفارقة الأكثر قسوة لم تكن في المسار السياسي بحد ذاته، بل في توقيته. في الثامن من نيسان، سقط أكثر من 300 لبناني نتيجة العدوان، في لحظة كان يُفترض أن تعيد رسم أولويات الدولة. إلا أن ما تلا ذلك لم يكن سوى مشهد مزدوج: إعلان حداد على الضحايا، مقابل الانخراط في مفاوضات مباشرة مع الجهة نفسها التي قتلتهم. كأن الدم لم يكن عنصر ضغط، بل تفصيلًا يُطوى سريعًا في حسابات التهدئة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بهذا المعنى، لا يمكن قراءة ما جرى كخطأ عابر أو سوء تقدير، بل كنهج متكامل يقوم على التخلي المسبق عن عناصر القوة، وعلى إدارة الصراع بعقلية الطرف الأضعف، حتى في اللحظات التي يمتلك فيها ما يكفي لتغيير المعادلة. وفي بلد كلبنان، لا يبدو أن المشكلة يومًا كانت في غياب الفرص، بل في قرارات تضيّعها عندما تصبح متاحة.", "type": "text"}, {"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "In a rare regional moment, where interests intersect and the balance of power across the region is being reshaped, Lebanon lacked only a political decision capable of seizing the opportunity. Yet what happened was the exact opposite: a state that possesses real leverage, but willingly chooses to abandon it, heading into negotiations from a position of weakness, even while under fire.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The developments were not merely a passing detail. The closure of the Strait of Hormuz, a vital artery for global energy, was not a technical event but a strategic shift that placed the United States before a real test, especially given the gap between its oil production and consumption, and its partial reliance on supplies passing through this corridor. With its limited ability to endure for long, it was natural for it to move toward an understanding with Iran, an understanding from which Lebanon was not excluded, but rather one of its direct headings through the clause of stopping the aggression against it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At that precise moment, Lebanon was not outside the game, but at its core. Objectively, it had an opportunity to move from the position of recipient to that of an actor, benefiting from the intersection of regional pressure with the field reality. But the Lebanese state decided, once again, to act as if it were not concerned, or incapable of translating these factors into political gains.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Under the title of independence of decision, Nawaf Salam spoke of the priority of diplomacy, as if 15 months of this approach had not been enough to prove its failure. The problem was not in the principle itself, but in clinging to it as the only option, even at a moment that required a different approach, more balanced between diplomacy and elements of strength. Yet the decision was clear: avoiding any escalation, even if that came at the expense of the ability to impose better terms.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "With Israel breaching the understanding and resuming its aggression, the scene returned to a sharper point, with the reclosure of the Strait of Hormuz and the return of regional pressure to the forefront. But instead of constituting an additional opportunity for Lebanon, it seemed like a factor that did not concern it, or at least did not deserve to be invested. Here lies the paradox: the higher the cost of confrontation at the regional level, the lower the ceiling of the Lebanese position.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The absence of opportunity was not the problem, but the absence of will to exploit it. The state, instead of employing the available elements of strength, from regional pressure to field realities, chose to act as a pre-defeated party, seeking to reduce its losses rather than improve its position. Thus, negotiation shifted from a tool to impose conditions into a means of entrenching weakness.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The harshest paradox was not in the political path itself, but in its timing. On April 8, more than 300 Lebanese fell as a result of the aggression, at a moment that was supposed to redraw the state’s priorities. Yet what followed was nothing but a dual scene: declaring mourning for the victims, while engaging in direct negotiations with the same party that killed them. As if blood was not a pressure factor, but a detail quickly folded into calculations of de-escalation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this sense, what happened cannot be read as a passing mistake or miscalculation, but as a complete approach based on the prior abandonment of elements of strength, and on managing the conflict with the mentality of the weaker party, even in moments when it possesses enough to change the equation. In a country like Lebanon, the problem has never seemed to be the absence of opportunities, but decisions that waste them when they become available.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/260408-lebanon-israel--beirut-mn-0845-7fcf84-orvvMNhtFxvjpO1nMS15v4AMXlddkG.jpg', false, false, 382, 1096, TIMESTAMP '2026-04-10 08:12:34.332', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Unstable weather bids farewell to Lebanon… and warm spring conditions starting from this day', 'طقس متقلّب يودّع لبنان… وأجواء ربيعية دافئة اعتبارًا من هذا اليوم', 'lebanon-springwea-soon', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "لا تزال الأجواء في لبنان متقلّبة بين أمطار متفرقة وطقس بارد نسبيًا، تحت تأثير منخفض جوي محدود الفعالية متمركز فوق تركيا، على أن يبدأ بالانحسار تدريجيًا اعتبارًا من يوم الإثنين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، أوضح رئيس فرع التقديرات الجوية في مطار رفيق الحريري الدولي، وسام أبو خشفة، في حديث إلى \"ليبانون ديبايت\"، أن الطقس اليوم الأحد سيكون غائمًا جزئيًا إلى غائم أحيانًا، مع ضباب على المرتفعات وانخفاض في درجات الحرارة، إضافة إلى رياح ناشطة تترافق مع أمطار متفرقة تشتد أحيانًا اعتبارًا من بعد الظهر، مع احتمال حدوث برق ورعد، وتساقط للثلوج على ارتفاع 2000 متر وما فوق", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما يوم الإثنين، فيتجه الطقس نحو الاستقرار التدريجي، حيث يكون غائمًا جزئيًا مع ارتفاع طفيف بدرجات الحرارة، وضباب محلي على المرتفعات، مع احتمال تساقط أمطار خفيفة خلال ساعات الصباح في المناطق الشمالية، قبل أن يتحوّل خلال النهار إلى قليل الغيوم، مع انخفاض في نسبة الرطوبة بدءًا من بعد الظهر", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب أبو خشفة، تبدأ الأجواء الربيعية الدافئة بالسيطرة اعتبارًا من ظهر يوم الثلاثاء، نتيجة تأثر المنطقة بكتل هوائية دافئة نسبيًا، ما يؤدي إلى ارتفاع ملموس في درجات الحرارة، خصوصًا في المناطق الداخلية والجبلية، على أن تبلغ ذروتها يوم الخميس، حيث قد تلامس 30 درجة مئوية، مع استقرار في الطقس وظهور طبقات من الغبار في الأجواء", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار إلى أن يوم الأربعاء سيكون غائمًا جزئيًا مع سحب مرتفعة، وارتفاع واضح بدرجات الحرارة بحدود 5 درجات فوق معدلاتها الموسمية، مع احتمال تشكّل الغبار في الأجواء", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ما يتعلق بدرجات الحرارة اليوم، تتراوح على الساحل بين 14 و20 درجة مئوية، وبين 5 و16 درجة في المناطق الجبلية، وبين 5 و17 درجة في البقاع، فيما يكون البحر مائجًا، وتبلغ حرارة سطح المياه 19 درجة، مع نسبة رطوبة على الساحل تتراوح بين 65 و85%، وضغط جوي يبلغ 760 ملم زئبق", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Weather conditions in Lebanon remain unstable, with scattered rain and relatively cold weather, under the influence of a weak low-pressure system centered over Turkey, which is expected to gradually recede starting Monday.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, the head of the Forecasting Department at Rafic Hariri International Airport, Wissam Abu Khashfeh, explained in an interview with Lebanon Debate that the weather today, Sunday, will be partly cloudy to occasionally cloudy, with fog over the highlands and a drop in temperatures, in addition to active winds accompanied by scattered rain that may intensify at times starting in the afternoon, with a possibility of thunder and lightning, and snowfall at elevations of 2000 meters and above.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As for Monday, the weather will gradually stabilize, becoming partly cloudy with a slight rise in temperatures, and local fog over the highlands, with a chance of light rain during the morning hours in the northern regions, before turning during the day into mostly clear skies, with a decrease in humidity starting in the afternoon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Abu Khashfeh, warm spring-like conditions will begin to dominate starting Tuesday noon, as the region is affected by relatively warm air masses, leading to a noticeable rise in temperatures, especially in inland and mountainous areas, reaching their peak on Thursday, where they may approach 30 degrees Celsius, with stable weather and the presence of dust layers in the atmosphere.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also noted that Wednesday will be partly cloudy with high clouds, and a clear rise in temperatures of about 5 degrees above seasonal averages, with a possibility of dust forming in the air.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding today’s temperatures, they range along the coast between 14 and 20 degrees Celsius, between 5 and 16 degrees in the mountainous areas, and between 5 and 17 degrees in the Bekaa, while the sea is rough, with a surface water temperature of 19 degrees, and coastal humidity ranging between 65 and 85%, with atmospheric pressure at 760 millimeters of mercury", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Lebanon-autumn-3-MOtut8p3j4qfFu9UJpwGPpfjvGmYkR.jpg', false, false, 111, 520, TIMESTAMP '2026-04-12 09:34:39.753', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Planned major assassination operations and leaked sensitive data… investigations arrest a dangerous suspect accused of collaborating with Mossad', 'خطّط لعمليات اغتيال بارزة وسرّب بيانات حساسة... التحقيقات تُوقِف مشتبهًا خطيرًا بتعامله مع الموساد', 'dangerous-israeli-agent', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "توقيف مشتبه بتعامله مع “الموساد”… شبكة خطوط وتسريب بيانات وارتباط باغتيالات", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "تواصل مديرية المخابرات في الجيش اللبناني تحقيقاتها مع موقوف يُشتبه بتعامله مع جهاز “الموساد” الإسرائيلي، في ملف يتضمن تسهيل عمليات اغتيال وتسريب بيانات حساسة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الموقوف “إيلي. ض” (مواليد 1996 – حارة صخر) هو عسكري سابق في الحرس الجمهوري، طُرد من الجيش بعد حالات فرار، قبل أن يتجه إلى مجال القرصنة الإلكترونية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تشير التحقيقات إلى احتمال تورطه في تسهيل اغتيال محمد كوراني في فندق “كومفورت” في الحازمية، وحمزة ركان في الرحاب، عبر أسلوب يعتمد على تأكيد وجود الهدف قبل استهدافه. ففي العملية الأولى، جرى الاتصال بالفندق وانتحال صفة طبيب لطلب تصوير الممرات، ما ساهم في تحديد الموقع. وفي الثانية، انتحل المتصل صفة ضابط مخابرات وتواصل مع سكان المبنى والناطور للتأكد من وجود الهدف.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وخلال مداهمة منزله، ضُبطت أجهزة وعدد كبير من الشرائح الهاتفية، بينها 14 شريحة مخبأة داخل الثلاجة، وتبيّن استخدام بعضها في أنشطة أمنية. وأقرّ بأنه كان يشتري خطوطًا لبنانية بأسماء وهمية، ويفعّلها على أجهزة منفصلة ويرسل رموز “واتساب” لمشغّلين عبر “تلغرام”، مقابل مبالغ مالية تُحوّل عبر العملات الرقمية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح أنه تواصل مع شخصين باسم “مارك” و”جورج”، طلبا منه تأمين خطوط إضافية مع اتباع إجراءات أمنية صارمة، ليرتفع العدد إلى نحو 20 شريحة، إضافة إلى شراء أجهزة مخصصة لها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أقرّ بتسليم قواعد بيانات حساسة حصل عليها عبر القرصنة، تشمل معلومات من وزارات ومؤسسات رسمية، مثل العمل والاتصالات والصحة وكهرباء لبنان، إضافة إلى لوائح الشطب وبيانات من مطار بيروت وموقع “اشتري”، وتتضمن أسماء وأرقام هواتف وعناوين سكن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار إلى أن مشغّليه طلبوا بيانات إضافية، بينها معلومات عقارية ومحاولات لاختراق منصات مثل “Toters”، بهدف الوصول إلى بيانات أوسع عن اللبنانيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم ادعائه أنه لم يكن متأكدًا من هوية الجهة التي يتعامل معها، إلا أنه أقرّ بأنه بدأ يشك لاحقًا بارتباطهم بالاستخبارات الإسرائيلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولا تزال التحقيقات مستمرة، مع تحليل البيانات المضبوطة وتتبع الشبكة المحتملة، تمهيدًا لاستكمال الإجراءات أمام القضاء العسكري.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "بتصرف عن قناة المحطة", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "التفاصيل كاملة -  More details", "type": "text"}]}, {"type": "iframe", "attrs": {"src": "https://www.youtube.com/embed/lML4JZVHyG8?si=LSFzTetcBolK_hF5"}}, {"type": "paragraph"}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Arrest of a suspect accused of collaborating with Mossad… a network of lines, data leaks, and links to assassinations", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Intelligence Directorate of the Lebanese Army continues its investigations with a detainee suspected of collaborating with the Israeli Mossad, in a case involving facilitating assassination operations and leaking sensitive data.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The detainee Eli D. (born 1996 – Haret Sakhr) is a former member of the Republican Guard who was dismissed from the army after cases of desertion, before turning to cyber hacking.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Investigations indicate the possibility of his involvement in facilitating the assassination of Mohammad Kourani at the Comfort Hotel in Hazmieh, and Hamza Rakan in Rehab, through a method based on confirming the target’s presence before targeting him. In the first operation, the hotel was contacted and a doctor’s identity was impersonated to request filming the corridors, which helped determine the location. In the second, the caller impersonated an intelligence officer and contacted residents of the building and the concierge to confirm the target’s presence.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "During a raid on his home, devices and a large number of SIM cards were seized, including 14 SIM cards hidden inside the refrigerator, and it was found that some were used in security activities. He admitted that he was buying Lebanese lines under fake names, activating them on separate devices, and sending WhatsApp codes to operators via Telegram, in exchange for sums of money transferred through digital currencies.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He explained that he communicated with two individuals named Mark and George, who asked him to secure additional lines while following strict security measures, bringing the number to about 20 SIM cards, in addition to purchasing devices dedicated to them.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also admitted to handing over sensitive databases obtained through hacking, including information from ministries and official institutions such as labor, telecommunications, health, and Electricité du Liban, in addition to electoral lists and data from Beirut Airport and the Ishtari website, including names, phone numbers, and residential addresses.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He indicated that his operators requested additional data, including real estate information and attempts to hack platforms such as Toters, aiming to access broader data about Lebanese citizens.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite claiming he was not certain of the identity of the party he was dealing with, he admitted that he later began to suspect their connection to Israeli intelligence.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Investigations are still ongoing, with analysis of the seized data and tracking of the potential network, in preparation for completing procedures before the military judiciary", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/%25D8%25AA%25D9%2588%25D9%2582%25D9%258A%25D9%2581-%25D8%25A7%25D9%2584%25D9%2582%25D8%25A8%25D8%25B6-sahafi.org-1-euBNPG1nXtXo9ZDBeqJzteG2fc8dkf.jpg', false, false, 2194, 4087, TIMESTAMP '2026-04-12 20:53:30.721', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Ministry of Education reveals in numbers and plans the reality of education in wartime', 'وزارة التربية تكشف بالأرقام والخطط واقع التعليم في زمن الحرب', 'edu-latest-updates', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}}, {"type": "paragraph", "content": [{"text": "منذ بداية العدوان على لبنان، وجد القطاع التربوي نفسه أمام تحديات استثنائية، من تحويل عدد من المدارس والثانويات الرسمية إلى مراكز إيواء للنازحين، إلى ضرورة تأمين استمرارية التعليم للطلاب في مختلف المناطق. وفي هذا السياق، عرضت وزارة التربية والتعليم العالي واقع العملية التعليمية خلال هذه المرحلة، مشيرة إلى الإجراءات التي اعتمدتها للحد من الخسائر التربوية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "استمرار جزئي وتعطّل في مناطق المواجهة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وأوضحت الوزارة أنها أطلقت ورشة عمل شملت إداراتها والمناطق التربوية ومديري المدارس، بهدف تقليص الفاقد التعليمي، لا سيما في القطاع الرسمي الذي تأثر بشكل كبير. وبحسب المعطيات، تمكن نحو 50% من المدارس والثانويات الرسمية من الاستمرار في التعليم الحضوري ضمن المناطق الآمنة، فيما تم اعتماد التعليم عن بُعد للطلاب الذين تعذّر حضورهم. في المقابل، توقفت نحو 15% من المدارس كليًا نتيجة وقوعها في مناطق متأثرة مباشرة بالحرب.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "متابعة فردية للطلاب والمعلمين", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي موازاة ذلك، أكدت الوزارة أنها تعمل بالتعاون مع إدارات المدارس على متابعة أوضاع الطلاب والمعلمين بشكل فردي، من خلال مسح شامل يهدف إلى تحديد الاحتياجات وتأمين الدعم اللازم، بما يساهم في الحد من الانقطاع التربوي", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "التعليم عن بُعد والدعم التقني", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وضمن خطة استمرارية التعليم، اعتمدت الوزارة التعليم عن بُعد للطلاب النازحين، وكذلك للطلاب الذين تحولت مدارسهم إلى مراكز إيواء، كما فعّلت حسابات الطلاب والأساتذة على منصة Microsoft Teams، وأمّنت باقات إنترنت مجانية لتسهيل استخدامها. كذلك عملت، بالتعاون مع المركز التربوي للبحوث والإنماء، على توفير مواد تعليمية رقمية عبر منصة “مدرستي”، إلى جانب تفعيل خدمة “Call and Learn” التي تتيح التواصل المجاني مع الأساتذة", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مراكز دعم لتعزيز العملية التعليمية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي إطار تعزيز الدعم، أطلقت الوزارة مراكز دعم التعلّم (Teaching and Learning Hubs) عبر تجمّعات مدرسية ضمن نطاقات جغرافية محددة، بهدف تأمين بيئة تعليمية مناسبة، وتمكين الأساتذة من استخدام الموارد التعليمية وتبادل الخبرات، إضافة إلى إشراك الطلاب في أنشطة تعليمية، خصوصًا ذوي الاحتياجات الخاصة", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الامتحانات الرسمية والتنسيق المؤسسي", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "أما في ما يتعلق بالامتحانات الرسمية، فأكدت الوزارة أنها ستضع الرأي العام في صورة أي قرار يُتخذ استنادًا إلى الواقع التربوي والمعطيات المتوافرة، وبالتعاون مع المؤسسات التعليمية. كما دعت الشركاء المحليين والدوليين، والبلديات، والجمعيات، والناشطين التربويين، إلى التنسيق معها حصراً في أي مبادرة لدعم خطة استمرارية التعلم", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "توحيد الجهود في ظل الأزمة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وشددت الوزارة على أن توحيد الجهود والتنسيق المؤسسي يشكلان أولوية في هذه المرحلة، بما يضمن خدمة مصلحة الطلاب والحفاظ على استمرارية التعليم، رغم الظروف الصعبة التي يمر بها لبنان", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Since the beginning of the aggression on Lebanon, the education sector has found itself facing exceptional challenges, from turning a number of public schools and secondary schools into shelters for the displaced, to the need to ensure continuity of education for students across different regions. In this context, the Ministry of Education and Higher Education presented the reality of the educational process during this phase, pointing to the measures it adopted to limit educational losses.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Partial continuity and disruption in conflict areas", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry explained that it launched a workshop involving its departments, educational regions, and school principals, aimed at reducing learning loss, especially in the public sector which was heavily affected. According to the data, about 50% of public schools and secondary schools managed to continue in-person education in safe areas, while distance learning was adopted for students unable to attend. In contrast, about 15% of schools completely stopped due to being located in areas directly affected by the war.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Individual follow-up for students and teachers", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, the ministry confirmed that it is working in cooperation with school administrations to follow up on the conditions of students and teachers individually, through a comprehensive survey aimed at identifying needs and providing the necessary support, contributing to reducing educational disruption.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Distance learning and technical support", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As part of the education continuity plan, the ministry adopted distance learning for displaced students, as well as for those whose schools were turned into shelters, and activated student and teacher accounts on the Microsoft Teams platform, while providing free internet packages to facilitate its use. It also worked, in cooperation with the Center for Educational Research and Development, to provide digital educational materials through the Madrasti platform, in addition to activating the Call and Learn service, which allows free communication with teachers.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Support centers to strengthen the educational process", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As part of strengthening support, the ministry launched Teaching and Learning Hubs through school clusters within specific geographic areas, aiming to provide a suitable learning environment, enable teachers to use educational resources and exchange expertise, and involve students in educational activities, especially those with special needs.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Official exams and institutional coordination", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding official exams, the ministry confirmed that it will keep the public informed of any decision taken based on the educational reality and available data, in cooperation with educational institutions. It also called on local and international partners, municipalities, associations, and educational activists to coordinate exclusively with it on any initiative to support the education continuity plan.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Unifying efforts amid the crisis", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry stressed that unifying efforts and institutional coordination are a priority at this stage, ensuring the service of students’ interests and maintaining the continuity of education despite the difficult circumstances Lebanon is going through", "type": "text"}]}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-909926-639081522563272735-t1kg6XFyK1GJsKoOi3uIPLYQUAeq3F.jpg', false, false, 1192, 2443, TIMESTAMP '2026-04-13 15:20:16.744', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Trump’s blockade of the Strait of Hormuz… how is it implemented?', 'حصار ترامب على مضيق هرمز... كيف يتم تطبيقه؟', 'trump-hormuz-blockage', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "دخل تهديد الرئيس الأمريكي دونالد ترمب بحصار جميع السفن الداخلة إلى الموانئ الإيرانية والخارجة منها حيّز التنفيذ، الساعة العاشرة صباحا بتوقيت الساحل الشرقي (الخامسة مساء بتوقيت بيروت)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأعلن الجيش الأمريكي أنه سيفرض حصارا في خليج عُمان وبحر العرب شرق مضيق هرمز، وقال إنه سيشمل جميع السفن بصرف النظر عن الأعلام التي ترفعها، مشيرا إلى أنه يبدأ اليوم الاثنين في الساعة المذكورة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "ترمب: سندمّر سفن إيران إذا اقتربت", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفور دخول تهديده حيّز التنفيذ، توعد ترمب السفن الإيرانية التي ستقترب من الحصار، بالقضاء عليها على الفور، مضيفا أنه سيجر التعامل معها، بالأسلوب ذاته الذي تستخدمه بلاده ضد \"تجار المخدرات\" على متن القوارب في البحر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال ترمب عبر منصته \"تروث سوشيال\" إن البحرية الإيرانية \"ترقد في قاع البحر\"، مشيرا إلى أنها دُمِّرت بالكامل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وذكر أن قوات بلاده دمّرت 158 سفينة إيرانية، مضيفا \"ما لم نستهدفه هو العدد القليل من سفنهم، التي يسمونها (سفن الهجوم السريع)، لأننا لم نعتبرها تهديدا كبيرا\".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "كيف يُنفذ الحصار؟", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "قبل ساعات قليلة من دخول الحصار حيّز التنفيذ، أكد بيان صادر عن القيادة المركزية الأمريكية للبحارة أن \"أي سفينة تدخل أو تغادر المنطقة المحاصرة دون تصريح ستُعرَّض للاعتراض والتحويل والاحتجاز\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن الحصار لن يعوق ما وصفتها بـ\"حركة العبور المحايدة\" عبر المضيق، من وجهات غير إيرانية وإليها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح البيان أن الحصار \"يشمل الساحل الإيراني كله بما في ذلك الموانئ ومحطات النفط على سبيل المثال لا الحصر\"، مضيفا أنه سيُسمَح بمرور الشحنات الإنسانية بما في ذلك المواد الغذائية والإمدادات الطبية وغيرها من السلع الأساسية، بعد تفتيشها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال رئيس العمليات في البحرية الأمريكية إن زرع الألغام أو التهديد الناجم عنها قد يمثل تحديا غير متماثل في مضيق هرمز، مضيفا أنه يجب النظر إلى الحصار البحري بأنه إشكالية وتحدٍّ بالغ الصعوبة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن قائد القيادة المركزية يعكف على بلورة القرار بشأن الحصار، لافتا إلى أنه يستحضر اعتبارات الحصار بما فيها الاعتبارات القانونية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "حصار بلا سقف زمني", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وقال مسؤول أمريكي للجزيرة إن الحصار البحري على ايران سيُطبَّق مهما طالت المدة التي يقررها ترمب، وشدَّد على استعداد قوات بلاده لتنفيذ الحصار، مضيفا \"لدينا ما يكفي من القوات والعتاد لتنفيذه\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويرى خبراء أن الحصار يسعى إلى عزل إيران تماما عن خطوط الملاحة الدولية، وسط تساؤلات بشأن قدرة الجانبين على ضبط إيقاع المواجهة دون الانزلاق إلى حرب شاملة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "كيف ستتصرف إيران؟", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "على الطرف الآخر، أعلن مقر خاتم الأنبياء العسكري أن طهران ستطبّق بحزم آلية دائمة للتحكم في مضيق هرمز، محذرا من أن أمن الموانئ في الخليج وبحر عُمان إما أن يكون للجميع أو لا يكون لأحد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال رئيس لجنة الأمن القومي في البرلمان الإيراني إبراهيم عزيزي إن هذه المحاولة تُعَد حربا وسترد إيران عليها، واصفا تصريحات الرئيس الأمريكي بشأن حصار المضيق بأنها \"مجرد تهديد\" بعيد عن الواقع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار عزيزي عبر حسابه  إلى وجود أوراق أخرى يمكن استخدامها لمواجهة التهديد بالحصار، دون الكشف عنها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وذكر أن محاولة حصار مضيق هرمز ستزيد الوضع تعقيدا وتُفاقم تقلبات السوق العالمية، مؤكدا ضرورة احترام الشعب الإيراني لتحقيق أي تحسُّن في الوضع الراهن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأردف مخاطبا امريكا \"تقبَّلوا هزيمتكم، لا تطالبوا على طاولة المفاوضات بما لم تستطيعوا كسبه في الحرب\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Trump’s threat to impose a blockade on all ships entering and leaving Iranian ports came into effect at 10 a.m. Eastern Time (5 p.m. Beirut time).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The US military announced it will enforce a blockade in the Gulf of Oman and the Arabian Sea east of the Strait of Hormuz, stating it will include all ships regardless of the flags they carry, and that it begins today, Monday, at the specified time.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Trump: we will destroy Iran’s ships if they approach", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As soon as his threat came into effect, Trump warned Iranian ships that approach the blockade that they will be eliminated immediately, adding that they will be dealt with using the same method his country uses against drug traffickers on boats at sea.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trump said on his Truth Social platform that the Iranian navy lies at the bottom of the sea, indicating that it has been completely destroyed.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He stated that US forces destroyed 158 Iranian ships, adding that what was not targeted was the small number of vessels they call fast attack boats, because they were not considered a major threat.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "How is the blockade implemented?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hours before the blockade took effect, a statement issued by US Central Command to mariners confirmed that any ship entering or leaving the blockaded area without authorization will be subject to interception, diversion, and detention.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It added that the blockade will not hinder what it described as neutral transit through the strait, to and from non-Iranian destinations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The statement clarified that the blockade includes the entire Iranian coast, including ports and oil facilities among others, adding that humanitarian shipments, including food, medical supplies, and other essential goods, will be allowed to pass after inspection.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The US Navy’s chief of operations said that the laying of mines or the threat posed by them could represent an asymmetric challenge in the Strait of Hormuz, adding that the naval blockade should be viewed as a highly complex issue and challenge.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added that the commander of US Central Command is working on shaping the decision regarding the blockade, noting that it takes into account various considerations, including legal ones.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A blockade without a time limit", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A US official told Al Jazeera that the naval blockade on Iran will be applied for as long as Trump decides, stressing that US forces are ready to implement it, adding that they have sufficient forces and equipment to do so.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Experts believe the blockade aims to completely isolate Iran from international shipping routes, amid questions about the ability of both sides to control the pace of confrontation without slipping into a full-scale war.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "How will Iran respond?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other side, the Khatam al-Anbiya military headquarters announced that Tehran will firmly implement a permanent mechanism to control the Strait of Hormuz, warning that the security of ports in the Gulf and the Gulf of Oman must either be for everyone or for no one.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The head of the National Security Committee in the Iranian parliament, Ebrahim Azizi, said that this attempt is considered a war and that Iran will respond to it, describing the US president’s statements about the blockade of the strait as merely a threat far from reality.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Azizi pointed out that there are other options that can be used to confront the blockade threat, without revealing them.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He stated that the attempt to blockade the Strait of Hormuz will increase complexity and intensify volatility in global markets, stressing the need to respect the Iranian people to achieve any improvement in the current situation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added, addressing America, accept your defeat, do not demand at the negotiating table what you could not achieve in war", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/500px-US_Navy_031130-N-3653A-002_USS_George_Washington_%2528CVN_73%2529_Carrier_Strike_Group_formation_sails_in_the_Atlantic_Ocean-vkGe3I0rRpIuOfkp8wPB3QDhWmh1ae.jpg', false, false, 790, 2291, TIMESTAMP '2026-04-13 16:16:26.719', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Türkiye warns Israel: We know what Netanyahu wants', 'تركيا تحذر إسرائيل: نعرف ما يريده نتنياهو', 'turkeyisrael', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "حذّر وزير الخارجية التركي ", "type": "text"}, {"text": "هاكان فيدان", "type": "text", "marks": [{"type": "bold"}]}, {"text": " من أن إسرائيل تستغل الحروب والتوترات في المنطقة لتوسيع نفوذها، مؤكدًا أن أنقرة تدرك أهداف رئيس الوزراء الإسرائيلي ", "type": "text"}, {"text": "بنيامين نتنياهو", "type": "text", "marks": [{"type": "bold"}]}, {"text": " في سوريا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ما الذي يحدث:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "قال فيدان إن التطورات منذ ", "type": "text"}, {"text": "أكتوبر 2023", "type": "text", "marks": [{"type": "bold"}]}, {"text": " فتحت المجال أمام إسرائيل لتعزيز وجودها العسكري والسياسي في المنطقة، وغالبًا ما يتم تقديم هذه الخطوات تحت غطاء الاحتياجات الأمنية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن بعض السياسات الإسرائيلية قد تسعى أيضًا إلى ", "type": "text"}, {"text": "خلق عدو جديد في المنطقة، وهو تركيا", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ما الذي قالته تركيا:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "تركيا تراقب التحركات الإسرائيلية في سوريا عن كثب.", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "أنقرة تدرك ما يريده نتنياهو في سوريا", "type": "text", "marks": [{"type": "bold"}]}, {"text": " وتتابع أي تغييرات محتملة في موازين القوى.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• إسرائيل قد ", "type": "text"}, {"text": "تؤجل بعض خطواتها بسبب الحرب مع إيران", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، لكن ذلك لا يعني أن هذه الخطط لن تعود لاحقًا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "النقطة الأوسع:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تركيا ترى أن بعض السياسات الإسرائيلية قد تهدف إلى ", "type": "text"}, {"text": "إعادة تشكيل التوازنات الإقليمية", "type": "text", "marks": [{"type": "bold"}]}, {"text": " مستفيدة من الصراعات الجارية في المنطقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "انتقادات إضافية:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "فيدان انتقد أيضًا ", "type": "text"}, {"text": "تعزيز التعاون بين إسرائيل واليونان", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، محذرًا من أنه قد يزيد التوتر في شرق المتوسط.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ما التالي:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• تركيا تقول إنها ", "type": "text"}, {"text": "تتابع التطورات في سوريا عن كثب", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• أنقرة قد ", "type": "text"}, {"text": "تتخذ خطوات سياسية أو دبلوماسية", "type": "text", "marks": [{"type": "bold"}]}, {"text": " إذا رأت تهديدًا لمصالحها أو لاستقرار المنطقة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Türkiye’s Foreign Minister ", "type": "text"}, {"text": "Hakan Fidan", "type": "text", "marks": [{"type": "bold"}]}, {"text": " warned that Israel is using regional conflicts to expand its influence, saying Ankara understands Israeli Prime Minister ", "type": "text"}, {"text": "Benjamin Netanyahu’s", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goals in Syria.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What’s happening:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Fidan said developments since ", "type": "text"}, {"text": "October 2023", "type": "text", "marks": [{"type": "bold"}]}, {"text": " created new opportunities for Israel to increase its military and political presence in the region, often framed as security needs.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also suggested that some Israeli policies aim to ", "type": "text"}, {"text": "create a new regional enemy — Türkiye", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What Türkiye says:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Türkiye is closely monitoring Israeli moves in Syria.", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Ankara knows what Netanyahu wants in Syria", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and is watching for changes in the regional balance.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Israel may ", "type": "text"}, {"text": "delay certain plans because of the war with Iran", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", but they could return later.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The bigger picture:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Türkiye believes some Israeli policies aim to ", "type": "text"}, {"text": "reshape regional power dynamics", "type": "text", "marks": [{"type": "bold"}]}, {"text": " during ongoing conflicts in the Middle East.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Additional criticism:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Fidan also criticized ", "type": "text"}, {"text": "growing cooperation between Israel and Greece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", warning it could raise tensions in the Eastern Mediterranean.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What’s next:", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Türkiye says it will ", "type": "text"}, {"text": "continue monitoring developments in Syria", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Ankara may ", "type": "text"}, {"text": "take political or diplomatic steps", "type": "text", "marks": [{"type": "bold"}]}, {"text": " if it sees threats to its interests or regional stability.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/w%3D1080%2Cq%3D80-VyQg2qiLnQvVvxk2f9jPTHbhxd7EBF', false, false, 572, 1342, TIMESTAMP '2026-04-14 00:45:11.607', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Arrest of a thief caught in the act', 'توقيف سارق بالجرم المشهود', 'thief-caught', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "صدر عن المديريّة العامّة لقوى الأمن الداخلي ـ شعبة العلاقات العامّة البلاغ الآتي: ", "type": "text", "marks": [{"type": "bold"}]}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "\"في إطار المتابعة اليوميّة التي تقوم بها قوى الأمن الدّاخلي للحدّ من الجرائم بمختلف أنواعها، ولا سيّما تلك المتعلّقة بسرقة الدّرّاجات الآليّة، رصدت دوريّة من مفرزة استقصاء بيروت في وحدة شرطة بيروت، بتاريخ 21-4-2025 شخصَين يقومان بجرّ درّاجة آليّة من دون لوحات، في محلّة بدارو.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "فور مشاهدتهما لعناصر الدوريّة، لاذ أحدهما بالفرار، فيما تمكّنت العناصر من توقيف المشتبه به الثّاني بعد مطاردته، ويُدعى:", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "ج. أ. (مواليد عام 2004، لبناني)", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وهو من أصحاب السّوابق في جرائم سرقة سيّارات.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "باستماعه، اعترف بإقدامه في اليوم ذاته على سرقة الدّراجة من محلّة مار مخايل، بعد أن قام بخلع مقودها، بالاشتراك مع شخصٍ آخر تولّى قطر الدّرّاجة المسروقة.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "أعيدت الدّرّاجة إلى مالكها، وأودع الموقوف القطعة المعنيّة لإجراء المقتضى القانوني بحقّه، بناءً على إشارة القضاء المختصّ.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "العمل مستمرّ لتوقيف المتورّط الثّاني", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The General Directorate of Internal Security Forces – Public Relations Division issued the following statement:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "As part of the daily follow-up carried out by the Internal Security Forces to limit crimes of various types, especially those related to motorcycle theft, a patrol from the Beirut Investigation Unit in the Beirut Police Unit, on 21-4-2025, spotted two individuals dragging a motorcycle without plates in the Badaro area.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Upon seeing the patrol, one of them fled, while the officers managed to arrest the second suspect after a chase, identified as:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "J.A. (born in 2004, Lebanese)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He has a prior record in car theft crimes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "During questioning, he admitted that on the same day he stole the motorcycle from the Mar Mikhael area after breaking its steering lock, in cooperation with another person who was towing the stolen motorcycle.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The motorcycle was returned to its owner, and the detainee was referred to the concerned unit for legal action against him, based on the direction of the competent judiciary.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Efforts are ongoing to arrest the second suspect", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/site-template-Recovered1x_1jpg_654563-RnRBCPCQfhzfMJ87tA7AZk34Fvj4oT.jpeg', false, false, 184, 699, TIMESTAMP '2026-04-14 09:55:51.308', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'US aircraft carrier changes course… from the Mediterranean to the Arabian Sea via Africa', 'حاملة طائرات أميركية تغيّر مسارها… من المتوسط إلى بحر العرب عبر أفريقيا', 'us-airc-carrier', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أفادت البحرية الأميركية بأن حاملة الطائرات «بوش» تتواجد حالياً قبالة سواحل ناميبيا، في طريقها إلى بحر العرب، ضمن تحرك بحري يعكس تبدلات في الانتشار العسكري الأميركي في المنطقة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مسار بديل لتجنّب البحر الأحمر", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وبحسب الموقع الإعلامي للبحرية الأميركية، نقلًا عن مسؤولين أميركيين، فإن الحاملة ومجموعتها الضاربة تقوم بدورية في أفريقيا، بعدما غادرت مسار البحر الأبيض المتوسط. وأوضح المسؤولون أن السفينة تسلك حالياً طريقًا أطول يلتف حول القارة الأفريقية، متجنبة المرور عبر البحر الأحمر ومضيق باب المندب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشاروا إلى أن هذا القرار يأتي لتفادي المخاطر الأمنية، لا سيما الهجمات الصاروخية التي تشنها حركة «أنصار الله» في اليمن، وفق ما نقلت وكالة «تسنيم» الإيرانية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تصاعد التهديدات في البحر الأحمر", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وكان قائد «أنصار الله»، السيد عبد الملك الحوثي، قد أعلن في وقت سابق أن عمليات الجماعة تتجه نحو التصعيد، مؤكدًا أنها تأتي ضمن خطة مدروسة تأخذ في الاعتبار تطورات الحرب وامتدادها الزمني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبر الحوثي أن من أبرز نتائج هذه العمليات هو منع الولايات المتحدة وإسرائيل من استخدام البحر الأحمر في تنفيذ عمليات عسكرية ضد إيران وحلفائها.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تصعيد أميركي في المقابل", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بالتوازي، دخل تهديد الرئيس الأميركي دونالد ترامب بفرض حصار على جميع السفن المتجهة إلى الموانئ الإيرانية أو الخارجة منها حيّز التنفيذ، صباح أمس بتوقيت الساحل الشرقي للولايات المتحدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأعلن الجيش الأميركي أن الحصار سيُفرض في خليج عُمان وبحر العرب شرق مضيق هرمز، وسيشمل جميع السفن بغض النظر عن الأعلام التي ترفعها.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تطورات بعد فشل المفاوضات", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التحركات في أعقاب إعلان كل من واشنطن وطهران انتهاء المفاوضات التي جرت في العاصمة الباكستانية إسلام آباد، من دون التوصل إلى اتفاق لإنهاء الحرب، ما يعكس تصعيدًا متبادلًا في الميدانين العسكري والسياسي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The US Navy reported that the aircraft carrier Bush is currently off the coast of Namibia, on its way to the Arabian Sea, as part of a naval movement reflecting shifts in US military deployment in the region.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Alternative route to avoid the Red Sea", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "According to the US Navy’s media website, citing US officials, the carrier and its strike group are conducting a patrol in Africa after leaving the Mediterranean route. Officials explained that the ship is currently taking a longer path around the African continent, avoiding passage through the Red Sea and the Bab el-Mandeb Strait.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They noted that this decision comes to avoid security risks, particularly missile attacks launched by Ansar Allah in Yemen, according to Iran’s Tasnim Agency.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Escalating threats in the Red Sea", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The leader of Ansar Allah, Sayyed Abdul Malik al-Houthi, had previously announced that the group’s operations are heading toward escalation, stressing that they come ضمن a studied plan that takes into account developments in the war and its prolonged duration.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Al-Houthi considered that one of the main outcomes of these operations is preventing the United States and Israel from using the Red Sea to carry out military operations against Iran and its allies.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "US escalation in response", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "At the same time, the threat by US President Donald Trump to impose a blockade on all ships heading to or leaving Iranian ports came into effect yesterday morning Eastern Time.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The US military announced that the blockade will be imposed in the Gulf of Oman and the Arabian Sea east of the Strait of Hormuz, and will include all ships regardless of the flags they carry.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Developments after failed negotiations", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "These movements come after both Washington and Tehran announced the end of negotiations held in Islamabad, Pakistan, without reaching an agreement to end the war, reflecting mutual escalation on both the military and political fronts", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2-KnYWNBq7NLr8AOgm5d0cl5zT0h0YWR.jpeg', false, false, 26, 228, TIMESTAMP '2026-04-14 13:08:11.413', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Preventing the return of civilians and ongoing occupation: here is Israel’s plan after the negotiations', 'منع عودة المدنيين واحتلال مستمر: إليكم شروط إسرائيل بعد المفاوضات', 'israel-plans-inleb', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أفادت قناة “الميادين” بأن الشروط الإسرائيلية المطروحة تتضمن تقسيم الأراضي اللبنانية إلى ثلاث مناطق، ضمن خطة تهدف إلى تفكيك حزب الله ونزع سلاحه.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "منطقة عازلة دائمة في الجنوب", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتقضي الشروط بإنشاء منطقة أولى عازلة ودائمة بعمق 8 كيلومترات، يُمنع فيها عودة المدنيين النازحين.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "جنوب الليطاني منطقة عمليات عسكرية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما المنطقة الثانية، فتشمل جنوب نهر الليطاني، على أن تُعتبر منطقة عمليات عسكرية إسرائيلية، حيث يستمر الوجود العسكري الإسرائيلي فيها حتى تحقيق أهدافه.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "شمال الليطاني تحت مسؤولية الجيش اللبناني", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتضم المنطقة الثالثة شمال نهر الليطاني وبقية الأراضي اللبنانية، على أن يتولى الجيش اللبناني فيها مهمة تفكيك حزب الله بشكل مستقل.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "شرط أساسي: لا انسحاب قبل “القضاء على حزب الله”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب ما نقلته “الميادين”، فإن الشرط الأساسي يتمثل في عدم انسحاب إسرائيل بشكل كامل قبل ما تصفه بـ”القضاء على حزب الله”", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Al Mayadeen reported that the proposed Israeli conditions include dividing Lebanese territory into three areas, as part of a plan aimed at dismantling Hezbollah and disarming it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A permanent buffer zone in the south", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The conditions stipulate the creation of a first permanent buffer zone with a depth of 8 kilometers, where the return of displaced civilians is prohibited.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "South of the Litani as a military operations zone", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The second area includes south of the Litani River, to be considered an Israeli military operations zone, where Israeli military presence continues until its objectives are achieved.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "North of the Litani under Lebanese Army responsibility", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The third area includes north of the Litani River and the rest of Lebanese territory, where the Lebanese Army would be tasked with dismantling Hezbollah independently.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Key condition: no withdrawal before eliminating Hezbollah", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Al Mayadeen, the main condition is that Israel will not fully withdraw before what it describes as the elimination of Hezbollah", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/USA-ISRAEL--1_1776181691345_1776181701081-AopLOmISK0hzJBUWjDm7poFuzgjuJO.JPG', false, false, 1331, 2813, TIMESTAMP '2026-04-14 18:20:40.775', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Stifling heat, dust, and muddy rain… this is what awaits Lebanon in the coming hours', 'حرّ خانق وغبار وأمطار موحلة… هذا ما ينتظر لبنان في الساعات المقبلة', 'leb-dusty-weather', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "توقّعت دائرة التقديرات في مصلحة الأرصاد الجوية أن يتأثر لبنان والحوض الشرقي للمتوسط بكتل هوائية دافئة محمّلة بالغبار مصدرها مصر، ما يؤدي إلى ارتفاع ملحوظ بدرجات الحرارة لتتخطى معدلاتها الموسمية، على أن يبلغ تأثيرها ذروته يوم الخميس، خصوصًا على الساحل الجنوبي حيث قد تتجاوز الحرارة 30 درجة وسط أجواء عابقة ومغبرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت إلى أن هذه الموجة تبدأ بالانحسار اعتبارًا من ظهر يوم الجمعة، مع تأثر المنطقة بمنخفض جوي يتمركز شمالًا ويقترب تدريجيًا، ما يؤدي إلى طقس متقلب يترافق مع أمطار موحلة وانخفاض ملحوظ بدرجات الحرارة، لتعود إلى معدلاتها الموسمية، على أن يستمر تأثيره حتى ظهر الاثنين قبل عودة الاستقرار.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الأربعاء: غبار ورياح ناشطة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يكون الطقس غائمًا جزئيًا إلى غائم بسحب مرتفعة، مع انخفاض في نسبة الرطوبة وارتفاع ملموس بدرجات الحرارة يتجاوز المعدلات الموسمية بنحو 5 درجات. كما تنشط الرياح لتصل سرعتها إلى نحو 55 كم/س، وتكون محمّلة بطبقات من الغبار تؤدي إلى سوء في الرؤية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الخميس: ذروة الحرارة وأجواء خانقة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يكون الطقس غائمًا بسحب مرتفعة وأجواء عابقة ومغبرة، مع رياح ناشطة تصل سرعتها إلى 55 كم/س، وارتفاع إضافي بدرجات الحرارة التي تتخطى 30 درجة على الساحل. ومع ساعات بعد الظهر، تتكاثف الغيوم وتتساقط أمطار متفرقة موحلة، خاصة في المناطق الداخلية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الجمعة: بداية الانخفاض وأمطار رعدية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يكون الطقس غائمًا جزئيًا إلى غائم بسحب متوسطة، مع بقاء الحرارة مرتفعة خلال النهار، قبل أن تبدأ بالانخفاض التدريجي اعتبارًا من بعد الظهر. ترتفع نسبة الرطوبة وتستمر الأجواء المغبرة، مع تشكّل الضباب على المرتفعات وتساقط أمطار موحلة متفرقة، قد تترافق مع برق ورعد ورياح ناشطة تصل أحيانًا إلى 70 كم/س، ما يؤدي إلى ارتفاع موج البحر.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "السبت: انخفاض ملحوظ واستقرار تدريجي", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يكون الطقس غائمًا جزئيًا إلى غائم أحيانًا، مع انخفاض ملحوظ بدرجات الحرارة وعودتها إلى معدلاتها الموسمية. يتكوّن الضباب على المرتفعات، وتتساقط أمطار متفرقة صباحًا مع احتمال حدوث برق ورعد، قبل أن تخف حدتها بعد الظهر مع انفراجات واسعة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "معطيات عامة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "تهب الرياح السطحية شمالية شرقية بسرعة تتراوح بين 10 و35 كم/س، تنشط بعد الظهر لتصل إلى 55 كم/س خصوصًا في جنوب البلاد. يكون الانقشاع متوسطًا ويسوء أحيانًا بسبب الغبار، فيما تتراوح نسبة الرطوبة على الساحل بين 30 و55%. أما البحر فمتوسط ارتفاع الموج، وحرارة سطح المياه تبلغ 19 درجة مئوية، والضغط الجوي 1015 هكتوباسكال", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Forecasting Department at the Meteorological Service expected Lebanon and the eastern Mediterranean basin to be affected by warm air masses loaded with dust coming from Egypt, leading to a noticeable rise in temperatures exceeding seasonal averages, with the peak expected on Thursday, especially along the southern coast where temperatures may exceed 30 degrees amid hazy and dusty conditions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It indicated that this wave will begin to recede starting Friday afternoon, as the region becomes affected by a low-pressure system centered to the north and gradually approaching, leading to unstable weather accompanied by muddy rain and a noticeable drop in temperatures, returning to seasonal averages, with its impact continuing until Monday afternoon before stability returns.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Wednesday: dust and active winds", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather will be partly cloudy to cloudy with high clouds, with a decrease in humidity and a noticeable rise in temperatures exceeding seasonal averages by about 5 degrees. Winds will become active, reaching speeds of around 55 km/h, carrying layers of dust that will reduce visibility.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Thursday: peak heat and stifling conditions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather will be cloudy with high clouds and hazy, dusty conditions, with active winds reaching 55 km/h, and a further rise in temperatures exceeding 30 degrees along the coast. In the afternoon, clouds will thicken and scattered muddy rain will fall, especially in inland areas.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Friday: beginning of the drop and thunderstorms", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather will be partly cloudy to cloudy with medium clouds, with temperatures remaining high during the day before gradually decreasing starting in the afternoon. Humidity will rise and dusty conditions will persist, with fog forming over the highlands and scattered muddy rain falling, possibly accompanied by thunder and lightning, and active winds that may reach 70 km/h, leading to higher sea waves.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Saturday: noticeable drop and gradual stability", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather will be partly cloudy to occasionally cloudy, with a noticeable drop in temperatures returning to seasonal averages. Fog will form over the highlands, and scattered rain will fall in the morning with a possibility of thunder and lightning, before easing in the afternoon with wide clear intervals.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "General conditions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Surface winds will be northwesterly to northeasterly, ranging between 10 and 35 km/h, becoming active in the afternoon and reaching 55 km/h, especially in the south. Visibility will be moderate, sometimes worsening due to dust, while humidity along the coast will range between 30 and 55%. The sea will have moderate waves, with a surface water temperature of 19 degrees Celsius, and atmospheric pressure at 1015 hectopascals", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-924895-639118298537269722-hcLfBFG3VOFHYfZqWbUjBvC9qsyHHw.jpg', false, false, 92, 408, TIMESTAMP '2026-04-15 08:59:52.542', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Stopping the Israeli war on Lebanon: a binding Iranian condition… not a request', 'وقف الحرب الإسرائيلية على لبنان: شرط إيراني مُلزِم... وليس طلباً', 'iran-stop-lebwar', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "جاء في الاخبار:", "type": "text", "marks": [{"type": "bold"}]}, {"type": "hardBreak", "marks": [{"type": "bold"}]}, {"text": "في مقابل جنوح لبنان الرسمي نحو فصل المسارات، وسعي تل أبيب إلى فرض إرادتها على بيروت، تتمسّك طهران بربط تفاوضها مع واشنطن بوقف العدوان الإسرائيلي على الجبهة اللبنانية", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "تنظر الأوساط السياسية الإسرائيلية إلى انخراط الحكومة اللبنانية في التفاوض المباشر كخطوة إيجابية ومحاولة لفك ارتباطها بحزب الله، وفصل الملف اللبناني عن المفاوضات الأميركية - الإيرانية في باكستان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفيما تصرّ تل أبيب على عدم شمول لبنان بالهدنة الإقليمية، تنظر طهران إلى الموقف اللبناني الرسمي، على أنه عقدة ساهمت في عدم التوصل إلى اتفاق في إسلام آباد، السبت الفائت. وتؤكد مصادر دبلوماسية إيرانية واكبت المفاوضات في العاصمة الباكستانية، لـ«الأخبار»، أن «إيران بما تملكه من أوراق قوة، قادرة على الإسهام في تهيئة الظروف اللازمة لفرض وقف شامل لإطلاق النار في المنطقة، وعلى رأسها لبنان». وتشير إلى الموقف الثابت لإيران الذي تُرجم في اتفاقية وقف إطلاق النار بين إيران والولايات المتحدة، والذي يؤكد وجوب أن يتوقف العدوان الإسرائيلي على لبنان. وهو ما ورد أيضاً في بيان رئيس الوزراء الباكستاني شهباز شريف، قبل أن تنتهك إسرائيل الاتفاقية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتكشف المصادر عن ضغوطات تعرّض لها الوفد الإيراني المفاوض في إسلام آباد من قبل الباكستانيين والأميركيين، الذي كانوا يواجهون إصرار الوفد الإيراني على عدم الانخراط في مفاوضات مع الولايات المتحدة إلا بعد وقف الهجمات الإسرائيلية على لبنان. وتشير إلى طرح أسئلة على الوفد الايراني «حول سبب الإصرار على هذا الموقف، بينما تنخرط الحكومة اللبنانية نفسها في مفاوضات مع الكيان، رغم عدم وجود وقف لإطلاق النار بينهما». وتلفت إلى أنه «بناءً على المصالح القائمة والوعود الأميركية بخفض الهجمات على لبنان، ولا سيما على بيروت، كان هناك فتح لمسار آخر من قبل الحكومة اللبنانية، وهو ما دفع إيران إلى المشاركة في مفاوضات إسلام آباد».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "مع ذلك، تؤكد المصادر أن «طهران لن تتراجع عن موقفها؛ فلا يمكن الحديث عن اتفاقية لحل المشكلات أو وقف الهجمات مع الولايات المتحدة في ظل استمرار الاعتداءات على الجبهة اللبنانية. وهذا يعني أن أي اتفاقية محتملة لن تكون مستقرة أو مستمرة؛ لذا يجب وقف كلّ الهجمات والعدوان الإسرائيلي في المنطقة».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتوضح المصادر أن «وقف إطلاق النار في لبنان هو شرط من الشروط وليس طلباً»، بمعنى أنه لا يمكن عقد جولة أخرى من المفاوضات مع الطرف الأميركي من دونه، فـ«إمّا أن يأخذ الأميركيون بالشروط الإيرانية كلها كسلة واحدة، وإمّا سيؤدي رفض أحدها إلى معنى واحد، وهو رفض الكل»، كاشفة وجود «تبادل للرسائل حالياً بين واشنطن وطهران».", "type": "text"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "الموقف اللبناني المسارع إلى فتح قنوات تفاوض مباشرة مع إسرائيل شكّل إحدى العقد الأساسية التي أدّت إلى فشل مفاوضات إسلام آباد", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "paragraph", "content": [{"text": "وفي الوقت نفسه، واستكمالاً إلى خط الاتصال الذي كان مفتوحاً بين المفاوض الإيراني في باكستان وقيادة حزب الله في لبنان، تؤكد المصادر نفسها استمرار هذا التواصل بين طهران والضاحية الجنوبية لبيروت لـ«تبادل المستجدات الميدانية وتنسيق الخطوات الدبلوماسية».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب المصادر نفسها، تلقّى الإيرانيون ردوداً على رسائلهم المتبادلة مع الأميركيين، في جزئها المتعلّق بلبنان «تتضمن في معظمها إحالات أميركية إلى نواف سلام بوصفه رئيس حكومة لبنان الذي يصرّ على فتح مسار تفاوضي مع إسرائيل منفصل عن السياق الأميركي - الإيراني في باكستان».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في هذا الوقت، سُجّل تواصل إيراني - سعودي إيجابي حول لبنان، فُهم منه أن الرياض «لديها محاذير واضحة، فهي لا تريد أن تذهب الدولة اللبنانية منفردة إلى التطبيع مع إسرائيل بمعزل عن المسار الذي ترعاه السعودية، وفي نفس الوقت لا تريد انهيار حكومة سلام». لذا، عملت الرياض في الأيام القليلة الماضية، عبر تواصلها مع العديد من القوى السياسية في لبنان، على رسم «سقوف محدّدة للخلاف اللبناني - اللبناني، بما لا يؤدي إلى تجاوز تلك المحاذير».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "يبدو واضحاً بالنسبة إلى طهران سعي رئيس الحكومة الإسرائيلية بنيامين نتنياهو الدؤوب إلى إفشال مفاوضات باكستان. ومن هذه الزاوية، يُعمل على فصل الملف اللبناني عن أي اتفاق محتمل بين إيران والولايات المتحدة، للاستفراد بلبنان تمهيداً لتحقيق مكاسب سياسية وميدانية كبيرة. لكنّ المصادر الإيرانية تُعيد وتؤكد أن «طهران مصرّة، وهي قادرة على تهيئة الظروف اللازمة لتحقيق وقفٍ شامل لإطلاق النار في المنطقة، ومن ضمنها لبنان».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بقلم حمزة الخنسا", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Al Akhbar reported:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In contrast to Lebanon’s official tendency toward separating tracks, and Tel Aviv’s efforts to impose its will on Beirut, Tehran insists on linking its negotiations with Washington to stopping the Israeli aggression on the Lebanese front.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli political circles view the Lebanese government’s engagement in direct negotiations as a positive step and an attempt to detach itself from Hezbollah, and to separate the Lebanese file from the US-Iranian negotiations in Pakistan.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "While Tel Aviv insists on excluding Lebanon from the regional truce, Tehran considers the official Lebanese position to be an obstacle that contributed to the failure to reach an agreement in Islamabad last Saturday. Iranian diplomatic sources that followed the negotiations in the Pakistani capital told Al Akhbar that 'Iran, with the leverage it possesses, is capable of helping create the necessary conditions to impose a comprehensive ceasefire in the region, foremost in Lebanon'. They pointed to Iran’s firm position, which was reflected in the ceasefire agreement between Iran and the United States, affirming that Israeli aggression on Lebanon must stop. This was also mentioned in the statement of Pakistani Prime Minister Shehbaz Sharif before Israel violated the agreement.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The sources reveal that the Iranian negotiating delegation in Islamabad was subjected to pressure from both Pakistani and American sides, who were confronted with the Iranian delegation’s insistence on not engaging in negotiations with the United States unless Israeli attacks on Lebanon were halted. They noted that questions were raised to the Iranian delegation about the reason for this insistence, while the Lebanese government itself was engaging in negotiations with the entity despite the absence of a ceasefire between them. They added that based on existing interests and American promises to reduce attacks on Lebanon, particularly on Beirut, another track was opened by the Lebanese government, which prompted Iran to participate in the Islamabad negotiations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nevertheless, the sources stressed that 'Tehran will not retreat from its position; it is not possible to speak of an agreement to resolve issues or stop attacks with the United States while assaults on the Lebanese front continue. This means that any potential agreement will not be stable or lasting; therefore all attacks and Israeli aggression in the region must stop'.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The sources clarified that 'a ceasefire in Lebanon is a condition, not a request', meaning that no new round of negotiations with the American side can be held without it, as 'either the Americans accept all Iranian conditions as a single package, or rejecting any one of them means rejecting all', revealing that 'messages are currently being exchanged between Washington and Tehran'.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Lebanese position, rushing to open direct negotiation channels with Israel, constituted one of the main obstacles that led to the failure of the Islamabad negotiations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, continuing the line of communication that was open between the Iranian negotiator in Pakistan and Hezbollah’s leadership in Lebanon, the same sources confirmed the continuation of this contact between Tehran and the southern suburbs of Beirut to exchange field developments and coordinate diplomatic steps.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the same sources, the Iranians received responses to their exchanged messages with the Americans regarding Lebanon, most of which included American references to Nawaf Salam as Lebanon’s Prime Minister, who insists on opening a negotiation track with Israel separate from the US-Iranian context in Pakistan.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, positive Iranian-Saudi communication regarding Lebanon was recorded, from which it was understood that Riyadh has clear reservations, as it does not want the Lebanese state to move alone toward normalization with Israel outside the path sponsored by Saudi Arabia, and at the same time does not want the collapse of Salam’s government. Therefore, in recent days, Riyadh has worked, through its communication with various political forces in Lebanon, to set specific limits to Lebanese internal disagreements in a way that does not cross those reservations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It appears clear to Tehran that Israeli Prime Minister Benjamin Netanyahu is persistently seeking to undermine the Pakistan negotiations. From this perspective, efforts are being made to separate the Lebanese file from any potential agreement between Iran and the United States, in order to single out Lebanon in preparation for achieving significant political and field gains. However, Iranian sources reiterate that 'Tehran is determined, and it is capable of creating the necessary conditions to achieve a comprehensive ceasefire in the region, including Lebanon'.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By Hamza Al Khansa", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2-ZTI9jlQ7a6CaVFypKCo1D80gyu1Q0n.jpg', false, false, 355, 1371, TIMESTAMP '2026-04-15 12:55:52.449', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Foreign Press Accuses Israeli Army of Fabricating Image to Justify Targeting Journalist Ali Shoeib', 'الصحافة الأجنبية تتهم الجيش الإسرائيلي بفبركة صورة لتبرير استهداف الصحافي علي شعيب', 'ali-shoaib', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "اتهمت ", "type": "text"}, {"text": "رابطة الصحافة الأجنبية", "type": "text", "marks": [{"type": "bold"}]}, {"text": " الجيش الإسرائيلي بنشر ", "type": "text"}, {"text": "صورة مفبركة باستخدام الذكاء الاصطناعي", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لتبرير استهداف الصحافي اللبناني ", "type": "text"}, {"text": "علي شعيب", "type": "text", "marks": [{"type": "bold"}]}, {"text": " خلال غارة في جنوب لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ما الذي حدث:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• في ", "type": "text"}, {"text": "28 آذار", "type": "text", "marks": [{"type": "bold"}]}, {"text": " استهدفت غارة إسرائيلية الصحافي ", "type": "text"}, {"text": "علي شعيب", "type": "text", "marks": [{"type": "bold"}]}, {"text": " مراسل قناة المنار.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الغارة أصابت أيضًا ", "type": "text"}, {"text": "مراسلة من قناة الميادين ومصورًا صحافيًا", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الرواية الإسرائيلية:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• الجيش الإسرائيلي قال إن شعيب كان ", "type": "text"}, {"text": "عنصرًا في قوة الرضوان التابعة لحزب الله", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• وزعم أنه كان يعمل ", "type": "text"}, {"text": "متخفيًا بصفة صحافي", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ويكشف مواقع الجيش الإسرائيلي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الجدل حول الصورة:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• الجيش نشر صورة على منصة ", "type": "text"}, {"text": "إكس (تويتر سابقًا)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " تُظهر شعيب بزي عسكري فوق سترة صحافة.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• لاحقًا أقر المتحدث باسم الجيش ", "type": "text"}, {"text": "نداف شوشاني", "type": "text", "marks": [{"type": "bold"}]}, {"text": " بأن الصورة كانت ", "type": "text"}, {"text": "\"معدّلة\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "انتقادات الصحافة الأجنبية:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• رابطة الصحافة الأجنبية قالت إن الصورة كانت ", "type": "text"}, {"text": "مزيفة وتشوه سمعة الصحافي", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• وأضافت أنه خلال الحروب الأخيرة أصبح من الشائع ", "type": "text"}, {"text": "تشويه سمعة الصحافيين ونشر ادعاءات دون أدلة واضحة", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "السياق الأوسع:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• منظمات إعلامية حذرت من ", "type": "text"}, {"text": "تزايد المخاطر على الصحافيين", "type": "text", "marks": [{"type": "bold"}]}, {"text": " خلال تغطية الحرب في لبنان.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• كما أثارت الحادثة ", "type": "text"}, {"text": "مخاوف بشأن استخدام المعلومات المضللة لتبرير استهداف الصحافيين", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المصدر: الجديد", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Foreign Press Association", "type": "text", "marks": [{"type": "bold"}]}, {"text": " has accused the Israeli military of publishing a ", "type": "text"}, {"text": "fabricated image generated with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to justify the targeting of Lebanese journalist ", "type": "text"}, {"text": "Ali Shoeib", "type": "text", "marks": [{"type": "bold"}]}, {"text": " during a strike in southern Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What happened:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• On ", "type": "text"}, {"text": "March 28", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", an Israeli strike targeted ", "type": "text"}, {"text": "Ali Shoeib", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a correspondent for Al-Manar TV.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• The attack also injured ", "type": "text"}, {"text": "a reporter from Al-Mayadeen and a press cameraman", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israel’s claim:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• The Israeli military said Shoeib was ", "type": "text"}, {"text": "a member of Hezbollah’s Radwan Force", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• It alleged he was ", "type": "text"}, {"text": "operating under the cover of journalism", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to expose Israeli army positions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Controversy over the image:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• The Israeli army published a photo on ", "type": "text"}, {"text": "X (formerly Twitter)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " showing Shoeib wearing a ", "type": "text"}, {"text": "military uniform under a press vest", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Later, Israeli military spokesperson ", "type": "text"}, {"text": "Nadav Shoshani", "type": "text", "marks": [{"type": "bold"}]}, {"text": " acknowledged the image was ", "type": "text"}, {"text": "“edited.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Criticism from foreign press groups:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• The Foreign Press Association said the image was ", "type": "text"}, {"text": "misleading and damages the journalist’s reputation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• It added that during recent conflicts it has become common to ", "type": "text"}, {"text": "discredit journalists by spreading claims without clear evidence", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The bigger picture:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• Media organizations warn of ", "type": "text"}, {"text": "growing risks for journalists", "type": "text", "marks": [{"type": "bold"}]}, {"text": " covering the war in Lebanon.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• The incident has raised concerns about ", "type": "text"}, {"text": "misinformation being used to justify attacks on journalists", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Source: Al Jadeed", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/6006f546be1b4c7306a1c9c25e7175d8-fAq17k4MyI8N9xH0OFJn0uNqIHDw9j', false, false, 44, 243, TIMESTAMP '2026-04-15 15:14:55.399', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Iran raises the level of confrontation: We will leave no one alive in any ground attack', 'ايران ترفع سقف المواجهة: لن نُبقي أحدًا حيًا في أي هجوم برّي', 'new-iran-threat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في تصعيد عسكري لافت، أعلن المتحدث باسم الجيش الإيراني محمد أكرمي نيا أن القائد العام للجيش أمير حاتمي أصدر أوامر واضحة تقضي بأنه “في حال حدوث أي عدوان بري، يجب ألا يبقى أحد من المعتدين على قيد الحياة”، في موقف يعكس رفع سقف التهديد في المواجهة مع الولايات المتحدة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "استهداف طائرة أميركية جنوب أصفهان", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي التفاصيل الميدانية، أوضح أكرمي نيا أن القوات الإيرانية استهدفت طائرة أميركية من طراز “C-130” بصاروخ محمول على الكتف خلال عملية تسلل جنوب أصفهان، ما أدى إلى إحباط المهمة واضطرار القوات الأميركية إلى الانسحاب من المنطقة. وأشار إلى سقوط عدد من الشهداء خلال التصدي لمحاولة التسلل، من دون تحديد حصيلة دقيقة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "ردّ على الحصار البحري الأميركي", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي سياق متصل، شدد قائد مقر “خاتم الأنبياء” علي عبد اللهي على أن إيران ستتخذ خطوات “حازمة وقوية” للدفاع عن مصالحها الوطنية وسيادتها، وذلك على خلفية إعلان الولايات المتحدة فرض حصار على حركة الملاحة البحرية المرتبطة بالموانئ الإيرانية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تهديد بتوسيع المواجهة البحرية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "واعتبر عبد اللهي أن استمرار ما وصفه بـ“الإجراءات غير القانونية” من جانب واشنطن، سواء عبر الحصار البحري أو خلق حالة من انعدام الأمن للسفن التجارية وناقلات النفط الإيرانية، يشكل مقدمة لانتهاك وقف إطلاق النار. وأكد أن القوات المسلحة الإيرانية لن تسمح باستمرار أي نوع من الصادرات أو الواردات في منطقة الخليج وبحر عُمان والبحر الأحمر في حال استمرار الحصار الأميركي.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تصعيد متسارع ومخاوف من التوسع", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التطورات في ظل تصعيد متسارع بين واشنطن وطهران، حيث تتداخل المواجهة العسكرية مع الضغوط البحرية والاقتصادية، وسط مخاوف متزايدة من توسع نطاق الاشتباك في المنطقة وامتداده إلى الممرات الحيوية للطاقة والتجارة العالمية", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "In a notable military escalation, Iranian army spokesperson Mohammad Akrami Nia announced that the Commander-in-Chief of the army, Amir Hatami, issued clear orders stating that 'in the event of any ground aggression, none of the attackers should be left alive', in a stance reflecting a raised level of threat in the confrontation with the United States.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Targeting a US aircraft south of Isfahan", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In field details, Akrami Nia explained that Iranian forces targeted a US C-130 aircraft with a shoulder-fired missile during an infiltration operation south of Isfahan, which led to thwarting the mission and forcing US forces to withdraw from the area. He pointed to the fall of a number of martyrs during the response to the infiltration attempt, without specifying an exact toll.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Response to the US naval blockade", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a related context, the commander of the Khatam al-Anbiya Headquarters, Ali Abdollahi, stressed that Iran will take 'decisive and strong' steps to defend its national interests and sovereignty, following the United States announcing a blockade on maritime traffic linked to Iranian ports.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Threat to expand the naval confrontation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Abdollahi considered that the continuation of what he described as 'illegal measures' by Washington, whether through the naval blockade or creating a state of insecurity for Iranian commercial ships and oil tankers, constitutes a prelude to violating the ceasefire. He affirmed that the Iranian armed forces will not allow the continuation of any type of exports or imports in the Gulf, the Sea of Oman, and the Red Sea if the US blockade continues.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Rapid escalation and fears of expansion", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These developments come amid a rapid escalation between Washington and Tehran, where military confrontation overlaps with maritime and economic pressure, amid growing fears of an expansion of the conflict in the region and its extension to vital routes for global energy and trade.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/im-88861666-zLubCUxvFggG5xasa9Ia1tiIBA7qPE', false, false, 40, 331, TIMESTAMP '2026-04-16 09:10:52.937', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A major deal in Lebanon: CMA CGM acquires the Fattal Group', 'صفقة ضخمة في لبنان: CMA CGM تستحوذ على مجموعة فتّال بالكامل', 'cgm-fattal-acquisition', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت مجموعة «CMA CGM» أنها توصّلت إلى اتفاق مع مساهمي مجموعة فتّال يقضي باستحواذها عبر شركاتها التابعة، على 100% من أسهم مجموعة فتّال، على أن يخضع إتمام هذه الصفقة، إلى صدور الموافقات التنظيمية. ويتوقع أن يتم ذلك خلال الربع الثالث من عام 2026.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "رغم امتلاك «فتال» تلك «الإمبراطورية»، إلا أن الشركة كانت تعاني من مشكلات مفرطة بين المالكين، وهو ما دفعهم أكثر من مرّة إلى البحث عن شارٍ لفضّ هذه الشراكة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب المعطيات المتداولة في السوق، فإن الاتفاق تم على قاعدة 9 أضعاف مقياس الـEBITDA الذي يحتسب على أساس صافي الأرباح قبل حسم الفوائد والضرائب والإستهلاكات والدين. وبذلك، يتوقع ألا تتجاوز قيمة الصفقة مبلغ 500 مليون دولار، في مقابل حصول الشاري على شبكة ومخزون الشركة في لبنان والخارج بنسبة 100%.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكان أحد الشروط الأساسية لتحقق الصفقة هي الاستحواذ الكامل، إذ اشارت بعض المعطيات إلى أن بعض الشركاء في لبنان والخارج كانوا يمانعون أو يفضلون البقاء ضمن الشركة، لكن «CMA CGM» المملوكة من رودولف سعادة لا يناسبها أن يبقى شركاء بينما هو يسعى إلى بناء امبراطورية تبدأ بكونه يملك ثالث أكبر شركة شحن بحري وتمتد إلى مجموعة ملكيات في عالم التوصيل والتجزئة في لبنان وأوروبا، فضلاً عن استثمارات إعلامية أيضاً ورغبات بالتوسّع في الشرق الأوسط.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "وتملك «مجموعة فتال» عدداً من العقارات في نهر بيروت وسن الفيل من بينها مقرّ الشركة بالإضافة إلى عدد من المستودعات، وهي كانت أمراً أساسياً أُخذ في الحسبان عند تنفيذ عملية التخمين الأوّلية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولدى «فتال» حجم عمليات ضخم يعكس حصّة سوقية في لبنان تتجاوز 30% من مجموع مبيعات السلع الاستهلاكية والمنزلية والعناية الشخصية، بالإضافة إلى انتشار خارجي في شمال أفريقيا وأجزاء من أوروبا والإمارات العربية المتحدة وفرنسا والعراق والأردن ومصر وقبرص والجزائر.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "المصدر: الاخبار", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "CMA CGM Group announced that it has reached an agreement with the shareholders of the Fattal Group to acquire, through its subsidiaries, 100% of the shares of the Fattal Group, with the completion of the deal subject to obtaining regulatory approvals. The transaction is expected to be finalized in the third quarter of 2026.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite Fattal owning this empire, the company was suffering from excessive disputes among its owners, which pushed them more than once to seek a buyer to dissolve this partnership", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to market information, the agreement was based on a valuation of 9 times EBITDA, calculated on the basis of net profits before interest, taxes, depreciation, and debt. Accordingly, the value of the deal is expected not to exceed $500 million, in exchange for the buyer acquiring 100% of the company’s network and inventory in Lebanon and abroad.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "One of the key conditions for completing the deal was full acquisition, as some information indicated that certain partners in Lebanon and abroad preferred to remain within the company, but CMA CGM, owned by Rodolphe Saadé, does not favor maintaining partners while it seeks to build an empire that begins with owning the world’s third-largest maritime shipping company and extends to holdings in the delivery and retail sectors in Lebanon and Europe, in addition to media investments and ambitions to expand in the Middle East.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Fattal Group owns a number of real estate assets in Nahr Beirut and Sin El Fil, including the company’s headquarters and several warehouses, which were a key factor taken into account during the initial valuation process.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Fattal also has a large scale of operations, reflecting a market share in Lebanon exceeding 30% of total sales in consumer goods, household products, and personal care, in addition to an external presence in North Africa and parts of Europe, the United Arab Emirates, France, Iraq, Jordan, Egypt, Cyprus, and Algeria.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Source: Al Akhbar", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/https%253A%252F%252Fphotos.watchmedier-FS5CYDXieVEbxoa3i6BrZCP1wRa5Dj.dk%252FImages%252F19170359%252Flnjto2%252FALTERNATES%252Fschema-16_9%252Fusa-transport', false, false, 146, 489, TIMESTAMP '2026-04-16 09:59:36.882', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'General Security warns of a suspicious page on Facebook', 'الأمن العام ينبّه من صفحة مشبوهة على فيسبوك', 'sus-pg-fb', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "حذّرت المديرية العامة للأمن العام في بيان، المواطنين من التفاعل مع صفحة مشبوهة على “فيسبوك” تحمل اسم CSTO والتي كان اسمها سابقاً FGIH قبل تاريخ 20/12/2020", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما طلبت من المواطنين عدم التفاعل مع هذه الصفحة أو تزويدها بأي معلومات شخصية، تجنباً للوقوع في فخ التجنيد الإلكتروني المشبوه", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The General Directorate of General Security warned in a statement citizens against interacting with a suspicious page on Facebook named CSTO, which was previously called FGIH before the date 20/12/2020", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It also asked citizens not to interact with this page or provide it with any personal information, in order to avoid falling into the trap of suspicious online recruitment", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/facebook-lCEDNhoVZ0flCYPOe2ioEniQyaGBDB.jpg', false, false, 143, 495, TIMESTAMP '2026-04-16 12:41:03.302', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A statement by President Berri on the developments of the ceasefire', 'بيان للرئيس بري عن مستجدات وقف إطلاق النار', 'berri-ceasfire-stat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رئيس مجلس النواب نبيه بري:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ـ يا أهلنا الأعزاء يا من حملتم الجنوب والبقاع والضاحية في قلوبكم وأنتم تغادرون الأرض المباركة والذين كتب أبناؤكم بالدم والتضحيات سيرة الصمود والإباء والانتماء الوطني يامن تشتعل فيكم لهفة العودة إلى البلدات والقرى، كما كنتم على الدوام في الاستحقاقات الصعبة، نعرف وجع الشوق ومرارة الانتظار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ـ  لهذا نخاطبكم بأن الحفاظ على السلامة والأرواح من أولى الواجبات وهو أصدق وفاء للأرض، نتمنى على الجميع التريث في الانتقال إلى البلدات والقرى حتى تتضح الأمور والمجريات وفقا لإتفاق وقف إطلاق النار", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Speaker of Parliament Nabih Berri:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "'Our dear people, you who carried the south, the Bekaa, and the southern suburbs in your hearts as you left the blessed land, and whose sons wrote with blood and sacrifices a history of resilience, pride, and national belonging, you whose longing to return to towns and villages burns within you, as you have always been in difficult times, we know the pain of longing and the bitterness of waiting.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For this, we address you that preserving safety and lives is among the foremost duties and the truest loyalty to the land. We ask everyone to remain patient in returning to towns and villages until matters and developments become clear according to the ceasefire agreement.'", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/GettyImages-1636798873-m1a0G4GTgaRh8LUnTIZ8PinLbHprdK.jpg', false, false, 378, 1064, TIMESTAMP '2026-04-16 17:33:59.082', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Hours before the truce… resistance operations ignite the front from the south to the Israeli depth', 'قبل الهدنة بساعات... عمليات المقاومة تشعل الجبهة من الجنوب إلى العمق الإسرائيلي', 'hezb-stat16april', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "شهد يوم 16 نيسان 2026، في الساعات الأخيرة التي سبقت دخول وقف إطلاق النار حيّز التنفيذ، تصعيدًا غير مسبوق في وتيرة عمليات المقاومة الإسلامية، التي أعلنت تنفيذ أكثر من 50 عملية عسكرية خلال أقل من 24 ساعة، توزعت بين قصف صاروخي مكثف، هجمات بالمسيّرات، استهداف آليات ودبابات، واشتباكات مباشرة على خطوط التماس.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "العمليات تركّزت بشكل أساسي في الجنوب اللبناني، ولا سيما في بنت جبيل، القنطرة، الخيام، الطيبة، والعديسة، بالتوازي مع استهدافات طالت عمق الأراضي الفلسطينية المحتلة، من نهاريا وعكا إلى كريات شمونة والجولان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في بنت جبيل، شكّلت المدينة محورًا أساسيًا للاشتباك، حيث استهدفت المقاومة تجمعات للجنود والآليات في عدة نقاط داخلها ومحيطها عبر ضربات صاروخية متتالية توزعت على أكثر من موقع، بالتزامن مع استهداف دبابات “ميركافا” في محيطها. كما تجدد القصف في الساعات الأخيرة من الليل، مستهدفًا محيط مدرسة الإشراق ومجمع موسى عباس ومثلث التحرير.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما في القنطرة، فبرزت كأكثر الجبهات اشتعالًا، إذ نُفذ فيها عدد كبير من العمليات تجاوز العشرة، تنوعت بين قصف صاروخي ومدفعي واستهدافات دقيقة للآليات. وشهدت المنطقة اشتباكات مباشرة مع قوة إسرائيلية حاولت التقدم، أسفرت بحسب البيانات عن تدمير أربع دبابات وناقلتي جند، إلى جانب استهداف آليات أخرى بصواريخ موجهة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي تفاصيل استهداف دبابات “ميركافا”، أعلنت المقاومة تدمير:", "type": "text"}, {"type": "hardBreak"}, {"text": "دبابة واحدة عند الأطراف الشمالية الشرقية لمدينة بنت جبيل،", "type": "text"}, {"type": "hardBreak"}, {"text": "ودبابة ثانية في محيط سوق بنت جبيل،", "type": "text"}, {"type": "hardBreak"}, {"text": "وثالثة في بلدة البيّاضة حيث شوهدت تحترق،", "type": "text"}, {"type": "hardBreak"}, {"text": "إضافة إلى دبابتين عند مرتفع الصلعة في بلدة القنطرة،", "type": "text"}, {"type": "hardBreak"}, {"text": "ليصل مجموع الدبابات المستهدفة إلى خمس دبابات خلال هذه العمليات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما امتدت الضربات إلى مناطق متعددة، حيث استهدفت تجمعات للجنود والآليات في الخيام، الطيبة، رب ثلاثين، العديسة، ومحيط معتقل الخيام، إضافة إلى مرابض مدفعية بين العديسة ورب ثلاثين، ومواقع أخرى على طول الجبهة، مع تسجيل قصف متأخر استهدف جنوب الخيام والطيبة والبيّاضة في الدقائق الأخيرة قبل الهدنة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي موازاة ذلك، كثّفت المقاومة هجماتها على المواقع العسكرية والمستوطنات في العمق، مستهدفة كريات شمونة، شلومي، يعرا، نهاريا، كفرجلعادي، كرمئيل، بكيعين، ومسغاف عام، إضافة إلى قواعد عسكرية بارزة، منها قاعدة “شراغا” مقر قيادة لواء غولاني، وثكنة ليمان، ومدرسة ضباط البحرية في خليج عكا، وموقع رأس الناقورة الذي استُهدف أكثر من مرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما استخدمت المقاومة بشكل واسع الطائرات المسيّرة الانقضاضية، مستهدفة مواقع عدة بينها حانيتا، المالكية، رأس الناقورة، قاعدة لوجستية للفرقة 146، مرابض مدفعية في العديسة وكفرجلعادي، وصولًا إلى منصة “القبة الحديدية” وتموضع للجنود في ثكنة العليقة في الجولان السوري المحتل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وامتدت الضربات حتى اللحظات الأخيرة، حيث تكرر قصف مستوطنة نهاريا مرتين خلال أقل من ساعة، إلى جانب استهداف بنى تحتية عسكرية في مستوطنة كرميئيل، في وقت تواصلت فيه الضربات الصاروخية على تجمعات الجنود داخل الأراضي اللبنانية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وسُجل تطور نوعي بإعلان إسقاط طائرة مسيّرة إسرائيلية من نوع “هرمز 450” قبالة بلدة عدلون بصاروخ أرض-جو، حيث شوهدت تسقط في البحر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه العمليات، وفق بيانات المقاومة، في سياق الرد على خروقات إسرائيل لاتفاق وقف إطلاق النار، مع تأكيد استمرارها حتى توقف العدوان، في مشهد ميداني يعكس ذروة التصعيد التي بلغت أقصاها في الدقائق الأخيرة قبل دخول الهدنة حيّز التنفيذ.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "On April 16, 2026, in the final hours before the ceasefire came into effect, an unprecedented escalation took place in the pace of operations by the Islamic Resistance, which announced carrying out more than 50 military operations in less than 24 hours, ranging between intense rocket fire, drone attacks, targeting vehicles and tanks, and direct clashes along the front lines.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The operations were mainly concentrated in southern Lebanon, particularly in Bint Jbeil, Qantara, Khiam, Taybeh, and Adaisseh, alongside strikes reaching deep into occupied Palestinian territories, from Nahariya and Acre to Kiryat Shmona and the Golan.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Bint Jbeil, the city formed a central محور of confrontation, where the resistance targeted تجمعات of soldiers and vehicles at multiple points داخلها ومحيطها through consecutive rocket strikes across more than one location, alongside targeting Merkava tanks in its surroundings. Shelling also resumed in the final hours of the night, targeting the vicinity of Al Ishraq School, Moussa Abbas complex, and Tahrir triangle.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As for Qantara, it emerged as the most intense front, with a large number of operations exceeding ten, varying between rocket and artillery fire and precise targeting of vehicles. The area witnessed direct clashes with an Israeli force attempting to advance, resulting, according to statements, in the destruction of four tanks and two armored personnel carriers, in addition to targeting other vehicles with guided missiles.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding the targeting of Merkava tanks, the resistance announced the destruction of:", "type": "text"}, {"type": "hardBreak"}, {"text": "one tank at the northeastern outskirts of Bint Jbeil,", "type": "text"}, {"type": "hardBreak"}, {"text": "a second tank near Bint Jbeil market,", "type": "text"}, {"type": "hardBreak"}, {"text": "a third in the town of Bayyada where it was seen burning,", "type": "text"}, {"type": "hardBreak"}, {"text": "in addition to two tanks at the Sallaa hill in the town of Qantara,", "type": "text"}, {"type": "hardBreak"}, {"text": "bringing the total number of targeted tanks to five during these operations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The strikes also extended to multiple areas, targeting تجمعات of soldiers and vehicles in Khiam, Taybeh, Rab Thalathin, Adaisseh, and the surroundings of Khiam detention center, in addition to artillery positions between Adaisseh and Rab Thalathin, and other sites along the front, with late shelling recorded targeting southern Khiam, Taybeh, and Bayyada in the final minutes before the truce.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In parallel, the resistance intensified its attacks on military sites and settlements in the depth, targeting Kiryat Shmona, Shlomi, Yaara, Nahariya, Kfar Giladi, Karmiel, Peki’in, and Misgav Am, in addition to prominent military bases, including the Shraga base, headquarters of the Golani Brigade, Leman barracks, the naval officers school in Acre Bay, and the Ras Naqoura site, which was targeted more than once.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The resistance also made wide use of kamikaze drones, targeting several locations including Hanita, al-Malkiya, Ras Naqoura, a logistical base of Division 146, artillery positions in Adaisseh and Kfar Giladi, reaching an Iron Dome platform and a troop position in Alaliqa barracks in the occupied Syrian Golan.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Strikes continued until the final moments, with Nahariya settlement shelled twice in less than an hour, alongside targeting military infrastructure in Karmiel, while rocket attacks on تجمعات of soldiers inside Lebanese territory also continued.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A notable development was recorded with the announcement of the downing of an Israeli Hermes 450 drone off the coast of Adloun using a surface-to-air missile, where it was seen falling into the sea.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These operations come, according to resistance statements, in response to Israeli violations of the ceasefire agreement, with confirmation of their continuation until the aggression stops, in a field scene reflecting the peak escalation that reached its maximum in the final minutes before the truce came into effect.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2023-05-23_10-49-05_345841-crIzFKaMcotiNTMo9mtOi0MI92BsjQ.jpg', false, false, 66, 355, TIMESTAMP '2026-04-16 19:16:53.975', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Between Islamabad negotiations and the naval blockade… US escalation keeps the specter of confrontation looming', 'بين مفاوضات إسلام آباد والحصار البحري… تصعيد أميركي يُبقي شبح المواجهة قائماً', 'ir-isl-us-escal', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رغم مساعي باكستان لتقريب وجهات النظر بين إيران والولايات المتحدة والتحضير لجولة ثانية من المفاوضات، لا تزال احتمالات التصعيد قائمة، في ظل استمرار الإجراءات الأميركية، ولا سيما الحصار البحري وتعزيز الوجود العسكري في المنطقة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في هذا الإطار، زار قائد الجيش الباكستاني عاصم منير طهران، حيث التقى مسؤولين إيرانيين بينهم محمد باقر قاليباف وعباس عراقجي، في محاولة لتمهيد الطريق أمام مفاوضات جديدة في إسلام آباد تقوم على التفاهم حول “الإطار العام” للاتفاق، قبل انتقاله إلى واشنطن لاستكمال الوساطة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويبقى البرنامج النووي الإيراني محور الخلاف الأساسي، خصوصًا ما يتعلق بمخزون اليورانيوم المخصب والقيود المفروضة على التخصيب. ومع الحديث عن جولة قريبة وربما تمديد الهدنة التي تنتهي قريبًا، يبرز وقف إطلاق النار في لبنان كجزء من التفاهم بين طهران وواشنطن، رغم اعتراض إيران على المفاوضات المباشرة بين بيروت وتل أبيب، ومحاولة فصل هذا الملف عن التفاوض النووي", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، فرضت الولايات المتحدة حصارًا بحريًا على الموانئ الإيرانية، إلا أن تطبيقه لا يزال جزئيًا، إذ تستمر حركة السفن التجارية وناقلات الشحن بشكل طبيعي إلى حد كبير، مع قيود محدودة فقط على بعض ناقلات النفط، فيما لم يتوقف عبور النفط عبر مضيق هرمز", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "هذا الواقع يثير مخاوف داخل إيران من أن يؤدي تمديد وقف إطلاق النار دون نتائج ملموسة إلى منح واشنطن وقتًا لتعزيز قواتها ورفع مستوى الضغط الاقتصادي، خصوصًا مع تقارير عن نشر أكثر من 10 آلاف جندي أميركي إضافي في الشرق الأوسط", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بالتوازي، تؤكد طهران أنها تتعامل بحذر مع أي مفاوضات جديدة، فيما تعلن جهوزيتها العسكرية الكاملة للرد على أي هجوم، في حين تؤكد واشنطن بدورها استعدادها لاستئناف العمليات. كما حذّرت جهات دولية، بينها مجلس الأمن الروسي، من أن التعزيزات الأميركية قد تعكس تحضيرًا لعمل عسكري محتمل تحت غطاء المفاوضات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المحصلة، تسير الولايات المتحدة في مسارين متوازيين: التفاوض من جهة، والتصعيد العسكري والاقتصادي من جهة أخرى، ما يجعل الهدنة هشّة، واحتمال العودة إلى المواجهة قائمًا في أي لحظة", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Despite Pakistan’s efforts to bring Iran and the United States closer and prepare for a second round of negotiations, the chances of escalation remain, amid the continuation of US measures, particularly the naval blockade and the reinforcement of military presence in the region.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Pakistani Army Chief Asim Munir visited Tehran, where he met Iranian officials including Mohammad Bagher Ghalibaf and Abbas Araghchi, in an attempt to pave the way for new negotiations in Islamabad based on an understanding of the general framework of an agreement, before heading to Washington to continue mediation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Iranian nuclear program remains the main point of contention, especially regarding enriched uranium stockpiles and restrictions on enrichment. With talk of a possible upcoming round and perhaps an extension of the truce that is nearing its end, the ceasefire in Lebanon emerges as part of the understanding between Tehran and Washington, despite Iran’s objection to direct negotiations between Beirut and Tel Aviv and attempts to separate this file from the nuclear talks.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, the United States has imposed a naval blockade on Iranian ports, though its implementation remains partial, as commercial shipping and cargo vessels continue to operate largely normally, with only limited restrictions on some oil tankers, while oil transit through the Strait of Hormuz has not stopped.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This situation raises concerns within Iran that extending the ceasefire without tangible results could give Washington time to reinforce its forces and increase economic pressure, especially with reports of deploying more than 10,000 additional US troops in the Middle East.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, Tehran affirms that it is approaching any new negotiations with caution, while declaring full military readiness to respond to any attack, as Washington also confirms its readiness to resume operations. International bodies, including the Russian Security Council, have warned that US reinforcements may reflect preparations for possible military action under the cover of negotiations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In conclusion, the United States is moving on two parallel tracks: negotiation on one hand, and military and economic escalation on the other, making the truce fragile and the possibility of a return to confrontation present at any moment.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/1494903.jpeg-EggHGZFzkInpZrhytKj98aGZ2GWTUM.webp', false, false, 30, 316, TIMESTAMP '2026-04-17 09:10:43.640', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Google and the Pentagon are discussing a secret artificial intelligence deal', 'غوغل والبنتاغون تناقشان صفقة سرية للذكاء الاصطناعي', 'google-pent-deal', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "‌ذكر موقع \"ذي إنفورميشن\" -نقلا عن مصدرين مطلعين أمس الخميس- أن شركة غوغل التابعة لمجموعة \"ألفابت\" تُجري مفاوضات مع وزارة الحرب الأمريكية \"البنتاغون\" بشأن اتفاق يسمح للأخيرة بنشر نماذج الذكاء الاصطناعي \"جيميناي إيه آي\" في بيئات سرية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأفاد التقرير بأن الطرفين يناقشان إبرام اتفاق يسمح للبنتاغون باستخدام أدوات الذكاء الاصطناعي من غوغل في كافة الاستخدامات المشروعة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال الموقع إن غوغل اقترحت ‌‌خلال المفاوضات إضافة بنود إلى عقدها مع الوزارة لمنع استخدام الذكاء الاصطناعي الخاص بها في المراقبة الجماعية المحلية، أو الأسلحة ذاتية التشغيل دون رقابة بشرية مناسبة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال مسؤول في البنتاغون إن الوزارة ستواصل نشر قدرات الذكاء الاصطناعي المتطورة من خلال شراكات صناعية قوية على جميع المستويات، دون تأكيد أي محادثات مع غوغل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبينما لم تردّ شركة \"ألفابت\" -حتى الآن- على طلب وكالة رويترز للتعليق، إلا أن إبرامها صفقة مع البنتاغون سيساعدها على توسيع علاقاتها الحكومية، في الوقت الذي تعمل فيه الولايات المتحدة بقوة على دمج الذكاء الاصطناعي في عملياتها لتقليل التكاليف ‌‌وتسريع الأعمال الإدارية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وسبق أن غيرت شركة \"أوبن إيه آي\" في مارس/آذار الماضي بنود صفقتها مع وزارة الحرب الأمريكية (البنتاغون)، عقب موجة من الانتقادات الواسعة بسبب المخاوف من استخدام الذكاء الاصطناعي في تقنيات المراقبة الشاملة، حسب تقرير وكالة \"إن بي سي\" الأمريكية للأخبار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وجاء الإعلان عن البنود الجديدة على لسان المدير التنفيذي للشركة سام ألتمان عبر حسابه الرسمي في منصة \"إكس\" للتواصل الاجتماعي، حيث أكد أن البنود الجديدة تضمن عدم استخدام الذكاء الاصطناعي أو تقنيات الشركة في المراقبة الشاملة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكان ألتمان وصف -في منشور سابق- الصفقة وبنودها بأنها تبدو متسرعة واستغلالية إلى أبعد الحدود، حسب تقرير نشرته صحيفة الغارديان البريطانية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد ألتمان -في بيانه- أن البنتاغون لن يستخدم تقنيات الذكاء الاصطناعي مع الوكالات الاستخباراتية التابعة له مثل وكالة الأمن القومي الأمريكي، مضيفا أن حماية الحقوق المدنية للمواطنين أمر محوري ولا تنازل عنه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويُذكر أن شركة غوغل تراجعت -في فبراير/شباط 2025- عن تعهدها الذي كان يقضي بعدم استخدام الذكاء الاصطناعي لأغراض خطيرة مثل تطوير الأسلحة وأدوات المراقبة، إذ حدّثت مبادئها الأخلاقية المتعلقة بالذكاء الاصطناعي وأعلنت أنها لم تعد تُلزم نفسها بتجنب تطوير التقنيات التي يُحتمل أن تُسبب ضررا عاما، وفقا لموقع \"سي إن بي سي\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكانت النسخة السابقة من مبادئ الذكاء الاصطناعي للشركة تنص على أن غوغل لن تسعى إلى تسخير الذكاء الاصطناعي في تطوير أسلحة أو تقنيات أخرى قد تُلحق أذى بالناس سواء بطريقة مباشرة أو غير مباشرة، ولن تستخدم تقنيات جمع المعلومات لأغراض المراقبة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وذكرت غوغل أنها ستظل متماشية مع مبادئ القانون الدولي وحقوق الإنسان المعتمدة عالميا، وأنها ستحرص على أن تكون أعمالها في قطاع الذكاء الاصطناعي ذات فائدة أكبر وضرر أقل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومن الواضح أن شركة غوغل عملت على ترويج تقنياتها في مجال الذكاء الاصطناعي للعملاء، وقد سعى فريق القيادة برئاسة بيتشاي بشكل قوي للحصول على عقود مع الحكومة الفدرالية، مما أدى إلى حصول تصادمات واعتراضات داخل الشركة مع بعض القوى العاملة الرافضة لهذه السياسات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما سبق أن انسحبت الشركة عام 2018 من مزايدة على عقد بقيمة 10 مليارات دولار مع البنتاغون، لأنها لم تكن متأكدة من أنه سيتوافق مع مبادئ الذكاء الاصطناعي الخاصة بها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المصدر: وكالات", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Information website reported, citing two informed sources on Thursday, that Google, owned by Alphabet, is in talks with the US Department of Defense, the Pentagon, over an agreement that would allow it to deploy its Gemini AI models in classified environments.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report stated that both sides are discussing a deal that would allow the Pentagon to use Google’s artificial intelligence tools for all legitimate uses.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The site added that Google proposed during negotiations adding clauses to its contract with the department to prevent the use of its AI in domestic mass surveillance or in autonomous weapons without proper human oversight.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A Pentagon official said the department will continue to deploy advanced artificial intelligence capabilities through strong industrial partnerships at all levels, without confirming any talks with Google.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "While Alphabet has not yet responded to Reuters’ request for comment, reaching a deal with the Pentagon would help it expand its government ties, at a time when the United States is strongly working to integrate AI into its operations to reduce costs and speed up administrative work.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Previously, OpenAI changed the terms of its deal with the Pentagon last March, following a wave of widespread criticism over concerns about the use of AI in mass surveillance technologies, according to a report by NBC News.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The new terms were announced by the company’s CEO Sam Altman on his official account on the X platform, where he confirmed that the new clauses ensure that AI or the company’s technologies will not be used in mass surveillance.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Altman had previously described the deal and its terms as rushed and highly exploitative, according to a report published by The Guardian.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In his statement, Altman confirmed that the Pentagon would not use AI technologies with its intelligence agencies such as the US National Security Agency, adding that protecting citizens’ civil rights is a central and non-negotiable issue.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It is worth noting that Google backed away in February 2025 from its pledge not to use AI for dangerous purposes such as developing weapons or surveillance tools, as it updated its ethical AI principles and announced it was no longer committed to avoiding the development of technologies that could cause public harm, according to CNBC.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The previous version of the company’s AI principles stated that Google would not seek to use AI in developing weapons or other technologies that could harm people directly or indirectly, and would not use data collection technologies for surveillance purposes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Google said it will remain aligned with international law and globally recognized human rights principles, and will ensure that its work in the AI sector brings more benefit and less harm.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It is clear that Google has been promoting its AI technologies to clients, and its leadership team under Sundar Pichai has strongly pursued contracts with the federal government, leading to internal clashes and objections from some employees opposed to these policies.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The company had previously withdrawn in 2018 from bidding on a $10 billion Pentagon contract, as it was not sure it would align with its AI principles.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Source: Agencies", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/T6N73XWTD5PBHAZOFMX5AXWHWI-nr86Z4lGrh2T9juGIniF4pu3X0DVXl.jpg', false, false, 18, 91, TIMESTAMP '2026-04-17 09:56:13.284', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Cuba raises readiness… will it become the “next target” for Washington?', 'كوبا ترفع الجهوزية… هل تصبح “الهدف التالي” لواشنطن؟', 'cuba-wash-danger', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلن الرئيس الكوبي ميغيل دياز كانيل أن بلاده باتت \"على أهبة الاستعداد\" لمواجهة هجوم أميركي محتمل، في ظل تصاعد التوتر مع واشنطن واستمرار الضغوط التي يقودها الرئيس دونالد ترامب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي خطاب أمام حشد في هافانا بمناسبة ذكرى غزو خليج الخنازير، أكد دياز كانيل أن كوبا لا ترغب في حرب، لكنها \"ملزمة بالاستعداد لتجنبها، وإذا فُرضت، فعليها الانتصار فيها\"، واصفًا المرحلة الحالية بأنها \"بالغة الخطورة\" في ظل ما اعتبره \"عدوانًا متعدد الأوجه\" يشمل الحصار الاقتصادي وأزمة الطاقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويأتي هذا التصعيد على خلفية استمرار الحصار الأميركي، خصوصًا على قطاع الطاقة، حيث أدت القيود المفروضة على استيراد النفط من فنزويلا وروسيا والمكسيك إلى تفاقم الأزمة الاقتصادية، مع انقطاع الكهرباء ونقص الوقود، في ظل أزمة ممتدة منذ سنوات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، لوّح ترامب بإمكانية توجيه الاهتمام إلى كوبا بعد انتهاء المواجهة مع إيران، واصفًا إياها بـ\"الدولة الفاشلة\"، ومهددًا بإجراءات إضافية، بينها فرض عقوبات على الدول التي تزوّدها بالنفط، أو حتى تدخل مباشر، كما فعل سابقًا في فنزويلا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تطرح واشنطن شروطًا لتخفيف العقوبات، تشمل إطلاق سراح السجناء السياسيين، إنهاء ما تصفه بالقمع، وإصلاح الاقتصاد، وهي شروط ترفضها هافانا، التي تؤكد استعدادها للحوار ولكن \"من دون المساس بنظامها السياسي\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم الحديث عن محاولات تهدئة عبر قنوات غير مباشرة، لم تحقق أي تقدم يُذكر، فيما تشير المعطيات إلى أن كوبا باتت تتعامل بجدية مع سيناريو التصعيد، خاصة مع تصنيفها كـ\"الهدف التالي\" ضمن سياسة أميركية أوسع بعد فنزويلا وإيران.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويعيد هذا المشهد إلى الأذهان غزو خليج الخنازير عام 1961، حين فشلت عملية أميركية لإسقاط نظام كاسترو، في محطة تاريخية لا تزال حاضرة في الخطاب الكوبي اليوم، مع تأكيد القيادة الحالية أن البلاد \"مهددة لكنها لن تستسلم\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Cuban President Miguel Díaz-Canel announced that his country is now 'on high alert' to face a potential US attack, amid rising tensions with Washington and continued pressure led by President Donald Trump.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a speech before a crowd in Havana marking the anniversary of the Bay of Pigs invasion, Díaz-Canel stressed that Cuba does not seek war, but is 'obliged to prepare to avoid it, and if it is imposed, to prevail in it', describing the current phase as 'extremely dangerous' amid what he called 'multi-faceted aggression' including the economic blockade and the energy crisis.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This escalation comes against the backdrop of the ongoing US embargo, particularly on the energy sector, as restrictions on oil imports from Venezuela, Russia, and Mexico have worsened the economic crisis, with power outages and fuel shortages, in a crisis that has lasted for years.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, Trump hinted at the possibility of turning attention to Cuba after the confrontation with Iran ends, describing it as a 'failed state' and threatening additional measures, including imposing sanctions on countries that supply it with oil, or even direct intervention, as he previously did in Venezuela.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Washington is also proposing conditions to ease sanctions, including the release of political prisoners, ending what it describes as repression, and economic reforms, conditions rejected by Havana, which affirms its readiness for dialogue but 'without compromising its political system'.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite talk of de-escalation attempts through indirect channels, no significant progress has been achieved, while indications suggest that Cuba is taking the escalation scenario seriously, especially as it is being considered the 'next target' within a broader US policy following Venezuela and Iran.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This situation recalls the Bay of Pigs invasion in 1961, when a US-backed operation to overthrow Castro’s regime failed, a historical moment that remains present in Cuban discourse today, with the current leadership emphasizing that the country is 'under threat but will not surrender'.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/AFP__20260304__99YY7L7__v1__MidRes__CubaEnergyBlackout-1772667917-FKcYvYg5ZYnNlyVkUH9y632bykxFcg.jpg', false, false, 32, 307, TIMESTAMP '2026-04-17 10:09:45.009', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Key terms of the ceasefire, how were the reactions of both sides?', 'أبرز بنود وقف إطلاق النار، كيف كانت ردود فعل الطرفين؟', 'lebceasefire', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "ترامب يعلن وقف إطلاق نار لمدة 10 أيام بين إسرائيل ولبنان", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "أعلن الرئيس الأميركي ", "type": "text"}, {"text": "دونالد ترامب", "type": "text", "marks": [{"type": "bold"}]}, {"text": " التوصل إلى ", "type": "text"}, {"text": "اتفاق وقف إطلاق نار لمدة 10 أيام", "type": "text", "marks": [{"type": "bold"}]}, {"text": " بين إسرائيل ولبنان، دخل حيّز التنفيذ عند ", "type": "text"}, {"text": "17:00 بتوقيت شرق الولايات المتحدة (21:00 بتوقيت غرينتش؛ منتصف الليل بتوقيت لبنان) في 16 أبريل", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ودعا ترامب ", "type": "text"}, {"text": "حزب الله", "type": "text", "marks": [{"type": "bold"}]}, {"text": " إلى الالتزام بالهدنة، معربًا عن أمله بأن ", "type": "text"}, {"text": "“يتصرف بشكل جيد خلال هذه الفترة المهمة.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بالتزامن، أعلنت ", "type": "text"}, {"text": "إيران إعادة فتح مضيق هرمز بالكامل أمام الملاحة التجارية", "type": "text", "marks": [{"type": "bold"}]}, {"text": " خلال فترة وقف إطلاق النار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بنود الاتفاق:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• الهدنة تستمر ", "type": "text"}, {"text": "10 أيام", "type": "text", "marks": [{"type": "bold"}]}, {"text": " مع إمكانية ", "type": "text"}, {"text": "تمديدها إذا تقدمت المفاوضات", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• تحتفظ إسرائيل ", "type": "text"}, {"text": "بحق الرد والدفاع عن النفس ضد أي هجمات", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• على لبنان اتخاذ ", "type": "text"}, {"text": "خطوات لمنع حزب الله أو أي مجموعات مسلحة أخرى من مهاجمة إسرائيل", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "قوات الأمن اللبنانية تتحمل المسؤولية الحصرية عن أمن البلاد", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ستواصل ", "type": "text"}, {"text": "الولايات المتحدة تسهيل المفاوضات المباشرة", "type": "text", "marks": [{"type": "bold"}]}, {"text": " بين لبنان وإسرائيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقالت واشنطن إن الاتفاق يمثل ", "type": "text"}, {"text": "“بادرة حسن نية” من إسرائيل", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لفتح الباب أمام مفاوضات نحو ", "type": "text"}, {"text": "اتفاق دائم للسلام والأمن", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما دعا ترامب ", "type": "text"}, {"text": "رئيس الوزراء الإسرائيلي بنيامين نتنياهو", "type": "text", "marks": [{"type": "bold"}]}, {"text": " والرئيس اللبناني جوزاف عون إلى ", "type": "text"}, {"text": "البيت الأبيض", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لمواصلة المفاوضات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ردود الفعل:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• نتنياهو وصف الاتفاق بأنه ", "type": "text"}, {"text": "“فرصة لاتفاق سلام تاريخي.”", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• رئيس الحكومة اللبنانية ", "type": "text"}, {"text": "نواف سلام", "type": "text", "marks": [{"type": "bold"}]}, {"text": " أعرب عن أمله بعودة النازحين إلى منازلهم.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الرئيس ", "type": "text"}, {"text": "جوزاف عون", "type": "text", "marks": [{"type": "bold"}]}, {"text": " قال إن هذه الفرصة ", "type": "text"}, {"text": "“لا يجب أن تُهدر.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "من جهته، أبدى ", "type": "text"}, {"text": "حزب الله", "type": "text", "marks": [{"type": "bold"}]}, {"text": " استعدادًا لاحترام وقف إطلاق النار لكنه طالب بـ:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "وقف كامل للهجمات الإسرائيلية على لبنان", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "عدم حرية تحرك القوات الإسرائيلية داخل الأراضي اللبنانية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وقال المسؤول في حزب الله ", "type": "text"}, {"text": "وفيق صفا", "type": "text", "marks": [{"type": "bold"}]}, {"text": " إن مسألة نزع السلاح ", "type": "text"}, {"text": "لن تُطرح قبل انسحاب إسرائيل وتحقيق وقف إطلاق نار حقيقي", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بقاء القوات الإسرائيلية في الجنوب:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "رغم الهدنة، أعلن نتنياهو أن ", "type": "text"}, {"text": "القوات الإسرائيلية ستبقى على عمق نحو 10 كلم داخل جنوب لبنان", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ضمن ما تسميه إسرائيل ", "type": "text"}, {"text": "“منطقة أمنية.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• أكثر من ", "type": "text"}, {"text": "1.2 مليون شخص نزحوا في لبنان", "type": "text", "marks": [{"type": "bold"}]}, {"text": " منذ بدء القتال.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• أكثر من ", "type": "text"}, {"text": "1400 مبنى دُمّر في جنوب لبنان", "type": "text", "marks": [{"type": "bold"}]}, {"text": " بحسب تقديرات.  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• إسرائيل تدرس توسيع المنطقة حتى ", "type": "text"}, {"text": "نهر الليطاني", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقد انتقد لبنان ودول أوروبية و**الأمم المتحدة** هذه الخطوة، معتبرين أنها قد تعني ", "type": "text"}, {"text": "احتلالًا جديدًا لأراضٍ لبنانية", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ارتباط الصراع بإيران:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بدأ التصعيد بعد ", "type": "text"}, {"text": "ضربات أميركية وإسرائيلية ضد إيران", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، تبعتها هجمات من طهران وحلفائها في المنطقة، بينهم حزب الله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأدى ذلك إلى ", "type": "text"}, {"text": "إغلاق مؤقت لمضيق هرمز", "type": "text", "marks": [{"type": "bold"}]}, {"text": " الذي يمر عبره نحو ", "type": "text"}, {"text": "20% من تجارة النفط والغاز العالمية", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، ما تسبب بارتفاع أسعار الطاقة عالميًا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم إعلان إيران إعادة فتح المضيق، قال ترامب إن ", "type": "text"}, {"text": "الحصار البحري الأميركي على الموانئ الإيرانية سيستمر حتى اكتمال الاتفاق مع طهران", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الخسائر منذ 2 مارس:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• أكثر من ", "type": "text"}, {"text": "2100 شهيد و7000 جريح في لبنان", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• بينهم ", "type": "text"}, {"text": "260 امرأة و172 طفلًا", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "مقتل مدنيين اثنين في إسرائيل", "type": "text", "marks": [{"type": "bold"}]}, {"text": " جراء هجمات حزب الله  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "•اعترف جيش العدو ", "type": "text"}, {"text": "بمقتل 13 جنديًا إسرائيليًا", "type": "text", "marks": [{"type": "bold"}]}, {"text": " في القتال داخل لبنان", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Trump Announces 10-Day Israel–Lebanon Ceasefire", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "US President ", "type": "text"}, {"text": "Donald Trump", "type": "text", "marks": [{"type": "bold"}]}, {"text": " announced a ", "type": "text"}, {"text": "10-day ceasefire agreement between Israel and Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which took effect at ", "type": "text"}, {"text": "17:00 EST (21:00 GMT; midnight local time) on April 16", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trump urged ", "type": "text"}, {"text": "Hezbollah", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to respect the truce, saying he hopes the group will ", "type": "text"}, {"text": "“act nicely and well during this important period.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "At the same time, ", "type": "text"}, {"text": "Iran announced the Strait of Hormuz is fully open for commercial shipping", "type": "text", "marks": [{"type": "bold"}]}, {"text": " during the ceasefire.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ceasefire terms:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• The truce will last ", "type": "text"}, {"text": "10 days", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", with the possibility of ", "type": "text"}, {"text": "extension if negotiations progress", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Israel retains the ", "type": "text"}, {"text": "right to self-defense against any attacks", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Lebanon must take ", "type": "text"}, {"text": "steps to prevent Hezbollah or other armed groups from attacking Israel", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Lebanese security forces hold exclusive responsibility for national security", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• The ", "type": "text"}, {"text": "US will continue facilitating direct talks", "type": "text", "marks": [{"type": "bold"}]}, {"text": " between Israel and Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Washington described the agreement as a ", "type": "text"}, {"text": "“gesture of goodwill” by Israel", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to enable negotiations toward a ", "type": "text"}, {"text": "permanent peace and security deal", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trump also invited ", "type": "text"}, {"text": "Israeli Prime Minister Benjamin Netanyahu", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Lebanese President Joseph Aoun", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to the ", "type": "text"}, {"text": "White House", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for further talks.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Reactions:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• Netanyahu called the truce ", "type": "text"}, {"text": "“an opportunity for a historic peace agreement.”", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Lebanese Prime Minister ", "type": "text"}, {"text": "Nawaf Salam", "type": "text", "marks": [{"type": "bold"}]}, {"text": " said it could allow displaced civilians to ", "type": "text"}, {"text": "return home", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• President ", "type": "text"}, {"text": "Joseph Aoun", "type": "text", "marks": [{"type": "bold"}]}, {"text": " said the opportunity ", "type": "text"}, {"text": "“must not be wasted.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Hezbollah", "type": "text", "marks": [{"type": "bold"}]}, {"text": " signaled willingness to respect the ceasefire but demanded:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "A complete halt to Israeli attacks across Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "No freedom of movement for Israeli forces", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Senior Hezbollah official ", "type": "text"}, {"text": "Wafiq Safa", "type": "text", "marks": [{"type": "bold"}]}, {"text": " said disarmament ", "type": "text"}, {"text": "will not be discussed until Israel withdraws and a real ceasefire is in place", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli troops remain in southern Lebanon:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Despite the truce, Netanyahu said ", "type": "text"}, {"text": "Israeli forces will remain about 10 km inside southern Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in what Israel calls a ", "type": "text"}, {"text": "“security zone.”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• More than ", "type": "text"}, {"text": "1.2 million people have been displaced in Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Over ", "type": "text"}, {"text": "1,400 buildings destroyed in southern Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Israel may extend the zone up to the ", "type": "text"}, {"text": "Litani River", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Lebanon, the ", "type": "text"}, {"text": "UN", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and several European countries criticized the move, warning it could mean ", "type": "text"}, {"text": "a new occupation of Lebanese territory", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Link to the Iran conflict:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The escalation followed ", "type": "text"}, {"text": "US and Israeli strikes on Iran", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which triggered retaliation from Tehran and its regional allies, including Hezbollah.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Iran temporarily ", "type": "text"}, {"text": "blocked the Strait of Hormuz", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", through which ", "type": "text"}, {"text": "around 20% of global oil and LNG shipments pass", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", causing global energy prices to surge.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although Iran has reopened the strait during the ceasefire, Trump said ", "type": "text"}, {"text": "US maritime restrictions on Iranian ports will remain until negotiations with Tehran are fully completed", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Casualties since March 2:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "2,100+ killed and 7,000 wounded in Lebanon", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "260 women and 172 children", "type": "text", "marks": [{"type": "bold"}]}, {"text": " among the dead  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "2 civilians killed in Israel", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "13 Israeli soldiers killed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in combat in Lebanon", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the latest development, the ", "type": "text"}, {"text": "Israeli military destroyed the last bridge connecting southern Lebanon to the rest of the country", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", further isolating the region and raising fears of ", "type": "text"}, {"text": "long-term occupation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/