s": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "محطة قطر:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• التقى الشرع في ", "type": "text"}, {"text": "الدوحة", "type": "text", "marks": [{"type": "bold"}]}, {"text": " أمير قطر ", "type": "text"}, {"text": "الشيخ تميم بن حمد آل ثاني", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• أكد الطرفان ", "type": "text"}, {"text": "أهمية تطوير العلاقات الثنائية في مختلف المجالات", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• كما جرى بحث ", "type": "text"}, {"text": "الأوضاع الإقليمية وسبل التنسيق للحفاظ على استقرار المنطقة", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد الشرع خلال اللقاء ", "type": "text"}, {"text": "تضامن سوريا مع الدول العربية التي تعرضت لهجمات إيرانية", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المصدر: سانا", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Syrian President ", "type": "text"}, {"text": "Ahmed Al-Sharaa", "type": "text", "marks": [{"type": "bold"}]}, {"text": " arrived in ", "type": "text"}, {"text": "Abu Dhabi", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on Wednesday for an official visit to the ", "type": "text"}, {"text": "United Arab Emirates", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", where he is expected to meet ", "type": "text"}, {"text": "UAE President Sheikh Mohammed bin Zayed Al Nahyan", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to discuss regional developments and ways to strengthen bilateral cooperation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Al-Sharaa and the accompanying delegation were received in Abu Dhabi by ", "type": "text"}, {"text": "UAE Foreign Minister Abdullah bin Zayed Al Nahyan", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", according to Syria’s state news agency ", "type": "text"}, {"text": "SANA", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Gulf tour:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• Al-Sharaa began his Gulf tour ", "type": "text"}, {"text": "Tuesday with a visit to Saudi Arabia", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• He met ", "type": "text"}, {"text": "Crown Prince Mohammed bin Salman", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to discuss ", "type": "text"}, {"text": "expanding economic and investment partnerships", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• The two leaders also discussed ", "type": "text"}, {"text": "regional and international developments and their impact on regional security", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Qatar stop:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "• Earlier today, Al-Sharaa met ", "type": "text"}, {"text": "Qatar’s Emir Sheikh Tamim bin Hamad Al Thani", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in ", "type": "text"}, {"text": "Doha", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Both sides emphasized the ", "type": "text"}, {"text": "importance of strengthening bilateral relations", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• Discussions also covered ", "type": "text"}, {"text": "regional developments and coordination to maintain regional stability", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Al-Sharaa also expressed ", "type": "text"}, {"text": "Syria’s solidarity with Arab countries that faced Iranian attacks", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Source: SANA", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/HGg3uwYXsAAy_k9_164532_large-jFk9RvVkkdy1zBmV9VNX2O8jU5APrb.webp', false, false, 5, 136, TIMESTAMP '2026-04-22 13:56:18.217', CURRENT_TIMESTAMP,
