INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The US fleet under pressure: Iran’s mosquito strategy is disrupting destroyers and complaints of supply shortages', 'الأسطول الأمريكي تحت الضغط: خطة "البعوض" الإيراني تربك المدمرات وشكاوى من نقص الإمدادات', 'usmarines-struggle', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "تمتلك الولايات المتحدة ترسانة بحرية متطورة، تتصدرها مدمرات حديثة مثل \"فرانك إي. بيترسون\" و\"مايكل ميرفي\"، إذ يتجاوز طول كل منهما 155 مترا، وتزيد كلفة الواحدة عن ملياري دولار. وتحمل هذه المدمرات نحو 96 صاروخا موجها قادرا على التعامل مع الطائرات والصواريخ والغواصات، إضافة إلى تنفيذ ضربات برية دقيقة، ما يمنحها تفوقا ناريا واضحا على أي أسطول تقليدي في المنطقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لكن هذا التفوق لا يُترجم دائما إلى سيطرة مطلقة، خاصة في بيئات معقدة مثل مضيق هرمز، حيث تضيق الجغرافيا وتتغير قواعد الاشتباك. هنا، تعتمد إيران على تكتيكات \"الحرب غير المتكافئة\"، وعلى رأسها أسلوب \"أسراب البعوض\"، الذي يقوم على إطلاق أعداد كبيرة من الزوارق السريعة بهدف إرباك دفاعات الخصم بدل مواجهته بشكل مباشر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "مغارات محصنة واستراتيجية مختلفة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "من داخل مغارات محصنة على السواحل والجزر، تنطلق هذه الزوارق — مثل \"ذي الفقار\" و\"سراج\" و\"عاشوراء\" و\"طوفان\" و\"حيدر 110\" — ضمن هجمات تعتمد على السرعة والمناورة والكثافة العددية. ويعكس هذا النهج إدراكا إيرانيا للفجوة التكنولوجية، حيث تركز طهران على إشباع الدفاعات الأمريكية بدلا من منافستها في سباق المدمرات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتنتشر هذه الزوارق في أكثر من 10 قواعد محصنة، من بينها جزيرة فارور الاستراتيجية، ما يسمح بتنفيذ هجمات متزامنة من عدة اتجاهات. ويختلف تسليح كل زورق حسب دوره، إذ تشمل:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "مدافع رشاشة ثقيلة (أقل من 2 كم)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "قاذفات صواريخ (حتى 8 كم)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "صواريخ مضادة للسفن (حتى 100 كم)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "طوربيدات خفيفة (نحو 10 كم)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "مسيّرات هجومية (حتى 50 كم)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "ألغام بحرية وزوارق انتحارية", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "ولا يهدف هذا التكتيك بالضرورة إلى تدمير السفن الحربية، بل إلى استنزاف أنظمتها الدفاعية وإرباكها، خصوصا أن المدمرة — رغم قوتها — لا تستطيع حماية كل السفن التجارية في المضيق في وقت واحد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الكلفة الخفية: الضغط اللوجستي على القوات الأمريكية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في المقابل، لا تقتصر التحديات الأمريكية على المواجهة العسكرية فقط، بل تمتد إلى الأعباء اللوجستية الضخمة. فكل جندي من المارينز على متن حاملات الطائرات يكلف نحو 500 دولار يوميا للغذاء فقط، وقد تصل التكلفة الإجمالية إلى نحو 1000 دولار يوميا للفرد عند احتساب بقية النفقات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتحول حاملات الطائرات إلى مدن عائمة عالية الكلفة. على سبيل المثال:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "تحمل USS Lincoln نحو 6000 عنصر و90 طائرة، ويحتاج الفرد إلى 3500 سعرة حرارية يوميا", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "بينما تضم USS Tripoli حوالي 2200 مقاتل، مع معدل يصل إلى 9000 وجبة يوميا", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "ومع نشر أكثر من 10 آلاف جندي، و12 سفينة، و100 طائرة، وعدد من المدمرات في المنطقة، تتضاعف الضغوط التشغيلية بشكل كبير.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تراجع المعنويات ونقص الإمدادات", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "كشفت تقارير أمريكية عن شكاوى داخلية من طواقم السفن، خاصة \"لينكولن\" و\"تريبولي\"، بسبب نقص الإمدادات الغذائية وتراجع المعنويات. ووفقا لشهادات بعض الجنود، يتم تقنين الطعام بسبب محدودية الكميات، مع نقص واضح في الخضروات الطازجة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقد أدى ذلك إلى قلق عائلات الجنود، الذين حاولوا إرسال طرود غذائية، إلا أن توقف خدمة البريد العسكري في الشرق الأوسط حال دون وصولها. كما أقر عضو الكونغرس مايك ليفين بوجود مشكلة، معتبرا أن اضطرار الجنود لتقليل وجباتهم \"أمر غير مقبول\".", "type": "text"}]}, {"type": "image", "attrs": {"alt": null, "src": "https://c.ndtvimg.com/2026-04/ikhqmnm_us-iran-war-food_625x300_17_April_26.jpeg?downsize=773:435", "title": null, "width": null, "height": null}}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "معادلة معقدة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في ظل هذه المعطيات، تبدو المواجهة في الخليج معادلة مركبة: تفوق عسكري أمريكي هائل يقابله تكتيك إيراني مرن ومنخفض الكلفة، يقترن بضغط لوجستي متزايد على القوات الأمريكية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي بيئة ضيقة مثل مضيق هرمز، لا يتطلب تعطيل الملاحة معركة كبرى؛ فقد يكون مجرد تهديد أو إصابة سفينة واحدة كافيا لإحداث ارتباك واسع، تتجاوز آثاره حدود المنطقة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The United States possesses an advanced naval arsenal, led by modern destroyers such as Frank E. Petersen and Michael Murphy, each exceeding 155 meters in length, with a cost of more than $2 billion per ship. These destroyers carry around 96 guided missiles capable of dealing with aircraft, missiles, and submarines, in addition to executing precise land strikes, giving them clear firepower superiority over any conventional fleet in the region.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "However, this superiority does not always translate into absolute control, especially in complex environments such as the Strait of Hormuz, where geography narrows and the rules of engagement change. Here, Iran relies on asymmetric warfare tactics, foremost among them the mosquito swarm approach, which is based on launching large numbers of fast boats to disrupt enemy defenses rather than confront them directly.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Fortified caves and a different strategy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From within fortified caves along the coasts and islands, these boats are launched, such as Zolfaghar, Seraj, Ashura, Toofan, and Haidar 110, in attacks that rely on speed, maneuverability, and numerical density. This approach reflects an Iranian awareness of the technological gap, as Tehran focuses on saturating US defenses rather than competing in a destroyer race.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These boats are deployed across more than 10 fortified bases, including the strategic Farur Island, allowing simultaneous attacks from multiple directions. The armament of each boat varies depending on its role, including:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heavy machine guns with a range of less than 2 km", "type": "text"}, {"type": "hardBreak"}, {"text": "Rocket launchers with a range of up to 8 km", "type": "text"}, {"type": "hardBreak"}, {"text": "Anti-ship missiles with a range of up to 100 km", "type": "text"}, {"type": "hardBreak"}, {"text": "Light torpedoes with a range of around 10 km", "type": "text"}, {"type": "hardBreak"}, {"text": "Attack drones with a range of up to 50 km", "type": "text"}, {"type": "hardBreak"}, {"text": "Naval mines and suicide boats", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This tactic does not necessarily aim to destroy warships, but rather to exhaust their defense systems and confuse them, especially since a destroyer, despite its strength, cannot protect all commercial ships in the strait at the same time.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The hidden cost: logistical pressure on US forces", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, US challenges are not limited to military confrontation, but extend to heavy logistical burdens. Each Marine aboard aircraft carriers costs about $500 per day for food alone, and the total cost can reach around $1,000 per person per day when accounting for other expenses.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Aircraft carriers effectively become high-cost floating cities. For example:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "USS Lincoln carries around 6,000 personnel and 90 aircraft, with each individual requiring 3,500 calories per day", "type": "text"}, {"type": "hardBreak"}, {"text": "USS Tripoli includes about 2,200 personnel, with a rate reaching 9,000 meals per day", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "With the deployment of more than 10,000 troops, 12 ships, 100 aircraft, and several destroyers in the region, operational pressures increase significantly.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Declining morale and supply shortages", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "US reports have revealed internal complaints from ship crews, especially on Lincoln and Tripoli, due to shortages in food supplies and declining morale. According to testimonies from some soldiers, food is being rationed due to limited quantities, with a clear shortage of fresh vegetables.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This has raised concern among soldiers’ families, who attempted to send food packages, but the suspension of military mail services in the Middle East prevented their delivery. Congressman Mike Levin acknowledged the issue, stating that forcing soldiers to reduce their meals is unacceptable.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A complex equation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In light of these factors, the confrontation in the Gulf appears as a complex equation: overwhelming US military superiority matched by a flexible and low-cost Iranian tactic, combined with increasing logistical pressure on US forces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a narrow environment like the Strait of Hormuz, disrupting navigation does not require a major battle; even the threat or damage of a single ship may be enough to create widespread disruption, with effects that extend beyond the region.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/image-1776652969-NzhXC8SUFWzMmLd77s904T4vEP8LPJ.jpg', false, false, 567, 1268, TIMESTAMP '2026-04-22 18:51:26.672', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Security reveals the circumstances of a horrific crime in Jdeideh', 'الأمن يكشف ملابسات جريمةٍ مروّعة في الجديدة', '23april-new-crime', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "صدر عن المديريّة العامّة لقوى الأمن الدّاخلي - شعبة العلاقات العامّة البلاغ التّالي:", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "\"بتاريخ 23-03-2026، ادّعى أحد المحامين بتعرّض المدعو م. ش.، مواليد عام 1996، سوري الجنسية لعملية خطف من مجهولين في محلة الجديدة، وذلك أثناء وجوده على متن سيارة رباعية الدفع نوع \"رانج روفر\" مستأجرة.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وبنتيجة الكشف الميداني الذي قامت به شعبة المعلومات في المحلة المذكورة، عُثر على مظروفَي إطلاق نار عائدين لبندقية كلاشينكوف ومسدس حربي، إضافةً إلى بقعة دماء كبيرة، ما رجّح لدى محققي الشعبة حصول جريمة قتل.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ومن خلال المتابعة، تم العثور على السيارة المستأجرة، وبتفتيشها عُثر في داخلها على هاتف خلوي.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "على الفور، باشرت القطعات المختصة في الشعبة إجراءاتها الميدانية والاستعلامية لكشف ملابسات الحادثة.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وبنتيجة المتابعة الحثيثة، تم تحديد هوية أحد المشتبه بهم، ويدعى: م. م. (مواليد عام 1991، لبناني)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بتاريخ 28-03-2026، وبعد عملية رصد ومراقبة دقيقة، تمكّنت إحدى دوريات شعبة المعلومات من توقيفه في محلة الزعرور. وبتفتيش منزله، ضبطت كمية كبيرة من المخدّرات وأسلحة حربية.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بالتحقيق معه، اعترف بقيامه بترويج المخدرات، وبمعرفته بالمدعو (م. ش.)، مشيراً إلى حصول خلاف بينهما فجر تاريخ 23-03-2026 قرب منزله على خلفية قضايا مخدرات. وأفاد أنه أثناء وجوده في المكان، أقدم المغدور على ملاحقته إلى موقف البناية برفقة شخصين آخرين على متن سيارة رباعية الدفع نوع \"FJ\"، حيث شهر مسدساً حربياً بوجهه وأطلق النار باتجاهه دون إصابته. عندها، أطلق الموقوف النار من بندقية كلاشينكوف كانت بحوزته، ما أدى إلى إصابة (م. ش.) وسقوطه أرضاً، فيما فرّ مرافقاه. وأضاف أنه حاول إسعافه، إلا أنه تبيّن له أنه فارق الحياة، فقام بوضع الجثة داخل سيارته ونقلها إلى بلدة كفر عقاب، حيث عمد إلى إحراقها بهدف إخفاء معالم الجريمة.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وقد أُجريت دلالة على مكان إحراق الجثة في محلة كفر عقاب، حيث تم أخذ عينات لإجراء الفحوص المخبرية اللازمة. كما أسفر تفتيش منزل الموقوف في البلدة المذكورة عن ضبط كمية إضافية من المخدرات.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "أُجري المقتضى القانوني بحق الموقوف، وأُودع مع المضبوطات المرجع المعني بناءً لإشارة القضاء المختص، والعمل مستمر لتوقيف باقي المتورطين\"", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The General Directorate of the Internal Security Forces – Public Relations Division issued the following statement:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "'On 23-03-2026, a lawyer reported that M. Sh., born in 1996, a Syrian national, had been kidnapped by unknown individuals in the Jdeideh area, while he was inside a rented Range Rover vehicle.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Following a field inspection conducted by the Information Branch in the mentioned area, two spent bullet casings were found, one from a Kalashnikov rifle and another from a handgun, in addition to a large bloodstain, which led investigators to suspect that a murder had taken place.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Through further follow-up, the rented vehicle was located, and upon searching it, a mobile phone was found inside.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Immediately, the specialized units in the branch began field and investigative procedures to uncover the circumstances of the incident.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As a result of intensive follow-up, the identity of one suspect was determined, identified as M. M. (born in 1991, Lebanese).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On 28-03-2026, after a precise surveillance and monitoring operation, one of the Information Branch patrols managed to arrest him in the Zaarour area. A search of his home led to the seizure of a large quantity of drugs and military weapons.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "During interrogation, he confessed to drug trafficking and to knowing M. Sh., stating that a dispute occurred between them at dawn on 23-03-2026 near his residence over drug-related issues. He added that while he was there, the victim chased him to the building’s parking lot with two other individuals in an FJ vehicle, where the victim drew a handgun and fired at him without hitting him. The detainee then fired back with a Kalashnikov rifle he had in his possession, hitting M. Sh. and causing him to fall to the ground, while his companions fled. He added that he attempted to assist him, but realized he had died, so he placed the body in his car and transported it to the town of Kfar Aqab, where he burned it in an attempt to conceal the crime.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A site inspection was conducted at the location where the body was burned in Kfar Aqab, and samples were taken for necessary laboratory tests. A further search of the suspect’s residence in the same town resulted in the seizure of additional quantities of drugs.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Legal procedures have been carried out against the detainee, who has been referred along with the seized items to the competent authority upon the direction of the judiciary, and efforts are ongoing to arrest the remaining individuals involved.'", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/fd7756e2eacf439cd8f7154558da3f41_1024_576-kQHpSH6OyoBKQUB5fuiAXBjDHzNL1v.webp', false, false, 4047, 9687, TIMESTAMP '2026-04-23 09:16:25.214', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Political tension reaches the stadiums… widespread debate over Iran’s participation in the World Cup', 'التوتر السياسي يصل إلى الملاعب… جدل واسع حول مشاركة إيران في كأس العالم', 'ir-usa-26wc', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "التوتر السياسي يصل إلى الملاعب", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ألقى التصعيد بين واشنطن وطهران بظلاله على قطاع الرياضة، مع تصاعد الجدل حول مشاركة منتخب إيران في نهائيات كأس العالم 2026، بعد طرح مقترح أميركي باستبعاده واستبداله بإيطاليا.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "واشنطن: لا اعتراض على اللاعبين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أكد وزير الخارجية الأميركي ماركو روبيو أن الولايات المتحدة لا تعارض مشاركة اللاعبين الإيرانيين، لكنها ترفض دخول أشخاص على صلة بالحرس الثوري ضمن الوفد. وأوضح أن المشكلة ليست مع الرياضيين، بل مع بعض المرافقين الذين قد يُقدَّمون كصحفيين أو مدربين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من جهته، شدد الرئيس دونالد ترامب على أن إدارته “لا تريد التأثير على الرياضيين”، رغم أنه كان قد نصح سابقًا بعدم مشاركة اللاعبين الإيرانيين “حرصًا على سلامتهم”، قبل أن يؤكد لاحقًا أن المنتخب مرحب به.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مقترح استبدال إيران بإيطاليا", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الجدل تصاعد بعد اقتراح قدمه المبعوث الأميركي باولو زامبولي باستبعاد إيران ومنح مكانها لإيطاليا، مستندًا إلى تاريخ الأخيرة الكروي، إلا أن المقترح قوبل برفض واسع.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "رفض إيطالي رسمي", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في إيطاليا، أثار الطرح ردود فعل غاضبة، إذ أكد وزير الرياضة أندريا أبودي أن التأهل يُحسم في الملعب، بينما وصف وزير الاقتصاد جيانكارلو جيورجيتي الفكرة بأنها “مخزية”. كما اعتبر رئيس اللجنة الأولمبية الإيطالية أن المشاركة يجب أن تكون مستحقة، لا بقرار سياسي.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "إيران تتمسك بالمشاركة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، أكدت طهران تمسكها بالمشاركة في البطولة، حيث أعلنت المتحدثة باسم الحكومة فاطمة مهاجراني أن المنتخب يستعد لـ”مشاركة فخورة وناجحة”. كما شدد رئيس الاتحاد الإيراني مهدي تاج على أن المنتخب سيشارك وفق المعطيات الحالية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "خلاف على مكان المباريات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكانت إيران قد طلبت نقل مبارياتها في دور المجموعات من الولايات المتحدة إلى المكسيك بسبب الحرب، إلا أن “فيفا” رفض الطلب، ما يزيد من تعقيد الملف.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الاستعدادات مستمرة رغم التوتر", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم التصعيد السياسي، يواصل المنتخب الإيراني تحضيراته، حيث خطط لخوض أربع مباريات ودية في تركيا استعدادًا للمونديال، في مؤشر على أن المشاركة لا تزال قائمة حتى الآن.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Political tension reaches the stadiums", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The escalation between Washington and Tehran has cast its shadow over the sports sector, with growing controversy over Iran’s participation in the 2026 World Cup finals, following a US proposal to exclude it and replace it with Italy.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Washington: no objection to players", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "US Secretary of State Marco Rubio confirmed that the United States does not oppose the participation of Iranian players, but refuses the entry of individuals linked to the Revolutionary Guard within the delegation. He explained that the issue is not with the athletes, but with some accompanying individuals who may be presented as journalists or coaches.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For his part, President Donald Trump stressed that his administration does not want to affect athletes, although he had previously advised against Iranian players participating for their safety, before later confirming that the team is welcome.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Proposal to replace Iran with Italy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The controversy escalated after a proposal by US envoy Paolo Zampolli to exclude Iran and grant its place to Italy, citing the latter’s football history, but the proposal was met with widespread rejection.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Official Italian rejection", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Italy, the proposal sparked angry reactions, as Sports Minister Andrea Abodi confirmed that qualification is decided on the field, while Economy Minister Giancarlo Giorgetti described the idea as shameful. The head of the Italian Olympic Committee also stated that participation should be earned, not decided politically.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Iran insists on participation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, Tehran affirmed its insistence on participating in the tournament, with government spokesperson Fatemeh Mohajerani announcing that the team is preparing for a proud and successful participation. The president of the Iranian federation, Mehdi Taj, also stressed that the team will participate under current conditions.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Dispute over match venues", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Iran had requested to move its group stage matches from the United States to Mexico due to the war, but FIFA rejected the request, further complicating the situation.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Preparations continue despite tension", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite the political escalation, the Iranian team continues its preparations, planning to play four friendly matches in Turkey ahead of the World Cup, indicating that participation remains in place for now.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/03112026_iran_103801-gREV5rQ0vkW21qXYTWt06GwOmoy69R.jpg', false, false, 27, 153, TIMESTAMP '2026-04-24 09:24:57.367', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'sport'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Saad Hariri mourns one of his personal escorts', 'سعد الحريري ينعى أحد مرافقيه الشخصيين', 'saad-mourns-esc', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نعى رئيس الحكومة الأسبق سعد الحريري، اليوم الجمعة، محمد سعد الدين البرجاوي، أحد أفراد فريق الحراسة الخاصة به، الذي وافته المنية بعد صراع مع المرض.", "type": "text", "marks": [{"type": "bold"}]}, {"type": "hardBreak", "marks": [{"type": "bold"}]}, {"type": "hardBreak", "marks": [{"type": "bold"}]}, {"text": "وفي منشور عبر منصة فيسبوك، عبّر الحريري عن حزنه، قائلاً: \"اليوم لا أودّع فردا من الحراسة الخاصة فقط، بل أودّع رجلًا حمل الأمانة بإخلاص، وكان مثالا في الوفاء والرجولة والالتزام. رحم الله محمد سعد الدين البرجاوي\".", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Former Prime Minister Saad Hariri mourned today, Friday, Mohammad Saadeddine Al Barjawi, a member of his personal security team, who passed away after a battle with illness.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a post on Facebook, Hariri expressed his sadness, saying: 'Today I do not bid farewell to just a member of my personal security team, but to a man who carried the responsibility with sincerity and was an example of loyalty, manhood, and commitment. May God have mercy on Mohammad Saadeddine Al Barjawi'", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-570821-639126449327459186-VZCVFWmWWg3grNRs3JsXjEI6BZpLet.JPG', false, false, 1858, 6107, TIMESTAMP '2026-04-24 16:38:13.680', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Raad: I fear the country may fall into something worse than May 17', 'رعد: أخشى أن تقع البلاد في أسوأ من 17 أيار', 'ra-fea-17may', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد رئيس كتلة «الوفاء للمقاومة»، النائب محمد رعد، أن التفاوض المباشر مع العدو الإسرائيلي سوف يوقع البلاد في أسوأ مما أوقِعت به في 17 آيار، ناصحاً السلطة بالتراجع عن هذه الخطوة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتوجه رعد للسلطة قائلاً: «عليكم أن تخجلوا من الشعب والانسحاب مما سميَّ مفاوضات مباشرة مع العدو الصهيوني، وأخشى ما نخشاه من الإصرار على هذه الخطيئة أن تقع البلاد في أسوأ مما أوقِعت به في 17 آيار المشؤوم مطلع الثمانينات».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد في بيان، اليوم الجمعة، أن «أي تواصل رسمي أو لقاء يجمع بين طرف لبناني وإسرائيلي في حال الحرب القائمة بين لبنان وكيان الإحتلال الصهيوني لن يحظى بتوافق وطني لبناني على الإطلاق وسيشكل مخالفة دستورية موصوفة لن تغفرها ذريعةٌ ولا مصلحةٌ مُدَّعاة».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وشدد رئيس كتلة «الوفاء للمقاومة»، على أن «كلُّ هدنةٍ مفترضة، تمنح العدو المحتل في لبنان، استثناءً خاصاً لإطلاقه النار أو القيام بأي تحرك أو إجراء ميداني في مناطق المواجهة وضمن الأراضي اللبنانية سواء كان ذلك لتثبيت موقع أو زرع لغم أو تنفيذ إغتيالٍ أو تفجير منزلٍ أو منشأة أو تجريف أرضٍ أو ما شابه ذلك، فهي ليست هدنة على الإطلاق، وإنما هي خداع ماكر واستغباء للآخرين ينطوي على تغطية العدوانية الإسرائيلية وغضّ الطرف عن مواصلة العدو خروقاته وانتهاكاته».", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Head of the Loyalty to the Resistance bloc, MP Mohammad Raad, confirmed that direct negotiations with the Israeli enemy will place the country in a worse situation than it was placed in on May 17, advising the authorities to backtrack from this step.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Raad addressed the authorities, saying: 'You must be ashamed before the people and withdraw from what has been called direct negotiations with the Zionist enemy, and what we fear most from insisting on this mistake is that the country will fall into something worse than what it fell into on the ill-fated May 17 in the early eighties.'", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement today, Friday, he affirmed that 'any official communication or meeting between a Lebanese party and Israel while the ongoing war exists between Lebanon and the Zionist occupation entity will not receive any Lebanese national consensus whatsoever and will constitute a clear constitutional violation that no excuse or claimed interest will forgive.'", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He stressed that 'any supposed truce that grants the occupying enemy in Lebanon a special exception to open fire or carry out any movement or field action in confrontation areas and within Lebanese territory, whether to تثبيت موقع or plant a mine or carry out an assassination or blow up a house or facility or bulldoze land or the like, is not a truce at all, but rather a cunning deception and an act of misleading others that involves covering up Israeli aggression and turning a blind eye to the enemy’s continued violations and breaches.'", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/0c32836a-cd4f-4983-b75b-168184c3fcb7_16x9_1200x676-Zmjli7wVMzn0PpJ5WleLoi9OAi2Ejq.jpg', false, false, 47, 231, TIMESTAMP '2026-04-24 19:23:27.472', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'What history books did not mention 3: the concessions that opened the door to the occupation of Lebanese lands', 'ما لم تذكره كتب التاريخ 3: التنازلات التي فتحت الباب لإحتلال أراضٍ لبنانية', 'lebisr-invasion-part3', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الاجتياح المنسي… حين وصلت إسرائيل إلى الليطاني قبل 1978", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "تُقدّم كتب التاريخ اللبنانية عام 1978 كأول اجتياح إسرائيلي للبنان، لكن الوقائع تعود إلى عام 1948، حين تقدّمت القوات الإسرائيلية داخل الأراضي اللبنانية، وسيطرت على قرى عدة وصولًا إلى نهر الليطاني، في حدث لم يُوثّق رسميًا وبقي خارج الذاكرة العامة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "من “حيرام” إلى القرى السبع", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "خلال حرب 1948، أطلقت إسرائيل عملية “حيرام” للسيطرة على الجليل خلال 60 ساعة. ومع انهيار الدفاعات العربية، وصلت إلى الحدود اللبنانية، وسيطرت على القرى السبع ذات الغالبية اللبنانية الشيعية، والتي لا تزال محتلة حتى اليوم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بعدها، فتحت الطريق نحو الداخل اللبناني، مستفيدة من الغياب شبه الكامل للدولة والجيش في الجنوب.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "قرار رسمي بعدم المواجهة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في 14 أيار 1948، أقرّ الرئيس بشارة الخوري استراتيجية دفاعية تقتصر على حماية الداخل، ومنع الجيش من القتال خارج لبنان. وأكد فؤاد شهاب أن الجيش “دفاعي لا هجومي” لتجنّب إعطاء ذريعة لإسرائيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "حتى مع وجود قوات سورية في بنت جبيل، تراجعت الدولة عن المواجهة بعد معركة المالكية، ولم تُبدِ حماسة للدفاع عن المناطق الحدودية، التي كانت بغالبيتها من المسلمين الشيعة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مناشير ثم اجتياح", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في 28 تشرين الأول 1948، ألقت إسرائيل مناشير تحذّر اللبنانيين من التدخل، زاعمة أنها لا تريد إيذاء لبنان. لكن بعد أيام، استكملت هجومها داخل الأراضي اللبنانية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مجزرة حولا", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في 30 تشرين الأول، قصفت إسرائيل قرية حولا رغم خلوّها من أي وجود عسكري، لتكون أول قرية تُحتل داخل الحدود. وفي اليوم التالي، أعدمت 34 مدنيًا ونسفت منازل فوق رؤوسهم، ما أدى إلى سقوط أكثر من 85 شهيدًا خلال 24 ساعة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "15 قرية خلال ساعات", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "خلال نحو 12 ساعة، سيطرت القوات الإسرائيلية على 15 قرية لبنانية وصولًا إلى الليطاني، من دون مقاومة تُذكر.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "صمت الدولة وتغييب الحقيقة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "بدل المواجهة، طلبت الدولة من واشنطن الضغط على إسرائيل، فقوبل الطلب بالرفض ودُعيت بيروت للتوجه إلى مجلس الأمن. لكن بشارة الخوري فضّل عدم تقديم شكوى لإبقاء القضية سرية، خوفًا من المساءلة الداخلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "حتى أن بعض السياسيين نفوا حصول الاجتياح، واعتمدت الدولة سياسة الصمت، ما أدى إلى تغييب الحدث عن التاريخ الرسمي.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "نتيجة خطيرة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "أدركت إسرائيل من هذه التجربة أن الدولة اللبنانية ليست عائقًا حقيقيًا، لا عسكريًا ولا سياسيًا، ما فتح الباب لاحقًا لاجتياحات أوسع وصولًا إلى بيروت.", "type": "text"}, {"type": "hardBreak"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "The forgotten invasion… when Israel reached the Litani before 1978", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Lebanese history books present 1978 as the first Israeli invasion of Lebanon, but the facts go back to 1948, when Israeli forces advanced into Lebanese territory and took control of several villages, reaching the Litani River, in an event that was not officially documented and remained outside public memory.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "From Hiram to the seven villages", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "During the 1948 war, Israel launched Operation Hiram to control the Galilee within 60 hours. With the collapse of Arab defenses, it reached the Lebanese border and took control of the seven villages with a Shiite Lebanese majority, which remain occupied to this day.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It then opened the way into the Lebanese الداخل, taking advantage of the near total absence of the state and army in the south.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "An official decision not to confront", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "On May 14, 1948, President Bishara al-Khoury adopted a defensive strategy limited to protecting the الداخل and preventing the army from fighting outside Lebanon. Fouad Chehab confirmed that the army was defensive, not offensive, to avoid giving Israel a pretext.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Even with Syrian forces present in Bint Jbeil, the state withdrew from confrontation after the Battle of Malkiya and showed little enthusiasm to defend the border areas, which were mostly inhabited by Shiite Muslims.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Leaflets then invasion", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "On October 28, 1948, Israel dropped leaflets warning Lebanese not to intervene, claiming it did not want to harm Lebanon. But days later, it continued its advance into Lebanese territory.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "The Hula massacre", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "On October 30, Israel shelled the village of Hula despite the absence of any military presence, making it the first village to be occupied within the borders. The next day, it executed 34 civilians and blew up homes over their heads, resulting in more than 85 martyrs within 24 hours.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "15 villages in hours", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Within about 12 hours, Israeli forces took control of 15 Lebanese villages up to the Litani, with no resistance.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "State silence and erasure of the truth", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Instead of confronting, the state asked Washington to pressure Israel, but the request was rejected, and Beirut was advised to go to the UN Security Council. However, Bishara al-Khoury preferred not to file a complaint to keep the issue secret, fearing internal accountability.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Some politicians even denied that the invasion had occurred, and the state adopted a policy of silence, leading to the event being erased from official history.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A dangerous outcome", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "From this experience, Israel realized that the Lebanese state was not a real obstacle, neither militarily nor politically, which later opened the door to broader invasions reaching Beirut.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Israel-Defense-Forces-Operation-Horev-1948-Arab-Israeli-War-Egypt-3hIELos26l2XVv2dUkxRVrE8jmxhen.jpg', true, false, 1699, 3268, TIMESTAMP '2026-04-25 16:42:34.861', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'history'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Leaks about the Ministry of Education’s plan for the Brevet exams', 'تسريبات حول خطة وزارة التربية لامتحانات البريفيه', 'brevet-leaks', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نقلا عن طلاب لبنان، إليكم خطة الوزارة للإمتحانات البريفيه", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "1 – خطة الوزارة هي بإجراء امتحانات موحّدة في كل لبنان يجريها الطلاب في مدارسهم تحت عنوان \"امتحان وطني\"", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "2 – المسابقات ترسلها الوزارة الى المدارس صباحًا عبر الإيميل، وتقوم المدارس بطباعتها، ثم توزعها على الطلاب في الأوقات التي تحددها الوزارة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "3 – الامتحانات ستجري في كل المواد", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "4 – أساتذة المدرسة سيقومون بتصحيح المسابقات داخل المدرسة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "5 - ترسل الإدارة العلامات للوزارة ثم تقوم الوزارة بإصدار النتائج والشهادات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• شكوك كبيرة حول عملية المراقبة داخل المدارس حيث سيتولّى أساتذة المدرسة المراقبة على طلابهم", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• شكوك أيضًا حول عملية التصحيح، حيث يهمّ المدرسة أن ينال طلابها علامات عالية، مما يؤثر على شفافية التصحيح ووضع العلامات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• احتمال أن النتيجة النهائية ستكون موزعة بين علامات المدرسة + الامتحان الوطني", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "(50% للعلامات + 50% للوطني) ولم يتم حسم هذا التفصيل حتى الآن", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "According to Tollab Lebnen, here is the ministry’s plan for the Brevet exams", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "1 – The ministry’s plan is to conduct unified exams across Lebanon, taken by students in their schools under the title national exam", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "2 – The exam papers will be sent by the ministry to schools in the morning via email, schools will print them, then distribute them to students at the times set by the ministry", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "3 – Exams will be held in all subjects", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "4 – School teachers will correct the exams inside the school", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "5 – The administration will send the grades to the ministry, then the ministry will issue the results and certificates", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• There are major doubts about the monitoring process inside schools, as school teachers will supervise their own students", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• There are also doubts about the correction process, as schools have an interest in their students receiving high grades, which affects the transparency of grading", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• There is a possibility that the final result will be divided between school grades and the national exam", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "(50% for grades + 50% for the national), and this detail has not yet been finalized", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/678945251108-uAH9golExGPbpbEkB5yKE7sk59nof7.jpg', false, false, 714, 1948, TIMESTAMP '2026-04-26 09:57:40.217', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Iran’s attacks on US bases… greater damage than declared and a multi-billion-dollar bill', 'هجمات إيران على القواعد الأميركية… أضرار أكبر من المعلن وفاتورة بمليارات الدولارات', 'usdamage-bills', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "خسائر أوسع من الرواية الرسمية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "كشفت شبكة “إن بي سي نيوز”، نقلًا عن مصادر مطلعة، أن الهجمات الإيرانية التي استهدفت قواعد عسكرية أميركية في الشرق الأوسط منذ اندلاع الحرب في 28 شباط 2026، خلّفت أضرارًا أوسع بكثير مما تم الاعتراف به علنًا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب التقرير، فإن الضربات التي طالت قواعد أميركية في عدد من دول المنطقة ألحقت أضرارًا “أشد بكثير” من الروايات الرسمية، وسط تقديرات بأن أعمال الإصلاح وإعادة التأهيل قد تتطلب ميزانيات بمليارات الدولارات.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مواقع حساسة تحت الضربات", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وأشار التقرير إلى أن إيران استهدفت عشرات المواقع الحساسة داخل تلك القواعد، بينها مستودعات أسلحة، مقار قيادة، بنى تحتية للاتصالات عبر الأقمار الصناعية، مدارج طائرات، أنظمة رادار متطورة، إضافة إلى عدد من الطائرات العسكرية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، لم تكشف وزارة الدفاع الأميركية تفاصيل دقيقة حول حجم الخسائر، فيما امتنعت القيادة المركزية الأميركية عن التعليق على تقييمات الأضرار القتالية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "استياء داخل الكونغرس", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ونقلت الشبكة عن مسؤولين في الكونغرس، بينهم نواب جمهوريون، أنهم عبّروا في أحاديث غير علنية عن استيائهم من غياب المعلومات التفصيلية حول حجم الخسائر وكلفة الإصلاح، خصوصًا مع مطالبة البنتاغون بميزانيات دفاعية قياسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال أحد مساعدي الكونغرس إن المشكلة ليست في غياب الأسئلة، بل في عدم الحصول على إجابات منذ أسابيع، رغم استمرار طلب البنتاغون تمويلًا إضافيًا.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "جدل حول الوجود الأميركي قرب إيران", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يرى التقرير أن حجم الأضرار والتكاليف المحتملة قد يفتح نقاشًا سياسيًا واسعًا داخل الولايات المتحدة حول جدوى استمرار نشر قواعد عسكرية قريبة من إيران في الشرق الأوسط.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي السياق نفسه، أفادت صحيفة “التايمز” بأن المواجهة مع إيران رتّبت فاتورة باهظة على واشنطن، مشيرة إلى فشل البنتاغون في التكيّف مع حرب المسيّرات، في ظل تحول الصراع من مواجهة تنظيمات مسلحة إلى حرب مع دولة وجيش نظامي.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "إيران بين الدمار والكلفة الاقتصادية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تشير التقارير إلى أن إيران نفسها تكبدت دمارًا واسعًا، مع تضرر أو تدمير أكثر من 7600 مبنى، بينها منشآت تعليمية وصحية وسكنية. وتركزت الأضرار خصوصًا في العاصمة، حيث أدى تداخل المناطق السكنية مع المنشآت العسكرية والصناعية إلى توسيع رقعة الدمار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "اقتصاديًا، قدّرت الحكومة الإيرانية الخسائر المباشرة وغير المباشرة بنحو 270 مليار دولار، وهو رقم يقترب من الناتج المحلي الإجمالي السنوي للبلاد. كما تضررت عشرات آلاف الوحدات السكنية، وتوقفت منشآت حيوية، وسط توقعات بارتفاع التضخم إلى أكثر من 70%.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "حرب بدأت بضربات مشتركة وردّ إيراني واسع", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وكانت إسرائيل والولايات المتحدة قد شنتا في 28 شباط هجمات مشتركة استهدفت طهران وعددًا من المدن الإيرانية، ما أدى إلى مقتل المرشد الأعلى الإيراني علي خامنئي وعدد من القادة العسكريين والمدنيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وردّت إيران بإطلاق موجات من الصواريخ والطائرات المسيّرة على إسرائيل وقواعد ومصالح أميركية في الشرق الأوسط، إضافة إلى فرض إجراءات مشددة على حركة الملاحة في مضيق هرمز، أحد أبرز الممرات البحرية الاستراتيجية في العالم.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Losses beyond the official narrative", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "NBC News revealed, citing informed sources, that the Iranian attacks targeting US military bases in the Middle East since the outbreak of the war on February 28, 2026, caused far more extensive damage than publicly acknowledged.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the report, the strikes that hit US bases across several countries in the region inflicted damage that was far more severe than official accounts, with estimates suggesting that repair and rehabilitation efforts may require budgets amounting to billions of dollars.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Sensitive sites under attack", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report indicated that Iran targeted dozens of sensitive locations within those bases, including weapons depots, command centers, satellite communications infrastructure, airstrips, advanced radar systems, in addition to several military aircraft.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, the US Department of Defense did not disclose precise details regarding the scale of the losses, and US Central Command declined to comment on battle damage assessments.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Frustration within Congress", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The network نقل عن officials in Congress, including Republican lawmakers, that they expressed frustration in private discussions over the lack of detailed information about the extent of the damage and repair costs, especially as the Pentagon is requesting record defense budgets.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "One congressional aide said the issue is not the lack of questions, but the absence of answers for weeks, despite the Pentagon continuing to seek additional funding.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Debate over US presence near Iran", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report suggests that the scale of the damage and potential costs may open a broad political debate within the United States about the feasibility of maintaining military bases close to Iran in the Middle East.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the same context, The Times reported that the confrontation with Iran imposed a heavy cost on Washington, noting the Pentagon’s failure to adapt to drone warfare, as the conflict shifted from fighting armed groups to confronting a state and a regular army.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Iran between destruction and economic cost", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, reports indicate that Iran itself sustained widespread destruction, with more than 7,600 buildings damaged or destroyed, including educational, health, and residential facilities. The damage was particularly concentrated in the capital, where the overlap between residential areas and military and industrial sites expanded the scope of destruction.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Economically, the Iranian government estimated direct and indirect losses at around $270 billion, a figure close to the country’s annual GDP. Tens of thousands of housing units were also affected, and vital facilities were shut down, with expectations of inflation rising above 70%.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A war that began with joint strikes and a wide Iranian response", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israel and the United States had launched joint attacks on February 28 targeting Tehran and several Iranian cities, resulting in the killing of Iran’s Supreme Leader Ali Khamenei and a number of military and civilian leaders.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Iran responded by launching waves of missiles and drones at Israel and US bases and interests in the Middle East, in addition to imposing strict measures on navigation in the Strait of Hormuz, one of the world’s most strategic maritime passages.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-pIy3WVEv77OgojW0K35jIC7ksFOdsR', false, false, 70, 214, TIMESTAMP '2026-04-26 13:26:12.920', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'After the Saqiet al-Janzir incident… generator owners reject chaos and call for fair regulation', 'بعد حادثة ساقية الجنزير… أصحاب المولدات يرفضون الفوضى ويطالبون بتنظيم عادل', 'gen-rej-chaos', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "استنكار الاعتداء والدعوة للمحاسبة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "أصدر \"تجمع أصحاب المولدات الخاصة\" بيانًا كشف فيه ملابسات حادثة ساقية الجنزير، مستنكرًا الاعتداء الذي تعرّض له أحد أصحاب المولدات، ومطالبًا بمحاسبة المسؤولين عبر الأطر القانونية والقضائية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وشدد التجمع على رفض أي أسلوب عنفي أو غير قانوني في معالجة الخلافات، معتبرًا أن أي مخالفة يجب أن تُعالج عبر المؤسسات المختصة، بما يحفظ كرامة جميع الأطراف.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "قطاع أساسي في ظل أزمة الكهرباء", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ولفت إلى الدور الذي يقوم به قطاع المولدات الخاصة في تأمين الكهرباء للمواطنين، خصوصًا في ظل العجز المزمن في إنتاج الطاقة، ما يستوجب التعاطي مع هذا القطاع بمسؤولية وتوازن.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مطالب بإعادة النظر في التسعيرة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ودعا التجمع الحكومة ووزارة الطاقة إلى إعادة النظر في آلية التسعيرة، ووضع مقاربة عادلة تراعي مصلحة المواطنين وأصحاب المولدات، بهدف تخفيف الاحتقان والحد من الإشكالات.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "توترات متكررة وغياب التنظيم", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "تأتي هذه الحادثة ضمن سلسلة توترات بين أصحاب المولدات والمواطنين، غالبًا ما ترتبط بالتسعيرة والالتزام بالمعايير، في ظل تضارب بين كلفة التشغيل المرتفعة والقدرة الشرائية المحدودة، إلى جانب ضعف الرقابة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الحاجة إلى حل جذري", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي ظل تكرار هذه الإشكالات، تتجدد الدعوات إلى تنظيم هذا القطاع بشكل واضح، وإصلاح قطاع الكهرباء بشكل جذري، بما يخفف الاعتماد على المولدات ويؤسس لعلاقة قانونية مستقرة بين الدولة والمشغلين والمواطنين.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Condemnation of the assault and call for accountability", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Association of Private Generator Owners issued a statement revealing the circumstances of the Saqiet al-Janzir incident, condemning the assault on one of the generator owners and calling for those responsible to be held accountable through legal and judicial channels.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The association stressed its rejection of any violent or illegal methods in handling disputes, considering that any violation must be addressed through the relevant institutions in a way that preserves the dignity of all parties.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A vital sector amid the electricity crisis", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It highlighted the role played by the private generator sector in providing electricity to citizens, especially in light of the chronic deficit in energy production, which requires dealing with this sector with responsibility and balance.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Calls to review pricing", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The association called on the government and the Ministry of Energy to reconsider the pricing mechanism and adopt a fair approach that takes into account the interests of both citizens and generator owners, with the aim of easing tensions and reducing disputes.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Recurring tensions and lack of regulation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This incident comes as part of a series of tensions between generator owners and citizens, often linked to pricing and compliance with standards, amid a mismatch between high operating costs and limited purchasing power, in addition to weak oversight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "The need for a fundamental solution", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "With the recurrence of such incidents, calls are renewed to clearly regulate this sector and implement comprehensive reform of the electricity sector, in a way that reduces reliance on generators and establishes a stable legal relationship between the state, operators, and citizens.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/r43fr4fg_603534-AvVZkeLTUVnBluLRNgcWzIR7X8KYBg.jpg', false, false, 31, 128, TIMESTAMP '2026-04-26 13:40:38.221', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Fragile stability at the mercy of dollar flows', 'استقرار هشّ في مهبّ الدولارات', 'usd-cris-lb', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "استقرار مبني على الهشاشة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "منذ عام 2023، توقّف انهيار الليرة اللبنانية عند حدود 89500 ليرة للدولار، ما أعطى انطباعًا بعودة نوع من الاستقرار بعد خسارتها نحو 99% من قيمتها منذ عام 2019. لكن هذا الاستقرار لم يكن نتيجة تعافٍ اقتصادي حقيقي، بل نتج عن إدارة دقيقة لنقص الدولار، عبر ضبط السيولة بالليرة وخلق توازن هشّ بين العرض والطلب على العملة الأجنبية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "اقتصاد بلا عملة فاعلة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في الواقع، لم يعد لليرة دور فعلي في الاقتصاد اللبناني، حيث باتت معظم العمليات مرتبطة بالدولار بشكل مباشر أو غير مباشر. ومع تصاعد التوترات الإقليمية وانخراط لبنان فيها، يصبح هذا “الاستقرار” أكثر عرضة للاهتزاز، لأنه قائم على عوامل خارجية لا يمكن التحكم بها داخليًا.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "الدولار من الخارج: أساس التوازن", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "يقوم استقرار سعر الصرف على قدرة الاقتصاد على جذب الدولارات من الخارج، لا على إنتاجها داخليًا. وتشير الدراسات إلى ثلاثة مصادر أساسية لهذا التدفق: تحويلات المغتربين، تطورات أسعار النفط، وضعف أو قوة الصادرات. إلا أنّ هذه العوامل الثلاثة باتت مهدّدة في الوقت نفسه، ما يضع الليرة أمام اختبار حقيقي.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تحويلات المغتربين ليست مضمونة", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "رغم أنها شكّلت صمّام أمان أساسيًا خلال السنوات الماضية، فإن تحويلات المغتربين تبقى مرتبطة بأداء اقتصادات الخليج. ومع تغيّر أولويات هذه الدول نحو إعادة الإعمار والاستثمار في قطاع الطاقة بعد الأزمات الأخيرة، قد تتراجع فرص العمل والدخل، وبالتالي تنخفض هذه التحويلات.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "النفط: عامل ضغط مضاعف", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ارتفاع أسعار النفط يشكّل عبئًا مزدوجًا على الاقتصاد اللبناني، إذ يزيد فاتورة الاستيراد ويُضعف القدرة على تمويلها. وفي ظل غياب بدائل للطاقة، يتحوّل هذا الارتفاع إلى تضخم داخلي سريع، يرفع الطلب على الدولار ويزيد الضغط على سعر الصرف.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تصدير شبه معطّل", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في المقابل، لا يقدّم التصدير أي دعم فعلي للاستقرار النقدي. فالاقتصاد اللبناني يعاني من ضعف مزمن في الصادرات، تفاقم بسبب القيود السياسية والتجارية، إضافة إلى صعوبات النقل عبر سوريا. وهذا يعمّق الاعتماد على الدولار القادم من الخارج بدل توليده محليًا.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "سياسة نقدية بلا أدوات حقيقية", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "المشكلة الأساسية أن هذه العوامل جميعها تقع خارج سيطرة مصرف لبنان، ما يجعل السياسة النقدية عاجزة عن التأثير الحقيقي. فاستقرار الليرة لم يعد مرتبطًا بقرارات داخلية، بل بمتغيرات إقليمية ودولية متقلّبة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "حلقة مغلقة تهدّد الاستمرار", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "تعتمد السياسة الحالية على سحب الليرة من السوق عبر الجباية وربط الإنفاق بالدولار، ما يجعل الاستقرار مرتبطًا باستمرار الاستيراد. لكن الاستيراد يحتاج إلى الدولار، والدولار يعتمد على تدفقات خارجية مهدّدة، ما يخلق حلقة مفرغة يصعب كسرها.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "السؤال ليس “إذا” بل “متى”", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "في ظل هذا الواقع، لم يعد السؤال ما إذا كانت الليرة ستتراجع مجددًا، بل متى سيبدأ هذا التراجع. فأي خلل في تدفّقات الدولار، في غياب احتياطات كافية، كفيل بإعادة فتح مسار الانهيار.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Fragile stability", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Since 2023, the collapse of the Lebanese pound has halted at around 89,500 per dollar, giving the impression of a return to a form of stability after losing about 99% of its value since 2019. But this stability is not the result of real economic recovery, rather it stems from a careful management of dollar scarcity, by controlling liquidity in the local currency and creating a fragile balance between supply and demand for foreign currency.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "An economy without an effective currency", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In reality, the pound no longer has an effective role in the Lebanese economy, as most transactions are now directly or indirectly tied to the dollar. With rising regional tensions and Lebanon’s involvement in them, this stability becomes more vulnerable to disruption, because it is based on external factors that cannot be controlled internally.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "External dollars as the basis of balance", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Exchange rate stability depends on the economy’s ability to attract dollars from abroad, not to generate them internally. Studies point to three main sources of these inflows: remittances from expatriates, developments in oil prices, and the strength or weakness of exports. However, all three factors are now simultaneously under threat, placing the pound before a real test.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Remittances are not guaranteed", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although they have served as a key safety valve in recent years, expatriate remittances remain tied to the performance of Gulf economies. With shifting priorities in these countries toward reconstruction and investment in the energy sector after recent crises, job opportunities and incomes may decline, leading to a drop in these transfers.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Oil as a double pressure factor", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rising oil prices impose a double burden on the Lebanese economy, as they increase the import bill and weaken the ability to finance it. In the absence of energy alternatives, this rise turns into rapid internal inflation, raising demand for dollars and increasing pressure on the exchange rate.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Nearly paralyzed exports", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, exports provide no real support for monetary stability. The Lebanese economy suffers from chronic export weakness, worsened by political and trade restrictions, in addition to transportation difficulties through Syria. This deepens reliance on dollars coming from abroad instead of generating them locally.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Monetary policy without real tools", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The core problem is that all these factors lie outside the control of the central bank, making monetary policy unable to exert real influence. The stability of the pound is no longer linked to internal decisions, but to fluctuating regional and international variables.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "A closed loop threatening sustainability", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The current policy relies on withdrawing local currency from the market through taxation and linking spending to the dollar, making stability dependent on continued imports. But imports require dollars, and dollars depend on external inflows under threat, creating a vicious cycle that is difficult to break.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "The question is not if, but when", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In light of this reality, the question is no longer whether the pound will decline again, but when this decline will begin. Any disruption in dollar inflows, in the absence of sufficient reserves, is enough to reopen the path of collapse.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/11Lebanon-Dispatch-articleLarge-buJkfgG3JHkzYDvizBdm2J8pcBY94S.jpg', false, false, 90, 252, TIMESTAMP '2026-04-27 08:05:43.105', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Martyrdom fighters are back… a party official: we will use 1980s tactics', 'الإستشهاديون عادوا... مسؤوول في الحزب: سنستخدم أساليب الثمانينيات', 'hezb-new-stat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كشف مسؤول في حزب الله، في حديث لقناة «الجزيرة»، أنّ الحزب سيعتمد تكتيكات تعود إلى ثمانينيات القرن الماضي، مع تفعيل مجموعات استشهادية لمنع استقرار العدو", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أنّ مجموعات كبيرة من الاستشهاديين ستنتشر في المناطق المحتلة وفق خطط معدّة مسبقًا، مشيرًا إلى أنّ مهمتها ستكون الالتحام المباشر مع ضباط وجنود العدو داخل القرى اللبنانية المحتلة", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "A Hezbollah official revealed, in an interview with Al Jazeera, that the party will adopt tactics dating back to the 1980s, with the activation of martyrdom units to prevent the enemy from stabilizing", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added that large groups of these fighters will be deployed in occupied areas according to pre-prepared plans, noting that their mission will be direct engagement with enemy officers and soldiers inside occupied Lebanese villages", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/4786650-4qlDjQWRhVT865O7GUPJbNl9DRjXhy.jpg', false, false, 275, 728, TIMESTAMP '2026-04-27 12:42:32.193', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'In a well-planned ambush in Downtown Beirut… the Information Branch arrests a wanted suspect for various crimes', ' بكمينٍ محكم في وسط بيروت... شعبة المعلومات توقف مطلوباً للقضاء بجرائم مختلفة', 'trap-dt-sus', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت المديرية العامة لقوى الأمن الداخلي ـ شعبة العلاقات العامة أنه في إطار المتابعة اليوميّة التي تقوم بها قوى الأمن الدّاخلي لتوقيف المطلوبين للقضاء في مختلف الجرائم على كل الأراضي اللّبنانية، وبنتيجة المتابعة الميدانية والاستعلامية، تمكّنت القطعات المختصة في شعبة المعلومات من تحديد مكان وجود أحد المطلوبين في محلّة وسط بيروت، ويُدعى: ع. ن. (مواليد العام 1996، لبناني)، بحقّه تسع مذكّرات عدلية بجرائم سرقة، محاولة قتل، مخدّرات، تأليف عصابة، تأليف جمعيّة لارتكاب الجنايات، مقاومة رجال السّلطة، ومخالفة الأنظمة والقوانين.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وأفادت بأنه بتاريخ 16-4-2026، وبعد عمليّة رصد ومراقبة دقيقة، تمكّنت إحدى دوريّات الشّعبة من توقيفه بكمينٍ محكمٍ في المحلّة المذكورة.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وقد أُجري المقتضى القانوني بحقّه، وأودع المرجع المعنيّ، بناءً على إشارة القضاء المختصّ.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The General Directorate of the Internal Security Forces – Public Relations Division announced that, as part of the daily follow-up carried out by the Internal Security Forces to arrest individuals wanted by the judiciary for various crimes across Lebanese territory, and as a result of field and intelligence tracking, specialized units of the Information Branch were able to determine the location of one of the wanted individuals in Downtown Beirut, identified as A. N. (born in 1996, Lebanese), who is subject to nine judicial warrants for crimes including theft, attempted murder, drugs, forming a gang, forming an association to commit felonies, resisting authorities, and violating laws and regulations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It added that on 16-4-2026, after a precise surveillance and monitoring operation, one of the branch’s patrols managed to arrest him in a well-planned ambush in the المذكورة area.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Legal procedures have been carried out against him, and he has been referred to the competent authority upon the direction of the relevant judiciary.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-928214-639129086994494275-XIf7ZNBxqYx5ZRFkpLH9HvnhbTr27X.jpeg', false, false, 92, 408, TIMESTAMP '2026-04-27 19:11:18.374', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Hezbollah and Amal call for postponing exams and canceling the Brevet', 'مطالب من حزب الله و أمل بتأجيل الامتحانات وإلغاء «البروفيه»', 'hzb-amal-stat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "طالب حزب الله وحركة أمل وزارة التربية بالتريّث في تثبيت مواعيد امتحانات الشهادة الثانوية الرسمية، والدعوة إلى إلغاء شهادة المتوسطة «البروفيه» لهذا العام والاكتفاء بنتائج العلامات المدرسية، في ظل الظروف الاستثنائية في المناطق الجنوبية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ودعا الطرفان، في بيان مشترك، إلى تقليص المناهج من 24 إلى 18 أسبوعًا، وتأجيل تطبيق المناهج الجديدة إلى حين استكمال إعدادها وتأمين الاستقرار الأمني ووضع خطة تدريبية واضحة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما شدد البيان على ضرورة الحفاظ على كيان المدارس الرسمية في المناطق المتضررة، والاستمرار في استخدامها كمراكز لإيواء النازحين من دون ممارسة أي ضغوط عليهم، إلى جانب تقديمها كمراكز إضافية عند الحاجة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الشق المالي، طالب بإعفاء المدارس الخاصة في المناطق الحدودية من اشتراكات الضمان، وإقرار سلسلة رواتب جديدة تراعي التضخم، وصرف مستحقات الأساتذة، وتسوية أوضاع المتعاقدين، إلى جانب دعم أساتذة الجامعة اللبنانية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبر البيان أنّ هذه الإجراءات تشكّل «ضرورة تربوية ووطنية» لضمان استمرارية القطاع التعليمي في ظل الظروف الراهنة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Hezbollah and the Amal Movement called on the Ministry of Education to wait before confirming the dates of the official secondary certificate exams, and to cancel the intermediate certificate Brevet for this year, relying instead on school grades, in light of the exceptional conditions in the southern regions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a joint statement, the two parties also called for reducing the curriculum from 24 to 18 weeks, and postponing the implementation of the new curricula until they are fully prepared, security stability is ensured, and a clear training plan is established.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The statement also stressed the need to preserve public schools in the affected areas and continue using them as shelters for displaced people without applying any pressure on them, in addition to providing them as additional shelter centers when needed.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the financial side, it called for exempting private schools in border areas from social security contributions, approving a new salary scale that takes inflation into account, paying teachers’ dues, settling the status of contracted staff, and supporting Lebanese University professors.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The statement considered these measures a necessary educational and national step to ensure the continuity of the education sector under the current conditions.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/678945251108-plH1cdKGRcjaIOda44u24qJXbAYGYm.jpg', false, false, 59, 267, TIMESTAMP '2026-04-28 16:36:33.315', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'US ambiguity unsettles Tel Aviv: between rejecting the Iranian offer and a temporary agreement', 'غموض أميركي يربك تل أبيب: بين رفض العرض الإيراني واتفاق مرحلي', 'us-isr-ambiguity', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في ظل تصاعد التوتر بين واشنطن وطهران، تتزايد حالة الضبابية حول الموقف الأميركي من المقترح الإيراني الأخير، ما ينعكس مباشرة على حسابات تل أبيب ويضعها أمام سيناريوهات متناقضة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في هذا السياق، كشفت صحيفة «يديعوت أحرونوت» عن حالة ارتباك داخل إسرائيل نتيجة غموض مواقف الرئيس الأميركي دونالد ترامب، متسائلة عمّا إذا كان سيتجه إلى رفض العرض الإيراني أو التعامل معه ضمن مقاربة مرحلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت الصحيفة إلى أن تصريحات ترامب الأخيرة، ولا سيما منشوره عبر «تروث سوشيل» الذي تحدث فيه عن «حالة انهيار» في إيران وطلبها فتح مضيق هرمز، لم تتضمن رفضًا صريحًا للمقترح، ما زاد من حالة عدم اليقين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب القراءة الإسرائيلية، يقوم العرض الإيراني على فتح مضيق هرمز بالتوازي مع رفع الحصار الأميركي، مقابل ضمانات بإنهاء الحرب، وتأجيل الملفات الأساسية، وعلى رأسها البرنامج النووي، إلى مراحل لاحقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما لفتت إلى أن ترامب يكرر الحديث عن انقسام داخل القيادة الإيرانية، وهو ما يستخدمه لتبرير تمديد وقف إطلاق النار من دون تحديد سقف زمني، بانتظار «رد منظم» من طهران، رغم نفي إيران لهذه المعطيات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، نقلت تقارير أميركية، بينها «سي إن إن» و«نيويورك تايمز»، أن موقف ترامب داخل الاجتماعات الأمنية أكثر تحفظًا، إذ يرفض فتح مضيق هرمز قبل معالجة ملف تخصيب اليورانيوم، خشية خسارة أوراق الضغط.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشارت إلى أن ترامب غير راضٍ عن العرض، لا سيما أنه يتمسك بشرط منع إيران من امتلاك سلاح نووي مستقبلًا، فيما يرى بعض مستشاريه أن القبول به قد يُفسَّر كتنازل يحرمه من «إعلان النصر».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي موازاة ذلك، كشفت الصحيفة عن انقسام داخل الإدارة الأميركية بشأن جدوى الاستمرار في الحصار البحري، إذ يرى فريق أن تمديده قد يدفع طهران إلى تقديم تنازلات، بينما يشكك آخرون في ذلك، في ظل تشدد إيران ورفضها التراجع عن برنامجها النووي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تؤكد طهران تمسكها بموقفها، حيث شدد المتحدث باسم لجنة الأمن القومي في البرلمان الإيراني على أن بلاده «لن تساوم» في الملف النووي، في وقت أعلن فيه مسؤول عسكري أن الاستعدادات لاستئناف الضربات لا تزال قائمة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب التحليل، فإن الإشكالية الأساسية بالنسبة لإسرائيل لا تكمن فقط في الموقف الإيراني، بل في غياب وضوح الموقف الأميركي، ما يضعها أمام تحدي التعامل مع سيناريوهات مفتوحة، في ظل احتمال تمرير اتفاق مرحلي لا يعالج جوهر الخلاف.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Amid escalating tensions between Washington and Tehran, uncertainty is growing over the US position on the latest Iranian proposal, directly impacting Tel Aviv’s calculations and placing it before conflicting scenarios.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Yedioth Ahronoth revealed a state of confusion داخل Israel due to the ambiguity of US President Donald Trump’s positions, questioning whether he will move toward rejecting the Iranian offer or dealing with it within a phased approach.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The newspaper pointed out that Trump’s recent statements, particularly his post on Truth Social in which he spoke of a state of collapse in Iran and its request to reopen the Strait of Hormuz, did not include an explicit rejection of the proposal, increasing uncertainty.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the Israeli reading, the Iranian offer is based on reopening the Strait of Hormuz in parallel with lifting the US blockade, in exchange for guarantees to end the war and postponing core issues, primarily the nuclear program, to later stages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It also noted that Trump continues to speak of divisions within the Iranian leadership, using this to justify extending the ceasefire without setting a time frame, while waiting for an organized response from Tehran, despite Iran denying these claims.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, US reports, including CNN and The New York Times, indicated that Trump’s position inside security meetings is more cautious, as he refuses to reopen the Strait of Hormuz before addressing uranium enrichment, fearing the loss of leverage.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They also noted that Trump is dissatisfied with the offer, especially as he insists on preventing Iran from acquiring nuclear weapons in the future, while some of his advisers believe accepting it could be interpreted as a concession that would deprive him of declaring victory.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, the newspaper revealed divisions within the US administration over the usefulness of continuing the naval blockade, with one camp believing its extension could push Tehran to make concessions, while others doubt this, given Iran’s firm stance and refusal to retreat from its nuclear program.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, Tehran continues to adhere to its position, with the spokesperson for the Iranian parliament’s National Security Committee stressing that Iran will not compromise on the nuclear issue, while a military official confirmed that preparations to resume strikes remain in place.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the analysis, the core problem for Israel lies not only in the Iranian position, but in the lack of clarity in the US stance, placing it before the challenge of dealing with open-ended scenarios, amid the possibility of passing a temporary agreement that does not address the root of the dispute.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/licensed-image-Ezo3sHULNaKq6VZc6n5Had22gslH65', false, false, 22, 82, TIMESTAMP '2026-04-28 17:11:50.881', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'April bids farewell with fragile stability… local rain and fog dominate the atmosphere', 'نيسان يودّع باستقرار هشّ… أمطار محلية وضباب يخيّمان على الأجواء', 'end-ap-wea', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يستمر الطقس في لبنان خلال هذه الفترة الربيعية بحالة من عدم الاستقرار النسبي، حيث تتناوب الأجواء بين فترات من الغيوم وفرص هطول أمطار محلية، لا سيما في المناطق الداخلية والشمالية الشرقية. وتُعد هذه التقلبات سمة طبيعية للمرحلة الانتقالية، التي تترافق عادةً مع ضباب كثيف على المرتفعات وفوارق واضحة في درجات الحرارة بين الساحل والداخل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا الإطار، أوضحت رئيسة فرع التقديرات في مصلحة الأرصاد الجوية منى عمر، في حديث إلى \"ليبانون ديبايت\"، أن طقس يوم الأربعاء سيكون بين الصحو الجزئي والغائم، مع تشكّل ضباب على المرتفعات، وارتفاع طفيف في درجات الحرارة خاصة في المناطق الجبلية والداخلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت إلى أنّ الغيوم تبدأ بالتكاثف اعتبارًا من بعد الظهر في المناطق الداخلية، وخصوصًا في الشمال الشرقي، ما يهيئ الأجواء لتساقط أمطار متفرقة قد تترافق مع برق ورعد ورياح ناشطة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما يوم الخميس، فتوقعت أن يكون الطقس غائمًا جزئيًا مع استمرار الارتفاع في درجات الحرارة، لا سيما في الداخل وعلى المرتفعات، إلى جانب تشكّل ضباب محلي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبالنسبة ليوم الجمعة، لفتت إلى أنّ الأجواء ستكون بين قليلة الغيوم وغائمة جزئيًا، مع ضباب كثيف يبدأ من ارتفاعات منخفضة نتيجة ارتفاع نسبة الرطوبة، فيما تبقى درجات الحرارة ضمن معدلاتها المعتادة، مع احتمال هطول أمطار خفيفة ومتفرقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ما يخص يوم السبت، توقعت أن يكون الطقس غائمًا جزئيًا بسحب متوسطة ومرتفعة، مع ارتفاع إضافي في درجات الحرارة، واستمرار تشكّل الضباب على المرتفعات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ما يتعلق بالمعدلات الطبيعية لدرجات الحرارة خلال شهر نيسان، أشارت إلى أنها تتراوح في بيروت بين 15 و24 درجة، وفي طرابلس بين 13 و23 درجة، وفي زحلة بين 9 و22 درجة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما بيّنت أن الرياح السطحية تكون جنوبية غربية بسرعة تتراوح بين 10 و35 كيلومترًا في الساعة، فيما تتراوح نسبة الرطوبة على الساحل بين 65 و85 في المئة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Weather in Lebanon during this spring period continues in a state of relative instability, with conditions alternating between periods of cloudiness and chances of local rainfall, especially in inland and northeastern areas. These fluctuations are a natural feature of the transitional phase, usually accompanied by dense fog over the highlands and clear temperature differences between the coast and inland regions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Mona Omar, head of the Forecasting Department at the Meteorological Service, explained in an interview with Lebanon Debate that Wednesday’s weather will range between partly clear and cloudy, with fog forming over the highlands and a slight rise in temperatures, especially in mountainous and inland areas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "She noted that clouds will begin to thicken starting in the afternoon in inland regions, particularly in the northeast, creating conditions for scattered rainfall that may be accompanied by thunder, lightning, and active winds.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As for Thursday, she expected partly cloudy weather with a continued rise in temperatures, especially inland and over the highlands, along with the formation of local fog.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding Friday, she pointed out that conditions will range between mostly clear and partly cloudy, with dense fog forming at lower elevations due to increased humidity, while temperatures remain within seasonal averages, with a chance of light and scattered rain.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For Saturday, she expected partly cloudy weather with medium and high clouds, a further rise in temperatures, and continued fog formation over the highlands.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As for average temperatures during April, she noted that they range in Beirut between 15 and 24 degrees, in Tripoli between 13 and 23 degrees, and in Zahle between 9 and 22 degrees.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "She also indicated that surface winds will be southwesterly at speeds between 10 and 35 km/h, while coastal humidity ranges between 65 and 85 percent.", "type": "text"}]}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-10b0l0HsNLzzEMs91iUC3dj31Ov8nx', false, false, 17, 84, TIMESTAMP '2026-04-29 12:11:47.783', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'weather'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Israeli admission of failure to counter Hezbollah drones', 'إعتراف إسرائيلي بفشل التصدي لمسيرات حزب الله', 'isr-adm-hzbdrone', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يتزايد القلق داخل الأوساط العسكرية الإسرائيلية مع تصاعد استخدام حزب الله للمسيّرات الانقضاضية في جنوب لبنان، في ظل المواجهات المستمرة. هذا السلاح لم يعد مجرد أداة دعم، بل تحوّل إلى عنصر أساسي في إدارة المعركة، سواء من حيث التأثير الميداني أو الضغط النفسي على القوات الإسرائيلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتعترف مصادر أمنية إسرائيلية بوجود فجوة في الاستعداد لمواجهة هذا النوع من التهديد. فقد نقل موقع «i24NEWS» عن مسؤول أمني أن استخدام المسيّرات المفخخة شكّل مفاجأة في ساحة القتال، مؤكداً أن الجيش لم يطوّر جاهزية كافية للتعامل معها، وأن التدريبات المرتبطة بها بدأت بشكل محدود فقط مع انطلاق العمليات. كما أشارت تقارير عبرية، بينها قناة «كان»، إلى أن هذا الخطر كان معروفاً منذ سنوات، لكن التعامل معه بقي دون المستوى المطلوب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في الميدان، تظهر فعالية هذه المسيّرات بوضوح. إذ يعتمد حزب الله بشكل متزايد على مسيّرات «FPV» الانتحارية، التي تتمتع بدقة عالية وقدرة على المناورة في بيئات معقدة، ما يجعلها فعالة ضد القوات البرية. ووفق إذاعة جيش الاحتلال، يتم استخدام عشرات المسيّرات أسبوعياً، سواء لتنفيذ هجمات مباشرة أو لإسقاط ذخائر على أهداف عسكرية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "هذا التحدي دفع القوات الإسرائيلية إلى اتخاذ إجراءات توصف بالمحدودة أو الارتجالية. فقد لجأت بعض الوحدات إلى نصب شبكات حماية فوق مواقعها، فيما تقتصر التعليمات الميدانية في أحيان كثيرة على الرصد وإطلاق النار. هذه الإجراءات لم تُخفِ حالة الإحباط داخل الوحدات، حيث نقلت إذاعة الجيش عن ضباط ميدانيين اعترافهم بصعوبة التعامل مع هذا التهديد وقلة الخيارات المتاحة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "على مستوى القيادة العسكرية، أصبح ملف المسيّرات في صلب النقاشات. وذكرت إذاعة الجيش أن هذا التهديد كان محور اجتماعات في قاعدة «رامات دافيد»، حيث وُصف بأنه تحدٍ كبير يتطلب إعادة نظر في أساليب المواجهة. وفي السياق نفسه، أفاد موقع «i24NEWS» بأن الاستخبارات العسكرية الإسرائيلية بدأت العمل على استهداف البنية الكاملة المرتبطة بهذه المسيّرات، بما يشمل الموردين والمشغّلين والمعدات، في محاولة للحد من انتشارها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من جهتها، انتقدت الصحافة العبرية أداء الجيش في هذا الملف. فقد اعتبرت صحيفة «معاريف» أن إسرائيل، رغم امتلاكها منظومات دفاعية متقدمة مثل «آرو» وطائرات «F-35»، عجزت عن مواجهة مسيّرات منخفضة الكلفة، في مشهد يعيد إلى الأذهان إخفاقات سابقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "سياسياً، يسعى المسؤولون الإسرائيليون إلى ربط العمليات الجارية بهدف تقليص قدرات حزب الله. وفي هذا الإطار، أكد وزير الخارجية جدعون ساعر أن الوجود العسكري الإسرائيلي في لبنان مرتبط بتفكيك بنية الحزب العسكرية، مشيراً إلى أن استمرار هذا الوجود مرهون ببقاء التهديد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ميدانياً، يواصل حزب الله استخدام المسيّرات كجزء من ردّه على خروقات وقف إطلاق النار، حيث أعلن تنفيذ عدة عمليات استهدفت آليات وتجمعات عسكرية، بينها جرافة ودبابة «ميركافا»، إضافة إلى مواقع عسكرية، مؤكداً تحقيق إصابات مباشرة في هذه الهجمات.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Concern is growing within Israeli military circles as Hezbollah intensifies its use of attack drones in southern Lebanon amid ongoing confrontations. This weapon is no longer just a support tool, but has become a central element in managing the battle, both in terms of field impact and psychological pressure on Israeli forces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli security sources acknowledge a gap in preparedness to مواجهة this type of threat. The i24NEWS website quoted a security official saying that the use of explosive drones came as a surprise on the battlefield, confirming that the army had not developed sufficient readiness to deal with them, and that related training only began in a limited manner with the start of operations. Hebrew reports, including from Kan channel, also noted that this threat had been known for years, but the response to it remained below the required level.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the ground, the effectiveness of these drones is clearly evident. Hezbollah increasingly relies on FPV suicide drones, which offer high precision and maneuverability in complex environments, making them effective against ground forces. According to Israeli Army Radio, dozens of drones are used weekly, whether for direct attacks or dropping munitions on military targets.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This challenge has pushed Israeli forces to adopt measures described as limited or improvised. Some units have resorted to installing protective nets over their positions, while field instructions often remain limited to surveillance and opening fire. These measures have not hidden the sense of frustration within units, as army radio quoted field officers admitting the difficulty of dealing with this threat and the lack of available options.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the military leadership level, the drone file has become central in discussions. Army radio reported that this threat was the focus of meetings at Ramat David base, where it was described as a major challenge requiring a reassessment of confrontation methods. In the same context, i24NEWS reported that Israeli military intelligence has begun working on targeting the entire infrastructure linked to these drones, including suppliers, operators, and equipment, in an attempt to limit their spread.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For its part, the Hebrew press has criticized the army’s performance on this issue. Maariv newspaper considered that Israel, despite possessing advanced defense systems such as Arrow and F-35 aircraft, has failed to confront low-cost drones, in a scene reminiscent of past failures.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Politically, Israeli officials are seeking to link ongoing operations to the goal of reducing Hezbollah’s capabilities. In this context, Foreign Minister Gideon Sa’ar stated that the Israeli military presence in Lebanon is tied to dismantling Hezbollah’s military structure, noting that the continuation of this presence depends on the persistence of the threat.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the ground, Hezbollah continues to use drones as part of its response to ceasefire violations, announcing several operations targeting vehicles and military تجمعات, including a bulldozer and a Merkava tank, as well as military positions, confirming direct hits in these attacks.", "type": "text"}]}]}$c$::jsonb, 'https://pbs.twimg.com/card_img/2048806839567998976/Ri-VEcJX?format=jpg&name=900x900', false, false, 546, 1805, TIMESTAMP '2026-04-29 12:49:23.295', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'New generator tariffs for April: how much did it cost subscribers?', 'تسعيرة جديدة لمولدات نيسان: كم بلغت الكلفة على المشتركين؟', 'generator-price-april26', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت وزارة الطاقة والمياه أنّ «السعر العادل» لتعرفات المولدات الكهربائية الخاصة عن شهر نيسان حدّد بـ49,395 ليرة لبنانية لكل كيلواط/ساعة للمناطق الواقعة دون 700 متر أو ضمن المدن والتجمعات المكتظة، و54,335 ليرة لكل كيلواط/ساعة للمناطق المرتفعة أو المتباعدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت أنّه بالنسبة للمشتركين بالعدادات في المدن، بلغت التسعيرة الثابتة 385,000 ليرة لاشتراك 5 أمبير و685,000 ليرة لاشتراك 10 أمبير، على أن تُضاف الكلفة الشهرية وفق الاستهلاك. أما في القرى والمناطق المرتفعة، فتعتمد نفس الشطور الثابتة مع احتساب الكيلواط/ساعة وفق التسعيرة الأعلى. كما يُضاف 300,000 ليرة على الشطر الثابت لكل 5 أمبير إضافي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت الوزارة إلى أنّ هذه التسعيرة مبنية على متوسط سعر صفيحة المازوت في نيسان، البالغ 2,480,683 ليرة، مع احتساب مختلف التكاليف التشغيلية وهامش ربح لأصحاب المولدات، إضافة إلى كلفة التوزيع وسعر صرف وسطي للدولار بلغ 89,700 ليرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت أنّ التسعيرة صادرة وفق الآلية المعتمدة منذ عام 2010 وقرارات مجلس الوزراء ذات الصلة، بالتنسيق مع وزارات الداخلية والاقتصاد، مشيرة إلى أنها أحالت التسعيرة إلى الجهات المعنية لمتابعة تنفيذها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ودعت الوزارة أصحاب المولدات إلى الالتزام بتركيب العدادات وعدم فرض أي رسوم إضافية غير قانونية، مثل ضريبة القيمة المضافة غير المسجّلة أو كلفة الصيانة أو رسوم على مستخدمي الطاقة الشمسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما شددت على ضرورة تكثيف الرقابة من قبل وزارة الاقتصاد والجهات المعنية لضمان حسن تطبيق التسعيرة واتخاذ الإجراءات بحق المخالفين، لافتة إلى نشر جدول تركيب الأسعار على موقعها الرسمي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Ministry of Energy and Water announced that the “fair price” for private generator tariffs for the month of April has been set at 49,395 Lebanese pounds per kilowatt/hour for areas below 700 meters or within cities and densely populated areas, and 54,335 pounds per kilowatt/hour for higher or more remote areas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It explained that for subscribers with meters in cities, the fixed tariff amounts to 385,000 pounds for a 5-amp subscription and 685,000 pounds for a 10-amp subscription, with the monthly cost added based on consumption. In villages and higher مناطق, the same fixed tiers apply, with the kilowatt/hour calculated according to the higher tariff. An additional 300,000 pounds is added to the fixed tier for each extra 5 amps.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry indicated that this tariff is based on the average price of a diesel can in April, which reached 2,480,683 pounds, taking into account various operational costs, a profit margin for generator owners, distribution costs, and an average exchange rate of 89,700 pounds per dollar.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It confirmed that the tariff is issued according to the mechanism adopted since 2010 and relevant Council of Ministers decisions, in coordination with the Ministries of Interior and Economy, noting that it has been referred to the concerned authorities for follow-up on its implementation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry called on generator owners to comply with installing meters and not to impose any additional illegal fees, such as unregistered VAT, maintenance costs, or charges on solar energy users.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It also stressed the need to intensify monitoring by the Ministry of Economy and relevant authorities to ensure proper implementation of the tariff and to take action against violators, noting that the price schedule has been published on its official website.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/466989_677355-klNdB2YV0l4zEstzd9bSRabM3Q6oab.jpeg', false, false, 154, 649, TIMESTAMP '2026-04-29 15:59:31.354', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A “friendly” dispute between the two presidents… what is the difference between the ceasefire under Aoun’s approach and the one approved by Berri?', 'خلاف "ودي" بين الرئيسين... ما الفارق بين وقف إطلاق النار وفق مقاربة عون وذلك الذي أقرّه بري؟', 'dispute-berri-aoun', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يثير الجدل بين رئيس مجلس النواب نبيه بري والرئيس جوزاف عون تساؤلات حول طبيعة اتفاق وقف إطلاق النار، خصوصًا بعدما أكّد عون أنّ الاتفاق الذي وُقّع هو نفسه الذي كان قد وقّعه بري، قبل أن يردّ الأخير بعد ساعات قليلة بأنّه ليس الاتفاق نفسه، بل يختلف عنه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في اتفاق بري (تشرين الثاني 2024)، النص واضح: “لن تنفّذ إسرائيل أي عمليات عسكرية هجومية ضد أهداف لبنانية”، ما يعني حظرًا صريحًا للضربات داخل لبنان وتكريسًا لوقف شامل للأعمال العدائية، مع حق دفاع عن النفس ضمن إطار محدود.", "type": "text"}]}, {"type": "image", "attrs": {"alt": null, "src": "https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/content/1000690242-aAeXHLj1E9xdZ1KZHqFNCI56lFXsIK.jpg", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "أما في اتفاق جوزاف عون (نيسان 2026)، فتتغيّر الصياغة بشكل لافت، إذ ينصّ على أنّ “إسرائيل تحتفظ بحقّها في اتخاذ جميع التدابير اللازمة للدفاع عن النفس، في أي وقت”، وأن هذا الحق لا يقيّده وقف إطلاق النار.", "type": "text"}]}, {"type": "paragraph"}, {"type": "image", "attrs": {"alt": null, "src": "https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/content/1000690243-o0MTnce0JP5oy8eUqFQY3n1d7YYHmF.jpg", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "الفرق الجوهري أنّ اتفاق بري يقيّد الضربات ويمنعها، فيما اتفاق عون يوسّع هامشها تحت عنوان “الدفاع عن النفس”، ما يفتح الباب عمليًا أمام استمرار العمليات العسكرية رغم وقف إطلاق النار، وهو ما يفسّر التباين السريع في موقفي عون وبري.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Images were taken from Al Mahatta platform", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The debate between Speaker Nabih Berri and President Joseph Aoun raises questions about the nature of the ceasefire agreement, especially after Aoun confirmed that the agreement that was signed is the same one previously signed by Berri, only for the latter to respond hours later that it is not the same agreement, but rather differs from it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Berri’s agreement (November 2024), the text is clear: 'Israel will not carry out any offensive military operations against Lebanese targets,' meaning an explicit ban on strikes inside Lebanon and the establishment of a comprehensive cessation of hostilities, with a limited right to self-defense.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Joseph Aoun’s agreement (April 2026), the wording changes notably, stating that 'Israel retains the right to take all necessary measures for self-defense, at any time,' and that this right is not restricted by the ceasefire.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The key difference is that Berri’s agreement restricts and prevents strikes, while Aoun’s agreement expands their scope under the title of self-defense, effectively opening the door to the continuation of military operations despite the ceasefire, which explains the rapid divergence in the positions of Aoun and Berri.", "type": "text"}]}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2025-01-09t131100z-1976614870-rc2c6cai0agr-rtrmadp-3-lebanon-politics-presidency-dDRzHhM6ucfjTfXlk4cTnpSXNOjBzn.JPG', false, false, 91, 258, TIMESTAMP '2026-04-30 10:20:59.079', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Makki on Labor Day: working despite pain… and standing firm despite loss', 'مكي في عيد العمال: العمل رغم الألم… والصمود رغم الفقد', 'makki-labor-day', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "بمناسبة الأول من أيار، تحية تقدير لكل من يواصل العمل والصمود رغم ما يعيشه من فقدان وخسائر كبيرة وضغوط قاسية، سعيًا إلى العيش بكرامة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "يأتي هذا العيد مثقّلًا بالألم، ليس فقط نتيجة ما خلّفه العدوان الإسرائيلي من فقدان للأرواح ومعاناة إنسانية طالت آلاف العائلات، بل أيضًا بسبب الدمار الواسع الذي أصاب المباني والمنشآت، وحرَم الكثيرين من الأمان ومصادر رزقهم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "إنّ وقف العدوان بشكل فوري يبقى المدخل الأساسي للحد من تفاقم هذه الخسائر، وصون كرامة الإنسان وحقه في العمل والحياة الآمنة. كما يقتضي ذلك تحمّل المجتمع الدولي مسؤولياته في حماية المدنيين، وضمان احترام القوانين الدولية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي موازاة ذلك، يشكّل توثيق الأضرار والانتهاكات بشكل منهجي ركيزةً لأي تحرّك مستقبلي للبنان ضمن الأطر القانونية الدولية، ودفاعًا عن حقوقه وحقوق المتضررين على أسس واضحة ومدعّمة بالأدلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الرحمة للشهداء، والشفاء العاجل للجرحى، والتقدير لكل من يواصل العمل رغم كل التحديات.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "On the occasion of May 1, a salute of appreciation to all those who continue to work and remain steadfast despite the loss, heavy hardships, and severe pressures they face, striving to live with dignity.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This occasion comes weighed down with pain, not only due to the loss of lives and humanitarian suffering caused by the Israeli aggression affecting thousands of families, but also because of the widespread destruction of buildings and infrastructure, depriving many of safety and their sources of livelihood.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An immediate halt to the aggression remains the essential entry point to limiting further losses and preserving human dignity and the right to work and live safely. It also requires the international community to assume its responsibilities in protecting civilians and ensuring respect for international laws.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, systematically documenting damages and violations is a cornerstone for any future Lebanese action within international legal frameworks, in defense of its rights and the rights of those affected on clear and evidence-based grounds.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mercy to the martyrs, a speedy recovery to the wounded, and appreciation to all those who continue to work despite all challenges.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/TqozhBhFyHKYPB4o3DDwbkzBGnHgL6iMvfssxlJ6%40md-7TKa7sJBmgRgsQvLtA2WDL3hz5cUvF.jpg', false, false, 23, 138, TIMESTAMP '2026-04-30 18:46:18.916', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'US support for Lebanon… and Aoun’s visit to Washington on hold', 'دعم أميركي للبنان… وزيارة عون إلى واشنطن معلّقة', 'us-lb-support', $c${"type": "doc", "content": [{"type": "paragraph"}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "أعلن السفير الأميركي لدى بيروت، ميشال عيسى، استمرار دعم الولايات المتحدة للبنان ومؤسساته، خلال لقائه رئيس الجمهورية جوزاف عون في قصر بعبدا، عقب عودته من واشنطن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتناول اللقاء التطورات الراهنة، ولا سيما ملف تثبيت وقف إطلاق النار ووقف استهداف المدنيين والمنشآت، تمهيداً لاستكمال الاجتماعات في واشنطن بهدف تحقيق الاستقرار على الحدود. من جهته، شكر عون الدعم الأميركي المتواصل للبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما التقى عيسى رئيس الحكومة نواف سلام في السرايا، حيث جرى البحث في تثبيت وقف إطلاق النار والمحادثات المرتبطة بالتفاوض مع إسرائيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في موازاة ذلك، أفادت معلومات بأن مساعي ترتيب زيارة لعون إلى الولايات المتحدة مجمّدة حالياً، وسط مخاوف من عدم تحقيق أي مكاسب واضحة في ملفي وقف إطلاق النار والانسحاب. وبحسب المصدر، أبلغ الجانب الأميركي عون بعدم وجود ضمانات لوقف شامل لإطلاق النار قبل الزيارة، وأن مسألة الانسحاب ستبقى ضمن إطار التفاوض.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The US ambassador to Beirut, Michel Issa, affirmed continued US support for Lebanon and its institutions during his meeting with President Joseph Aoun at Baabda Palace, following his return from Washington.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The meeting addressed current developments, particularly the issue of تثبيت the ceasefire and halting the targeting of civilians and infrastructure, in preparation for continuing meetings in Washington aimed at achieving stability along the border. For his part, Aoun thanked the United States for its ongoing support to Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Issa also met Prime Minister Nawaf Salam at the Grand Serail, where discussions focused on تثبيت the ceasefire and talks related to negotiations with Israel.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, information indicated that efforts to arrange a visit by Aoun to the United States are currently frozen, amid concerns over the lack of clear gains regarding the ceasefire and withdrawal issues. According to the source, the US side informed Aoun that there are no guarantees for a comprehensive ceasefire before the visit, and that the withdrawal issue will remain within the framework of negotiations.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-zHFp3Cb3ndpKAbc2uiW7cllEagplBf', false, false, 22, 128, TIMESTAMP '2026-05-01 17:35:16.660', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Hezbollah drones pose a new challenge to Israel… and resemble children’s toys?', 'مسيّرات حزب الله تفرض تحدياً جديداً على اسرائيل.. وتُشبه ألعاب الأطفال؟', 'hzb-exp-drones', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نشرت وكالة فرانس برس تقريراً، مفاده أن “مسيّرات حزب الله العاملة بالألياف الضوئية تُشكّل تحدّياً جديداً للقوات الإسرائيلية في جنوب لبنان، ما يفرض على الأخيرة تكييف تكتيكاتها لمواجهة تهديد يزداد فتكاً”.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووصفت الباحثة البارزة في “معهد دراسات الأمن القومي الإسرائيلي” أورنا مزراحي لفرانس برس، أن “المسيّرات العاملة بالألياف الضوئية متاحة بسهولة، وتشبه “ألعاب الأطفال”، فضلاً عن كوْنها صغيرة ومنخفضة الكلفة”.", "type": "text"}]}, {"type": "image", "attrs": {"alt": null, "src": "https://www.independentarabia.com/sites/default/files/styles/1368x911/public/article/mainimage/2026/05/01/1153342-566669185.png", "title": null, "width": null, "height": null}}, {"type": "paragraph", "content": [{"text": "وقالت مزراحي لوكالة فرانس برس، إن “الجيش الإسرائيلي يفتقر حالياً إلى وسائل فعّالة للتعامل مع تهديدات من هذا النوع، لأنه لم يتهيّأ لمواجهة متفجرات متخلّفة تقنياً”.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضافت: “بفضل سرعتها ودقّتها، تستطيع هذه المسيرات إحداث أضرار كبيرة بالأهداف الإسرائيلية، بينما يفرض غياب البصمات الإلكترونية على القوات المستهدَفة الاعتماد على الرادار أو الرصد البصري، وهو ما يحدث غالبا بعد فوات الأوان”.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويقول خبراء إن “كلفة تجميع المسيّرات العاملة بالألياف الضوئية تراوح بين بضع مئات من الدولارات ونحو أربعة آلاف دولار، بحسب جودة المكوّنات ونوعها، وهي متاحة عبر منصات تسوّق إلكترونية مثل “علي إكسبرس”.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويقوم المشغّلون بقيادة هذه المسيّرات بأسلوب الرؤية من منظور الشخص الأول (FPV) باستخدام شاشات أو نظارات واقع افتراضي، علماً أن ذلك لا يتطلّب سوى قدر محدود من التدريب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووفقا للخبير في “معهد دراسات الأمن القومي” آري أفيرام فإنه “نظرا إلى أن الطائرة المسيّرة لا تنقل الصورة عبر بثّ لاسلكي ولا تتلقّى أوامر التوجيه عبر مستقبِل راديوي، فلا يمكن رصدها بوسائل الاستخبارات الإلكترونية أو تعطيلها عبر الحرب الإلكترونية”، بحسب فرانس برس.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Agence France-Presse reported that Hezbollah’s fiber-optic drones pose a new challenge to Israeli forces in southern Lebanon, forcing them to adapt their tactics to confront an increasingly dangerous threat.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Researcher Orna Mizrahi from Israel’s Institute for National Security Studies described these drones as easily accessible, low-cost, small in size, and resembling “children’s toys.” She noted that the Israeli army currently lacks effective tools to counter such threats, as it was not prepared for this type of low-tech explosive systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Thanks to their speed and precision, these drones can cause significant damage to Israeli targets. Their lack of electronic signatures forces targeted forces to rely on radar or visual detection, often after it is too late.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Experts say the cost of assembling fiber-optic drones ranges from a few hundred to about $4,000, depending on the quality and type of components, and they are available through online platforms like AliExpress. Operators control them using first-person view (FPV) systems via screens or VR goggles, requiring only limited training.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to expert Ari Aviram, because these drones do not transmit images wirelessly or receive commands via radio signals, they cannot be detected by electronic intelligence or jammed through electronic warfare.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/screen_shot_2020-08-01_at_17.20.24-INogKP0AudnIIcj5D7m9ohXVFRbvuN.png', false, false, 535, 1220, TIMESTAMP '2026-05-02 10:51:12.084', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Makki: The ongoing and brutal Israeli aggression on the south, at this pace, must stop', 'مكي: الاعتداء الإسرائيلي الغاشم والمستمر على الجنوب، بهذه الوتيرة العدوانية، يجب أن يتوقف!', 'mak-jnoub2m26', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "‏منذ أمس وحتى اليوم، لا تزال الاعتداءات الإسرائيلية تتواصل، وقد طالت بلدتي حبّوش، مسفرةً عن سقوط شهداء وجرحى أبرياء من أهلنا الصامدين، بمن فيهم نساء وأطفال.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "‏خالص التعازي لعائلات الشهداء، والتمنيات بالشفاء العاجل للجرحى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "‏نجدّد الدعوة إلى المجتمع الدولي لتحمّل مسؤولياته والضغط لوقف هذا العدوان الإسرائيلي فوراً، ووضع حدّ للانتهاكات المستمرة بحق المدنيين والتدمير الممنهج للقرى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "‏ونؤكد أننا نعمل بكل ما أوتينا من قوة لتثبيت وقف إطلاق النار وتوسيعه، ووضع حدّ للاعتداءات الإسرائيلية المستمرة على كامل الأراضي اللبنانية دون استثناء.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Since yesterday until today, Israeli attacks have continued, targeting the town of Habboush, resulting in martyrs and injured civilians from our steadfast people, including women and children.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sincere condolences to the families of the martyrs, and wishes for a speedy recovery to the wounded.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "We renew our call on the international community to assume its responsibilities and exert pressure to immediately stop this Israeli aggression and put an end to the ongoing violations against civilians and the systematic destruction of villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "We also affirm that we are working with all our efforts to تثبيت and expand the ceasefire, and to put an end to the continued Israeli attacks across all Lebanese territory without exception", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/898653-1739033566-OS5AterSHTx5dvPjxdRR5JZSzKqXBZ.jpg', false, false, 45, 235, TIMESTAMP '2026-05-02 12:34:19.271', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Exceptional meeting between Haykal and the head of the mechanism committee', 'اجتماع استثنائي بين هيكل ورئيس لجنة الميكانيزم', 'mech-hai-meet', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد قائد الجيش رودولف هيكل خلال اجتماع استثنائي مع رئيس لجنة الإشراف على اتفاق وقف الأعمال العدائية «الميكانيزم» جوزاف كليرفيلد، على أهمية دعم القوات المسلحة اللبنانية في المرحلة الحالية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقد بحث هيكل، في الاجتماع الذي عُقد نتيجة زيارة سريعة قام بها كليرفيلد إلى قاعدة بيروت الجوية، «الوضع الأمني في لبنان والتطورات على صعيد المنطقة وسبل الاستفادة القصوى من الميكانيزم وتطوير عملها».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تم التأكيد على «أهمية دور الجيش وضرورة دعمه في ظل المرحلة الحالية»، وقد غادر كليرفيلد الأراضي اللبنانية بعد الاجتماع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الأثناء، واصل العدو الإسرائيلي عدوانه على الجنوب اللبناني، حيث شنّ سلسلة غارات على عدد من البلدات، منها زبدين وكفرا ودير الزهراني والدوير، وقد أسفرت عن استشهاد عشرات المدنيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بدورها، أعلنت وزارة الصحة ارتفاع حصيلة العدوان الإسرائيلي على لبنان منذ الثاني من آذار الفائت إلى 2659 شهيداً و8183 جريحاً.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Army Commander Rodolphe Haykal, during an exceptional meeting with the head of the ceasefire monitoring committee (“mechanism”) Joseph Clirfield, stressed the importance of supporting the Lebanese Armed Forces at this stage.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The meeting, held following a brief visit by Clirfield to Beirut Air Base, discussed the security situation in Lebanon, regional developments, and ways to maximize the mechanism’s effectiveness and improve its work.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It was also emphasized that the army’s role is vital and must be supported under current circumstances. Clirfield left Lebanon after the meeting.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, Israeli airstrikes on southern Lebanon continued, targeting towns including Zebdine, Kfara, Deir al-Zahrani, and Doueir, resulting in dozens of civilian casualties.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Ministry of Health announced that the death toll from Israeli attacks on Lebanon since March 2 has risen to 2,659 killed and 8,183 injured.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2-rEI2uuRyWzrvB7dQD7jFGCS26yhVkj.jpg', false, false, 25, 226, TIMESTAMP '2026-05-02 16:50:20.272', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Mystery surrounds the assassination of Saif al-Islam Gaddafi', 'غموض يلفّ اغتيال سيف الإسلام القذافي', 'saif-gad-mystery', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في تطور قضائي يسلّط الضوء على تعقيدات المشهد الأمني في ليبيا، أعلن فريق الدفاع عن سيف الإسلام القذافي أن التحقيقات في قضية اغتياله لا تزال تراوح مكانها، رغم مرور 90 يوماً على الحادثة، وسط اتهامات بتأخير غير مبرر وتعطيل للإجراءات القانونية.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وأوضح الفريق أن النيابة العامة كانت قد حدّدت 3 مشتبهين في الجريمة، إلا أنهم لم يُعتقلوا حتى الآن، مشيراً إلى أن بعضهم يتحصّن ضمن مجموعات مسلّحة، ما أعاق تنفيذ أوامر القبض الصادرة بحقهم.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، أكد المحامي خالد الزايدي وجود \"تأخر غير مبرر\" في كشف حقيقة الاغتيال، لافتاً إلى أن الاكتفاء بتحديد هوية المتهمين من دون استكمال الإجراءات القضائية يطرح تساؤلات حول جدية التعاطي مع الملف.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما كشف فريق الدفاع أنه تقدّم بأكثر من 14 طلباً قانونياً للحصول على معلومات وتوضيحات، لكنها قوبلت بالصمت، معتبراً أن ذلك يشكّل إخلالاً بمبادئ العدالة وحق الدفاع في الوصول إلى الأدلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وحذّر الزايدي من أن استمرار التأخير قد يؤدي إلى ضياع الأدلة وإفلات المتورطين من العقاب، داعياً إلى تحريك الملف بشكل عاجل وضمان مسار قضائي شفاف.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في موازاة ذلك، تتصاعد ردود الفعل الشعبية، لا سيما في أوساط أنصار النظام السابق، حيث طُرحت تساؤلات حول أسباب التأخر في كشف ملابسات الجريمة، وسط مطالبات بمحاسبة المسؤولين وكشف هوية الجناة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما دعت جهات قبلية وشبابية إلى تحرّك أوسع للضغط باتجاه تسريع التحقيقات، محذّرة من تداعيات استمرار الغموض على الاستقرار الداخلي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه القضية في سياق أوسع من الانتقادات التي تواجهها السلطات الليبية، على خلفية بطء إجراءات التقاضي، خصوصاً في القضايا ذات الطابع السياسي والأمني، حيث غالباً ما تبقى ملفات الاغتيالات من دون حسم واضح، في ظل تعقيدات أمنية وتداخلات سياسية.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "In a judicial development highlighting the complexity of Libya’s security landscape, the defense team of Saif al-Islam Gaddafi announced that investigations into his assassination remain stalled, 90 days after the incident, amid accusations of unjustified delays and obstruction of legal procedures.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The team stated that the public prosecution had identified three suspects, but none have been arrested so far, noting that some are sheltered within armed groups, hindering the تنفيذ of arrest warrants.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lawyer Khaled al-Zaidi pointed to an “unjustified delay” in uncovering the truth, stressing that merely identifying suspects without completing judicial procedures raises questions about the seriousness of the case.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The defense also revealed it had submitted more than 14 legal requests for information and clarification, all met with silence, considering this a violation of justice principles and the right to access evidence.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Al-Zaidi warned that continued delays could lead to loss of evidence and allow those involved to escape accountability, calling for urgent action and a transparent judicial process.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, public reactions are growing, particularly among supporters of the former regime, with increasing questions about the delay in revealing the circumstances of the crime and calls to hold those responsible accountable.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tribal and youth groups have also called for broader action to pressure authorities into accelerating the investigation, warning of the impact of continued ambiguity on internal stability.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This case comes amid wider criticism of Libyan authorities over slow judicial processes, especially in politically and security-sensitive cases, where assassination files often remain unresolved due to security complexities and political interference.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2026-02-13_16-21-41_617590-juoiOcRnggQVVFJQjTQatOa8HJCsRl.jpg', false, false, 86, 350, TIMESTAMP '2026-05-02 18:32:09.214', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Israel arms itself with new US systems… can they stop Hezbollah’s drones?', 'إسرائيل تتسلح بمنظومات أميركية جديدة.. هل تصد مسيّرات حزب الله؟', 'def-sys-us-isr', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت الخارجية الأميركية أن واشنطن وافقت على بيع منظومة عتاد عسكري مخصصة لاعتراض الطائرات المسيّرة، لإسرائيل بقيمة 992.4 مليون دولار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقالت صحيفة «هآرتس» العبرية، إنه بموجب الاتفاقية ستزود الولايات المتحدة تل أبيب بـ10 آلاف مجموعة -منخفضة التكلفة نسبياً من منظومة «أدفانسد بريسيجن كيل ويبون سيستم» (APKWS) لاعتراض الطائرات المسيّرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت الصحيفة أن هذه المنظومة تقوم بتحويل صواريخ «جو-أرض» غير الموجهة، إلى ذخائر موجهة بدقة قادرة على ضرب أهداف أرضية، مبيّنةً أن أهم مميزات المنظومة هي اعتراض الطائرات المسيّرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لكن رغم الفعالية العالية لمنظومة (APKWS) -بحسب الصحيفة- فإنها غير قادرة على اعتراض المسيّرات الموجهة سلكياً الخاصة بحزب الله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضافت «النظام أثبت فعاليته ضد الذخائر الجوالة مثل مسيّرات «شاهد» الإيرانية، لكنه لم يُصمم لمواجهة الطائرات المسيّرة الصغيرة التي أصبحت تؤرق الجيش الإسرائيلي جنوبي لبنان، ويستخدمها حزب الله بكثافة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ونقلت الصحيفة عن مسؤولين إسرائيليين قولهم إن الجيش الإسرائيلي يواجه تحدياً متزايداً من الطائرات المسيّرة التي تنجح في التهرب من أنظمة الدفاع الجوي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويقدّر الجيش الإسرائيلي أن حزب الله قد يزيد من إطلاق مثل هذه المسيّرات على المستوطنات وقوات الجيش الإسرائيلي في جنوب لبنان في الأيام المقبلة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The US State Department announced that Washington has approved the sale of a military system designed to intercept drones to Israel, valued at $992.4 million.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Haaretz, under the deal the United States will supply Israel with 10,000 relatively low-cost kits of the Advanced Precision Kill Weapon System (APKWS) for intercepting drones.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The system converts unguided air-to-ground rockets into precision-guided munitions capable of striking ground targets, with one of its key features being drone interception.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "However, despite its high effectiveness, the system is not capable of intercepting Hezbollah’s wire-guided drones.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The newspaper added that while the system has proven effective against loitering munitions such as Iranian “Shahed” drones, it was not designed to counter small drones increasingly troubling the Israeli army in southern Lebanon and used extensively by Hezbollah.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli officials say the army is facing a growing challenge from drones that are able to evade air defense systems, with estimates that Hezbollah may increase such drone launches against settlements and Israeli forces in southern Lebanon in the coming days.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/ap_69f6e2ee7a62d-1777787630-8RCgmdQubkoXoPBiUQs6DS8c0HKvEx.jpg', false, false, 72, 302, TIMESTAMP '2026-05-03 13:27:18.721', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Exams in public schools: confusion dominates the scene', 'الامتحانات في المدارس الرسمية: الإرباك سيّد الموقف', 'exam-pub-skl-confusion', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "الأخبار - فاتن الحاج", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "تنطلق اليوم امتحانات السعي الثالث من الفصل الثاني في المدارس والثانويات الرسمية «بالوسائل المُتاحة»، مع فوارق بين مدارس وأخرى. فالمدارس في المناطق الآمنة، تُجري الامتحان حضورياً، مع لجوء مدارس أخرى إلى التقييم عن بُعد. أمّا المدارس المُستخدمة كمراكز إيواء، فحاولت تأمين غرف بديلة داخل المدرسة أو خارجها، لتفادي إجراء الامتحان إلكترونياً. وبالنسبة إلى النتيجة، تعتمد جميع المدارس نظام تقييم واحداً، لكن بمعايير متعدّدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في هذا السياق، يوضح الخبير التربوي، داود حرب، أن «تقييم أداء التلامذة عن بُعد مسألة مُعقّدة بطبيعتها، وتزداد صعوبة في ظل الأزمات». ويشير إلى أن «الواقع اللبناني يضيف تحدّيات قانونية أيضاً، في ظل غياب نصوص واضحة تحدّد آليات التقييم الأنسب لكل مرحلة»، لافتاً إلى أن «التجارب العالمية متعدّدة، من المقابلات الشفهية إلى الامتحانات الإلكترونية وملفات الإنجاز (بورتفوليو)، إلا أن الوزارة لم تعتمد سابقاً الامتحانات أونلاين، حتى في ظروف صعبة، إذ بقيت الامتحانات حضورية».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويشدّد حرب على أن «جوهر الإشكالية يكمن في موثوقية التقييم: من يجيب فعلياً على الامتحان؟ وهل يتم ذلك بشكل مستقلّ أم بمساعدة خارجية، سواء من الأهل أو عبر أدوات رقمية وبرمجيات مثل الذكاء الاصطناعي؟».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويرى أن «هذا الواقع يخلق تفاوتاً إضافياً بين التلامذة، تبعاً لقدرتهم على الوصول إلى هذه الوسائل، ما يجعل العلامة لا تعكس بالضرورة مستوى التحصيل العلمي بقدر ما تعكس اختلاف بيئات الامتحان». ويذكّر بـ«وجود نص قانوني يتيح، في الظروف الاستثنائية، إعفاء التلامذة من الامتحانات النهائية واعتماد علامات منتصف العام»، مشيراً إلى أن «غالبية المدارس أنجزت هذه الامتحانات، ما كان يمكن أن يشكّل مخرجاً، ولا سيما في المناطق المتضررة، إلا أن هذا الخيار لا يبدو مطروحاً حالياً، في ظل إصرار الوزارة على إجراء الامتحانات النهائية».", "type": "text"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "نص قانوني يتيح في الظروف الاستثنائية إعفاء التلامذة من الامتحانات النهائية واعتماد علامات منتصف العام", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "هذا التباين يظهر بوضوح على أرض الواقع. أستاذ في إحدى الثانويات في الضاحية الجنوبية لبيروت يشير إلى أن «الاستحقاق فُرض من دون تحضير كافٍ أو تدريب فعلي على تنظيم امتحانات أونلاين تضمن الشفافية». ومع تعذّر العودة الحضورية، لجأ المعلمون إلى «حلول مرتجلة، كإرسال المسابقة كصورة ليجيب عنها التلامذة في منازلهم، ثم يعيدونها للتصحيح، من دون آليات فعّالة لضبط الغش». ويلفت إلى أن «أساتذة المواد العلمية يواجهون صعوبات في عرض الرموز والقواعد بدقّة، فيما تعاني مواد اللغات من مشاكل تقنية أيضاً، ما ينعكس على نوعية التقييم».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من جهته، يرى مدير مدرسة رسمية في الجنوب أن «كلام الوزارة عن إجراء تقييمات لاحقة للتلامذة الذين لم يتمكنوا من متابعة التعليم، حضورياً أو عن بعد ليس واقعياً، لأن هؤلاء هم الأغلبية». ويتساءل عن «كيفية التعامل مع نتائج غير مكتملة»، محذّراً من «أن ترك الأمور للاجتهادات الفردية يفتح الباب أمام تفاوت كبير في النتائج، وربما أمام إشكالات قانونية».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تفرض الظروف الميدانية تحدّيات كبيرة، من النزوح واستخدام المدارس كمراكز إيواء، والوصول الآمن إليها، وصعوبة تأمين الكادر التعليمي. وبينما لا يبدو وقف التقييم بالكامل خياراً مطروحاً، يبرز تساؤل حول كيفية الحفاظ على حدّ أدنى من المعايير المشتركة، بما يمنع تحوّل اختلاف الوسائل إلى تفاوت في النتائج.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولا تقتصر الإشكالية على المرحلة الراهنة، بل تمتد إلى ما بعدها، إذ إن اعتماد أنماط تقييم غير متكافئة، حتى لو فرضتها الظروف، قد يؤسّس لسابقة يصعب التراجع عنها. ومع احتمال تحوّل الامتحانات الإلكترونية إلى خيار دائم مستقبلاً، لا يعود النقاش تقنياً فقط، بل يرتبط أيضاً بمصداقية الشهادات وثقة المجتمع بالنظام التربوي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Third-term exams for the second semester in public schools and secondary institutions begin today “using available means,” with noticeable differences between schools. In safer areas, exams are held in person, while others rely on remote assessment. Schools used as shelters have tried to secure alternative rooms to avoid online exams. Despite this, all schools adopt a unified grading system, but with varying criteria.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Educational expert Daoud Harb explains that remote evaluation is inherently complex, especially during crises. He notes that Lebanon faces additional legal challenges due to the absence of clear frameworks governing appropriate assessment methods. While global models range from oral exams to online tests and portfolios, Lebanon has traditionally maintained in-person exams—even in difficult conditions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Harb highlights that the core issue lies in credibility: who is actually completing the exam, and whether students are working independently or with external help, including AI tools. This reality creates inequality among students based on access to such resources, meaning grades may reflect exam conditions more than actual academic performance.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although legal provisions allow, in exceptional cases, replacing final exams with midterm results, this option is not currently being considered, as the ministry insists on proceeding with final exams.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the ground, the disparity is evident. A teacher in Beirut’s southern suburbs says the process was imposed without proper preparation or training for transparent online exams. Teachers resorted to improvised solutions, such as sending exam sheets as images for students to complete at home, without effective anti-cheating measures. Scientific subjects face challenges in presenting formulas accurately, while language subjects encounter technical issues, affecting evaluation quality.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A school principal in the south considers the ministry’s proposal for later evaluations unrealistic, noting that most students have been unable to follow classes. He warns that relying on individual discretion could lead to inconsistent results and possible legal disputes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Field conditions—displacement, use of schools as shelters, safety concerns, and staff shortages—further complicate the situation. While halting assessments entirely is not an option, questions remain about maintaining minimum unified standards to prevent disparities.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The issue extends beyond the current phase. Unequal evaluation methods, even if imposed by circumstances, risk setting a precedent that could be difficult to reverse. With the possibility of online exams becoming a permanent option, the debate is no longer purely technical—it also concerns the credibility of certificates and public trust in the education system.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/132849588569-HCAYSNXxCsuuOTKSqyqxA4TSRwUQEn.jpg', false, false, 212, 534, TIMESTAMP '2026-05-04 09:51:16.136', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Warning against misuse of the Lebanese University’s name… suspicious ads targeting students', 'تحذير من استغلال اسم الجامعة اللبنانية… وإعلانات مشبوهة تستهدف الطلاب', 'lbuni-warning-4th5', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "صدر عن رئاسة الجامعة اللبنانية، بيان، لفت إلى أنّه \"انتشرت في الفترة الأخيرة إعلانات وبوسترات عبر صفحات ومواقع إلكترونية تدّعي تأمين فرص عمل للطلاب والخريجين وتقديم استشارات، وتستخدم اسم الجامعة اللبنانية وشعارها.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "إنّ رئاسة الجامعة اللبنانية تُحذّر من التواصل مع الأرقام الموجودة في تلك الإعلانات المشبوهة، وتؤكد أن إي إعلان بخصوص فرص العمل أو غيرها يجري نشره حصرًا عبر الموقع الإلكتروني الرسمي للجامعة وصفحاتها على وسائل التواصل الاجتماعي.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "كما تؤكد رئاسة الجامعة اللبنانية احتفاظها بحق ملاحقة ومقاضاة من يقف خلف تلك الصفحات المشبوهة\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Lebanese University presidency warned that advertisements and posters circulating online claiming to offer job opportunities and consultations using the university’s name and logo are fake.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It urged students not to contact the numbers listed in these suspicious ads, stressing that any official announcements are published only عبر the university’s official website and social media pages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The presidency also affirmed its right to take legal action against those behind these fraudulent pages.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/lebanese-university-hadath-lebanon-4-rMhBTrxJ1UEaUWlIKnO418Jqn1MU0t.jpg', false, false, 137, 576, TIMESTAMP '2026-05-04 12:29:30.529', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'General amnesty law nearing approval… political compromises amid divisions', 'قانون العفو العام نحو الإقرار... تسويات سياسية على حساب التباينات', 'annesty-law-55', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رغم ستّ جلسات متتالية خُصّصت لبحث اقتراح قانون العفو العام، لا تزال الهوّة بين الكتل النيابية قائمة، وسط مشهد سياسي يقوم على شدّ الحبال، حيث يسعى كل فريق إلى تحصيل مكاسب تعزّز حضوره في بيئته.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "هذا التباين انعكس بوضوح في أولويات النقاش: فبينما دفع عدد من النواب باتجاه معالجة ملف الموقوفين الإسلاميين، ركّزت كتل مسيحية على قضايا المتهمين بالتجسّس أو الفارّين إلى الأراضي المحتلة. وفي المقابل، ورغم التحفّظات، لم يتردّد نواب حزب الله وحركة أمل في الانخراط في بحث مواد تتعلّق بجرائم المخدرات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومع ذلك، يلتقي معظم الأطراف عند نقطة أساسية، وهي أن هذه المداولات، على ما تشهده من تباينات، ستنتهي بصيغة توافقية تُرفع إلى الهيئة العامة، بعد إدخال تعديلات قانونية تسمح لكل فريق بتسويقها سياسياً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الجلسة الأخيرة عكست هذا المسار، إذ اتّسمت بنقاشات حادة، تخللتها إشارات إلى مرونة نسبية لدى نواب «القوات اللبنانية» في ملف قضايا الإرهاب، وهو ما اعتبره النواب السنّة تقدّماً، خصوصاً بعد تأكيد النائب جورج عدوان دعم إقرار القانون وعدم اعتراضه على شمول الموقوفين الإسلاميين.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "صراع حول سقوف العقوبات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لكن هذا المناخ لم يدم طويلاً، إذ عاد الخلاف ليطفو حول مسألة العقوبات. فقد تمسّك وزير الدفاع وممثّلو المؤسسة العسكرية باقتراح تحديد الأشغال الشاقّة المؤبّدة بـ20 عاماً، واستبدال الإعدام بالسجن 25 عاماً. في المقابل، شدّد فريق رئيس الجمهورية على رفع هذه السقوف إلى 25 و30 عاماً، ملوّحاً بإمكانية ردّ القانون في حال عدم الأخذ بها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في الجهة المقابلة، طالب النواب السنّة بتخفيض هذه العقوبات إلى ما دون 15 و20 عاماً، ما أعاد التوتر إلى الجلسة، خاصة بعد مداخلة النائب أشرف ريفي التي أثارت سجالاً حاداً مع النائب حسين الحاج حسن، قبل أن يُصار إلى احتواء الموقف.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تعديل المسار أم الالتفاف عليه؟", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تركّزت جهود «القوات اللبنانية» على تعديل بنود الاقتراح بما يتيح شمول الفارّين إلى الأراضي المحتلة والمتخلّين عن جنسيتهم. إلا أن هذا الطرح قوبل برفض واسع، إذ اعتبر نواب أن هذه الفئة مشمولة أصلاً بقانون 2011، وأن المشكلة تكمن في عدم تطبيقه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، طُرح حلّ وسط يقضي بإدراج مادة تؤكد نفاذ القانون السابق، مع التشديد على ضرورة إصدار مراسيمه التطبيقية، على أن يُستكمل البحث في هذا الاتجاه في جلسات لاحقة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "ملف المخدرات يعود إلى الواجهة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بدوره، أعاد ملف المخدرات إشعال النقاش، مع مطالبة نواب «الثنائي» بإدراج أصحاب الأراضي الذين تورّطوا دون علمهم بزراعة الحشيشة، في حين شدّد آخرون على ضرورة التفريق بين كبار المتورطين في الاتجار وحالات الترويج المحدودة أو التعاطي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، جرى التوافق على إدخال مادة تستند إلى الاجتهادات القضائية لتقليص التفاوت في الأحكام، بالتوازي مع طرح وزير العدل إلغاء عقوبة الإعدام واستبدالها بالمؤبد، بما يتيح استعادة سجناء لبنانيين من الخارج.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "خصوصية العسكريين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في موازاة ذلك، برز موقف واضح لوزير الدفاع وممثلي المؤسسة العسكرية بضرورة استثناء العسكريين من قانون العفو، انطلاقاً من خصوصية وضعهم، مع اعتماد معايير أكثر تشدداً في مقاربة ملفاتهم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في الخلاصة، وعلى الرغم من حدّة التباينات، يبدو أن مسار التفاوض يسير نحو تسوية شاملة، تقوم على تبادل التنازلات، تمهيداً لإقرار قانون عفو يرضي مختلف الأطراف، ولو بحدود دنيا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المصدر: بتصرف عن الأخبار", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Despite six consecutive sessions dedicated to discussing the general amnesty law proposal, the gap between parliamentary blocs persists, within a political scene marked by tug-of-war, as each side seeks gains that strengthen its standing within its base.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This divergence is reflected in priorities: some MPs pushed to address the ملف of Islamist detainees, while Christian blocs focused on cases involving alleged collaborators or fugitives in occupied territories. Meanwhile, despite reservations, Hezbollah and Amal MPs engaged in discussions on drug-related offenses.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Still, most parties converge on a key point: these discussions, despite differences, are expected to lead to a توافق formula to be presented to the general assembly, after legal amendments allow each side to market it politically.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The latest session reflected this trajectory, with heated debates and signs of relative flexibility from Lebanese Forces MPs on terrorism-related cases—seen as progress by Sunni MPs, especially after MP Georges Adwan expressed support for passing the law, including Islamist detainees.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dispute over sentencing limits", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "However, disagreements quickly resurfaced over penalties. The defense minister and military representatives insisted on setting life imprisonment at 20 years and replacing the death penalty with 25 years in prison. In contrast, the president’s camp pushed for raising these limits to 25 and 30 years, warning of rejecting the law otherwise.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, Sunni MPs called for lowering sentences below 15 and 20 years, reigniting tensions—particularly after a heated exchange between MP Ashraf Rifi and MP Hussein Hajj Hassan before things were contained.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Amendment or circumvention?", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The Lebanese Forces focused on amending provisions to include fugitives in occupied territories and those who renounced their nationality. This proposal faced broad rejection, with MPs arguing such cases are already covered by the 2011 law, and the issue lies in its non-implementation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A compromise was proposed: adding a clause affirming the enforcement of the previous law, alongside calls to issue its تطبيقية decrees, with further discussions to follow.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Drug file resurfaces", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The drug file also reignited debate, with “the duo” MPs calling for including landowners unknowingly involved in cannabis cultivation, while others stressed distinguishing between major traffickers and minor cases of promotion or use.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A consensus emerged on introducing a clause based on judicial precedents to reduce sentencing disparities, alongside the justice minister’s proposal to abolish the death penalty and replace it with life imprisonment—potentially allowing the return of Lebanese prisoners from abroad.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Special status for military personnel", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "At the same time, the defense minister and military representatives emphasized excluding military personnel from the amnesty law, citing the privacy of their status and the need for stricter standards.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Conclusion", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Despite sharp divisions, negotiations appear to be moving toward a comprehensive compromise based on mutual concessions, paving the way for a general amnesty law that satisfies all parties—at least minimally.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Roumieh-prison-Arabic-%25D8%25B3%25D8%25AC%25D9%2586-%25D8%25B1%25D9%2588%25D9%2585%25D9%258A%25D8%25A9-is-the-largest-and-most-notorious-prison-in-Lebanon-4-XiZy9awFcUmnBvCMQZQhF9iOADhVyi.jpg', false, false, 673, 1482, TIMESTAMP '2026-05-05 11:11:26.691', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'What history books did not mention 4: The Litani River… an Israeli objective from the very beginning', 'ما لم تذكره كتب التاريخ 4: نهر الليطاني… هدف إسرائيلي منذ البداية', 'lebisr-invasion-part4', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "منذ نشأة الحركة الصهيونية، لم يكن نهر الليطاني مجرّد خط أمني على الخريطة، ولا تفصيلًا جغرافيًا عابرًا، بل كان جزءًا من مشروع أوسع، بدأ من الهندسة والمياه والطاقة، وانتقل لاحقًا إلى السياسة والحدود والحرب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "قبل عام 1948، لم يكن كيان العدو قائمًا على الأرض، بل كان فكرة سياسية اسمها الحركة الصهيونية، وهي النواة التي قامت عليها \"إسرائيل\". عملت هذه الحركة بهدوء على التخطيط لمشروعها، من حيث الاستيطان والحدود والطاقة والاقتصاد، وكان سؤال المياه حاضرًا منذ البداية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "عام 1896، وضع مؤسس الحركة الصهيونية تيودور هرتزل خريطة المنطقة أمامه وطرح السؤال الأساسي: من أين نأتي بالمياه؟ للشرب، والزراعة، والكهرباء، وسائر مقومات البقاء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي عام 1901، طلب هرتزل من المهندس السويسري ماكس بوركات إعداد خطة لاستغلال المياه في \"أرض إسرائيل\". جاء بوركات إلى المنطقة، وأجرى أبحاثًا حول مصادر المياه، ثم وضع خطة حملت اسم \"الخطة العامة لمعالم الطاقة المائية والري في إسرائيل\". ومن ضمن هذه الخطة، طُرح وصل نهر الليطاني بنهر الأردن عبر نفق، بهدف زيادة مياهه، وتحويله إلى نهر صالح للملاحة، والاستفادة منه في توليد الكهرباء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "عام 1916، وخلال تقسيم المنطقة بين بريطانيا وفرنسا بموجب اتفاقية سايكس–بيكو، طلبت الحركة الصهيونية من بريطانيا توسيع حدود الانتداب لتشمل نهر الليطاني شمالًا، ومنطقة نهر الأردن حتى الحاصباني في لبنان. وكانت بريطانيا قد وعدت الحركة الصهيونية بإعطائها فلسطين في وعد بلفور، الوعد الذي شكّل أصل البلاء في المنطقة ومهّد لقيام \"إسرائيل\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وافقت بريطانيا على الطرح الصهيوني، لكن فرنسا كانت تملك أطماعًا في المناطق نفسها، فبقي الليطاني والحاصباني ضمن النفوذ الفرنسي. ورغم ذلك، لم تتراجع الحركة الصهيونية عن مطلبها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في مؤتمر السلام في فرساي عام 1919، عادت الحركة الصهيونية لمحاولة فرض رؤيتها. وفي الخريطة التي عرضتها، طالبت بالوصول إلى نهر الأولي في لبنان، أي أبعد بكثير من الليطاني، استنادًا إلى ما اعتبرته حدودًا توراتية، أي مشروع \"إسرائيل الكبرى\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "حاولت الحركة الصهيونية تمرير هذه المطالب عبر الأساليب الدولية والإعلامية، لكن فرنسا عارضتها، لأنها كانت تعتبر تلك المنطقة جزءًا من حصتها، ولا تريد إضعاف حلفائها الموارنة في لبنان. فالتنازل عنها كان يعني خسارة جزء من نفوذها المباشر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بعد فشل المعركة السياسية لضم الليطاني إلى \"أرض إسرائيل\"، لجأت الحركة الصهيونية إلى أساليب أخرى، أبرزها بناء شراكات داخل لبنان مع جهات وشخصيات يمكن أن تتقاطع معها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "عام 1936، نُشر بحث في الجامعة الأميركية في بيروت عن مشروع للطاقة الكهربائية على مستوى المنطقة. أوصى البحث بمنح حق استغلال الليطاني لشركة تخدم صور وصيدا والنبطية ومرجعيون، إضافة إلى صفد في شمال فلسطين. شجعت الحركة الصهيونية الفكرة، لكنها بقيت مجرّد مشروع على الورق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لاحقًا، تجاوب مع هذه الأفكار مهندس لبناني يُدعى ألبير نقاش، وهو قريب الرئيس ألفرد نقاش. اقترح نقاش بناء معمل إنتاج كهرباء مشترك بين لبنان والدولة اليهودية، بالاستفادة من مياه الليطاني. درست الحركة الصهيونية خطته بعد لقائها به، وأُحيلت للتنفيذ بشكل سرّي، كما جرت جولات ميدانية معه على امتداد النهر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كانت الخطة تقوم على إنشاء سدود وأحواض على الليطاني في سحمر وحاصبيا ومرجعيون لإنتاج الكهرباء في لبنان وفلسطين، إضافة إلى نقل المياه عبر أنفاق إلى داخل فلسطين لاستخدامها في ري المزروعات داخل \"إسرائيل\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "اعتبرت فرنسا خطة نقاش مؤامرة بريطانية بغطاء أميركي، تهدف إلى تعديل الحدود بين لبنان وفلسطين وتوسيع النفوذ البريطاني على حساب المصالح الفرنسية، فتوقفت الخطة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لكن إصرار الحركة الصهيونية استمر عبر خطط هندسية جديدة. ففي عام 1943، اعتمدت على خطة نشرتها شركة مياه \"أرض إسرائيل\" بإشراف أبراهام روتنبرغ. وفي عام 1944، أُعدّت خطة ثانية على يد الخبير العالمي والتر كلاي لودرملك، ثم ظهرت خطة إضافية عام 1946 من قبل السياسي البريطاني اليهودي هربرت صموئيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "فشلت هذه الخطط كلها بفعل المعارضة الفرنسية، إلى أن أُعلن قيام \"إسرائيل\" عام 1948 من دون الليطاني. لكن الضغط لاستغلال النهر على حساب حاجات لبنان بقي ثابتًا في وعي القيادة الصهيونية حتى اليوم، ولم تتخلَّ \"إسرائيل\" عن أي فرصة لاستغلاله أو تحويله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأحد الأدلة على ذلك ما جرى خلال الاحتلال الإسرائيلي لجنوب لبنان بين عامي 1982 و2000، حين نُفذت أشغال هندسية قرب مجرى الليطاني، وربطت شبكات مياه في القرى الحدودية بشبكة شمال فلسطين المحتلة، في عملية سرقة لمياه النهر. كما سُرقت مياه من نهر الوزاني والمياه الجوفية عبر أنابيب مخفية، بالتوازي مع منع أي مشاريع لبنانية لاستثمار مياه الليطاني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في الخلاصة، لم يكن نهر الليطاني يومًا تفصيلًا جغرافيًا على خريطة، بل كان جزءًا من مشروع كامل. فكرة الاستفادة من الليطاني موجودة في أساس قيام \"إسرائيل\"، وولدت قبلها بسنوات طويلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "زعماء الصهاينة، ومن بينهم بن غوريون، حددوا الليطاني كحدود شمالية لـ\"إسرائيل\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Since the emergence of the Zionist movement, the Litani River was not merely a security line on the map, nor a passing geographical detail. It was part of a broader project that began with engineering, water, and energy, and later extended into politics, borders, and war.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before 1948, the Israeli entity did not yet exist on the ground; it was a political idea known as the Zionist movement—the nucleus upon which “Israel” was later established. This movement quietly worked on planning its project in terms of settlement, borders, energy, and economy, with the issue of water present from the very beginning.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In 1896, the founder of the Zionist movement, Theodor Herzl, laid out a map of the region and posed a fundamental question: where will we get water—for drinking, agriculture, electricity, and all the essentials of survival?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In 1901, Herzl asked Swiss engineer Max Bourcart to prepare a plan for exploiting water in the “Land of Israel.” Bourcart came to the region, conducted research on water sources, and developed a plan titled “General Scheme for Hydroelectric Power and Irrigation in Israel.” As part of this plan, the idea was proposed to connect the Litani River to the Jordan River via a tunnel, in order to increase its water flow, make it navigable, and use it for electricity generation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In 1916, during the division of the region between Britain and France under the Sykes–Picot Agreement, the Zionist movement requested Britain to expand the mandate borders to include the Litani River to the north and the Jordan River basin up to the Hasbani River in Lebanon. Britain had already promised the Zionist movement Palestine through the Balfour Declaration—a promise that laid the foundation for the establishment of “Israel.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Britain agreed to the Zionist proposal, but France had ambitions in the same areas, so the Litani and Hasbani remained under French influence. Nevertheless, the Zionist movement did not abandon its demands.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the Versailles Peace Conference in 1919, the Zionist movement attempted again to impose its vision. In the map it presented, it demanded access as far as the Awali River in Lebanon—far beyond the Litani—based on what it considered biblical borders, i.e., the concept of “Greater Israel.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Zionist movement tried to advance these demands through international and media channels, but France opposed them, as it considered the region part of its share and did not want to weaken its Maronite allies in Lebanon. Ceding it would have meant losing part of its direct influence.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "After failing to politically annex the Litani to the “Land of Israel,” the Zionist movement resorted to other methods, notably building partnerships within Lebanon with parties and figures whose interests might align with it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In 1936, a study was published at the American University of Beirut about a regional electricity project. The study recommended granting rights to exploit the Litani to a company serving Tyre, Sidon, Nabatieh, and Marjayoun, as well as Safed in northern Palestine. The Zionist movement encouraged the idea, but it remained only on paper.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Later, a Lebanese engineer named Albert Naccache—relative of President Alfred Naccache—engaged with these ideas. He proposed building a joint power plant between Lebanon and the Jewish state using Litani waters. The Zionist movement studied his proposal after meeting him, and it was referred for secret implementation, including field visits along the river.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The plan involved building dams and reservoirs along the Litani in Sohmor, Hasbaya, and Marjayoun to generate electricity for both Lebanon and Palestine, as well as transporting water through tunnels into Palestine for irrigation within “Israel.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "France viewed Naccache’s plan as a British plot with American backing, aimed at altering the borders between Lebanon and Palestine and expanding British influence at the expense of French interests, so the plan was halted.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "However, the Zionist movement’s persistence continued through new engineering plans. In 1943, it adopted a plan published by the “Land of Israel” Water Company under the supervision of Abraham Rutenberg. In 1944, another plan was prepared by the international expert Walter Clay Lowdermilk, followed by an additional plan in 1946 by British Jewish politician Herbert Samuel.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "All these plans failed due to French opposition, until the establishment of “Israel” in 1948 without the Litani. Yet the pressure to exploit the river at Lebanon’s expense remained constant in Zionist strategic thinking and continues to this day.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "One example is what occurred during the Israeli occupation of southern Lebanon between 1982 and 2000, when engineering works were carried out near the Litani River, and water networks in border villages were connected to northern occupied Palestine’s system—effectively diverting water from the river. Water was also taken from the Wazzani River and groundwater through hidden pipelines, while Lebanese projects to utilize Litani waters were blocked.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In conclusion, the Litani River was never just a geographical detail on a map; it has always been part of a broader strategic vision. The idea of exploiting the Litani was embedded in the foundations of Israel’s establishment and predates it by many years.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Zionist leaders, including David Ben-Gurion, identified the Litani as the northern boundary of “Israel.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/02b868f_upload-1-hmhclxgg4urn-gettyimages-71519546-qP3hH6v2RudnF3cPDGqQGv4umLtJgf.jpg', true, false, 600, 1622, TIMESTAMP '2026-05-05 15:25:42.561', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'history'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Washington seeks a “political photo” in Beirut… and Aoun is cautious about meeting Netanyahu', 'واشنطن تبحث عن «صورة سياسية» في بيروت… وعون يتحفّظ على لقاء نتنياهو', 'us-isr-lb-pic', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كشفت صحيفة «هآرتس» العبرية عن تحرّكات أميركية تهدف إلى ترتيب لقاء بين رئيس الجمهورية جوزاف عون ورئيس وزراء الاحتلال بنيامين نتنياهو، في وقت تتواصل فيه الاعتداءات الإسرائيلية على لبنان، وتتراجع فرص التوصل إلى تفاهم بين واشنطن وطهران.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب الصحيفة، فإن الإدارة الأميركية تنظر إلى هذا اللقاء كفرصة لتحقيق اختراق سياسي سريع، بعد تعثّر مسار المفاوضات مع إيران، وفشل الجهود الأميركية في دفع السعودية نحو مفاوضات علنية مع تل أبيب. وترى أن الرئيس الأميركي دونالد ترامب يبحث عن «إنجاز رمزي» يمكن تسويقه سياسياً، عبر صورة تجمع عون ونتنياهو في واشنطن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبرت «هآرتس» أن مجرد العمل على جمع الطرفين في لقاء مباشر يُعد خطوة «دراماتيكية»، تعكس حجم الضغوط الأميركية لإنتاج مشهد سياسي جديد في المنطقة، خصوصاً في ظل الجمود الذي يواجهه البيت الأبيض في أكثر من ملف إقليمي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، أشارت الصحيفة إلى أن نتنياهو لا يجد سبباً لرفض الفكرة، إذ يرى فيها مكسباً سياسياً مجانياً، في وقت يواصل فيه الجيش الإسرائيلي عملياته العسكرية في جنوب لبنان من دون أن تضطر إسرائيل إلى تقديم أي تنازل فعلي، سواء عبر الانسحاب أو وقف الحرب بشكل كامل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما في الجانب اللبناني، فنقلت الصحيفة أن الرئيس جوزاف عون يتعامل بحذر شديد مع الطرح الأميركي، معتبراً أن أي لقاء من هذا النوع يجب أن يأتي بعد إنهاء المواجهة، لا في ظل استمرار العمليات العسكرية وتدمير القرى الجنوبية. كما أشارت إلى وجود مخاوف داخلية لبنانية من أن يشكّل لقاء علني مع نتنياهو «تجاوزاً لخط أحمر»، بما قد يؤدي إلى ردود فعل واسعة في الداخل اللبناني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورأت الصحيفة أن استعجال واشنطن لتحقيق «صورة نصر» قد يحمل تداعيات خطرة، خصوصاً مع استمرار القتال في الجنوب ووجود أعداد كبيرة من النازحين، معتبرة أن أي خطوة غير محسوبة قد تنعكس سلباً على الاستقرار الهش في لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي سياق المقارنة التاريخية، أعادت «هآرتس» التذكير باتفاق 17 أيار عام 1983 بين لبنان وإسرائيل، واصفة إياه بـ«الاتفاق الممتاز» الذي سقط بسبب الظروف الداخلية اللبنانية آنذاك وضعف السلطة السياسية. واعتبرت أن التجربة السابقة تُشكّل تحذيراً من محاولات فرض تسويات سياسية قبل نضوج الظروف اللازمة لها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختمت الصحيفة بالتأكيد أن الدفع نحو لقاء سريع بين عون ونتنياهو قد يهدّد المسار القائم بدل دعمه، معتبرة أن «التقاط صورة سياسية» لا يكفي لصناعة تسوية حقيقية في ظل الظروف الحالية.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Hebrew newspaper ", "type": "text"}, {"text": "Haaretz", "type": "text", "marks": [{"type": "italic"}]}, {"text": " revealed US efforts aimed at arranging a meeting between Lebanese President Joseph Aoun and Israeli Prime Minister Benjamin Netanyahu, at a time when Israeli attacks on Lebanon continue and chances of reaching an understanding between Washington and Tehran are declining.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the newspaper, the US administration views such a meeting as an opportunity to achieve a quick political breakthrough after negotiations with Iran stalled and after American efforts to push Saudi Arabia toward open talks with Tel Aviv failed. It believes that President Donald Trump is seeking a “symbolic achievement” that can be politically marketed through a photo bringing Aoun and Netanyahu together in Washington.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Haaretz", "type": "text", "marks": [{"type": "italic"}]}, {"text": " considered that merely working to bring the two sides together in a direct meeting is a “dramatic” step reflecting the scale of US pressure to produce a new political scene in the region, especially amid the stagnation facing the White House on several regional files.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, the newspaper noted that Netanyahu sees no reason to reject the idea, considering it a free political gain, while the Israeli army continues its military operations in southern Lebanon without Israel having to make any actual concession, whether through withdrawal or a complete halt to the war.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As for the Lebanese side, the newspaper reported that President Joseph Aoun is dealing with the American proposal with great caution, believing that any meeting of this kind should come after the confrontation ends, not while military operations and the destruction of southern villages continue. It also pointed to internal Lebanese concerns that a public meeting with Netanyahu would cross a “red line,” potentially provoking broad reactions inside Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The newspaper argued that Washington’s rush to secure a “victory photo” could carry dangerous consequences, especially with the ongoing fighting in the south and the large number of displaced people, warning that any miscalculated move could negatively affect Lebanon’s fragile stability.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a historical comparison, ", "type": "text"}, {"text": "Haaretz", "type": "text", "marks": [{"type": "italic"}]}, {"text": " recalled the May 17 Agreement of 1983 between Lebanon and Israel, describing it as an “excellent agreement” that collapsed due to Lebanon’s internal conditions at the time and the weakness of political authority. The paper considered the previous experience a warning against attempts to impose political settlements before the necessary conditions are mature.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The newspaper concluded by stressing that pushing for a quick meeting between Aoun and Netanyahu could threaten the current path rather than support it, arguing that “taking a political photo” is not enough to create a real settlement under the current circumstances.", "type": "text"}]}]}$c$::jsonb, 'https://thisisbeirut.com.lb/images/bibli/720/960/2/tib-website-when-aoun-meets-netanyahu-2026-04-21.jpg', false, false, 14, 77, TIMESTAMP '2026-05-07 11:49:31.996', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The Litani launches the irrigation season in the South', 'الليطاني يُطلق موسم الري جنوباً', 'litani-south-launch7-5', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت المصلحة الوطنية لنهر الليطاني بدء موسم الري لعام 2026، انطلاقاً من سدّ الزرارية وصولاً إلى منطقة الغازية، بعد استكمال أعمال صيانة وتأهيل واسعة طالت شبكة الري في الجنوب، رغم الظروف الأمنية المعقدة التي تشهدها المنطقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت المصلحة، في بيان، أن فرقها تمكنت خلال فترة قصيرة ومن داخل مناطق خطرة ميدانياً، من إصلاح الأضرار التي خلّفتها الاعتداءات الأخيرة، بما شمل إعادة تأهيل منشآت الري، وصيانة المآخذ، وتنظيف القنوات والأنفاق والمجاري المائية الرئيسية والفرعية، لضمان استمرارية تدفق المياه على كامل الشبكة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت أن الموسم الجديد يهدف إلى تأمين مياه الري لأكثر من 6000 هكتار من الأراضي الزراعية في الساحل الجنوبي، بما يساهم في دعم الأمن الغذائي وتعزيز صمود المزارعين واستمرار النشاط الزراعي في القرى الجنوبية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشارت إلى أن الفرق الفنية والإدارية واصلت أعمالها بالتنسيق مع الجيش اللبناني، حفاظاً على سلامة العاملين وضمان استمرار الأشغال والخدمات العامة رغم التهديدات الأمنية القائمة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ودعت المصلحة المزارعين إلى التعاون معها واعتماد الاستخدام الرشيد للمياه، بهدف الحد من الهدر وضمان توزيع عادل ومستدام للمياه على مختلف المناطق المستفيدة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Litani River Authority announced the start of the 2026 irrigation season, stretching from the Zrariyeh Dam to the Ghazieh area, following the completion of extensive maintenance and rehabilitation works on the irrigation network in southern Lebanon, despite the complex security conditions affecting the region.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement, the authority explained that its teams managed, within a short period and from highly dangerous field areas, to repair damage caused by the recent attacks. The works included rehabilitating irrigation facilities, maintaining water intakes, and cleaning canals, tunnels, and major and secondary waterways to ensure the continuous flow of water across the entire network.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The authority stressed that the new season aims to provide irrigation water for more than 6,000 hectares of agricultural land along the southern coast, contributing to food security, strengthening farmers’ resilience, and sustaining agricultural activity in southern villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It also noted that technical and administrative teams continued their work in coordination with the Lebanese Army to ensure workers’ safety and maintain ongoing operations and public services despite existing security threats.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The authority called on farmers to cooperate fully and adopt responsible water usage in order to reduce waste and ensure fair and sustainable water distribution across all beneficiary areas.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-819372-638682164851810729-E7PBFHnrPqhqlWINmmnpVxgwXBmVzx.jpg', false, false, 23, 127, TIMESTAMP '2026-05-07 14:57:24.861', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A rare virus raises concern... what is “Hantavirus” and why are its death rates high?', 'فيروس نادر يثير القلق… ما هو “هانتا” ولماذا ترتفع وفياته؟', 'new-virus-aboard-ha7-5', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "ارتفع عدد الإصابات المؤكدة بفيروس «هانتا» على متن السفينة السياحية «إم في هونديوس» إلى خمس حالات، وفق ما أعلنت منظمة الصحة العالمية، وذلك بعد وفاة زوجين هولنديين وتسجيل وفاة إضافية خلال الرحلة البحرية التي كانت متجهة من أوشوايا في الأرجنتين نحو الرأس الأخضر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبدأت الحادثة مع وفاة راكب هولندي من دون معرفة السبب، قبل أن تُصاب زوجته بالأعراض نفسها وتفارق الحياة لاحقاً. وبعد أيام، نُقل راكب بريطاني إلى جنوب أفريقيا لتلقي العلاج، حيث تبيّن أنه مصاب بفيروس «هانتا»، لتبدأ بعدها التحقيقات الطبية مع تسجيل إصابات إضافية بين الركاب وأفراد الطاقم. السفينة التي انطلقت قبل نحو ثلاثة أسابيع كانت تقلّ 149 شخصاً، فيما تستمر الفحوص للكشف عن حالات جديدة محتملة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "ما هو فيروس «هانتا»؟", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "يوضح اختصاصي الأمراض الجرثومية الدكتور بيار أبي حنا أن فيروس «هانتا» ليس جديداً، بل معروف منذ عقود، وقد سُجّلت إصابات به سابقاً في أوروبا وأفريقيا وأميركا الجنوبية. إلا أنه يُعتبر من الفيروسات النادرة، والخطر الأساسي فيه لا يرتبط بسرعة انتشاره بل بحدة مضاعفاته وارتفاع معدلات الوفيات الناتجة عنه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وينتقل الفيروس عادة عبر القوارض ومخلّفاتها، غير أن الجهات الصحية تدرس حالياً احتمال وجود سلالة قابلة للانتقال بين البشر، وهو أمر لم يكن شائعاً في الإصابات السابقة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "أعراض قد تصل إلى الرئتين والكلى", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تبدأ أعراض الفيروس بحالات عامة تشبه الإنفلونزا، قبل أن تتطور في بعض الحالات إلى مضاعفات خطيرة تصيب الرئتين والكلى. وتشمل الأعراض:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "الحمى", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "التعب والإرهاق", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "آلام العضلات والمفاصل", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "الصداع والدوار", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "التقيؤ والإسهال", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "آلام المعدة", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "صعوبات تنفسية مع تطور الحالة", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "ويشير أبي حنا إلى أن معدل الوفيات قد يصل إلى 40 في المئة، ما يجعل الفيروس خطيراً رغم محدودية انتشاره.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "هل يشكّل خطراً على لبنان والمنطقة؟", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بحسب أبي حنا، لم تُسجّل أي إصابة بفيروس «هانتا» سابقاً في لبنان أو في دول الشرق الأوسط، إذ تتركّز الحالات المعروفة في مناطق محددة من أوروبا وأفريقيا وأميركا الجنوبية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "كيف يُشخّص وهل له علاج؟", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "يُشخّص فيروس «هانتا» عبر فحص دم خاص، لكن لا يوجد حتى الآن علاج مباشر له. ويعتمد الأطباء على معالجة الأعراض والمضاعفات، خصوصاً دعم الجهاز التنفسي بالأوكسيجين عند تطور الإصابة إلى مشاكل رئوية حادة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The number of confirmed Hantavirus cases aboard the cruise ship ", "type": "text"}, {"text": "MV Hondius", "type": "text", "marks": [{"type": "italic"}]}, {"text": " has risen to five, according to the World Health Organization, following the deaths of a Dutch couple and another fatality during the voyage from Ushuaia in Argentina toward Cape Verde.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The incident began with the death of a Dutch passenger from unknown causes, before his wife developed similar symptoms and later died. Days later, a British passenger was transferred to South Africa for treatment, where doctors confirmed a Hantavirus infection, prompting medical investigations and the detection of additional cases among passengers and crew. The ship, which departed around three weeks ago, was carrying 149 people, while testing continues to identify any further infections.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "What is Hantavirus?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Infectious disease specialist Dr. Pierre Abi Hanna explained that Hantavirus is not new and has been known for decades, with previous cases recorded in Europe, Africa, and South America. However, it remains a rare virus, and its main danger lies not in rapid transmission but in the severity of its complications and its high fatality rate.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The virus is usually transmitted through rodents and their waste, though health authorities are currently investigating the possibility of a strain capable of spreading between humans—something uncommon in previous outbreaks.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Symptoms that may affect the lungs and kidneys", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Symptoms initially resemble influenza before potentially developing into severe complications affecting the lungs and kidneys. Symptoms include:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fever", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fatigue and exhaustion", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Muscle and joint pain", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Headaches and dizziness", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vomiting and diarrhea", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stomach pain", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Breathing difficulties as the condition worsens", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Abi Hanna noted that the mortality rate can reach up to 40%, making the virus particularly dangerous despite its limited spread.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Does it pose a threat to Lebanon and the region?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Abi Hanna, no Hantavirus cases have previously been recorded in Lebanon or the Middle East, with known infections mostly concentrated in parts of Europe, Africa, and South America.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "How is it diagnosed and is there treatment?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hantavirus is diagnosed through a specialized blood test, but there is currently no direct cure. Treatment focuses on managing symptoms and complications, particularly supporting the respiratory system with oxygen if severe lung problems develop.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/virus-HExiNIvenYPIUR8Peqkcej1fFcDF1d.jpg', false, false, 2477, 4701, TIMESTAMP '2026-05-07 16:20:28.063', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Trump comments on the spread of “Hantavirus” aboard a cruise ship… and health monitoring continues for infected cases', 'ترامب يعلّق على تفشي “هانتا” على متن سفينة سياحية… ومتابعة صحية للحالات المصابة', 'trump-hanta-stat', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "تصاعدت المخاوف الدولية بعد تفشي فيروس «هانتا» النادر على متن سفينة سياحية كانت تبحر في المحيط الأطلسي، في حادثة أسفرت حتى الآن عن وفاة ثلاثة ركاب وإصابة آخرين، وسط استنفار صحي في عدد من الدول لمتابعة المخالطين ومنع انتقال العدوى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأعاد المشهد إلى الأذهان البدايات الأولى لجائحة «كوفيد-19»، خصوصاً مع انتقال الركاب بين عدة دول ومغادرتهم السفينة قبل اكتشاف الإصابات بشكل رسمي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي أول تعليق له، قال الرئيس الأميركي دونالد ترامب إنه اطّلع على التقارير المتعلقة بالوضع الصحي على متن السفينة، معرباً عن أمله في أن يكون الوضع «تحت السيطرة». وأضاف خلال تصريحات صحافية: «هناك الكثير من الأشخاص المميزين يدرسون الأمر، ونأمل أن يكون كل شيء على ما يرام». وعندما سُئل عمّا إذا كان الأميركيون يجب أن يقلقوا، أكد أنه لا يعتقد أن الفيروس سيتحوّل إلى تهديد واسع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكانت وكالة الأمن الصحي البريطانية قد أعلنت تسجيل إصابات مؤكدة بين مواطنين بريطانيين، إلى جانب الاشتباه بحالة ثالثة مرتبطة بالسفينة السياحية «إن في هونديوس»، التي كانت تقل نحو 147 راكباً وأفراد الطاقم منذ انطلاقها من مدينة أوشوايا في جنوب الأرجنتين مطلع نيسان، قبل توجهها نحو جزر الكناري.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتكمن المخاوف الأساسية في أن عدداً من الركاب غادروا السفينة قبل رسوها النهائي قرب كاب فيردي، ما دفع سلطات صحية في عدة دول إلى إطلاق عمليات تتبع واسعة للتأكد من عدم انتقال العدوى إلى أشخاص آخرين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هولندا، أكدت مستشفيات إصابة راكبين تم إجلاؤهما من السفينة، فيما تبين أن الوفيات الثلاث المسجلة تعود لامرأة ألمانية وزوجين هولنديين كانوا قد شاركوا في جولة بأميركا الجنوبية قبل الرحلة البحرية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، حاولت منظمة الصحة العالمية تهدئة المخاوف، مشيرة إلى أن فيروس «هانتا» لا يُصنّف ضمن الأوبئة العالمية، وأنه لا ينتشر بالسرعة نفسها التي انتشر بها فيروس كورونا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم ذلك، سارعت بريطانيا والولايات المتحدة إلى اعتماد إجراءات صحية احترازية، فيما يواصل خبراء في الأرجنتين التحقيق لمعرفة ما إذا كانت العدوى بدأت هناك قبل انتقالها إلى السفينة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويُعتبر فيروس «هانتا» من الأمراض النادرة والخطيرة التي تنتقل عادة عبر القوارض أو إفرازاتها، وقد يؤدي في بعض الحالات إلى مضاعفات تنفسية حادة، وهو ما يفسّر تنامي القلق الدولي رغم محاولات التطمين الرسمية.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "International concerns have escalated after the spread of the rare Hantavirus aboard a cruise ship sailing in the Atlantic Ocean, in an incident that has so far resulted in the deaths of three passengers and infections among others, prompting health alerts in several countries to track contacts and prevent further transmission.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The situation has revived memories of the early days of the COVID-19 pandemic, especially as passengers traveled across multiple countries and left the ship before the infections were officially detected.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In his first comment on the matter, US President Donald Trump said he had reviewed reports related to the health situation aboard the ship and expressed hope that the situation was “under control.” Speaking to reporters, he said: “There are many talented people looking into it, and hopefully everything will be fine.” When asked whether Americans should be worried, he stressed that he does not believe the virus will become a widespread threat.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The UK Health Security Agency had earlier confirmed infections among British citizens, along with a suspected third case linked to the cruise ship ", "type": "text"}, {"text": "MV Hondius", "type": "text", "marks": [{"type": "italic"}]}, {"text": ", which was carrying around 147 passengers and crew members after departing from Ushuaia in southern Argentina in early April before heading toward the Canary Islands.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The main concern lies in the fact that several passengers disembarked before the ship’s final docking near Cape Verde, prompting health authorities in multiple countries to launch extensive contact-tracing operations to ensure the virus had not spread further.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the Netherlands, hospitals confirmed infections among two passengers evacuated from the ship, while the three recorded deaths were identified as a German woman and a Dutch couple who had participated in a South American tour before the voyage.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, the World Health Organization attempted to ease fears, noting that Hantavirus is not classified as a global pandemic threat and does not spread at the same speed as COVID-19.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite this, Britain and the United States quickly implemented precautionary health measures, while experts in Argentina continue investigating whether the outbreak began there before spreading aboard the ship.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hantavirus is considered a rare but dangerous disease usually transmitted through rodents or their secretions. In some cases, it can lead to severe respiratory complications, which explains the growing international concern despite official reassurances.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/mobius-ship-Qr35qgV5KEX0rMdo51VZMmlWruumSu.jpg', false, false, 340, 1135, TIMESTAMP '2026-05-08 13:15:10.639', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Instagram rolls back message encryption… what does this mean for users?', 'إنستغرام يتراجع عن تشفير الرسائل… ماذا يعني ذلك للمستخدمين؟', 'insta-new-encryption-9-5', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "في خطوة أثارت جدلاً واسعاً، قررت إنستغرام إنهاء العمل بميزة التشفير الكامل للرسائل الخاصة، وهي التقنية التي كانت تمنع أي طرف خارجي، حتى الشركة نفسها، من قراءة محتوى المحادثات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "القرار يعني عملياً أن الرسائل المتبادلة عبر التطبيق، بما فيها الصور والمقاطع الصوتية والفيديوهات، لم تعد تتمتع بالمستوى نفسه من الخصوصية الذي كانت توفره ميزة “End-to-End Encryption”.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم أن “ميتا” كانت قد أعلنت قبل سنوات توجهاً نحو تعزيز الخصوصية داخل تطبيقاتها، وتحدثت حينها عن مستقبل يعتمد على التشفير الكامل، فإن إنستغرام لم يعتمد هذه الميزة بشكل أساسي، بل أبقاها خياراً اختيارياً يحتاج إلى تفعيل يدوي داخل المحادثات، ما جعل استخدامها محدوداً بين المستخدمين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الشركة برّرت التراجع عن الميزة بأن عدد الأشخاص الذين استخدموها كان منخفضاً، في حين يرى منتقدون أن السبب الحقيقي يعود إلى تعقيد تفعيلها وعدم تشغيلها تلقائياً منذ البداية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الخطوة لاقت دعماً من جهات معنية بحماية الأطفال ومكافحة الجرائم الإلكترونية، إذ تعتبر هذه الجهات أن التشفير الكامل يصعّب رصد المحتوى الإجرامي أو حالات الاستغلال داخل المنصات الرقمية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، اعتبرت منظمات تُعنى بالخصوصية الرقمية أن ما قامت به “ميتا” يُشكّل تراجعاً واضحاً عن حماية بيانات المستخدمين، خصوصاً مع تزايد المخاوف المرتبطة باستخدام شركات التكنولوجيا للبيانات في تطوير تقنيات الذكاء الاصطناعي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويأتي القرار أيضاً في وقت تتجه فيه شركات التكنولوجيا إلى توسيع استخدام البيانات لتحسين أنظمة التوصيات والخدمات الذكية، رغم تأكيدات سابقة من إنستغرام بأن الرسائل الخاصة لا تُستخدم لتدريب أدوات الذكاء الاصطناعي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبينما تخلّت إنستغرام عن هذه الحماية، لا تزال تطبيقات أخرى مثل واتساب وسيغنال وفيسبوك ماسنجر تعتمد التشفير الكامل بشكل افتراضي، ما يجعلها أكثر جاذبية للمستخدمين الذين يضعون الخصوصية في مقدمة أولوياتهم.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "In a move that sparked widespread controversy, Instagram has decided to discontinue full end-to-end encryption for private messages — the technology that previously prevented any external party, including the company itself, from reading conversations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In practical terms, this means that messages exchanged through the app — including photos, voice notes, and videos — will no longer enjoy the same level of privacy previously offered by end-to-end encryption.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although Meta had announced years ago its intention to strengthen privacy across its apps and spoke about a future built around full encryption, Instagram never made the feature standard. Instead, it remained an optional setting requiring manual activation within chats, which limited its adoption among users.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The company justified the move by saying that only a small number of users activated the feature, while critics argue the real issue was the complexity of enabling it and the failure to make it active by default from the beginning.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The decision received support from organizations focused on child protection and combating cybercrime, which argue that full encryption makes it harder to detect criminal content or exploitation on digital platforms.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, digital privacy advocates considered Meta’s move a clear setback in protecting user data, especially amid growing concerns about technology companies using personal information to develop artificial intelligence systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The decision also comes at a time when tech companies are increasingly expanding their use of data to improve recommendation systems and smart services, despite Instagram’s previous assurances that private messages were not used to train AI tools.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "While Instagram has stepped back from this protection layer, other platforms such as WhatsApp, Signal, and Facebook Messenger still use end-to-end encryption by default, making them more attractive to users who prioritize privacy.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/cbad6e00-4a17-11f1-a7ce-b934bcb15ff4.jpg-52f9PHmjUA3mjgHhxpYiTjdrbFxQko.webp', false, false, 99, 370, TIMESTAMP '2026-05-09 00:26:31.843', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Massacre in Nabatieh… and a wide Israeli escalation targeting southern villages', 'مجزرة في النبطية… وتصعيد إسرائيلي واسع يطال قرى الجنوب', 'nab-isr-mas', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "استُشهد مواطن وأصيبت ابنته البالغة 12 عاماً بجروح خطيرة، اليوم، إثر استهداف نفذته مسيّرة إسرائيلية في مدينة النبطية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي التفاصيل، أطلقت المسيّرة ثلاثة صواريخ قرب ثانوية الصباح، مستهدفة الأب وابنته أثناء وجودهما على دراجة نارية. وبعد نجاتهما من الصاروخ الأول، استهدفته المسيّرة مجدداً ما أدى إلى استشهاده، قبل أن تطلق صاروخاً ثالثاً باتجاه الطفلة بعد ابتعادها عن المكان، ما تسبب بإصابتها بجروح خطيرة ونقلها إلى المستشفى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي اعتداء آخر، أدت غارة استهدفت سيارة بين برج رحال والعباسية إلى استشهاد ثلاثة أشخاص كانوا بداخلها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وترافق ذلك مع قصف وغارات طالت عدداً من بلدات الجنوب، بينها النبطية وبرعشيت وتولين والغندورية وفرون، إضافة إلى غارات على حاريص وكفرا والمنصوري، وسط تحليق مكثف للمسيّرات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما هدّد جيش الاحتلال سكان عدد من البلدات الجنوبية بإخلاء منازلهم، فيما استمر القصف المدفعي وإطلاق القنابل المضيئة على مناطق عدة خلال الليل.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "A civilian was killed and his 12-year-old daughter seriously injured today after an Israeli drone strike in the city of Nabatieh.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to reports, the drone fired three missiles near Al-Sabah Secondary School, targeting the father and daughter while they were riding a motorcycle. After surviving the first missile, the drone targeted them again, killing the father. It then launched a third missile at the child after she had moved away from the area, causing severe injuries and leading to her transfer to the hospital.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In another attack, an airstrike targeting a car between Burj Rahhal and Al-Abbassiyah killed three people inside the vehicle.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The escalation coincided with shelling and airstrikes targeting several southern towns, including Nabatieh, Braachit, Touline, Ghandoorieh, and Froun, in addition to strikes on Haris, Kfara, and Mansouri, amid heavy drone activity overhead.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Israeli army also warned residents of several southern villages to evacuate their homes, while artillery shelling and illumination flares continued across multiple areas overnight.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/058a7010-8bcd-11ef-b9e0-dbdcd2deee83-NvyYMNxMGQanIAG69R5s0yRqBraU4p.jpg', false, false, 108, 492, TIMESTAMP '2026-05-09 10:53:44.237', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'How did a café worker manage to deceive security officials?', 'كيف تمكن عامل مقهى من خداع مسؤولين أمنيين؟', 'cofe-worker-decieve', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أوقفت مديرية مخابرات الجيش اللبناني عاملًا عراقيًا انتحل صفة مسؤول أمني في سفارة بغداد في بيروت، بعدما تمكّن من نسج علاقات وعقد لقاءات مع مسؤولين أمنيين لبنانيين رفيعي المستوى، بحسب ما أفاد الجيش ومصدر عسكري الأحد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأورد الجيش في بيان أن مديرية المخابرات التابعة له أوقفت مواطنًا عراقيًا \"لانتحاله صفة مسؤول أمني عراقي داخل الأراضي اللبنانية ، وذلك نتيجة عملية رصد ومتابعة أمنية\".وأظهر التحقيق الأولي أن الموقوف \"استعان بمستندات مزورة\"، بحسب البيان الذي أكد أنه تمّ ضبط \"البزّة العسكرية التي كان يستخدمها\".", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وقال مصدر عسكري من جهته لوكالة \"فرانس برس\" إن الموقوف متزوج من لبنانية ويقيم في البلاد منذ سنوات، وكان لدى توقيفه يعمل مساعدًا لمالك مقهى شعبي في الضاحية، حيث كان بدأ العمل في خدمة ركن السيارات.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "عراقي يعمل في مقهى خدع مسؤولين أمنيين لبنانيين", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "إلا أنه \"تمكّن من التقرب من مسؤول استخبارات في بيروت وقدّم نفسه كضابط عراقي في فرع مكافحة الإرهاب وملحق أمني بالسفارة العراقية في بيروت\"، بحسب المصدر الذي طلب عدم كشف اسمه.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وأوضح أن المسؤول الأمني ساعد العراقي \"على التواصل مع مسؤولين أمنيين وعسكريين واللقاء بهم، ما مكّنه من خلق حيثية\" في لبنان.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وبحسب التحقيق الأولي مع الموقوف ومع ضباط التقوا به، لم يتبين بعد، وفق المصدر العسكري، \"هدفه من انتحال صفة ضابط عراقي في لبنان\".", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وفي حين أشار المصدر الى أن الموقوف \"قدّم خلال لقاءاته وعودًا بتوفير مساعدات مالية من العراق\"، رأى أن \"خطورة القضية تكمن في إقناعه ضباط استخبارات بشخصيته الوهمية في حين أنه عامل\" في مقهى.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وسبق للسلطات في بيروت أن كشفت هذا العام عن انتحال لبناني يعمل في حدادة السيارات، صفة أمير سعودي مقرب من الديوان الملكي، وقيامه بابتزاز سياسيين بينهم نواب ورئيس حكومة أسبق، لقاء مبالغ مالية بالتنسيق مع رجل دين مرتبط بدار الفتوى.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "ووصلت عمليات الابتزاز، وفق مصدر قضائي، إلى حدّ إملاء مواقف سياسية على عدد من النواب والوزراء الحاليين والسابقين.", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Lebanese Army Intelligence arrested an Iraqi worker who impersonated a security official at the Iraqi embassy in Beirut after he managed to build relationships and hold meetings with senior Lebanese security officials, according to the army and a military source on Sunday.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a statement, the army said its Intelligence Directorate arrested an Iraqi citizen “for impersonating an Iraqi security official on Lebanese territory” following a surveillance and security monitoring operation. Preliminary investigations showed that the suspect had used forged documents, while authorities also seized the military uniform he used.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A military source told AFP that the suspect is married to a Lebanese woman and has lived in Lebanon for years. At the time of his arrest, he was working as an assistant to the owner of a popular café in Beirut’s southern suburbs, where he had initially worked in valet parking services.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite this, he reportedly managed to approach an intelligence official in Beirut and introduced himself as an Iraqi officer in the counterterrorism branch and a security attaché at the Iraqi embassy in Beirut.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the source, the Lebanese security official helped him connect and meet with military and intelligence figures, enabling him to build credibility and influence in Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Initial investigations with the suspect and officers who met him have not yet determined his exact motive for impersonating an Iraqi officer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The source added that during his meetings, the suspect promised financial aid from Iraq. However, the real danger of the case lies in the fact that he convinced intelligence officers of his fabricated identity despite actually being a café worker.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Earlier this year, Lebanese authorities uncovered another impersonation case involving a Lebanese man working in car body repair who pretended to be a Saudi prince close to the royal court. In coordination with a cleric linked to Dar al-Fatwa, he allegedly extorted politicians—including MPs and a former prime minister—in exchange for money.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to a judicial source, the blackmail operations went as far as dictating political positions to several current and former ministers and MPs.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2024-11-02T145207Z_1652410250_RC22XAABFR38_RTRMADP_3_ISRAEL-PALESTINIANS-LEBANON-BATROUN-IrLOzWKXheLd1wJVZb8PCzvxV5Oq1x.webp', false, false, 248, 660, TIMESTAMP '2026-05-10 17:59:45.072', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Complaint filed against a private school in Beirut… are tuition fees taking priority over humanitarian circumstances?', 'شكوى ضد مدرسة خاصة في بيروت… هل تتقدّم الأقساط على الظروف الإنسانية؟', 'prv-skl-complaints', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعادت حادثة مرتبطة بإحدى المدارس الخاصة في بيروت فتح النقاش حول كيفية تعاطي المؤسسات التربوية مع العائلات خلال الأزمات الأمنية والاقتصادية، خصوصاً عندما تتحوّل الأقساط والالتزامات المالية إلى أولوية تتقدّم على الظروف الإنسانية التي يعيشها الأهالي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا الإطار، علمت «الأخبار» أن شكوى قُدّمت إلى وزارة التربية ضد إدارة المدرسة الألمانية الدولية في بيروت (DISB)، بعد إلغاء تسجيل عدد من التلامذة للعام الدراسي 2026 – 2027 بسبب عدم تسديد الدفعة الأولى ضمن المهلة المحددة، رغم أن الأسرة المعنية كانت قد نزحت من منزلها نتيجة التطورات الأمنية الأخيرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب مضمون الشكوى، فإن المدرسة كانت قد علّقت التعليم، بما فيه التعليم عن بُعد، بسبب الوضع الأمني، لكنها أبقت باب التسجيل مفتوحاً لفترة قصيرة لتسديد الدفعة الأولى، والتي توازي نحو 20% من القسط السنوي. وتزامنت مهلة الدفع مع ذروة النزوح والاضطراب الأمني، ما حال دون تمكن الأسرة من استكمال الإجراءات المطلوبة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتشير المعلومات إلى أن الأهل تواصلوا مع الإدارة فور تبلغهم قرار الإلغاء، وعرضوا تسديد كامل المبلغ مباشرة مقابل إعادة تسجيل أولادهم، إلا أن المدرسة رفضت التراجع عن قرارها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لاحقاً، برّرت الإدارة موقفها بعدم تلقيها إشعاراً خطياً مستقلاً يفيد بتعذّر الدفع خلال فترة الحرب، رغم أن العائلة كانت قد أبلغتها خطياً بواقعة النزوح قبل صدور قرار الشطب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "القضية لم تتوقف عند الجانب المالي، إذ استندت الشكوى أيضاً إلى المادة العاشرة من قانون تنظيم الموازنات المدرسية، التي تمنع اتخاذ إجراءات تضر بالتلميذ نتيجة خلاف مالي أو إداري مع ذويه. ويرى مقدّمو الشكوى أن ما جرى يطرح تساؤلات حول مدى انسجام القرار مع روح القانون، خصوصاً أن الأطفال وجدوا أنفسهم يتحملون نتائج ظروف فرضتها الحرب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي موازاة ذلك، أعادت الحادثة طرح أسئلة أوسع حول آلية الأقساط المعتمدة في بعض المدارس الخاصة، لا سيما لجهة مطالبة الأهالي بدفع نسبة كبيرة من الرسوم قبل أشهر طويلة من انطلاق العام الدراسي، وفي مرحلة لم تبدأ فيها بعد الكلفة التشغيلية الفعلية للسنة الجديدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويثير هذا الواقع تساؤلات لدى عدد من الأهالي حول ما إذا كانت هذه الدفعات تُستخدم فقط لضمان الاستقرار المالي للمؤسسات التعليمية، أم أنها باتت تشكّل وسيلة تمويل مبكر تُحمّل العائلات أعباء إضافية حتى في أصعب الظروف.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي انتظار ما ستقرره وزارة التربية بشأن الشكوى، تبدو القضية أبعد من مجرد خلاف بين مدرسة وأسرة، لتتحول إلى اختبار جديد لمفهوم المسؤولية الاجتماعية داخل القطاع التربوي الخاص في لبنان.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "A recent incident involving a private school in Beirut has reignited debate over how educational institutions deal with families during security and economic crises, especially when tuition fees and financial obligations appear to take priority over the humanitarian conditions families are facing.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, ", "type": "text"}, {"text": "Al-Akhbar", "type": "text", "marks": [{"type": "italic"}]}, {"text": " learned that a complaint was submitted to the Ministry of Education against the administration of the German International School Beirut (DISB), after the registration of several students for the 2026–2027 academic year was canceled due to the non-payment of the first installment within the specified deadline, despite the family having been displaced from their home because of recent security developments.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the complaint, the school had suspended classes, including remote learning, due to the security situation, but kept registration open for a short period to collect the first installment, equivalent to around 20% of the annual tuition. The payment deadline coincided with the peak of displacement and security chaos, preventing the family from completing the required procedures.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sources indicate that the parents contacted the administration immediately after learning of the cancellation decision and offered to pay the full amount directly in exchange for reinstating their children’s registration, but the school refused to reverse its decision.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Later, the administration justified its position by claiming it had not received a separate written notice explaining the family’s inability to pay during the war period, despite the fact that the family had already informed the school in writing about their displacement before the cancellation decision was issued.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The issue did not stop at the financial aspect. The complaint also referred to Article 10 of the school budget regulation law, which prohibits taking measures that harm students because of financial or administrative disputes with their parents. Those behind the complaint argue that what happened raises questions about whether the school’s decision aligns with the spirit of the law, especially since the children ended up bearing the consequences of circumstances imposed by war.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, the incident has revived broader questions about tuition payment systems adopted by some private schools, particularly the requirement for parents to pay large portions of fees months before the academic year begins, at a stage when the actual operational costs of the new year have not yet started.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This reality has prompted some parents to question whether these payments are solely intended to ensure financial stability for educational institutions, or whether they have become a form of early financing that places additional burdens on families even in the harshest conditions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "While awaiting the Ministry of Education’s decision regarding the complaint, the issue appears to go beyond a simple dispute between a school and a family, turning instead into a new test of the concept of social responsibility within Lebanon’s private education sector.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Doc-P-691779-638143206284779163-x8yD7PI2C86w9UtDREOFa2y9WIfYrR.jpg', false, false, 379, 1096, TIMESTAMP '2026-05-11 13:07:11.926', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'New Saudi-Iranian contact… ongoing coordination over regional files', 'تحرك سعودي إيراني لمواكبة التطورات الإقليمية', 'ir-sau-calls', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "شهدت الساعات الماضية جولة جديدة من التواصل الدبلوماسي بين السعودية وإيران، مع اتصال هاتفي جمع وزير الخارجية السعودي الأمير فيصل بن فرحان بنظيره الإيراني عباس عراقجي، في ظل التصعيد الإقليمي والمفاوضات الجارية بين طهران وواشنطن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب ما أعلنته الجهات الرسمية، تناول الاتصال التطورات السياسية والأمنية في المنطقة، إضافة إلى ملف الوساطة الباكستانية والمحادثات الإيرانية ـ الأميركية، إلى جانب الجهود المبذولة لخفض التوتر والحفاظ على الاستقرار الإقليمي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويأتي هذا التواصل بعد أيام فقط من اتصال مماثل بين الوزيرين، في مؤشر على استمرار التنسيق السياسي بين الرياض وطهران في مرحلة تشهد تحولات متسارعة على مستوى المنطقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت الخارجية الإيرانية أن النقاش شمل أيضاً سبل دعم الاستقرار وتعزيز التوازن الإقليمي في مواجهة التحديات الحالية، فيما شدد الطرفان على أهمية الحلول السياسية والدبلوماسية لتجنب المزيد من التصعيد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتزامن هذه الاتصالات مع استمرار التوترات المرتبطة بالحرب الدائرة والتطورات الأمنية في الخليج ولبنان، إضافة إلى استمرار المحادثات غير المباشرة بين إيران والولايات المتحدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما يعكس هذا الحراك استمرار مسار التقارب السعودي ـ الإيراني منذ استئناف العلاقات بين البلدين، وسط توقعات بأن يسهم هذا التواصل في تخفيف حدة التوتر وفتح قنوات تفاهم أوسع في ملفات المنطقة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Over the past hours, a new round of diplomatic communication took place between Saudi Arabia and Iran, with a phone call between Saudi Foreign Minister Prince Faisal bin Farhan and his Iranian counterpart Abbas Araghchi amid regional escalation and ongoing negotiations between Tehran and Washington.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to official statements, the call addressed political and security developments in the region, including the Pakistani mediation file and the Iranian-American talks, in addition to efforts aimed at reducing tensions and preserving regional stability.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This communication comes only days after a similar call between the two ministers, signaling continued political coordination between Riyadh and Tehran during a period marked by rapid regional changes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Iranian Foreign Ministry stated that discussions also covered ways to support stability and strengthen regional balance in the face of current challenges, while both sides stressed the importance of political and diplomatic solutions to avoid further escalation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These contacts coincide with ongoing tensions related to the war and security developments in the Gulf and Lebanon, as well as the continuation of indirect talks between Iran and the United States.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The diplomatic movement also reflects the continuation of the Saudi-Iranian rapprochement process since the restoration of relations between the two countries, amid expectations that such communication could help ease tensions and open broader channels of understanding on regional issues.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/gendmdsxyaafn0q_524919-ighblj4RE3UepyRdUMcGwL4SRYL4LT.jpeg', false, false, 21, 135, TIMESTAMP '2026-05-11 13:45:44.838', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Israel pursues the drone mystery in the South… and 100 operatives at the center of estimates', 'إسرائيل تلاحق لغز المسيّرات جنوباً… و100 عنصر في قلب التقديرات', '100drone-user-hzb-125', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "لا تزال المسيّرات المتفجرة التابعة لحزب الله تشكّل أحد أكثر التحديات تعقيداً أمام الجيش الإسرائيلي، في ظل إقرار متزايد داخل إسرائيل بصعوبة التعامل معها ميدانياً، رغم التفوق التكنولوجي والعسكري الذي تتحدث عنه تل أبيب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، كشفت القناة 12 الإسرائيلية أن الجيش يستعد لاحتمال توسيع عملياته البرية داخل لبنان، بانتظار قرار من المستوى السياسي، وذلك بسبب ما وصفته المؤسسة العسكرية بـ«التهديد الكبير» الذي تمثله المسيّرات على القوات الإسرائيلية المنتشرة في جنوب لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وخلال الأسابيع الأخيرة، أعلن الجيش الإسرائيلي بشكل شبه يومي وقوع إصابات في صفوف جنوده نتيجة هجمات نفذتها مسيّرات تابعة لحزب الله، بالتزامن مع عمليات التوغّل ونسف المباني داخل البلدات الجنوبية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم الإجراءات الأمنية والتقنيات الدفاعية المستخدمة، أقرت إذاعة الجيش الإسرائيلي بنجاح إحدى المسيّرات في استهداف بطارية تابعة لمنظومة «القبة الحديدية»، في تطور اعتُبر لافتاً داخل الأوساط العسكرية الإسرائيلية.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "100 مشغّل للمسيّرات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب تقديرات الجيش الإسرائيلي، فإن حزب الله يمتلك نحو 100 عنصر متخصص في تشغيل المسيّرات المتفجرة، مشيراً إلى أن عدداً محدوداً منهم فقط قُتل خلال العمليات الأخيرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت إذاعة الجيش أن تشغيل المسيّرات المزودة بتقنية الألياف الضوئية يُعد عملية معقدة تحتاج إلى تدريبات خاصة، لافتة إلى أن معظم المشغّلين تلقوا تدريباتهم خلال فترة وقف إطلاق النار السابقة بين أواخر 2024 وآذار 2026.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ونقلت الإذاعة عن ضابط إسرائيلي رفيع قوله إن استهداف هؤلاء المشغّلين بات أولوية استخبارية وعملية، مع اعترافه بأن النتائج المحققة حتى الآن «غير كافية»، وأن حزب الله يواصل تدريب عناصر إضافيين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشارت التقديرات الإسرائيلية إلى أن معظم عمليات تشغيل المسيّرات تتم من مناطق تقع جنوب نهر الليطاني، خارج ما يُعرف بـ«الخط الأصفر»، مستفيدة من تقنيات تعتمد على الألياف الضوئية بدلاً من إشارات الراديو التقليدية، ما يجعل رصدها أو التشويش عليها أكثر صعوبة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "مسيّرات يصعب رصدها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتعتمد هذه المسيّرات على خيط ألياف ضوئية رفيع ينفلت تدريجياً أثناء الطيران، ما يسمح بنقل الصور والأوامر بشكل مباشر، من دون الحاجة إلى موجات لاسلكية أو نظام GPS، وهو ما يمنحها قدرة أكبر على التخفّي وتجاوز أنظمة التشويش.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب خبراء عسكريين، فإن هذه التقنيات تمنح المشغّلين قدرة على تعديل مسار المسيّرة أو إيقافها مؤقتاً وتغيير هدفها أثناء التحليق، بفضل الكاميرات الدقيقة التي تحملها.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "«حزب الله ينتظر المواجهة»", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، رأى الخبير العسكري العميد حسن جوني أن أي توسيع إسرائيلي للعمليات البرية سيجعل الوضع أكثر تعقيداً بالنسبة للجيش الإسرائيلي، معتبراً أن تل أبيب تحاول الوصول إلى المشغّلين بعد عجزها عن إسقاط المسيّرات بعد إطلاقها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار إلى أن المواجهة البرية تبقى نقطة قوة لعناصر حزب الله الذين يعرفون جغرافية الجنوب جيداً، في وقت يفضّل فيه الجيش الإسرائيلي الاعتماد على القوة الجوية لتجنب الاحتكاك المباشر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبر جوني أن استهداف منصة «القبة الحديدية» قرب جل العلام يُعد تطوراً مهماً، لأن المنصة كانت مخصصة لحماية العمق الإسرائيلي، ما يعني أن «الجهة المكلفة بالحماية أصبحت نفسها هدفاً مباشراً».", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تطوير مستمر", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتعتقد إسرائيل أن حزب الله استغل فترة وقف إطلاق النار الماضية لتطوير قدراته في مجال المسيّرات، سواء عبر شراء وتجميع طائرات جديدة أو عبر توسيع برامج التدريب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تشير التقديرات الإسرائيلية إلى أن مشغّلي المسيّرات لا يتبعون وحدة واحدة داخل الحزب، بل يتوزعون ضمن وحدات جغرافية مختلفة في الجنوب، ما يزيد من صعوبة تعقبهم أو استهدافهم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويأتي ذلك في ظل استمرار التصعيد العسكري على الجبهة اللبنانية، حيث تواصل إسرائيل غاراتها وقصفها المدفعي وعمليات نسف المنازل، رغم سريان اتفاق وقف إطلاق النار الهش منذ نيسان الماضي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Hezbollah’s explosive drones continue to represent one of the most complex challenges facing the Israeli army, amid growing acknowledgment inside Israel of the difficulty in confronting them on the battlefield despite Tel Aviv’s claimed technological and military superiority.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Israel’s Channel 12 revealed that the army is preparing for the possibility of expanding its ground operations inside Lebanon, pending a political decision, due to what the military establishment described as the “major threat” posed by drones to Israeli forces deployed in southern Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Over recent weeks, the Israeli army has announced almost daily casualties among its soldiers resulting from Hezbollah drone attacks, coinciding with incursions and demolition operations inside southern villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite security measures and defensive technologies, Israeli Army Radio acknowledged that one drone successfully struck a battery belonging to the Iron Dome system, in what was described as a significant development within Israeli military circles.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "100 drone operators", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Israeli military estimates, Hezbollah possesses around 100 specialized operators of explosive drones, noting that only a limited number of them have been killed during recent operations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli Army Radio explained that operating drones equipped with fiber-optic technology is a complex process requiring special training, adding that most operators received training during the previous ceasefire period between late 2024 and March 2026.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The station quoted a senior Israeli officer saying that targeting these operators has become an intelligence and operational priority, while admitting that the results achieved so far are “insufficient” and that Hezbollah continues training additional personnel.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli assessments also indicate that most drone operations are launched from areas south of the Litani River, beyond the so-called “yellow line,” using fiber-optic systems instead of conventional radio signals, making detection and jamming far more difficult.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Drones difficult to detect", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These drones rely on a thin fiber-optic cable that unwinds gradually during flight, allowing direct transmission of images and commands without relying on wireless signals or GPS systems, giving them greater stealth and resistance to electronic warfare systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to military experts, these technologies allow operators to alter the drone’s route, temporarily stop it, or change targets mid-flight thanks to the precision cameras onboard.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "“Hezbollah is waiting for confrontation”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other side, military expert Brigadier General Hassan Jouni argued that any Israeli expansion of ground operations would make the situation more complicated for the Israeli army, saying Tel Aviv is attempting to reach drone operators after failing to intercept drones once launched.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He noted that ground confrontation remains a point of strength for Hezbollah fighters, who are highly familiar with southern Lebanon’s geography, while the Israeli army prefers relying on air power to avoid direct engagement.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Jouni also described the targeting of the Iron Dome platform near Jall al-Allam as an important development because the system had been designated to protect the Israeli interior, meaning “the entity tasked with protection has itself become a direct target.”", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Continuous development", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israel believes Hezbollah used the previous ceasefire period to expand its drone capabilities, whether through purchasing and assembling new drones or expanding training programs.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli estimates further indicate that drone operators are not concentrated within a single Hezbollah unit, but are distributed across various geographical units in southern Lebanon, increasing the difficulty of tracking or targeting them.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This comes amid ongoing military escalation on the Lebanese front, with Israel continuing airstrikes, artillery shelling, and home demolitions despite the fragile ceasefire agreement that has been in effect since last April.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/sd5f445-1778410143-sz0SHF4RFgFxpY0VvQVNbrzb3yWaDQ.jpg', false, false, 19, 38, TIMESTAMP '2026-05-12 11:55:40.158', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Russia Enters a New Arms Phase', 'روسيا تدخل مرحلة تسلّح جديدة', 'sarmat-rocket-new', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت روسيا نجاح اختبار منظومة «سارمات» النووية الجديدة، في خطوة تعكس تصاعد التنافس العسكري والنووي مع الغرب، فيما كشف الرئيس الروسي فلاديمير بوتين عن قدرات وصفها بـ«غير المسبوقة» للصاروخ العابر للقارات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وخلال استماعه إلى تقرير بشأن عملية الإطلاق، قال بوتين إن صاروخ «سارمات» لا يعتمد فقط على المسار الباليستي التقليدي، بل يمتلك القدرة على التحرك عبر مسار شبه مداري، ما يسمح له بتجاوز أنظمة الدفاع الصاروخي الحالية وحتى المستقبلية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن المنظومة الجديدة تتمتع بدقة عالية وقدرات كبيرة على اختراق الدفاعات، مشيراً إلى أن قوة رأسها الحربي تفوق بأكثر من أربعة أضعاف أي رأس حربي غربي مماثل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووصف بوتين «سارمات» بأنه «أقوى منظومة صواريخ في العالم»، مؤكداً أنها تتفوق على منظومة «فويفودا» السوفيتية التي شكّلت لعقود جزءاً أساسياً من الترسانة النووية الروسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وجاءت تصريحات الرئيس الروسي بعد إعلان قائد قوات الصواريخ الإستراتيجية سيرغي كاراكايف نجاح تجربة إطلاق الصاروخ، الذي يُعد من أحدث الصواريخ الباليستية العابرة للقارات العاملة بالوقود السائل الثقيل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويُنظر إلى «سارمات» كأحد أبرز أسلحة الردع الروسية، نظراً لقدرته على حمل عدة رؤوس نووية وتغيير مساراته أثناء التحليق لتفادي أنظمة الاعتراض.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي السياق نفسه، أكد بوتين أن موسكو تواصل تنفيذ برنامج تطوير قواتها النووية، كاشفاً أن منظومة «أوريشنيك» الأرضية متوسطة المدى دخلت الخدمة منذ عام 2025، مع إمكانية تزويدها برؤوس نووية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشار إلى أن العمل بات في مراحله الأخيرة على منظومتين جديدتين تعملان بمحركات نووية صغيرة، هما الغواصة المسيّرة «بوسيدون» وصاروخ كروز «بوريفستنيك».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التطورات في ظل تصاعد التوتر بين روسيا والغرب على خلفية الحرب في أوكرانيا، وسط تحذيرات من عودة سباق التسلح النووي إلى الواجهة الدولية بوتيرة غير مسبوقة منذ نهاية الحرب الباردة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Russia announced the successful test of its new nuclear “Sarmat” missile system, in a move reflecting the growing military and nuclear rivalry with the West. Russian President Vladimir Putin revealed what he described as the missile’s “unprecedented” capabilities.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "While listening to a report on the launch operation, Putin stated that the “Sarmat” missile does not rely solely on the traditional ballistic trajectory, but is also capable of traveling along a semi-orbital path, allowing it to bypass current and even future missile defense systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added that the new system possesses high precision and strong penetration capabilities, noting that the power of its warhead exceeds that of any comparable Western warhead by more than four times.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Putin described the “Sarmat” as “the most powerful missile system in the world,” emphasizing that it surpasses the Soviet-era “Voevoda” system, which had formed a key part of Russia’s nuclear arsenal for decades.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Russian president’s statements came after Strategic Missile Forces Commander Sergei Karakayev announced the successful launch test of the missile, considered one of the latest heavy liquid-fueled intercontinental ballistic missiles (ICBMs).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "“Sarmat” is regarded as one of Russia’s most prominent deterrence weapons due to its ability to carry multiple nuclear warheads and alter its flight path during travel to evade interception systems.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the same context, Putin confirmed that Moscow continues implementing its nuclear forces modernization program, revealing that the medium-range ground-based “Oreshnik” system has been in service since 2025, with the possibility of equipping it with nuclear warheads.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also indicated that work is in its final stages on two new systems powered by small nuclear engines: the unmanned submarine “Poseidon” and the “Burevestnik” cruise missile.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These developments come amid escalating tensions between Russia and the West over the war in Ukraine, alongside warnings of a renewed global nuclear arms race at a pace unseen since the end of the Cold War.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/xsoa08da7d7ayshaysaq6syqahs-NDvrAyCkagHJu0aQb6rjO4CSIq4Rb0.jpg', false, false, 370, 1036, TIMESTAMP '2026-05-12 17:04:54.137', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'From tanks to military vehicles and enemy positions… here are today’s resistance operations in numbers', 'من دبابات إلى آليات ومراكز للعدو... إليكم بالأرقام عمليات المقاومة اليوم', 'hezb-stat-125', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "25 عملية في يوم واحد… حزب الله يعلن استهداف دبابات وآليات إسرائيلية جنوباً", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "أعلن حزب الله تنفيذ 25 عملية عسكرية ضد الجيش الإسرائيلي خلال يوم واحد، قال إنها جاءت رداً على خروقات وقف إطلاق النار والاعتداءات الإسرائيلية على القرى الجنوبية والمدنيين.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وبحسب بيانات “المقاومة الإسلامية”، شملت العمليات استهداف 8 دبابات ميركافا، بينها دبابات في البياضة والطيبة والإسكندرونة وموقع العبّاد ووادي العين، إضافة إلى 7 آليات عسكرية مختلفة، من بينها آليات هندسية و”هامر” وآليات اتصالات.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "كما أعلن الحزب تنفيذ هجمات بواسطة المسيّرات الانقضاضية والصواريخ الموجّهة والقصف المدفعي، استهدفت تجمعات للجنود الإسرائيليين في الناقورة ورشاف والقوزح ودير سريان، إلى جانب استهداف جهاز تشويش على المسيّرات من نوع “درون دوم” في موقع العبّاد.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وتوزعت العمليات على بلدات عدة في الجنوب، بينها حولا والبياضة وطير حرفا والناقورة والطيبة ووادي العين، فيما أكد الحزب تحقيق إصابات مباشرة واحتراق عدد من الدبابات والآليات المستهدفة.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "وفي ختام بياناته، شدد حزب الله على أن هذه العمليات تأتي في إطار “الدفاع عن لبنان وشعبه” ومنع إسرائيل من “التمادي في اعتداءاتها”.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Hezbollah announced carrying out 25 military operations against the Israeli army in a single day, saying the attacks came in response to ceasefire violations and Israeli attacks on southern villages and civilians.", "type": "text"}, {"type": "hardBreak"}, {"text": "According to statements issued by the “Islamic Resistance,” the operations included targeting eight Merkava tanks, including tanks in Bayyada, Taybeh, Iskandaronah, the Al-Abbad site, and Wadi al-Ain, in addition to seven different military vehicles, including engineering vehicles, Humvees, and communications vehicles.", "type": "text"}, {"type": "hardBreak"}, {"text": "The group also announced attacks using suicide drones, guided missiles, and artillery shelling targeting gatherings of Israeli soldiers in Naqoura, Rashaf, Qouzah, and Deir Siryan, as well as a strike on a “Drone Dome” anti-drone jamming system at the Al-Abbad site.", "type": "text"}, {"type": "hardBreak"}, {"text": "The operations were carried out across several southern towns, including Houla, Bayyada, Tayr Harfa, Naqoura, Taybeh, and Wadi al-Ain, while Hezbollah claimed direct hits and the burning of several targeted tanks and vehicles.", "type": "text"}, {"type": "hardBreak"}, {"text": "In its concluding statements, Hezbollah stressed that the operations come within the framework of “defending Lebanon and its people” and preventing Israel from “continuing its aggression.”", "type": "text"}]}]}$c$::jsonb, 'https://thisisbeirut.com.lb/images/bibli/1920/1280/2/slah-hzb-allh.jpeg', false, false, 155, 477, TIMESTAMP '2026-05-12 21:19:03.524', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Here is a summary of the Minister of Education’s press conference on the official exams for all grade levels', 'إليكم ملخص المؤتمر الصحفي لوزيرة التربية عن الامتحانات الرسمية لكافة الصفوف', 'edu2026', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت وزيرة التربية خلال مؤتمر صحفي رسمي سلسلة قرارات تتعلّق بالامتحانات الرسمية للعام الدراسي الحالي، في ظل الظروف الاستثنائية التي مرّ بها لبنان خلال السنة الدراسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "استُهل المؤتمر بدقيقة صمت، قبل أن تؤكد الوزيرة أنّ العام الدراسي كان صعبًا جدًا، مشيرةً إلى أنّ نسب إنجاز المناهج تراوحت بين ", "type": "text"}, {"text": "60% و70%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " فقط في مختلف المدارس.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لا شهادة متوسطة هذا العام", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أكدت الوزيرة إلغاء امتحانات الشهادة المتوسطة ", "type": "text"}, {"text": "(البريفيه)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " رسميًا لهذا العام.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وسيتم اعتماد العلامات المدرسية وفق الآلية التالية:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "60%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لعلامات الامتحانات التي أُجريت قبل نهاية السنة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "40%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لعلامات امتحانات نهاية السنة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما شددت على أنّه ", "type": "text"}, {"text": "لن يتم إلغاء أي مادة", "type": "text", "marks": [{"type": "bold"}]}, {"text": " في الصف التاسع، موضحةً أنّ ملف الدروس المطلوبة والملغاة سيصدر الأسبوع المقبل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " 3 دورات لامتحانات البكالوريا", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أعلنت وزارة التربية اعتماد ", "type": "text"}, {"text": "ثلاث دورات", "type": "text", "marks": [{"type": "bold"}]}, {"text": " لامتحانات شهادة الثانوية العامة ", "type": "text"}, {"text": "(Bac II)", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، مع السماح لكل طالب بالتقدّم ", "type": "text"}, {"text": "لدورتين متتاليتين فقط", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " مواعيد الدورات:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "الدورة الأولى:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " من 29 حزيران حتى 6 تموز.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "الدورة الثانية:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " من 27 تموز حتى 3 آب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "الدورة الاستثنائية الثالثة:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " من 7 أيلول حتى 14 أيلول.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت الوزيرة أنّ مستوى الأسئلة سيكون نفسه في الدورات الثلاث، كما لن يتم اعتماد أي مواد اختيارية هذا العام.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "---", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تخفيف واسع للمناهج", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أشارت الوزارة إلى أنّ المناهج الدراسية خضعت لتخفيفات كبيرة، خاصةً في مواد:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- التاريخ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- التربية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الجغرافيا", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقد تم اعتماد الدروس حتى تاريخ ", "type": "text"}, {"text": "2 آذار", "type": "text", "marks": [{"type": "bold"}]}, {"text": " فقط، مع إضافة بعض المحاور المحدودة في باقي المواد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " وفي مادة الجغرافيا مثلًا، تم إلغاء آخر ", "type": "text"}, {"text": "3 دروس", "type": "text", "marks": [{"type": "bold"}]}, {"text": "، بما فيها:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- التجارة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- النفط", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الغاز", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ليصبح عدد الدروس المطلوبة ", "type": "text"}, {"text": "5 بدلًا من 8", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أكدت الوزارة أنّ ملف الدروس الرسمية المطلوبة والملغاة سيصدر رسميًا يوم ", "type": "text"}, {"text": "الإثنين 18 أيار", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "---", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " التعليم المهني", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما بالنسبة لطلاب التعليم المهني، فقد تم الإبقاء على نظام الدورتين كما هو معتاد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "المواعيد:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الامتحانات العملية: بين ", "type": "text"}, {"text": "6 و12 تموز", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الامتحانات الخطية – الدورة الأولى: بين ", "type": "text"}, {"text": "20 و30 تموز", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الامتحانات الخطية – الدورة الثانية: في ", "type": "text"}, {"text": "15 أيلول", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت الوزارة أيضًا عدم وجود مواد اختيارية في الامتحانات المهنية، فيما لا تزال البرامج المخففة بانتظار قرار مديرية التعليم المهني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ختام المؤتمر، قالت وزيرة التربية:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "\"لن ألغي الامتحانات مثل فرنسا، لأن هذه الوزارة مسؤوليتي.\"", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Lebanon’s Minister of Education officially announced a series of major decisions regarding this year’s official exams during a press conference held amid the country’s difficult academic conditions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " The conference began with a minute of silence before the minister stated that the school year had been exceptionally challenging, noting that curriculum completion rates ranged between ", "type": "text"}, {"text": "60% and 70%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " across schools.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " Brevet Exams Officially Cancelled", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The minister confirmed the cancellation of the ", "type": "text"}, {"text": "Brevet (Intermediate Certificate)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " official exams for this year.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Instead, students’ final grades will be calculated based on school assessments:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "60%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from exams conducted before the end of the academic year.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "40%", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from end-of-year examinations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "She also clarified that ", "type": "text"}, {"text": "no subjects would be cancelled", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for Grade 9 students, while the official list of required and removed lessons will be released next week.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "---", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " Three Sessions for Baccalaureate Exams", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Ministry announced the adoption of ", "type": "text"}, {"text": "three official sessions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the Lebanese Baccalaureate exams, with each student allowed to participate in only ", "type": "text"}, {"text": "two consecutive sessions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " Exam Dates:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "First session:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " June 29 – July 6", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "Second session:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " July 27 – August 3", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ", "type": "text"}, {"text": "Exceptional third session:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " September 7 – September 14", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the minister, the difficulty level of questions will remain identical across all three sessions. No optional subjects will be included this year.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "---", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " Major Curriculum Reductions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ministry revealed significant curriculum reductions, particularly in:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- History", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Civics", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Geography", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lessons taught up until ", "type": "text"}, {"text": "March 2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " will mainly be considered, with only limited additional topics included in some subjects.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " In Geography, for example, the final ", "type": "text"}, {"text": "three lessons", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — including:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Trade", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Oil", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Gas", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "were removed, reducing the syllabus from ", "type": "text"}, {"text": "8 lessons to 5", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The official curriculum adjustments and required lessons will be published on ", "type": "text"}, {"text": "Monday, May 18", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "---", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Vocational Education Exams", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For vocational education students, the traditional two-session system will remain unchanged.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " Schedule:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- Practical exams: ", "type": "text"}, {"text": "July 6 – July 12", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "- Written exams – First session: ", "type": "text"}, {"text": "July 20 – July 30", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "- Written exams – Second session: ", "type": "text"}, {"text": "September 15", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The minister also confirmed that there will be no optional subjects in vocational exams, while the reduced curricula for vocational programs are still pending approval from the Directorate of Vocational Education.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Concluding the conference, the minister stated:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "“I will not cancel exams like France did, because this ministry is my responsibility.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/132849588569-7L892fbIRn7yCml385XrbehhCb57Tk.jpg', false, false, 792, 1671, TIMESTAMP '2026-05-15 09:44:31.323', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Officially: Required lessons for 2026 terminal exams released for all subjects and branches', 'رسميًا: صدور الدروس المطلوبة لامتحانات الترمينال 2026 لجميع المواد والفروع', 'exams-2026', $c${"type": "doc", "content": [{"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• التاريخ: محور لبنان فقط من الحرب العالمية الأولى حتى الجلاء الاقتصادي والعسكري", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الجغرافيا: العالم المعاصر، الشمال والجنوب، القوة الأميركية والصين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الرياضيات: التفاضل والتكامل واللوغاريتمات والاحتمالات والمتتاليات والدوال مع تخفيف بعض المحاور بحسب الفروع", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الفيزياء: الطاقة والحركة والتذبذبات والكهرباء والتحريض الكهرومغناطيسي مع تعليق بعض التطبيقات والأجزاء بحسب الفروع", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الكيمياء: مادة الكيمياء ستشمل الحركية الكيميائية والتوازن والأحماض والقواعد والكيمياء العضوية مع تخفيف بعض محاور الأدوية بحسب الفروع", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• علوم الحياة: الوراثة والتكاثر والجهاز المناعي والدورة الجنسية إضافة إلى التغذية والجهاز العصبي والإدمان بحسب الفروع", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• علم الاجتماع: البحث الاجتماعي والثقافة والقيم والتفاوت الاجتماعي والاندماج والتغير والسياسات الاجتماعية والمجتمع اللبناني ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الاقتصاد: النمو والتنمية والأنظمة الاقتصادية والأزمات والسياسات الاقتصادية إضافة إلى الكلفة والإنتاج والفوائد", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الفلسفة: الإنسان والوعي والإدراك والخيال ومناهج المعرفة والعلم والفلسفة إضافة إلى قضايا الأخلاق والسياسة بحسب الفروع", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الفرنسية: فهم نصوص وحجاج مع “Le Rêve” و”L’Étranger”  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• الإنكليزية: تحليل نصوص ومواضيع عن التكنولوجيا والبيئة وحقوق الإنسان  ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• التربية الوطنية: الإعلام والرأي العام والاغتراب اللبناني والديمقراطية والانتخابات والأحزاب والنقابات وأنظمة الاقتراع", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "ملاحظة مهمة للطلاب: التخفيفات تختلف بين الفروع في بعض المواد العلمية والأدبية، لذلك يُنصح بالعودة إلى الملف الرسمي الخاص بكل فرع للتأكد من الدروس المطلوبة والمحذوفة بالتفصيل —> ", "type": "text", "marks": [{"type": "italic"}]}, {"text": "https://t.me/tollabn/2097", "type": "text", "marks": [{"type": "link", "attrs": {"rel": "noopener noreferrer nofollow", "href": "https://t.me/tollabn/2097", "class": null, "title": null, "target": "_blank"}}, {"type": "italic"}]}]}, {"type": "paragraph", "content": [{"text": "• الامتحانات الرسمية ستُجرى على ثلاث دورات متتالية، ويحق لكل طالب التقدّم إلى دورتين متتاليتين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• سيتم اعتماد العلامات المدرسية بنسبة 60% لأعمال السنة و40% للامتحان النهائي في بعض الشهادات وفق قرارات الوزارة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• لا مواد اختيارية في امتحانات الترمينال هذا العام", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "History:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Lebanon only, from World War I up to the economic and military evacuation.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Geography:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " The contemporary world, the Global North and South, American power, and China.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Mathematics:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Calculus, logarithms, probability, sequences, and functions, with some topics reduced depending on the academic track.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Physics:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Energy, motion, oscillations, electricity, and electromagnetic induction, with some applications and sections suspended depending on the academic track", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Chemistry:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chemical kinetics, equilibrium, acids and bases, and organic chemistry, with some pharmaceutical-related topics reduced depending on the academic track", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Life Sciences:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Genetics, reproduction, the immune system, the sexual cycle, nutrition, the nervous system, and addiction, depending on the academic track", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Sociology:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Social research, culture and values, social inequality, integration, social change, social policies, and Lebanese society", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Economics:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Growth and development, economic systems, crises, economic policies, as well as cost, production, and interest", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Philosophy:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Human beings, consciousness, perception, imagination, methods of knowledge, science and philosophy, in addition to ethical and political issues depending on the academic track", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "French:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Text comprehension and argumentative writing, with ", "type": "text"}, {"text": "Le Rêve", "type": "text", "marks": [{"type": "italic"}]}, {"text": " and ", "type": "text"}, {"text": "L’Étranger", "type": "text", "marks": [{"type": "italic"}]}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "English:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Text analysis and topics related to technology, the environment, and human rights", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "• ", "type": "text"}, {"text": "Civics / National Education:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Media and public opinion, the Lebanese diaspora, democracy, elections, political parties, labor unions, and electoral systems", "type": "text"}, {"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "Important note for students: Reductions differ between branches in several scientific and literary subjects, so students are advised to review the official file for their branch to confirm all required and cancelled lessons in detail —> ", "type": "text", "marks": [{"type": "italic"}]}, {"text": "https://t.me/tollabn/2097", "type": "text", "marks": [{"type": "link", "attrs": {"rel": "noopener noreferrer nofollow", "href": "https://t.me/tollabn/2097", "class": null, "title": null, "target": "_blank"}}, {"type": "italic"}]}]}, {"type": "paragraph", "content": [{"text": "• Official exams will be held over 3 consecutive sessions, with each student allowed to sit for 2 consecutive sessions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• School grades will account for 60% and final exams for 40% in some certificates according to ministry decision", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "• No elective subjects in terminal exams this year", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/polemica-en-majadahonda-por-la-fecha-de-los-examenes-de-oposicion-Zin6WFphwn7aHOeVzZ4uOSKEXlNaQf.webp', true, false, 1858, 3909, TIMESTAMP '2026-05-16 07:30:42.708', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'exclusive'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A Legal Controversy Surrounds the Ministry of Education’s Decisions on Official Examinations', 'جدل قانوني يرافق قرارات وزارة التربية بشأن الامتحانات الرسمية', 'clash-edu', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "قرارات جديدة حول الامتحانات الرسمية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أعلنت وزيرة التربية، ريما كرامي، سلسلة إجراءات تتعلّق بالامتحانات الرسمية لهذا العام، أبرزها إلغاء امتحانات الشهادة المتوسطة وفتح ثلاث دورات لامتحانات الثانوية العامة بفروعها المختلفة. وجاء الإعلان خلال مؤتمر صحافي، من دون عرض الملف مسبقاً على مجلس الوزراء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وعقب انتهاء المؤتمر مباشرةً، بدأت وزارة التربية بتنفيذ الإجراءات العملية، حيث أرسلت تعميماً إلى المدارس الرسمية والخاصة طلبت فيه من الطلاب اختيار الدورة التي يرغبون في التقدّم إليها، إضافة إلى تحديد المنطقة الجغرافية الأقرب إلى مكان سكنهم، على أن تُستكمل هذه الإجراءات قبل الأول من حزيران المقبل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "اعتراضات قانونية على آلية اتخاذ القرار", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أثارت هذه الخطوات نقاشاً قانونياً واسعاً حول مدى قانونية القرارات المتخذة، خصوصاً في ما يتعلق بحدود صلاحيات وزارة التربية. وترى مصادر قانونية مطّلعة أن أي قرار إداري مرتبط بالامتحانات الرسمية يجب أن يلتزم بالنصوص القانونية النافذة، حفاظاً على مبدأ الشرعية الإدارية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب هذه المصادر، فإن المرسومين رقم 5697 و5698 الصادرين عام 2001 حدّدا بشكل واضح كيفية تنظيم دورات الامتحانات الرسمية. إذ منح أحد المرسومين مجلس الوزراء صلاحية إقرار الدورة الاستثنائية الثانية، فيما سمح المرسوم الآخر لوزير التربية بممارسة هذه الصلاحية ضمن شروط محددة، أبرزها اقتراح المدير العام للتربية وأخذ رأي المركز التربوي للبحوث والإنماء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "إشكالية فتح دورة ثالثة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تعتبر المصادر نفسها أن التفويض الممنوح لوزير التربية يقتصر فقط على تنظيم دورة ثانية استثنائية، ولا يشمل إطلاق دورة ثالثة، حتى في ظل الظروف الاستثنائية. وتشير إلى أن توسيع هذا التفويض يُعدّ تجاوزاً للنصوص القانونية، لأن الدورة الثانية بحد ذاتها تُعتبر استثناءً على النظام الأساسي، وبالتالي لا يجوز البناء على هذا الاستثناء لإضافة استثناء جديد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما توضح أن مبدأ الظروف الاستثنائية لا يمنح الإدارة حق نقل الصلاحيات أو تعديلها، بل يسمح فقط بهامش معيّن من التحرّك ضمن الحدود القانونية القائمة. ومن هذا المنطلق، ترى المصادر أن استحداث دورة ثالثة يحتاج إلى قرار واضح من مجلس الوزراء باعتباره الجهة المخوّلة قانوناً اتخاذ مثل هذا القرار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الجدل حول إلغاء امتحانات البريفيه", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لم يقتصر النقاش القانوني على مسألة الدورات الثلاث، بل شمل أيضاً قرار إلغاء امتحانات الشهادة المتوسطة. إذ تعتبر المصادر أن هذا النوع من القرارات الأساسية يُفترض أن يصدر بموجب مرسوم أو قرار رسمي عن مجلس الوزراء، لا أن يُعلن فقط خلال مؤتمر صحافي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وترى أن الظروف الاستثنائية، مهما كانت، لا تُلغي ضرورة الالتزام بالأصول القانونية والإدارية المعتمدة في إدارة الامتحانات الرسمية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "عدد الدورات والتنظيم الإداري", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي مواجهة الطرح القائل إن الطالب لن يشارك فعلياً إلا في دورتين فقط، توضح المصادر أن المشكلة الأساسية لا ترتبط بعدد المشاركات الفردية للطلاب، بل بعدد الدورات التي تنظّمها الوزارة رسمياً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتشير إلى أن تنظيم ثلاث دورات يطرح تساؤلات قانونية مرتبطة بتوسيع حدود التفويض الإداري، إضافة إلى ما قد يسببه ذلك من أعباء مالية وإدارية إضافية على الدولة والوزارة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "التخوّف من خلق سوابق إدارية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تؤكد المصادر القانونية أن الهدف من الاعتراض ليس تعطيل الامتحانات أو زيادة الضغوط على الطلاب، بل منع تكريس سوابق إدارية قد تؤدي مستقبلاً إلى تجاوز الصلاحيات المحددة بالقوانين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تشدد على أن أي تدبير استثنائي يجب أن يمر عبر المرجع المختص، أي مجلس الوزراء، حفاظاً على مبدأ المشروعية وعلى استقرار النظام التربوي في البلاد.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "New Decisions Regarding Official Examinations", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Minister of Education, Rima Karami, announced a series of measures concerning this year’s official examinations. The most notable decisions included canceling the intermediate certificate exams (“Brevet”) and opening three examination sessions for the secondary school certificate across its various branches. The announcement was made during a press conference, without the file first being presented to the Council of Ministers.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Immediately after the conference ended, the Ministry of Education began implementing the measures in practice. It sent a circular to both public and private schools requesting students to choose the examination session in which they wished to participate, as well as the geographic area closest to their residence. These procedures are to be completed before the first of June.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Legal Objections to the Decision-Making Process", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These steps sparked broad legal debate regarding the legality of the decisions taken, especially concerning the limits of the Ministry of Education’s authority. Legal sources familiar with the matter argue that any administrative decision related to official examinations must comply with the applicable legal texts in order to preserve the principle of administrative legality.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to these sources, Decrees No. 5697 and 5698, issued in 2001, clearly defined how official examination sessions should be organized. One decree granted the Council of Ministers the authority to approve the second exceptional session, while the other allowed the Minister of Education to exercise this authority under specific conditions, most notably upon the proposal of the Director General of Education and after consulting the Educational Center for Research and Development.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Issue of Opening a Third Session", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The same sources consider that the authority delegated to the Minister of Education is limited solely to organizing a second exceptional session and does not include launching a third session, even under exceptional circumstances. They argue that expanding this delegation constitutes تجاوزاً للنصوص القانونية because the second session itself is already considered an exception to the basic system, and therefore it is not permissible to build another exception upon it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They further explain that the principle of exceptional circumstances does not grant the administration the right to transfer or alter powers, but merely allows a certain degree of flexibility within the existing legal framework. From this perspective, they believe that creating a third examination session requires a clear decision from the Council of Ministers, as it is the legally authorized body to make such a decision.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Debate Over Canceling the Brevet Exams", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The legal debate was not limited to the issue of the three examination sessions; it also extended to the decision to cancel the intermediate certificate exams. According to the sources, this type of fundamental decision is supposed to be issued through an official decree or decision by the Council of Ministers, rather than merely being announced during a press conference.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They maintain that exceptional circumstances, regardless of their nature, do not eliminate the necessity of adhering to the established legal and administrative procedures governing official examinations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Number of Sessions and Administrative Organization", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In response to the argument that each student would actually participate in only two sessions, the sources clarify that the core issue is not the number of individual attempts by students, but rather the number of sessions officially organized by the ministry.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They point out that organizing three sessions raises legal questions related to expanding the limits of administrative delegation, in addition to the potential financial and administrative burdens this could impose on the state and the ministry.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Concerns About Creating Administrative Precedents", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The legal sources emphasize that the goal of these objections is not to obstruct the examinations or increase pressure on students, but rather to prevent the establishment of administrative precedents that could, in the future, lead to تجاوز الصلاحيات المحددة بالقوانين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They also stress that any exceptional measure must pass through the competent authority — namely the Council of Ministers — in order to preserve the principle of legality and maintain the stability of the educational system in the country.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/zIsywDUuMS0S2RGHWSOez3_1764929160535_ezKMH-mpGBpbiok9mB18K1yYPycd7Fnkw17M.jpg', false, false, 905, 1959, TIMESTAMP '2026-05-18 13:39:37.882', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'exclusive'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Here is the proposed General Amnesty Law after the amendments', 'إليكم اقتراح قانون العفو العام بعد التعديلات', 'ann-law-edit1952026', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "التعديلات على قانون العفو العام أصبحت على الشكل التالي:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الإعدام 28 سنة سجنية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- المؤبد 17 سنة سجنية ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- تخفض العقوبات إلى الثلث", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- ربط تنفيذ أحكام العفو بالحق الشخصي أي انه لن يستفيد أي محكوم من العفو إلا اذا أسقط الحق الشخصي", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "- الإدغام أقر باعتماد الحكم الأعلى مع حق القاضي بالجمع بسقف ربع العقوبة الأشد", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأفادت المعلومات أنه \"بخصوص قضايا المخدرات العفو العام يشمل التعاطي والترويج واستثناء الترويج المنظم والتجارة\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The amendments to the General Amnesty Law have become as follows:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Death sentences → reduced to 28 years in prison", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Life sentences → reduced to 17 years in prison", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Other penalties → reduced to one-third", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The implementation of amnesty rulings is tied to the personal right claim, meaning no convicted person will benefit from the amnesty unless the victim or claimant drops the personal charges/claims", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Regarding combined sentences (“idgham”), it was approved to adopt the highest sentence, while giving the judge the right to combine sentences up to a ceiling of one quarter of the harshest penalty", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The information also stated that, regarding drug-related cases, the general amnesty includes drug use and promotion/distribution, while excluding organized trafficking and commercial drug trade.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/image-1769974529.jpg-G2wDBNDAv11oINT8xO3viiObEBK0kH.webp', false, false, 280, 724, TIMESTAMP '2026-05-19 11:34:04.036', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Tehran Presents Its Conditions to End the War', 'طهران تعرض شروطها لوقف الحرب', 'teh-prop-war', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت إيران تفاصيل المبادرة التي طرحتها خلال المفاوضات الجارية مع الولايات المتحدة، في إطار المساعي الرامية إلى إنهاء الحرب المستمرة منذ 28 شباط، والتي تتهم طهران واشنطن وتل أبيب بالوقوف خلفها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وخلال اجتماع عقدته لجنة الأمن القومي والسياسة الخارجية في البرلمان الإيراني، قدّم نائب وزير الخارجية للشؤون القانونية والدولية كاظم غريب آبادي إحاطة حول مسار التفاوض، تناولت مواقف الوفد الإيراني والبنود الأساسية التي تضمّنها المقترح المقدم إلى الجانب الأميركي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب ما طُرح في الاجتماع، تطالب طهران برفع كامل للعقوبات المفروضة عليها، والإفراج عن الأموال الإيرانية المجمدة في الخارج، إضافة إلى إنهاء ما تصفه بـ«الحصار» المفروض على البلاد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تضمّنت الرؤية الإيرانية المطالبة بتعويضات عن الأضرار الناتجة عن الحرب، بهدف استخدامها في إعادة الإعمار، إلى جانب إلغاء العقوبات الأحادية وقرارات مجلس الأمن المرتبطة بإيران، وسحب القوات الأميركية من المناطق المحاذية لها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد المسؤول الإيراني أن بلاده تتمسك بحقها في تطوير برنامج نووي لأغراض سلمية، مشيراً إلى أن الطرح الإيراني يشمل أيضاً وقف المواجهات على مختلف الساحات، ومن بينها لبنان، فضلاً عن إنهاء الحصار البحري والإفراج عن الأصول المحتجزة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "غريب آبادي شدد من جهته على أن الفريق التفاوضي الإيراني يتحرك ضمن ثوابت تعتبرها طهران مرتبطة بـ«حماية مصالح البلاد والحفاظ على قوتها الوطنية».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتناول اجتماع اللجنة كذلك آخر المستجدات المتعلقة بالمفاوضات الإيرانية الأميركية، إضافة إلى نتائج مشاركة وزير الخارجية عباس عراقجي في اجتماع وزراء خارجية دول «البريكس» في الهند، إلى جانب البحث في زيارة وزير الداخلية الباكستاني إلى العاصمة الإيرانية.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Iran announced details of the initiative it presented during the ongoing negotiations with the United States, as part of efforts aimed at ending the war that has continued since February 28, which Tehran accuses Washington and Tel Aviv of being behind.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "During a meeting held by the Iranian Parliament’s National Security and Foreign Policy Committee, Deputy Foreign Minister for Legal and International Affairs Kazem Gharibabadi gave a briefing on the course of the negotiations. He addressed the positions of the Iranian delegation and the main points included in the proposal submitted to the American side.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to what was discussed during the meeting, Tehran is demanding the complete lifting of sanctions imposed on Iran, the release of frozen Iranian assets abroad, and an end to what it describes as the “siege” imposed on the country.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Iranian vision also includes demands for compensation for damages resulting from the war, with the aim of using the funds for reconstruction, in addition to the cancellation of unilateral sanctions and UN Security Council resolutions related to Iran, as well as the withdrawal of American forces from areas bordering the country.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Iranian official emphasized that Iran insists on its right to develop a nuclear program for peaceful purposes, noting that the Iranian proposal also includes ending confrontations on various fronts, including Lebanon, as well as lifting the naval blockade and releasing detained assets.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For his part, Gharibabadi stressed that the Iranian negotiating team is operating according to principles that Tehran considers tied to “protecting the country’s interests and preserving its national strength.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The committee meeting also addressed the latest developments in the Iranian-American negotiations, in addition to the outcomes of Foreign Minister Abbas Araghchi’s participation in the BRICS foreign ministers’ meeting in India, as well as discussions regarding the visit of Pakistan’s Interior Minister to the Iranian capital.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-Ts5czOkI6lffK7aDGftbdl9Ld7Fo1e', false, false, 237, 633, TIMESTAMP '2026-05-19 13:43:34.196', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Growing Israeli Inability to Confront Hezbollah Drones', 'عجز إسرائيلي متزايد في مواجهة مسيّرات حزب الله', 'isr-drone-threat-lb', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "تهديد يتوسع على الحدود الشمالية", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "المسيّرات الانقضاضية تربك إسرائيل", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تواصل المسيّرات الانقضاضية التي يستخدمها حزب الله فرض تحدٍ متزايد على الجيش الإسرائيلي، وسط اعترافات داخل المؤسسة العسكرية بصعوبة احتواء هذا النوع من الهجمات، خصوصاً مع استخدام مسيّرات موجهة عبر الألياف الضوئية يصعب رصدها أو التشويش عليها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا السياق، كشفت وسائل إعلام إسرائيلية أن لجنة الخارجية والأمن في الكنيست ستعقد جلسة خاصة لبحث إخفاق الجيش في مواجهة هذا التهديد، بعدما تحولت المسيّرات إلى أحد أبرز مصادر الخطر على القوات الإسرائيلية المنتشرة في جنوب لبنان.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "خسائر وضغط ميداني", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب تقارير إسرائيلية، أسفرت هجمات نفذها حزب الله خلال الأسابيع الأخيرة عن سقوط قتلى وجرحى في صفوف الجيش، ما دفع القوات الإسرائيلية إلى تعديل أنماط انتشارها وتقليل التجمعات المكشوفة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويشير مراقبون إلى أن هذا النوع من المسيّرات يتميز ببصمة رادارية وحرارية منخفضة، إضافة إلى قدرته على التحليق على ارتفاعات متدنية وتنفيذ ضربات دقيقة، ما يقلص فعالية أنظمة الدفاع التقليدية، بما فيها “القبة الحديدية”.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "هجمات متبادلة جنوباً", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ميدانياً، أعلن حزب الله تنفيذ سلسلة هجمات استهدفت آليات ومواقع إسرائيلية في جنوب لبنان بواسطة مسيّرات انقضاضية وصواريخ، مؤكداً تحقيق إصابات مباشرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، قال الجيش الإسرائيلي إن صفارات الإنذار دوت في مستوطنات قرب الحدود اللبنانية بعد رصد عمليات إطلاق صواريخ ومسيّرات، مشيراً إلى اعتراض بعضها وسقوط أخرى في مناطق مفتوحة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتزامن هذه التطورات مع استمرار التوتر على الجبهة الجنوبية، رغم اتفاق وقف إطلاق النار المعلن منذ أبريل/نيسان الماضي، والذي يشهد خروقات متبادلة بشكل شبه يومي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Growing Threat on the Northern Border", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Kamikaze Drones Disrupt Israel", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The kamikaze drones used by Hezbollah continue to pose an increasing challenge to the Israeli army, amid acknowledgments within the military establishment of the difficulty in containing this type of attack, especially with the use of fiber-optic-guided drones that are difficult to detect or jam.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, Israeli media revealed that the Knesset’s Foreign Affairs and Defense Committee will hold a special session to discuss the army’s failure to confront this threat, after drones became one of the main sources of danger to Israeli forces deployed in southern Lebanon.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Losses and Battlefield Pressure", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Israeli reports, attacks carried out by Hezbollah in recent weeks resulted in deaths and injuries among army personnel, prompting Israeli forces to modify their deployment patterns and reduce exposed gatherings.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Observers note that this type of drone is characterized by a low radar and thermal signature, in addition to its ability to fly at low altitudes and carry out precise strikes, which reduces the effectiveness of traditional defense systems, including the “Iron Dome.”", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Reciprocal Attacks in the South", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the ground, Hezbollah announced carrying out a series of attacks targeting Israeli vehicles and positions in southern Lebanon using kamikaze drones and rockets, claiming direct hits.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In response, the Israeli army said that sirens sounded in settlements near the Lebanese border after detecting rocket and drone launches, noting that some were intercepted while others fell in open areas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These developments coincide with the continued tension on the southern front despite the ceasefire agreement announced since last April, which has witnessed near-daily mutual violations.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-WmaB2nVUaqgA4sSOO8lugIX65QjLX1', false, false, 139, 485, TIMESTAMP '2026-05-19 15:32:34.490', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Cement Crisis Deepens Ahead of Reconstruction', 'أزمة الإسمنت تتفاقم قبل الإعمار', 'cement-crisis-lkeb', $c${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 4}, "content": [{"text": "ارتفاع غير مسبوق قبل انطلاق الإعمار", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "يتجه ملف الإسمنت في لبنان إلى مزيد من التعقيد، مع تسجيل ارتفاع كبير في الأسعار بالتزامن مع تراجع الكميات المتوافرة في السوق، ما يثير مخاوف من أزمة أوسع مع اقتراب مرحلة إعادة الإعمار وارتفاع الطلب على مواد البناء.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ووصل سعر طن الإسمنت في السوق اللبنانية إلى نحو 250 دولاراً، رغم أن السعر الرسمي المحدد من وزارة الصناعة يبلغ 91 دولاراً فقط، وسط شكاوى من نقص الكميات وغياب الرقابة الفعلية على السوق.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "احتكار وخلافات داخل الحكومة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويعود جزء أساسي من الأزمة إلى استمرار احتكار السوق من قبل ثلاث شركات فقط، في وقت تواجه فيه معظم المقالع والكسارات عراقيل قانونية وإدارية أدت إلى توقف عدد كبير منها عن العمل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما يشهد الملف خلافاً متصاعداً داخل الحكومة بين وزارة البيئة ووزارة الصناعة حول آلية منح التراخيص وتشغيل المقالع، حيث ترفض وزارة البيئة العودة إلى سياسة الاستثناءات السابقة، فيما تحذر وزارة الصناعة من انعكاسات توقف الإنتاج على السوق والأسعار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب المعطيات، فإن شركة “ترابة سبلين” باتت الجهة الأساسية التي تواصل الإنتاج حالياً، بعد توقف مصانع أخرى، ما أثار مخاوف من تحوّل السوق عملياً إلى احتكار شبه كامل لمصلحة شركة واحدة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "أرباح ضخمة وفوضى في التسعير", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتشير المعطيات إلى أن الشركات تسلّم الطن للوكلاء بسعر يقارب 91 دولاراً، قبل أن يُباع في السوق بأسعار تتراوح بين 220 و250 دولاراً، ما يفتح الباب أمام أرباح كبيرة يتحمل كلفتها المستهلكون والمقاولون.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويزيد من الضبابية غياب نشرات رسمية دورية للأسعار من قبل وزارة الصناعة، إلى جانب غياب أي خطة واضحة لإدارة سوق الإسمنت خلال المرحلة المقبلة، سواء عبر تنظيم الإنتاج أو فتح باب الاستيراد أو تعزيز المنافسة.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "مخاوف قبل ورشة الإعمار", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتزايد المخاوف من أن يتحول ملف الإسمنت إلى واحدة من أكبر أزمات مرحلة إعادة الإعمار، في ظل توقع ارتفاع هائل في الطلب على مواد البناء خلال الأشهر المقبلة، مقابل سوق محدودة الإنتاج وتعاني من الاحتكار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا الإطار، ترتفع الدعوات إلى فتح باب استيراد الإسمنت لكسر الاحتكار ومنع انفلات الأسعار، خصوصاً مع استمرار الخلافات السياسية والإدارية التي تعيق إيجاد حل داخلي مستدام للقطاع.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Unprecedented Price Surge Ahead of Reconstruction", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lebanon’s cement sector is heading toward greater complexity, with a sharp rise in prices coinciding with declining quantities available on the market, raising fears of a broader crisis as the reconstruction phase approaches and demand for construction materials increases.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The price of one ton of cement in the Lebanese market has reached around $250, despite the official price set by the Ministry of Industry being only $91, amid complaints about shortages and the absence of effective market oversight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Monopoly and Government Disputes", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A major part of the crisis is linked to the continued domination of the market by only three companies, while most quarries and crushers are facing legal and administrative obstacles that have forced many of them to halt operations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The issue is also witnessing growing disagreements within the government between the Ministry of Environment and the Ministry of Industry over licensing mechanisms and quarry operations. The Ministry of Environment refuses to return to previous exemption policies, while the Ministry of Industry warns of the consequences of production stoppages on the market and prices.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to available information, “Sibline Cement” has become the main company still producing at the moment after other factories stopped operations, raising fears that the market may effectively turn into an almost complete monopoly benefiting a single company.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Huge Profits and Pricing Chaos", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Reports indicate that companies sell the ton to distributors for around $91 before it reaches the market at prices ranging between $220 and $250, opening the door to massive profits ultimately borne by consumers and contractors.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The uncertainty is worsened by the absence of regular official price bulletins from the Ministry of Industry, in addition to the lack of any clear plan to manage the cement market during the coming phase, whether through regulating production, opening imports, or enhancing competition.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Fears Ahead of Reconstruction Efforts", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Concerns are growing that the cement issue could become one of the biggest crises during the reconstruction phase, especially with expectations of a huge rise in demand for construction materials in the coming months, while the market remains limited in production and affected by monopolistic control.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, calls are increasing to open the door for cement imports in order to break the monopoly and prevent uncontrolled price hikes, particularly as ongoing political and administrative disputes continue to obstruct a sustainable internal solution for the sector.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-1o2vmgglDAbxVnQ5G3VN8jnvE5pqQC', false, false, 101, 335, TIMESTAMP '2026-05-19 15:47:05.492', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'General Security and the Army Respond to U.S. Sanctions: Our Loyalty Is Solely to the State', 'الأمن العام والجيش رداً على العقوبات الأميركية: ولاؤنا للدولة فقط', 'gen-sec-sanc-leb', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "ردّت المديرية العامة للأمن العام وقيادة الجيش اللبناني على الاتهامات الأميركية التي طالت ضباطاً لبنانيين بتسريب معلومات استخباراتية إلى جهات حزبية، بعد إعلان وزارة الخزانة الأميركية فرض عقوبات على تسعة أشخاص مرتبطين بحزب الله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد الأمن العام ثقته الكاملة بضباطه وعناصره، مشدداً على التزامهم بالقوانين وولائهم للدولة اللبنانية فقط، مع التأكيد أن أي عنصر يثبت تورطه في تسريب معلومات سيخضع للمساءلة القانونية والقضائية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بدورها، شددت قيادة الجيش اللبناني على أن العسكريين يؤدون واجباتهم باحتراف وانضباط ووفق توجيهات القيادة، مؤكدة أنها لم تتلقَّ أي معلومات رسمية عبر القنوات المعتمدة بشأن الاتهامات الأميركية، وأن ولاء العسكريين يبقى للمؤسسة العسكرية والوطن حصراً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكانت وزارة الخزانة الأميركية قد أعلنت فرض عقوبات على تسعة مسؤولين وشخصيات في لبنان، بينهم مسؤولون في حزب الله وحركة أمل، إضافة إلى ضابطين لبنانيين، بحجة عرقلة عملية السلام ومنع نزع سلاح الحزب", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The Lebanese General Security Directorate and the Lebanese Army Command responded to the American accusations targeting Lebanese officers accused of leaking intelligence information to party-affiliated groups, following the U.S. Treasury Department’s announcement of sanctions on nine individuals linked to Hezbollah.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "General Security affirmed its full confidence in its officers and personnel, stressing their commitment to the law and loyalty solely to the Lebanese state. It also emphasized that any member proven to be involved in leaking information would face legal and judicial accountability.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For its part, the Lebanese Army Command stressed that military personnel carry out their duties with professionalism and discipline in accordance with leadership directives. It confirmed that it had not received any official information through approved channels regarding the American accusations, and that the loyalty of soldiers remains exclusively to the military institution and the nation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The U.S. Treasury Department had announced sanctions against nine officials and figures in Lebanon, including members of Hezbollah and the Amal Movement, as well as two Lebanese officers, accusing them of obstructing the peace process and preventing Hezbollah’s disarmament.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/LebaneseArmyKhiam_223709_690973_393615_242378_399767-uK7b7WU2efHBobVhtGe3pkPdQGr0zt.jpeg', false, false, 87, 392, TIMESTAMP '2026-05-22 12:47:12.440', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Dahiyeh Cafés Between Broadcasting the World Cup and Security & Cost Challenges', 'مقاهي الضاحية بين نقل المونديال وتحديات الأمن والكلفة', 'dahieh-wc-cafe235', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "مع اقتراب انطلاق كأس العالم 2026، لا يزال مصير نقل مباريات المونديال في مقاهي الضاحية الجنوبية لبيروت غير محسوم، وسط انقسام بين أصحاب المقاهي بين متحمّسين لاستقبال الجمهور وآخرين يعتبرون أن الظروف الأمنية والاقتصادية لا تزال غير مناسبة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم الأضرار التي خلّفتها الغارات الإسرائيلية واستمرار التحليق المعادي، تواصل بعض المقاهي فتح أبوابها يومياً مع تراجع واضح في أعداد الزبائن بسبب النزوح وتضرر المنازل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "عدد من أصحاب المقاهي أكّدوا نيتهم نقل المباريات إذا سمحت الظروف، مشيرين إلى أن التحديات الأساسية تتمثل بالكلفة العالية والمخاوف الأمنية، خصوصاً بعد حوادث سابقة أثّرت على الحركة التجارية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، يرى آخرون أن الوضع لا يزال هشّاً، وأن نقل بطولة بحجم كأس العالم يحتاج إلى استقرار كامل وتشغيل المقاهي بكامل طاقتها، وهو ما لا يتوافر حالياً، إضافة إلى صعوبة جذب الزبائن في ساعات الفجر بسبب فارق التوقيت.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبين ارتفاع التكاليف وضعف الإقبال، يجد أصحاب المقاهي أنفسهم أمام خيارين صعبين: المجازفة بنقل المونديال رغم الظروف، أو الامتناع عن ذلك مع احتمال خسارة المزيد من الزبائن.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "As the 2026 World Cup approaches, the fate of broadcasting the tournament’s matches in cafés across Beirut’s southern suburbs remains uncertain, amid division among café owners between those eager to welcome fans and others who believe the security and economic conditions are still unsuitable.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Despite the damage caused by Israeli airstrikes and the continued hostile aerial presence, some cafés continue to open daily, though with a noticeable decline in customers due to displacement and damaged homes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Several café owners confirmed their intention to broadcast the matches if conditions allow, pointing out that the main challenges are the high costs and security concerns, especially after previous incidents that negatively affected commercial activity.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, others believe the situation remains fragile and that hosting an event as massive as the World Cup requires complete stability and cafés operating at full capacity — conditions that are currently unavailable. They also highlighted the difficulty of attracting customers during early morning hours because of the time difference.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Between rising expenses and weak customer turnout, café owners find themselves facing two difficult choices: taking the risk of broadcasting the World Cup despite the circumstances, or refraining from doing so and potentially losing even more customers.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/202212014e9ff6b6808d4ff397e8b1c1fd9177d2_729b7adb-eced-458c-bd44-4b86fb49859a-vrGId6WlbHfFNgBK4x03Bk4FBCnnFd.jpg', false, false, 70, 382, TIMESTAMP '2026-05-23 12:23:12.856', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Growing Israeli Frustration Over the Attrition in Southern Lebanon as Hezbollah Imposes Complex Equations', 'تصاعد الإحباط الإسرائيلي من استنزاف جنوب لبنان وحزب الله يفرض معادلات معقّدة', 'isr-hzb-threat-235x', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يتزايد الجدل داخل الأوساط العسكرية والإعلامية الإسرائيلية حول جدوى استمرار العمليات في جنوب لبنان، في ظل اعتراف متنامٍ بصعوبة حسم المواجهة مع حزب الله عسكرياً رغم التفوق الناري الإسرائيلي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتتحدث تقديرات إسرائيلية عن استمرار انتشار مجموعات تابعة لحزب الله في مناطق جنوبية قريبة من الحدود، حيث تعتمد على تكتيكات قتالية مرنة تشمل حرب العصابات، والتحرك ضمن خلايا صغيرة، واستخدام المسيّرات والصواريخ المضادة للدروع داخل بيئة ميدانية معقدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب تقارير عبرية، فإن المؤسسة الأمنية الإسرائيلية باتت ترى أن الضربات العسكرية المتواصلة قد تُضعف قدرات الحزب لكنها لن تنجح بالقضاء الكامل على تهديد الصواريخ والطائرات المسيّرة، ما يعزز الدعوات داخل إسرائيل للبحث عن مسار سياسي إلى جانب العمل العسكري.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، تشهد المؤسسة العسكرية الإسرائيلية حالة من الإحباط بسبب استمرار الاستنزاف البشري والعملياتي داخل ما يُعرف بـ«الحزام الأمني» جنوب لبنان، وسط غياب أهداف واضحة للحرب وتضارب حول طبيعة المهمة العسكرية الحالية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أظهرت تقارير إسرائيلية تنامي قدرات حزب الله الاستخباراتية، بعدما تمكن من رصد تحركات القوات الإسرائيلية واستهداف مواقع عسكرية حساسة، مستفيداً من استخدام تقنيات متطورة في المسيّرات يصعب اعتراضها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومع استمرار التصعيد، تبحث إسرائيل خيارات توسيع العمليات البرية في جنوب لبنان، بالتوازي مع أزمة متزايدة داخل الجيش تتعلق بنقص القوى البشرية والموارد اللازمة لاستمرار المواجهة لفترة طويلة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Debate is intensifying within Israeli military and media circles over the usefulness of continuing operations in southern Lebanon, amid growing acknowledgment of the difficulty of decisively defeating Hezbollah militarily despite Israel’s firepower superiority.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli assessments indicate that Hezbollah-affiliated groups continue to operate in southern areas near the border, relying on flexible combat tactics including guerrilla warfare, movement in small cells, and the use of drones and anti-tank missiles within a complex battlefield environment.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Hebrew media reports, the Israeli security establishment has come to believe that continuous military strikes may weaken Hezbollah’s capabilities but will not succeed in completely eliminating the threat posed by rockets and drones. This has strengthened calls within Israel to pursue a political path alongside military action.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, frustration is growing within the Israeli military due to the continued human and operational attrition inside what is referred to as the “security belt” in southern Lebanon, amid the absence of clear war objectives and conflicting views regarding the nature of the current military mission.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Israeli reports have also highlighted Hezbollah’s growing intelligence capabilities after the group managed to monitor Israeli troop movements and target sensitive military positions, benefiting from the use of advanced drone technologies that are difficult to intercept.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As the escalation continues, Israel is considering options to expand ground operations in southern Lebanon, while simultaneously facing a growing crisis within the army related to manpower shortages and the resources required to sustain a prolonged confrontation.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/images-3dmdIDFeMdYEnXHo66hHm8AxRDqH4s', false, false, 6, 14, TIMESTAMP '2026-05-23 15:02:56.032', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Litani Authority Warns of Disaster if Qaraoun Dam Is Targeted', 'مصلحة الليطاني تحذّر من كارثة في حال استهداف سد القرعون', 'qaraoun-disaster-warn-275', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "حذّرت المصلحة الوطنية لنهر الليطاني من خطورة استهداف محيط سد القرعون، بعد الغارات الإسرائيلية الأخيرة التي طالت الطريق المحاذية للسد في البقاع الغربي، مؤكدة أن أي ضرر مباشر أو غير مباشر قد يؤدي إلى تداعيات كارثية على المناطق الواقعة أسفل السد.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضحت المصلحة أن الطريق المستهدفة تُعد جزءاً من جسم السد والمنشآت المرتبطة به، ما يستدعي أعلى درجات الحذر والمتابعة التقنية والهندسية للحفاظ على السلامة العامة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشارت إلى أن سد القرعون يُعتبر منشأة مدنية استراتيجية مرتبطة بالأمن المائي والطاقة والري في لبنان، محذّرة من أن أي خلل إنشائي أو استهداف قد يتسبب بفيضانات وأضرار واسعة على السكان والبنى التحتية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأرفقت المصلحة دراسة أعدّتها الوكالة الأميركية للتنمية الدولية حول سيناريوهات انهيار السد والمناطق المعرّضة للخطر، داعيةً المسؤولين اللبنانيين إلى التحرّك دبلوماسياً لتحييد السد ومنشآت الليطاني عن أي اعتداءات، باعتبارها منشآت مدنية يحظر استهدافها وفق القانون الدولي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The National Litani River Authority warned of the dangers of targeting the surroundings of the Qaraoun Dam following recent Israeli airstrikes that hit the road adjacent to the dam in the western Bekaa, stressing that any direct or indirect damage could lead to catastrophic consequences for areas located downstream.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The authority explained that the targeted road is considered part of the dam’s structure and its associated facilities, which requires the highest levels of caution and technical and engineering monitoring to preserve public safety.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It also pointed out that the Qaraoun Dam is regarded as a strategic civilian facility linked to Lebanon’s water security, energy supply, and irrigation sector, warning that any structural damage or targeting could cause floods and widespread destruction affecting residents and infrastructure.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The authority attached a study prepared by the United States Agency for International Development (USAID) concerning dam-collapse scenarios and areas exposed to danger, calling on Lebanese officials to move diplomatically in order to shield the dam and Litani facilities from any attacks, considering them civilian installations protected under international law.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/photo_20260526_145113_145655_large-eXvuBWih95aeO1roU2UnSAC4AfVDaA.webp', false, false, 84, 410, TIMESTAMP '2026-05-27 14:50:23.509', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The Battle of Zawtar al-Sharqiya on the Verge of a Ceasefire', 'معركة زوطر الشرقية على مشارف وقف اطلاق النار', 'zawtar-resistance-battle-275', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كتب الصحافي حسن عليق على حسابه على فيسبوك:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "بعد موجة واسعة من الغـ..ـارات، وبعد مـ..ـواجهة أخّرت تقدمه لساعات، تمكّن جيش الـ.ـعــ.ـدو من الوصول إلى زوطر الشرقية بعد ظهر أمس.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "التأكيد الأول لوصول قوات الـ.ـعــ.ـدو إلى البلدة كان في بيانات الإعلام الحر بي. ففي البلدة، يتعرّض الغزاة لعــ..ــمـلـيات منذ ما بعد ظهر أمس، بينها أكثر من اشتباك مباشر صباح اليوم، وتدمـ..ـير دبابات وآليات. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ربما يكون هـ.ـدف الـ.ـعــ.ـدو الوصول إلى \"عليّ الطاهر\" وقلعة الشقيف من جهة، والجرمق والمحمودية من جهة أخرى، وهو ما قد يحتاج إلى هـ..ـجوم من تل نحاس نحو الخردلي وربما من القليعة - مرجعيون. وربما يكون هـ.ـدفه ما قالته مراسلة الlbci آمال شحادة، أي توسيع الأرض التي يحـ.ـتلها داخل الخط الأصفر، كون زوطر ويحمر وأرنون وقلعة الشقيف مشمولة جميعها بذلك الخط، لكن جيش الـ.ـعــ.ـدو لم يدخلها. وقد يكون ساعياً للاقتراب من النبطية. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في شتى الأحوال، وقبل إعلان وقف النار، يسعى الاحـ.ـتلال إلى إضافة أوراق ضغط إلى جعبته، ليبتز بها لبنان لاحقاً، مستنداً إلى وجود سلطة مستعدة للتنازل له قبل أن يطلب. ولتحقيق ذلك، قد يلجأ إلى اندفاعة على أكثر من محور، وإلى زيادة عدد غـ..ـاراته التدمـ..ـيرية. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من ناحية أخرى، يدرك الـ.ـعــ.ـدو أن كثراً منا يتعاملون مع الحر ب كما لو أنها مباراة كرم قدم، فترتفع معنوياتنا متى رأينا مشاهد المحلقات الانقضاضية، وتنخفض عندما يشـ..ـنّ الـ.ـعــ.ـدو سلسلة غـ..ـارات أو يتقدّم في واحدة من قرانا. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "مشاهد المحلقات محت جزءاً من الأثر النفسي للإبادة. أحد أهداف الـ.ـكـ..ـيان والغرب في سنوات ما بعد الطــوفـ.ــان كان محو صورة الجندي الذي يزحف هرباً من ابن غـ..ـزة في السابع من أكتوبر. وبعد سنتين ونصف السنة من \"أُلوهة\" الجيش الإســ..ـرائيلي واستخباراته، أعادت مشاهد المحلقات الجندي الإســ..ـرائيلي إلى \"طبيعته البشرية\": يهرب أمام المحلقة، ويفرّ من الآلية متى اقترب الخطر. المحلقات أيضاً، ومعها قــذائف الهاون والمد فعية وصوا ريخ الكاتيوشا والمسيّرات الانقضاضية ومعركة حدّاثا الأسطورية وملاحقة قائد اللواء 401 وعـ..ــمـلـيـة القوزح واستـ..ـهداف منصات الدفاع الصا روخي وثكنات الاحـ.ـتلال داخل شمال فلسـ.ـطين وسلسلة عــ..ــمـلـيات البياضة ورشاف وسواها… كل ذلك أعاد جيش الـ.ـعــ.ـدو أيضاً إلى القواعد \"الطبيعية\" لحدود القوة. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في الأسابيع الماضية، كان جيش الإبادة يشكو لمجتمع المستـ.ـوطنين أن حكومته تمنعه، بقرار أميركي، من توسيع نطاق عــ..ــمـلـياته إلى بيروت والضاحية. تلك العــ..ــمـلـيات التي أرادها للرد على المحلقات في الجنوب! كان ذلك الاعتراف الأوضح بعدم قدرة جيش الإبادة على وقف عــ..ــمـلـيات أبطالنا، وأن سبيله الوحيد لردعنا هو قـ.ـتل المدنيين وتدمـ..ـير المباني، أي استـ..ـهداف إرادتنا لدفعنا للضغط على المقا. و.مة من أجل الاستسلام. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "اعترف الـ.ـعــ.ـدو بذلك فيما هو يملك حرية حركة مطلقة في الجنوب والبقاع الغربي، حيث يمكنه استخدام قدرما يشاء من قوته الجوية والبرية والبحرية والاستخبارية على أنواعها، وحيث انسحبت المـ..ـقاومة بدءا من تشرين الثاني 2024 وسلّمت مواقعها للجيش اللبناني وفككت ما سلم من مراصدها. رغم ذلك، لم يقدر على \"معالجة\" المحلقات التي تضرب جنوده بأجسادهم وآلياتهم ومعدّاتهم، وتعيد صورته وقوته (الهائلة) إلى حدودها (وهي ليست ضيقة بطبيعة الحال). ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أمام هذا الواقع، هو يحتاج إلى ما يرمّم صورته، بصفته جيشاً إبادياً. وها هو اليوم يقول لنا إنه في زوطر الشرقية، في مزرعة الحمرا، وإنه يقترب من يحمر. والبلدتان، وإن كانتا ضمن ما يسمّيه \"الخط الأصفر\"، فإنهما تقعان شمال النهر. حاول الـ.ـعــ.ـدو الوصول إليهما أكثر من مرة، وفشل. هذه المرة، وصلت قواته إلى الأحياء الجنوبية الشرقية من زوطر، وحاولت الالتفاف حولها نحو الشمال، حيث تصدى لها أبطالنا، ولا يزالون. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "قد يتراجع الـ.ـعــ.ـدو تحت ضرباتهم، كما في حدّاثا وبيوت السياد. وقد يتقدّم في الساعات أو الأيام الفاصلة عن وقف إطلاق النار، لكنه في كل بلدة ومزرعة وبستان ووادٍ وتلة، سيلاقيه أبناؤنا الأبطال، الذين يضحّون بأرواحهم ويريقون دمــ..ـــاءهم من أجل عزتنا وكرامتنا، ومن أجل أن نبقى أحراراً في أرضنا. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وطالما أنهم كذلك، ستعود أرضنا حرة من الاحـ.ـتلال، وسنعود إليها، ولو بعد حين. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومهما جمع الـ.ـعــ.ـدو وتمدّد ودمّر، فإنه لن يكسر إرادتنا، ولن يحقق أهدافه، ما دام فينا شاب واحد يحمل عزمه ومحلقته ورشاشه، ويسلّح عبوته ويذخّر راجمته، ويطلق قـ.ـذيـفة من مد فع يحدد الـ.ـعــ.ـدو موقعه فور استخدامه، فتنهال عليه القــذائف والقنـ..ـابل بأطنان المتفجرات، لكن هذا الشاب لا يتراجع. بإرادته انتصرنا، وبإرادته سنعود لنبني دورَنا ونزرعها ريحاناً و\"زرّيعة\" وورداً وشجرا. ", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Journalist Hassan Olleik wrote on his Facebook account:", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "After a wide wave of airstrikes, and after clashes that delayed its advance for hours, the Israeli army managed to reach Zawtar al-Sharqiya yesterday afternoon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The first confirmation of the enemy forces reaching the town came through Hezbollah’s military media statements. Inside the town, the invading forces have been facing operations since yesterday afternoon, including more than one direct clash this morning, as well as the destruction of tanks and vehicles.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The enemy’s objective may be to reach Ali al-Taher and Beaufort Castle from one direction, and Jarmak and Mahmoudiyah from another, which could require an offensive from Tall al-Nahhas toward Khardali and perhaps from Qlayaa–Marjayoun. Or perhaps its goal is what LBCI correspondent Amal Shehadeh mentioned — expanding the territory it occupies inside the so-called “yellow line,” since Zawtar, Yohmor, Arnoun, and Beaufort Castle all fall within that line, though the Israeli army had not entered them before. It may also be seeking to move closer to Nabatieh.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In any case, before a ceasefire is announced, the occupation seeks to add pressure cards to its arsenal in order to later use them to blackmail Lebanon, relying on the existence of an authority ready to concede before even being asked. To achieve this, it may resort to pushing forward on several fronts and intensifying its destructive airstrikes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On the other hand, the enemy understands that many among us deal with war as if it were a football match: our morale rises when we see scenes of attack drones, and falls whenever the enemy launches a series of airstrikes or advances into one of our villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The drone footage erased part of the psychological effect of the destruction. One of the objectives of Israel and the West in the years following the “Al-Aqsa Flood” was to erase the image of the soldier crawling in fear from a Gaza fighter on October 7. But after two and a half years of portraying the Israeli army and its intelligence as invincible, the drone scenes returned the Israeli soldier to his “human reality”: fleeing from attack drones and abandoning vehicles whenever danger approached.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The drones — along with mortars, artillery, Katyusha rockets, kamikaze drones, the legendary battle of Haddatha, the pursuit of the commander of the 401st Brigade, the Qawzah operation, the targeting of missile-defense platforms and occupation barracks inside northern Palestine, and the series of operations in Bayyada, Rashaf, and elsewhere — all brought the Israeli army back to the “natural” limits of power.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In recent weeks, the Israeli army complained to settlers that its government, under an American decision, was preventing it from expanding operations into Beirut and the southern suburbs. Those operations, it claimed, were meant as retaliation for the drones launched from the south. This was the clearest admission that the Israeli army is incapable of stopping our fighters’ operations, and that its only means of deterrence is killing civilians and destroying buildings — in other words, targeting our will in order to pressure the resistance into surrender.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The enemy admitted this while enjoying complete freedom of movement in southern Lebanon and the western Bekaa, where it can use as much air, land, naval, and intelligence power as it wishes, and where the resistance had withdrawn since November 2024, handing over positions to the Lebanese Army and dismantling what remained of its observation posts. Despite that, it still could not “deal with” the drones striking its soldiers, vehicles, and equipment, reducing its supposedly overwhelming power to its real limits.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Faced with this reality, the enemy needs something to restore its image as an army of destruction. Today it says it is in Zawtar al-Sharqiya, in Mazraat al-Hamra, and approaching Yohmor. These towns, though within what it calls the “yellow line,” are north of the Litani River. The enemy attempted to reach them several times before and failed. This time, its forces reached the southeastern neighborhoods of Zawtar and attempted to maneuver northward around the town, where our fighters confronted them and continue to do so.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The enemy may retreat under their strikes, as happened in Haddatha and Bayt al-Sayyad. Or it may advance during the hours or days remaining before a ceasefire. But in every town, farm, orchard, valley, and hill, it will face our heroic sons, who sacrifice their lives and shed their blood for our dignity and honor, and so that we remain free in our land.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As long as they remain this way, our land will return free from occupation, and we too shall return to it, even if after some time.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "No matter how much the enemy gathers, expands, and destroys, it will not break our will or achieve its goals, as long as there remains among us even one young man carrying his determination, his drone, and his rifle; arming his explosive device, loading his rocket launcher, and firing artillery shells from a position immediately detected by the enemy, which then rains shells and bombs upon him — yet he does not retreat.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/wNMRx-zzqZA3Q06syxaVqPBP8g_elkx_-PtlPMtSQKkOMocDQmecmbVHb1jjO27.jpg', false, false, 274, 778, TIMESTAMP '2026-05-27 20:59:26.427', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'exclusive'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Widespread Rejection of the “Open City” Statement... The Threat Comes from Aggression, Not from the People of the Land', 'رفض واسع لبيان «المدينة المفتوحة»... الخطر من العدوان لا من أهل الأرض', 'nab-threat-agr30526', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أثار البيان الذي وقع عليه بعض اللبنانيين  ودعا إلى جعل النبطية ومحيطها «مدينة مفتوحة» جدلاً واسعاً بين أبناء المنطقة، الذين رأوا فيه تبنّياً لخطاب يحمّل الأهالي والمقاومة مسؤولية الاعتداءات الإسرائيلية، بدل تحميل المسؤولية للعدو نفسه", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويعترض كثيرون على استخدام عبارة «حروب الآخرين على أرضنا»، معتبرين أن أبناء الجنوب الذين قدّموا التضحيات دفاعاً عن أرضهم ليسوا «آخرين»، وأن هذا الخطاب يتجاهل تاريخ المنطقة ومواجهة أهلها للاحتلال الإسرائيلي", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويشير معارضو البيان إلى أن مفهوم «المدينة المفتوحة» في زمن الحروب يعني عملياً التخلي عن وسائل الدفاع وإزالة التحصينات وترك المدينة أمام القوات المهاجمة من دون مقاومة، وهو أسلوب استُخدم في عدد من المدن الأوروبية خلال الحرب العالمية الثانية، ما سمح للقوات الغازية بالسيطرة عليها من دون قتال", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أثيرت تساؤلات حول آلية جمع التواقيع على البيان، بعدما تحدث بعض الموقعين عن اختلاف بين النص الذي وقّعوا عليه والصيغة التي نُشرت لاحقاً. وبرزت في هذا السياق مواقف اعتراضية من شخصيات أكدت أنها لم تكن على علم بالمضمون النهائي للبيان عند توقيعه", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويرى المعترضون أن البيان يبتعد عن تحميل إسرائيل مسؤولية الاعتداءات، ويتجه نحو اعتبار المقاومة سبباً للأزمة، في حين أن المشكلة الأساسية بنظرهم هي استمرار العدوان الإسرائيلي على الجنوب واستهداف المدنيين والقرى والبنى التحتية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما يشير هؤلاء إلى أن ما جرى في جنوب الليطاني خلال السنوات الماضية أثبت أن إزالة المواقع العسكرية وتسليمها للجيش اللبناني لم يمنع الاعتداءات الإسرائيلية أو التوغلات العسكرية، ما يضعف الرهان على أن التخلي عن عناصر القوة سيؤدي إلى توفير الحماية للمنطقة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الوقت نفسه، يوجّه أبناء المنطقة انتقادات للدولة اللبنانية، معتبرين أنها لم تنجح في حماية المدنيين أو منع تدمير القرى وتهجير السكان، كما لم تتخذ خطوات كافية لوقف الاعتداءات أو محاسبة المسؤولين عنها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويؤكد رافضو البيان أن الخطر الحقيقي على الجنوب لا يأتي من أبنائه أو من المقاومة، بل من الاعتداءات الإسرائيلية المستمرة، وأن أي نقاش حول مستقبل المنطقة يجب أن يبدأ من تحميل إسرائيل مسؤولية ما يجري، لا من تحميل أبناء الأرض الذين يرفضون الاستسلام مسؤولية العدوان الواقع عليهم", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The statement signed by a number of Lebanese citizens calling for Nabatieh and its surroundings to be declared an “open city” has sparked widespread controversy among residents of the region, who see it as adopting a narrative that places responsibility for Israeli attacks on local residents and the resistance rather than on Israel itself.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Many have objected to the use of the phrase “other people’s wars on our land,” arguing that the people of southern Lebanon, who have made sacrifices in defense of their homeland, are not “others.” They contend that such rhetoric ignores the region’s history and its residents’ struggle against Israeli occupation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Opponents of the statement point out that the concept of an “open city” during wartime effectively means abandoning defensive measures, removing fortifications, and leaving the city exposed to attacking forces without resistance. They note that this approach was used in several European cities during World War II, allowing invading armies to take control without fighting.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Questions have also been raised regarding the process through which signatures were collected for the statement, after some signatories reportedly said there were differences between the text they signed and the version that was later published. Several individuals publicly objected, stating that they had not been aware of the final wording of the statement when they signed it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Critics argue that the statement shifts attention away from holding Israel responsible for the attacks and instead portrays the resistance as the source of the crisis. In their view, the central issue remains the continuation of Israeli military operations against southern Lebanon and the targeting of civilians, villages, and infrastructure.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They also argue that developments south of the Litani River in recent years have demonstrated that removing military positions and handing them over to the Lebanese Army did not prevent Israeli attacks or military incursions, weakening the argument that abandoning defensive capabilities would provide protection for the region.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "At the same time, residents direct criticism toward the Lebanese state, arguing that it has failed to protect civilians, prevent the destruction of villages, or stop the displacement of residents. They also believe that insufficient measures have been taken to halt the attacks or hold those responsible accountable.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Those rejecting the statement insist that the real threat to southern Lebanon does not come from its people or from the resistance, but from the ongoing Israeli attacks. They argue that any discussion about the future of the region should begin with holding Israel responsible for what is happening, rather than blaming the people of the land who refuse to surrender in the face of aggression.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Kamel-Jaber_prewar_Nabatieh_2528-1746849284-QdIulWseKHYo8MTWT3awO3PWqnXbdS.jpg', false, false, 74, 345, TIMESTAMP '2026-05-30 13:17:57.174', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Under Fire and Negotiations: Israel Rejects Withdrawal as Lebanon Insists on Ending the Aggression', 'تحت النار والمفاوضات: إسرائيل ترفض الانسحاب ولبنان يتمسّك بوقف العدوان', 'leb-ins-warend-3052026', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رغم التصعيد الإسرائيلي الواسع الذي استهدف مناطق في الجنوب والبقاع، تواصل السلطة اللبنانية المشاركة في الاجتماعات العسكرية مع العدو برعاية أميركية، وسط انتقادات متزايدة تعتبر أن استمرار المفاوضات في ظل القصف يمنح إسرائيل فرصة لمواصلة الضغط العسكري والسياسي في آن واحد", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وترى أوساط متابعة أن تل أبيب تتعامل مع المفاوضات والعمليات العسكرية كجزء من مسار واحد يهدف إلى فرض شروط جديدة على لبنان تحت ضغط النار، مستفيدة من تمسّك الدولة اللبنانية بخيار التفاوض وعدم انسحابها من المسار القائم رغم استمرار الغارات والاغتيالات", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي هذا الإطار، عُقد اجتماع عسكري لبناني – إسرائيلي في واشنطن بمشاركة ضباط أميركيين، تمهيداً لجولة جديدة من المفاوضات المباشرة مطلع حزيران. وترأس الوفد اللبناني مدير العمليات في الجيش العميد جورج رزق الله، مع تأكيد قيادة الجيش أن مهمة الوفد تقتصر على الجوانب التقنية والعسكرية المرتبطة بتثبيت وقف إطلاق النار ومنع التدهور الأمني، بعيداً من أي نقاش سياسي يتعلق بسلاح المقاومة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وحمل الوفد اللبناني إلى الاجتماعات مطلباً أساسياً يتمثل بوقف الاعتداءات الإسرائيلية وتثبيت الهدنة، مع السعي للحصول على ضغط أميركي يمنع إسرائيل من استخدام المفاوضات غطاءً لمواصلة عملياتها العسكرية. كما شددت الرئاسة اللبنانية خلال اتصالات مع الجانب الأميركي على أن وقف إطلاق النار يجب أن يكون المدخل لأي بحث في الملفات الأخرى", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، أصرّ الوفد الإسرائيلي على طرح ملفات تتعلق بالمسيّرات والبنية العسكرية شمال الليطاني، وربط أي نقاش حول الانسحاب من الأراضي اللبنانية المحتلة بإجراءات تستهدف قدرات حزب الله. كما رفضت إسرائيل، بحسب تقارير إعلامية، أي جدول زمني للانسحاب من المواقع التي تحتلها حالياً، مبررة ذلك بما تصفه بالتهديدات الأمنية", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتشير المعلومات إلى أن الجانب الأميركي يعمل على مقترحات جديدة تتضمن ترتيبات أمنية أوسع، من بينها أفكار تتعلق بمراقبة تنفيذ التفاهمات ونزع سلاح حزب الله، وهي طروحات قوبلت بتحفظات لبنانية ورفض لأي شكل من أشكال التنسيق الأمني المباشر مع إسرائيل", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ظل هذا المشهد، يبرز اقتناع متزايد لدى أوساط سياسية بأن الاجتماعات العسكرية لن تكون قادرة على حسم الملفات الأساسية، خصوصاً أن قضايا الانسحاب الإسرائيلي ومستقبل السلاح ترتبط بتوازنات سياسية وميدانية أكبر. كما أن أي تفاهمات تبقى مرتبطة بالواقع الميداني، في ظل تأكيد حزب الله أنه غير معني بهذه المفاوضات وأن المقاومة ستستمر طالما استمرت الحرب والاحتلال", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Despite the broad Israeli escalation targeting areas in southern Lebanon and the Bekaa, the Lebanese authorities continue to participate in military meetings with Israel under American sponsorship, amid growing criticism that maintaining negotiations during ongoing bombardment gives Israel an opportunity to continue applying both military and political pressure simultaneously.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Observers argue that Tel Aviv is treating negotiations and military operations as part of a single strategy aimed at imposing new conditions on Lebanon under the pressure of force, benefiting from the Lebanese state's commitment to negotiations and its refusal to withdraw from the current process despite continued airstrikes and targeted killings.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In this context, a Lebanese-Israeli military meeting was held in Washington with the participation of American officers, ahead of a new round of direct talks scheduled for early June. The Lebanese delegation was led by Brigadier General George Rizkallah, Director of Operations in the Lebanese Army. Army leadership emphasized that the delegation’s mission is limited to technical and military issues related to maintaining the ceasefire and preventing security deterioration, away from any political discussions concerning Hezbollah’s weapons.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Lebanese delegation reportedly brought a key demand to the meetings: ending Israeli attacks and solidifying the truce, while seeking American pressure to prevent Israel from using negotiations as cover for continued military operations. The Lebanese presidency also stressed in contacts with the American side that a ceasefire must be the starting point for discussing any other issues.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, the Israeli delegation insisted on raising issues related to drones and military infrastructure north of the Litani River, linking any discussion about withdrawal from occupied Lebanese territories to measures targeting Hezbollah’s capabilities. According to media reports, Israel also rejected any timetable for withdrawing from positions it currently occupies, citing what it describes as security threats.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Reports indicate that the United States is working on new proposals involving broader security arrangements, including ideas related to monitoring the implementation of understandings and the disarmament of Hezbollah. These proposals have reportedly been met with Lebanese reservations and rejection of any form of direct security coordination with Israel.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Against this backdrop, there is growing conviction among political circles that military meetings alone will not be able to resolve the core issues, particularly since questions related to Israeli withdrawal and the future of weapons are tied to broader political and military balances. Any agreements also remain dependent on developments on the ground, as Hezbollah has repeatedly stated that it is not involved in these negotiations and that the resistance will continue as long as war and occupation persist.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/000_b32t4q9_1-yq5B6IOrIJYoUzX8QR6WHRbkSiegug.jpg', false, false, 36, 146, TIMESTAMP '2026-05-30 15:01:52.733', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Beaufort Castle: A Strategic Stronghold Controlling the Keys to Southern Lebanon for Decades', 'قلعة الشقيف: مرتفع استراتيجي يتحكم بمفاتيح الجنوب منذ عقود', 'beaufort-castle-history31', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رغم مرور أكثر من أربعة عقود على معركة الشقيف الشهيرة، لا تزال القلعة تحتفظ بمكانتها كواحدة من أهم النقاط العسكرية في جنوب لبنان. ومع كل تصعيد أو مواجهة في المنطقة، تعود إلى الواجهة باعتبارها موقعاً قادراً على التأثير في ميزان السيطرة الميدانية بفضل موقعها الجغرافي وتاريخها العسكري الطويل", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وتُعدّ قلعة الشقيف من أهم المواقع الاستراتيجية في جنوب لبنان بسبب موقعها الجغرافي الفريد. فهي تقع على ارتفاع يتجاوز 700 متر فوق سطح البحر، ما يمنحها قدرة استثنائية على الإشراف على مساحات واسعة من الجنوب اللبناني وشمال فلسطين المحتلة. ومن على أسوارها يمكن مراقبة نهر الليطاني وعدد كبير من القرى والبلدات الجنوبية، إضافة إلى المحاور الرئيسية التي تربط بين النبطية ومرجعيون والقطاع الشرقي من الجنوب", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما تطل القلعة بشكل مباشر على مناطق أرنون وكفرتبنيت ويحمر وزوطر والطيبة ودير سريان والقنطرة، فضلاً عن مستوطنة المطلة الواقعة على مسافة تقل عن أربعة كيلومترات. وهذا ما يمنحها قيمة استخباراتية وعسكرية كبيرة، إذ تسمح برصد التحركات ومتابعة خطوط الإمداد والانتشار في مساحة واسعة من المنطقة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولا تقتصر أهمية الشقيف على ارتفاعها فقط، بل ترتبط أيضاً بموقعها فوق نهر الليطاني ووادي السلوقي، وهما من أهم المحاور العسكرية في جنوب لبنان. لذلك ينظر إليها العسكريون على أنها نقطة حاكمة ميدانياً، لأن من يسيطر عليها يمتلك قدرة أكبر على المراقبة والتوجيه والسيطرة على طرق الحركة في محيطها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتحمل القلعة أيضاً أهمية تاريخية كبيرة في الصراع اللبناني – الإسرائيلي. ففي حزيران عام 1982 شهدت واحدة من أشهر معارك الاجتياح الإسرائيلي للبنان، عندما تحصّن داخلها نحو 30 مقاتلاً فلسطينياً فقط في مواجهة أكثر من 1200 جندي إسرائيلي مدعومين بالدبابات والطائرات والمدفعية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واستمرت المعركة عدة أيام وكبّدت القوات الإسرائيلية خسائر كبيرة، قبل أن يتمكن الجيش الإسرائيلي من السيطرة على القلعة. وتروي المصادر الإسرائيلية أن وزير الدفاع آنذاك أريئيل شارون وصل إلى الموقع بعد انتهاء المعركة ليُفاجأ بأن عدد المدافعين كان محدوداً جداً مقارنة بحجم القوة التي خاضت الهجوم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبعد احتلالها، تحولت القلعة إلى موقع عسكري متقدم للجيش الإسرائيلي طوال سنوات الاحتلال. وأصبحت الطريق المؤدية إليها تُعرف داخل إسرائيل باسم «الطريق الدامي» بسبب كثرة العمليات والهجمات التي استهدفت القوات الإسرائيلية على هذا المحور.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وعندما قررت إسرائيل الانسحاب من جنوب لبنان عام 2000، أخلت القلعة بسرية قبل أن تقوم بتفجير أجزاء منها لمنع الاستفادة العسكرية منها بعد الانسحاب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واليوم، تعود الشقيف إلى دائرة الاهتمام العسكري بسبب قدرتها على توفير نقطة إشراف نارية واستخباراتية واسعة، تسمح بمراقبة أجزاء كبيرة من جنوب لبنان والتحكم بقدر مهم من الحركة الميدانية في المنطقة. ولهذا السبب لا يُنظر إليها كمجرد معلم أثري أو قلعة تاريخية، بل كواحدة من أهم العقد العسكرية والجغرافية في الجنوب، والتي ظلّت محور صراع منذ أكثر من أربعة عقود.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Despite more than four decades having passed since the famous Battle of Beaufort Castle, the fortress remains one of the most important military positions in southern Lebanon. With every escalation or confrontation in the region, it returns to the spotlight as a site capable of influencing the balance of battlefield control thanks to its geographical location and long military history.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Beaufort Castle, known locally as the Shqif Castle, is considered one of the most strategic locations in southern Lebanon because of its unique geographic position. Standing more than 700 meters above sea level, it offers exceptional oversight of vast areas of southern Lebanon and northern Israel. From its walls, observers can monitor the Litani River, numerous southern villages and towns, and the main routes linking Nabatieh, Marjayoun, and the eastern sector of the south.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The fortress directly overlooks Arnoun, Kfar Tebnit, Yohmor, Zawtar, Taybeh, Deir Siryan, and Qantara, as well as the settlement of Metula, located less than four kilometers away. This gives it significant intelligence and military value, allowing for the monitoring of movements, supply routes, and force deployments across a wide area.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Its importance is not limited to its elevation. The castle also overlooks the Litani River and the Wadi al-Slouqi valley, two of the most important military corridors in southern Lebanon. Military planners therefore regard it as a key commanding position, since whoever controls it enjoys greater capabilities for observation, direction, and control over movement routes in the surrounding area.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The fortress also holds major historical significance in the Lebanese-Israeli conflict. In June 1982, it witnessed one of the most famous battles of the Israeli invasion of Lebanon, when approximately 30 Palestinian fighters defended the castle against more than 1,200 Israeli troops supported by tanks, aircraft, and artillery.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The battle lasted several days and inflicted significant losses on Israeli forces before the castle eventually fell. Israeli accounts later reported that then-Defense Minister Ariel Sharon visited the site after the battle and was surprised to learn how few defenders had held off such a large attacking force.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Following its capture, the castle became an advanced military position for the Israeli army throughout the years of occupation. The road leading to it became known in Israel as the “Bloody Road” because of the numerous attacks carried out against Israeli forces along that route.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When Israel withdrew from southern Lebanon in 2000, it secretly evacuated the castle before demolishing parts of it to prevent its future military use.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Today, Beaufort Castle has once again become a focus of military attention because of its ability to provide a wide intelligence and fire-control vantage point, allowing oversight of large portions of southern Lebanon and influence over a significant share of military movement in the area. For this reason, it is viewed not merely as a historical landmark or ancient fortress, but as one of the most important military and geographical nodes in southern Lebanon, remaining at the center of regional conflict for more than four decades.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/a0OfQirJXgKx0n_Ic4CRmSTKKrCDI3mYKKT7xqHPaHkO7LNKHf0PJLo9PTqkhy7piVzNQPMK7ViBB3gEKRZODOWQZWq3zGPnUDEHMAg12_6bV6xTAdpouKH2MQCFnbG89tqvxx2M9d1i1osQ9hRoitgEkT3D_Av9ickBT81URmLHR_LUxTLnmI1Z0niTRbbq-SKN3g50XR89PAl9jgLsOKgZ90nOF88', true, false, 610, 2384, TIMESTAMP '2026-05-31 13:08:44.186', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'history'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Regarding Beaufort Castle, Hezbollah Reveals the Final Hours Behind the Battle and Confirms: The Footage Is Coming', 'بشأن الشقيف.. "حزب الله" يكشف كواليس الساعات الأخيرة ويؤكد: المشاهد قادمة', 'hezb-beaufort-isr', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلنت غرفة عمليّات \"​حزب الله​\" حول تواجد الجيش الإسرائيلي في قلعة الشّقيف التّاريخيّ، أنه \"مع التّأثير السّلبي الكبير الّذي تسبّبت به المواد المصوّرة التي تبثّها المقاومة الإسلاميّة لعمليّاتها ضدّ قوات جيش العدوّ الإسرائيليّ في وعي المستوطنين داخل كيان الاحتلال، سعى جيش العدوّ جاهدًا للحصول على صورة يروّج لها على أنّها انتصار ساحق، علّه يسكّن من خلالها روع مستوطني الشّمال، فكان الهدف هو قلعة الشّقيف التّاريخية في جنوب لبنان والتي تبعد عن الحدود اللّبنانيّة الفلسطينيّة حوالي 4 كلم فقط\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text"}, {"type": "hardBreak"}, {"text": " ", "type": "text"}, {"type": "hardBreak"}, {"text": "وأكد الحزب، أنع \"على مدى أكثر من 5 أيام، شنّ العدوّ الإسرائيليّ سلسلة من الاعتداءات الجويّة العنيفة والقصف المدفعيّ الكثيف على بلدة يحمر الشّقيف والقرى المحيطة بهدف السّيطرة عليها واحتلال قلعة الشّقيف، وما إن تقدّم باتّجاه أطراف البلدة الجنوبية حتّى واجه مقاومة بطوليّة وشرسة ونيران كثيفة من مجاهدي المقاومة الإسلاميّة منعته من تحقيق هدفه، فاكتفى بالّلجوء إلى أطراف البلدة الشرقيّة ذات التّضاريس الوعرة\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولفت الى أن \"غروب يوم السّبت 30/05/2026 تسلّلت مجموعة مشاة إسرائيليّة تحت غطاء دخانيّ كثيف من الجهة الشرقيّة لقلعة الشّقيف حيث المسارات غير المرئيّة، ووصلت إلى القلعة والتقطت مجموعة من الصّور الفوتوغرافيّة الّتي سارع العدوّ إلى توزيعها صباح الأحد والتّرويج بأنّه احتلّ القلعة، علمًا أنّ القلعة كانت خالية من أيّ وجود عسكريّ للمقاومة\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال \"يجد العدو منذ فجر أمس وحتى ساعة إصدار هذا البيان صعوبة كبيرة في تثبيت قوّاته في محيط القلعة، حيث تتواجد هذه القوّات قرب منطقة الاستراحة أسفل القلعة\"، مشددةً على أنه \"تخوض المقاومة الإسلاميّة معركة استنزاف ضدّ قوّات جيش العدوّ الإسرائيليّ المتواجدة في المنطقة، والمشاهد المصوّرة القادمة ستثبت ذلك\".", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Hezbollah’s Operations Room issued a statement regarding the presence of Israeli forces at the historic Beaufort Castle, saying that “due to the significant negative impact that footage released by the Islamic Resistance has had on the morale of settlers inside Israel, the Israeli army sought to obtain images it could promote as a decisive victory in an attempt to reassure residents of the north. Its target was the historic Beaufort Castle in southern Lebanon, located approximately four kilometers from the Lebanese-Palestinian border.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The group stated that “for more than five days, the Israeli army carried out a series of intense airstrikes and heavy artillery bombardments against Yohmor al-Shaqif and surrounding villages with the aim of taking control of the area and occupying Beaufort Castle. However, as soon as it advanced toward the southern outskirts of the town, it encountered fierce resistance and heavy fire from resistance fighters, preventing it from achieving its objective. It therefore limited its presence to the rugged eastern outskirts of the town.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hezbollah added that “at sunset on Saturday, May 30, 2026, an Israeli infantry unit infiltrated the eastern side of Beaufort Castle under dense smoke cover, using concealed routes. The force reached the castle and took photographs, which Israel quickly distributed on Sunday morning, claiming it had captured the site, despite the castle being devoid of any resistance military presence.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The statement further claimed that “since dawn yesterday and up until the time of issuing this statement, the enemy has faced major difficulties in establishing its forces around the castle, with troops positioned near the rest area below the fortress.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It concluded by stressing that “the Islamic Resistance is engaged in a war of attrition against Israeli forces present in the area, and the upcoming footage will prove it.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/1a710cddbb04db2fbb3d4b60ab179e8c-zKWMKk3eohyIGsQxjoDNkkQ7akOHHy', false, false, 357, 1081, TIMESTAMP '2026-06-01 13:29:28.201', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Qaani Raises the Threat Level: New Fronts May Open in Support of Lebanon', 'قاآني يرفع سقف التهديد: جبهات جديدة قد تُفتح إسناداً للبنان', 'qaani-threat-2626', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "لوّح قائد قوة القدس في الحرس الثوري الإيراني إسماعيل قاآني بإمكانية اتساع رقعة المواجهة في المنطقة، محذّراً من أن استمرار الاعتداءات الإسرائيلية على لبنان وقطاع غزة قد يدفع قوى محور المقاومة إلى تفعيل جبهات إضافية دعماً للجبهتين اللبنانية والفلسطينية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبر قاآني أن الدعم الأميركي لإسرائيل يساهم في تصعيد التوتر، مشيراً إلى أن التطورات الحالية قد تنعكس أيضاً على الممرات البحرية الاستراتيجية، في إشارة إلى مضيقي باب المندب وهرمز.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأضاف أن العمليات الإسرائيلية المتواصلة قد تؤدي إلى تصعيد أكبر في المنطقة، مؤكداً أن تل أبيب ستواجه تداعيات ما وصفها بـ«الجرائم المستمرة» في لبنان وغزة.", "type": "text"}, {"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "في موازاة ذلك، كشفت مصادر إيرانية أن طهران لم تحسم بعد موقفها النهائي من المقترحات المطروحة مع الولايات المتحدة، وأن المشاورات لا تزال مستمرة داخل المؤسسات المعنية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب المصادر، لم ترسل إيران حتى الآن ردها النهائي على النص المتداول، مؤكدة أنها تتعامل بحذر مع أي تفاهم جديد بسبب تجارب سابقة تتعلق بعدم التزام واشنطن بتعهداتها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وشددت المصادر على أن طهران تسعى إلى ضمانات وآليات تنفيذية واضحة قبل الموافقة على أي اتفاق محتمل، مؤكدة أن النقاشات لا تزال مفتوحة ولم تُتخذ أي قرارات نهائية حتى الآن.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Esmail Qaani warned of the possibility of a broader regional confrontation, cautioning that continued Israeli attacks on Lebanon and the Gaza Strip could prompt forces within the so-called Axis of Resistance to activate additional fronts in support of the Lebanese and Palestinian arenas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Qaani argued that American support for Israel is contributing to escalating tensions, adding that current developments could also affect strategic maritime routes, in an apparent reference to the Bab el-Mandeb and Hormuz straits.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He added that Israel’s ongoing military operations could lead to wider escalation across the region, asserting that Tel Aviv would face the consequences of what he described as its “continued crimes” in Lebanon and Gaza.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, Iranian sources revealed that Tehran has not yet finalized its position regarding proposals under discussion with the United States, and that consultations remain ongoing within the relevant institutions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the sources, Iran has not yet submitted its final response to the circulating draft, emphasizing that it is approaching any new understanding with caution due to previous experiences involving what it views as Washington’s failure to honor its commitments.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The sources stressed that Tehran is seeking clear guarantees and implementation mechanisms before approving any potential agreement, adding that discussions remain open and that no final decisions have been made so far.", "type": "text"}, {"type": "hardBreak"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/4385123-qCfSK2rht7UqcKg5mgBRKjIqq0QCpf.jpg', false, false, 197, 897, TIMESTAMP '2026-06-02 08:56:37.764', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT '**UN Report Warns of Worsening Humanitarian Challenges in Lebanon**', 'تقرير أممي يحذّر من تفاقم التحديات الإنسانية في لبنان', 'human-lb-reports-warning6226', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "حذّرت الأمم المتحدة من تفاقم الأزمة الإنسانية في لبنان مع استمرار الحرب وتوسع موجات النزوح، مشيرة إلى أن أكثر من مليون شخص ما زالوا خارج منازلهم وسط تراجع القدرة على تأمين الاحتياجات الأساسية وارتفاع معدلات انعدام الأمن الغذائي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح برنامج الأغذية العالمي أن ارتفاع الأسعار وفقدان مصادر الدخل والضغوط المتزايدة على الأسواق أدت إلى تدهور الأوضاع المعيشية في مختلف المناطق اللبنانية، مؤكداً أنه قدّم منذ مطلع آذار مساعدات غذائية ونقدية لأكثر من 700 ألف متضرر من الحرب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبيّن البرنامج أن استمرار الغارات وأوامر الإخلاء يعيقان وصول المساعدات الإنسانية ويؤديان إلى زيادة أعداد النازحين، خصوصاً في المناطق التي يصعب الوصول إليها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكشف أحدث تقييم للأمن الغذائي أن نحو 1.24 مليون شخص في لبنان يواجهون مستويات حادة من انعدام الأمن الغذائي بين نيسان وآب 2026، نتيجة النزوح المستمر وارتفاع أسعار المواد الغذائية والمحروقات وتراجع النشاط الاقتصادي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أشار إلى ارتفاع أسعار الخضروات بأكثر من 20% والخبز بنحو 15% منذ بداية التصعيد، فيما خرجت غالبية الأسواق في جنوب لبنان والنبطية من الخدمة، بينما تواجه الأسواق العاملة في مناطق أخرى ضغوطاً متزايدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وحذّر البرنامج من أن استمرار المساعدات مهدد بسبب نقص التمويل، مؤكداً حاجته إلى 112 مليون دولار خلال الأشهر المقبلة لضمان مواصلة تقديم الدعم الإنساني للفئات الأكثر تضرراً في لبنان.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The United Nations has warned of a worsening humanitarian crisis in Lebanon as the war continues and displacement expands, noting that more than one million people remain away from their homes amid a declining ability to secure basic necessities and rising levels of food insecurity.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The World Food Programme (WFP) explained that rising prices, loss of income sources, and increasing pressure on markets have led to a deterioration in living conditions across Lebanon. It added that since the beginning of March, it has provided food and cash assistance to more than 700,000 people affected by the war.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The agency stated that ongoing airstrikes and evacuation orders are hindering the delivery of humanitarian aid and contributing to a growing number of displaced people, particularly in hard-to-reach areas.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the latest food security assessment, around 1.24 million people in Lebanon are expected to face acute levels of food insecurity between April and August 2026 due to continued displacement, rising food and fuel prices, and declining economic activity.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report also noted that vegetable prices have risen by more than 20% and bread prices by around 15% since the escalation began. Meanwhile, most markets in southern Lebanon and the Nabatieh region are no longer functioning, while markets operating in other areas are facing increasing pressure.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The World Food Programme further warned that the continuation of aid operations is at risk because of funding shortages, stressing that it requires $112 million over the coming months to ensure continued humanitarian support for the most affected groups in Lebanon.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/kid_in_the_refugee_camp_of_bourj_el-barajneh_-_flickr_-_al_jazeera_english-CIRVhX9VvYZxsUhR2n76zwa2buTzDH.jpg', false, false, 123, 728, TIMESTAMP '2026-06-02 11:38:33.801', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Opposition to Official Exams Grows as New Action Looms', 'اعتراضات تتوسع على الامتحانات الرسمية وتحرك مرتقب', 'off-exams-opp', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يتجه المعترضون على إجراء الامتحانات الرسمية هذا العام إلى تصعيد تحركهم القانوني، مع التحضير لتقديم مراجعة أمام مجلس شورى الدولة لإبطال مرسوم الامتحانات الرسمية لعام 2026، بحجة مخالفته مبدأ المساواة بين التلامذة وعدم مراعاته للظروف الاستثنائية التي يعيشها لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكشف المحامي حسن عادل بزي أن المراجعة المرتقبة تستند إلى جملة من الأسباب القانونية والإنسانية، أبرزها التفاوت الكبير في ظروف الطلاب نتيجة النزوح والحرب، إضافة إلى الظروف نفسها التي استندت إليها مؤسسات الدولة سابقاً لتبرير تأجيل استحقاقات أخرى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار بزي إلى أن جميع الوزراء وافقوا على المرسوم وفق معلومات نقلها عن مصدر نيابي، لافتاً إلى أنه جرى أيضاً التقدم بمراجعة أمام قضاء العجلة تتعلق بسلامة القرار في ظل الأوضاع الأمنية والإنسانية الراهنة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويرى المعترضون أن آلاف الطلاب يواجهون ظروفاً استثنائية تجعل إجراء الامتحانات أمراً بالغ الصعوبة، سواء بسبب النزوح أو فقدان المنازل أو الأوضاع الاقتصادية المتدهورة. كما يطرحون تساؤلات حول قدرة الطلاب على التحضير للامتحانات في مراكز الإيواء والخيم، أو تحمّل تكاليف التنقل اليومية إلى مراكز الامتحانات في ظل الأزمة المعيشية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتشمل الاعتراضات أيضاً المخاوف الأمنية المرتبطة باستمرار الغارات والتهديدات، إضافة إلى الانعكاسات النفسية على الطلاب الذين فقد بعضهم أفراداً من عائلاتهم أو تعرّضوا لتجارب قاسية خلال الحرب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويؤكد أصحاب المبادرة أن تحركهم يهدف إلى حماية حق الطلاب في تعليم عادل وظروف امتحانية متكافئة، معتبرين أن الواقع الحالي لا يسمح بإجراء امتحانات رسمية تراعي مبدأ المساواة بين جميع التلامذة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Opponents of holding official examinations this year are preparing to escalate their legal campaign by filing a challenge before Lebanon’s State Council (Shura Council) seeking the annulment of the 2026 official examinations decree, arguing that it violates the principle of equality among students and fails to take into account the exceptional circumstances currently facing the country.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Lawyer Hassan Adel Bazi revealed that the anticipated legal challenge is based on a range of legal and humanitarian arguments, most notably the significant disparities in students’ circumstances resulting from displacement and war, as well as the same exceptional conditions that state institutions previously cited to justify postponing other official obligations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bazi stated that all ministers approved the decree, according to information he received from a parliamentary source, adding that an urgent judicial review has also been submitted regarding the validity of the decision in light of the current security and humanitarian conditions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Opponents argue that thousands of students are facing extraordinary circumstances that make sitting for examinations extremely difficult, whether due to displacement, the loss of homes, or worsening economic conditions. They also question how students are expected to prepare for exams while living in shelters or tents, or afford daily transportation costs to examination centers amid the ongoing economic crisis.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The objections also include security concerns linked to continued airstrikes and threats, as well as the psychological impact on students, some of whom have lost family members or experienced severe hardships during the war.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Those behind the initiative stress that their campaign aims to protect students’ right to fair education and equal examination conditions, maintaining that the current reality does not allow for official exams that uphold the principle of equality among all students.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Brevet-Is-Officially-Cancelled-For-Lebanese-Students-Here-Are-The-Details-D50uccbnlqAj3kftV04FgZuSxdUEbw.jpg', false, false, 334, 1375, TIMESTAMP '2026-06-03 11:26:24.823', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Raad: We Learned the Lesson from Palestine... That Is Why We Will Resist', 'رعد: لقد تعلّمنا الدرس من فلسطين... لذلك سنقاوم', 'raad-resistance-lebpales0326', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رأى رئيس كتلة الوفاء للمقاومة النائب محمد رعد أن المشهد اللبناني ينقسم اليوم إلى ثلاثة خيارات رئيسية في التعامل مع العدوان الإسرائيلي على لبنان، معتبراً أن مسار الأحداث الداخلية يتأثر بمدى تقدّم أو تراجع كل واحد من هذه الخيارات.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "1 - خيار التنصّل من أي مسؤولية لمواجهة العدوان، وتحميل المقاومة مسؤولية جرّ لبنان إلى الحرب، سواء بسبب تمسّكها بسلاحها وإصرارها على الصمود وعدم الاستجابة لدعوات التفاوض المباشر مع العدو، أو نتيجة قرارها الذي فاجأ الجميع بالردّ على الخروقات الإسرائيلية بعد 15 شهراً من التزام ضبط النفس، عربد خلالها العدو من دون أن تنجح الجهود السياسية والدبلوماسية في كبحه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويندفع أصحاب هذا الخيار بشكل محموم ومتسرّع إلى توسّل وقف الحرب ممن يدعمون العدو، ويؤيّدون مشروعه لإنهاء المقاومة، واستدراج لبنان إلى فخّ الإذعان والاستسلام لشروطه عبر تفاوض مباشر أو غير متوازن. ولإثبات «حسن» نياتهم، يعتمد هؤلاء خطاباً سياسياً مُزايداً على المقاومة في حفظ استقرار البلاد ووقف الحرب بأيّ ثمن، بالتوازي مع تبنّي مواقف وإجراءات ضاغطة عليها، استجابةً لمطالب العدو والقوى الدولية الداعمة للعدوان، ولرغبات بعض القوى الإقليمية الطامحة إلى لعب دور في لبنان يتناسب مع توجّهها لإنهاء الصراع العربي - الإسرائيلي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ضوء ذلك، يترجم أصحاب هذا الخيار مطالب العدو إلى مواقف وسياسات تهدف إلى محاصرة المقاومة في الداخل، مالياً واقتصادياً ولوجستياً وسياسياً، عبر قرارات حكومية وتجاوزات ميثاقية ودستورية وخطط تنفيذية، بدءاً من استهداف «القرض الحسن»، مروراً بـ«حصرية السلاح بيد الدولة» في ظل استمرار العدوان، وصولاً إلى قرار تجريم العمل المقاوم بذريعة حصرية «قرار الحرب والسلم» بيد الدولة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "والجدير ذكره أن السلطة التي تتبنّى هذا الخيار، مضى على تحمّلها للمسؤولية في البلاد أكثر من عام، لم يشهد خلاله اللبنانيون أيّ إنجاز فعلي تتباهى به، اللهم إلا التطبيق المُجتزأ والانتقائي المُشوِّه للدستور، بطريقة التشاطر والتدليس، وتحت شعار «اشهدوا لي عند الأمير بأنّني أول من رمى».", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "2 - خيار الرهان الصريح والواضح على نجاح العدوانية الصهيونية في إنهاء وجود حزب الله ومقاومته وحتى حضوره السياسي، وملاقاة العدو الصهيوني، من دون أيّ حرج أو مقدّمات، في اتفاقية سلام وعلاقات استراتيجية تشاركية لحفظ «استقرار المنطقة» و«مكافحة الإرهاب»، وتكريس الانتماء اللبناني إلى الغرب وإلى حلف الناتو، وإيجاد صيغة تَساكُنٍ وعلاقات حسن جوار مع دول العالم العربي والإسلامي تحت المظلة الأميركية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولا يتورّع أصحاب هذا الخيار عن أيّ إساءة أدب أو استخدام مُحرّم أو مواصلة التحريض اللئيم والخسيس، أخلاقياً وإعلامياً واقتصادياً وسياسياً وأمنياً، وحتى عسكرياً، ضد المقاومة وبيئتها، ولا يخفون خيبتهم على خذلان بعض الدول العربية والغربية لهم بإيصال مرشّحهم إلى رئاسة الجمهورية في الاستحقاق الرئاسي السابق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولا يخفي هؤلاء أنّهم لا يشبهون خصومهم في شيء، وأن خياراتهم الثقافية والسياسية والمصلحية هي تلك الوافدة من وراء البحار والمحمية بالقوة والهيمنة، وأن ما يلجأون إليه من أدوات تجميل لتمرير مشاريعهم ليس إلا عدّة شغل لا تستثني توظيف أيّ شيء، حتى الطقوس الدينية لتحقيق مصالحهم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "3 - خيار الصمود والمقاومة الذي يتبنّاه حزب الله وقوى إسلامية ووطنية وازنة. وهو بالنسبة إلى حزب الله، خيار وجوديّ واستراتيجيّ ينطلق من فهم عميق لطبيعة العدو الصهيوني ومشروعه التوسّعي الاستيطاني العنصري في المنطقة، ولعلاقة هذا العدو الوظيفية والعضوية مع مشروع الاستكبار العالمي الذي تتبنّاه دول الغرب الكبرى وتمثّل الولايات المتحدة اليوم قيادته ورأس الهرم فيه.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وينطلق أصحاب هذا الخيار من قناعة مفادها أن قيام إسرائيل شكّل تعبيراً عن التقاء المشروع الصهيوني مع المصالح الاستعمارية الغربية الساعية إلى تثبيت نفوذها في منطقة غرب آسيا، نظراً إلى موقعها الجيوسياسي وثرواتها الطبيعية وممراتها المائية الاستراتيجية. ومن هذا المنطلق، يرون أن إسرائيل ليست مجرّد دولة طبيعية في المنطقة، بل قاعدة متقدّمة تضمن استمرار النفوذ الغربي وتفوّقه السياسي والعسكري والاقتصادي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وينطلق هذا الخيار من قناعة بأن الكيان اللقيط الذي أُنشئ بالقوة على أرض فلسطين المحتلة، شكّل تعبيراً عن التقاء فكرة الاستيطان التلمودية الصهيونية مع المصالح الاستعمارية الغربية الساعية إلى تثبيت نفوذها في منطقة غرب آسيا التي يسمّونها «الشرق الأوسط»، نظراً إلى موقعها الجيوسياسي وثرواتها الطبيعية وممراتها المائية الاستراتيجية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكذلك لأن إحكام السيطرة والنفوذ يحتاج إلى مرتكز دائم وقوي يملك شاغلوه كلّ الحوافز الوجودية والأطماع المُحرِّضة، لأداء مهمة الاستطلاع والمراقبة الدائمة للتهديدات، والقدرة على انتهاز الفرص المؤاتية للتوسّع أو الاقتطاع، وضمان استمرار النزاعات الداخلية في المحيط لإضعافه، وتهيئة ظروف الانقضاض والقضم التدريجي، ثم الاحتلال والتثبيت واستثمار ثروات بلدان المنطقة، تحت وصاية دولية ضامنة لتفوّق كيان العدو على كل بلدان العالم العربي. ولبنان أحد أقرب تلك البلدان المُغرية للضمّ والاحتلال والتوسّع، ومن يغفل عن هذه الحقيقة لا يمكنه أن يواجه الخطر الصهيوني، فضلاً عن عجزه عن تصوّر حجم الدعم والاحتضان والمساندة لاعتداءاته ضد شعوب ودول المنطقة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "والوقائع التاريخية تؤكّد عزم الكيان الصهيوني الغاصب لفلسطين على المضي في خطوات ممنهجة لتحقيق حلم مُدّعى بإقامة دولة إسرائيل الكبرى التي عرض نتنياهو رسمها أمام العالم كله في أعقاب حرب الإبادة التي ارتكبها في غزّة، وسط خذلان عربي مَقيت وفضائحي، سيأتي يوم تُعرض فيه الخلفيات وتقاسم الأدوار في تلك الحرب المجنونة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أصحاب خيار الصمود والمقاومة لا تخدّرهم أنغام السلام الذي يروّج له الغزاة، ولا المساعي التي يرعاها داعموهم، لأن السلام الذي يفترضونه هو السلام الاستيطاني الذي يكرّس احتلال فلسطين والتنكّر لحق شعبها وابتزازه في كرامته، وفي بقية أرضه وموارده، وفي سيادته وحقّ تقرير مصيره، ولأن كلّ المفاوضات السابقة مع الكيان، أراد منها العدو إيجاد بديل وهمي لخيار المقاومة وتفكيك الاهتمام العربي الشعبي بقضيتها، وتوظيف فعّاليات الدول العربية لتظهير حسن سلوكها وحرصها على الأمان والسلام الدوليين، وإغراقها في وهم الحلول السلمية لقضية فلسطين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأصحاب هذا الخيار في لبنان تعلّموا الدرس جيداً من فلسطين، وعقدوا العزم على الدفاع عن بلدهم ومنع العدو الصهيوني ورعاة مشروعه الإرهابي من احتلال وطنهم، ولذلك شرعوا في المقاومة، ولم يغب عن بالهم أن طريق المشروع المقاوم شاقّ ودامٍ ومُكلِف، ولا يمكن أن يستمر من دون احتضان ووعي شعبيَّيْن، وإيمان وعزم ووحدة وتنظيم، وأنه طريق طويل محفوف بالمخاطر والمُنغِّصات، وأن فجره لا ينبلج إلا بعد اشتداد الظلام، وأن السالكين فيه يحتاجون إلى خطة وبرامج، وإلى وعي لمخاطر برامج العدو، وإلى تعبئة دائمة للناس لمواكبة العمل المقاوم بتفهّم ونقد، وازدياد في منسوب الأمل كما يحتاجون، أولاً، إلى عون الله وتوفيقه وتأييده، ودعم من المؤمنين بهذا الخيار، والقادرين على المساعدة ومدّ يد العون بالخبرة والموقف والإعداد والتسليح وغير ذلك، وطبعاً من دون شرط أو مقابل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومعلوم بما لا يخفى على أحد أن المقاومة الإسلامية التي بدأها حزب الله إنما انطلقت إثر اجتياح إسرائيلي للبنان عام 1982، وصل إلى بيروت العاصمة وراح يبتزّ السلطة اللبنانية ويستدرجها لعقد اتفاق يجعل من بلدنا محمية صهيونية، ويتيح للكيان إملاء السياسات والتوجّهات حسب مصالحه وبما يخدم مشاريعه للسيطرة والتوسّع.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ولولا الدعم شبه الوحيد الذي تلقّته المقاومة الإسلامية عبر سوريا من إيران، الثورة الفتية التي لم يكن قد مضى زمن طويل على انتصارها، لَما تسنّى للبنانيين أن يشهدوا هذا التحوّل السريع في التطورات الميدانية ضد مصلحة العدو الصهيوني، الذي بدأ العدّ التنازلي لاحتلاله لبنان منذ أن نجح الاستشهادي أحمد قصير في تفجير مقر الحاكم العسكري الإسرائيلي في صور، قبل أن تتصاعد العمليات ضد الاحتلال في مختلف أماكن انتشاره.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "فعل المقاومة، مهمته إيذاء العدو وإنهاكه ومنعه من الاستقرار في مواقع احتلاله، وملاحقته بالضغط اليومي المتواصل بكل الأساليب حتى يندحر. فيما الجيوش هي التي تعتمد التموضع في الجبهات والتصدّي بالسلاح الثقيل. ومن اللافت والمؤكّد أن ضعف التسلّح لدى جيشنا في لبنان أسهم في دفع المقاومة إلى القيام، بوسائلها القتالية، بما يجب أن يقوم به الجيش عادة أو أحياناً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومع ذلك، لا المقاومة تأخذ دور الجيش في المواجهة ولا الجيش يمكنه القيام بدور المقاومة ضد المحتلّين. ولذلك فإن التكامل بين دوريهما يعزّز قدرات المناورة ويضاعف الضغط على العدو. ولذا، تتفهّم المقاومة ظروف الضباط والجنود الأبطال والشجعان البواسل، وتقدّر انصياعهم للقرار السياسي القاصر عن مواكبة استعدادهم البطولي للمواجهة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومن جهة أخرى، فإن ضغط الفعل المقاوم المتواصل يستدرج الاهتمام لوقف القتال، من موقع المؤثّر والضاغط، لا من موقع المنهزم والمُحبَط، كما تقوم بذلك السلطة اللبنانية اليوم.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لجوء العدو إلى احتلال جزء من الأرض اللبنانية وتهجير الأهالي وتجريف بيوتهم وقراهم هو عدوان يملي على كلّ اللبنانيين واجب التصدّي له ودحره وإسقاط أهدافه. وهنا أهمية الفعل المقاوم وحاجة الدول إليه. وهنا يصبح الصمود الوطني العام فعل مقاومة أيضاً. فيما يؤدّي الإصرار على التفاوض المباشر مع العدو دوراً وظيفياً لتوهين الصمود الوطني ولإظهار الاستعداد للخضوع لمطالب العدو حتى من دون أن يلتزم بوقف إطلاق النار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "الكارثة الوطنية تحدث عندما تلوّح السلطة لعدو البلاد بإشارة الانهزام والتخلّي عن حق شعبها في المقاومة خلال العدوان.", "type": "text"}, {"type": "hardBreak"}, {"text": "انكفاء السلطة عن مواجهة العدو لا يقلّ انهزامية عن قرار تجريم المواطنين ومنعهم من حقّهم في المقاومة. وما أكثر الإشارات التي منحتها سلطتنا البائسة للعدو الإسرائيلي للتملّص من اتفاق وقف إطلاق النار الذي وافق عليه في 27/11/2024، ليفرض شروطه لاحقاً على السلطة ويزجّ البلاد في أزمة داخلية، وصولاً إلى التزامها صمتاً مريباً إزاء إعلان الخارجية الأميركية «بيان تفاهم» بين لبنان والكيان الصهيوني في 14 نيسان 2026، والذي يمنح العدو وحده حق الدفاع عن النفس.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في مقابل ذلك كلّه، لا يبقى سوى المقاومة والصمود بوصفهما الفعل الحيوي المضادّ للاحتلال، والذي لا بديل عنه ولا غنى عنه، وبدونه ينقاد البلد حكماً إلى الإذعان والاستسلام.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "المصدر: الأخبار", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Mohammad Raad: Lebanon Today Faces Three Choices in Dealing with Israeli Aggression", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Mohammad Raad, head of Hezbollah’s Loyalty to the Resistance parliamentary bloc, argued that the Lebanese political scene is currently divided into three main approaches toward the ongoing conflict with Israel:", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "1. The “Accommodation” Option", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Raad, this camp avoids confronting Israeli attacks and instead blames the resistance for drawing Lebanon into war. He claims its supporters seek a ceasefire through the countries backing Israel and support measures aimed at weakening the resistance politically, financially, and militarily.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He argued that this approach translates Israeli demands into domestic policies, including efforts to restrict resistance activities, promote exclusive state control over weapons during wartime, and criminalize armed resistance under the banner of placing decisions of war and peace solely in the hands of the state.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "2. The “Normalization” Option", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Raad described a second camp as openly betting on Israel’s success in eliminating Hezbollah and eventually pursuing peace agreements and strategic cooperation with Israel under American sponsorship.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He accused supporters of this approach of aligning Lebanon politically and strategically with the West and NATO while conducting continuous political, media, economic, and security campaigns against the resistance and its supporters.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "3. The “Resistance and Steadfastness” Option", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Raad said Hezbollah and allied national and Islamic forces embrace a third option based on resistance and confrontation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He argued that Israel is not merely a normal state but a strategic project tied to broader Western interests in the region. From this perspective, he maintained that resistance is necessary to prevent occupation, defend Lebanon’s sovereignty, and counter what he described as expansionist Israeli ambitions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Raad, supporters of this option view resistance as the only effective means of deterring Israel and preventing Lebanon from being forced into submission through military pressure or unequal negotiations.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Hezbollah’s View of Resistance", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Raad emphasized that Hezbollah’s resistance emerged following Israel’s 1982 invasion of Lebanon and was able to grow with support received from Iran through Syria. He argued that resistance operations played a central role in forcing Israel’s eventual withdrawal from southern Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also stressed that resistance and the Lebanese Army perform different but complementary roles, with the army defending the country conventionally while resistance movements wage irregular warfare against occupation forces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Raad concluded that, in his view, continued resistance and national steadfastness remain the only viable path to confronting Israeli occupation and preventing Lebanon from being driven toward surrender or submission. He warned that abandoning the right to resist during wartime would represent a serious national failure.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Vhut5AMegFbcE42uo2YFkLCSCfOTSZyaFcJStKYH%40md-qbBGeoV1A2eRRGC7byM2xeog94lw8e.jpg', false, false, 32, 157, TIMESTAMP '2026-06-03 12:00:02.582', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'We Came and Didn''t Find You... Hezbollah Releases Thermal Drone Footage of Beaufort Castle', 'جئنا ولم نجدكم... حزب الله ينشر فيديو لقلعة الشقيف بالكاميرا الحرارية', 'hzb-beaufort-mi0336', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نشر الإعلام الحربي في حزب الله مشاهد حرارية ليلية التقطتها مسيّرة «أبابيل» فوق قلعة الشقيف ومحيطها في جنوب لبنان، بعد أيام من إعلان الجيش الإسرائيلي السيطرة على الموقع ونشر صور لجنوده داخله.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وحمل الفيديو عنوان «جئنا ولم نجدكم»، في إشارة مباشرة إلى الجدل الذي أثارته الرواية الإسرائيلية بشأن القلعة. وأظهرت المشاهد الجوية الحرارية القلعة ومحيطها خلال التحليق الليلي من دون ظهور أي انتشار عسكري إسرائيلي واضح داخل الموقع.", "type": "text"}]}, {"type": "iframe", "attrs": {"src": "https://platform.twitter.com/embed/Tweet.html?id=2062162139423346815"}}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "ويأتي نشر الفيديو بعد بيان أصدره حزب الله نفى فيه الرواية الإسرائيلية حول السيطرة على القلعة، معتبراً أن القوة التي وصلت إلى الموقع اكتفت بالتقاط صور قبل الانسحاب، ومؤكداً أن التوترات في محيط الشقيف لا تزال مستمرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأعاد الفيديو فتح النقاش حول حقيقة الوضع الميداني في القلعة، بعدما تحوّلت خلال الأيام الماضية إلى محور سجال بين روايتين متناقضتين بشأن السيطرة الفعلية على الموقع الاستراتيجي الواقع في جنوب لبنان.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Hezbollah’s military media published nighttime thermal footage captured by an “Ababil” drone over Beaufort Castle and its surroundings in southern Lebanon, days after the Israeli army announced that it had taken control of the site and released photographs of its soldiers inside it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The video ended with ", "type": "text"}, {"text": "“We Came and Didn't Find You,”", "type": "text", "marks": [{"type": "bold"}]}, {"text": " a direct reference to the controversy surrounding the Israeli narrative about the castle. The thermal aerial footage showed the castle and its surrounding area during a nighttime flight, with no apparent Israeli military presence visible inside the site.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The video was released following a Hezbollah statement rejecting the Israeli account of the castle’s capture. The group claimed that the Israeli force that reached the site merely took photographs before withdrawing, and asserted that fighting in the Beaufort area is still ongoing.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The footage has reignited debate over the actual situation on the ground at the castle, which in recent days has become the center of a dispute between two conflicting narratives regarding who effectively controls the strategic site in southern Lebanon.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/IMG-20260603-WA0473-mFZjGN3h6aoArXBuuFkZyvuuBrOczz.jpg', false, false, 1984, 8234, TIMESTAMP '2026-06-03 13:16:09.131', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'A Notable Shift in Washington and Tel Aviv... Is the Era of U.S. Military Aid to Israel Approaching Its End?', 'تحول لافت في واشنطن وتل أبيب... هل يقترب زمن المساعدات العسكرية الأميركية لإسرائيل من نهايته؟', 'telav-fund-warns', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "كشفت تقارير أميركية وإسرائيلية عن تحرك داخل الكونغرس الأميركي لإنهاء المساعدات العسكرية المباشرة لإسرائيل، في خطوة لافتة حظيت بتأييد رئيس الوزراء الإسرائيلي بنيامين نتنياهو الذي دعا إلى تقليص الاعتماد على الدعم الأميركي وصولاً إلى إنهائه بالكامل خلال السنوات المقبلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبدأت المبادرة بعد تقديم عضو الكونغرس الجمهوري مارلين ستاتسمان مشروع قرار يدعو إلى إعداد مذكرة تفاهم جديدة بين واشنطن وتل أبيب تنهي المساعدات العسكرية السنوية البالغة 3.8 مليارات دولار، على أن تقوم إسرائيل مستقبلاً بشراء احتياجاتها العسكرية مباشرة من الولايات المتحدة بدلاً من الحصول على تمويل مجاني.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وبحسب التقارير، أبدى نتنياهو دعمه للفكرة خلال لقاء جمعه بستاتسمان في القدس، مؤكداً أن إسرائيل تسعى إلى الوقوف على قدميها والتحول من دولة تتلقى المساعدات إلى دولة شريكة للولايات المتحدة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويستند المقترح إلى قرب انتهاء مذكرة التفاهم الحالية بين البلدين عام 2028، والتي تنص على تقديم 38 مليار دولار من المساعدات الأمنية على مدى عشر سنوات.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويرى مؤيدو المبادرة أن إنهاء المساعدات المباشرة قد يعزز صورة إسرائيل كدولة مستقلة عسكرياً واقتصادياً، فيما يأتي الطرح في وقت يشهد فيه الرأي العام الأميركي تراجعاً ملحوظاً في مستوى التأييد لإسرائيل وتصاعداً للانتقادات المرتبطة بحجم الدعم المالي والعسكري الذي تحصل عليه من واشنطن.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ورغم أن المشروع لا يزال في مراحله الأولى، إلا أنه يُعد من أبرز المبادرات التي طُرحت داخل الكونغرس بشأن مستقبل المساعدات العسكرية لإسرائيل، ويعكس نقاشاً متزايداً داخل الولايات المتحدة حول طبيعة العلاقة بين البلدين خلال السنوات المقبلة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "American and Israeli reports have revealed a move within the U.S. Congress to end direct military aid to Israel, in a significant development that has reportedly received support from Israeli Prime Minister Benjamin Netanyahu, who has called for reducing dependence on American assistance and eventually ending it altogether over the coming years.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The initiative began after Republican Congressman Marlin Stutzman introduced a proposal calling for a new memorandum of understanding between Washington and Tel Aviv that would phase out the annual $3.8 billion in military aid. Under the proposal, Israel would purchase its military needs directly from the United States rather than receiving grant-based funding.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to the reports, Netanyahu expressed support for the idea during a meeting with Stutzman in Jerusalem, stating that Israel seeks to stand on its own feet and transition from a recipient of aid to a strategic partner of the United States.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The proposal comes as the current memorandum of understanding between the two countries is set to expire in 2028. That agreement provides Israel with $38 billion in security assistance over a ten-year period.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Supporters of the initiative argue that ending direct aid could strengthen Israel’s image as a militarily and economically independent state. The discussion also comes at a time when public support for Israel in the United States has shown signs of decline, accompanied by growing criticism regarding the scale of financial and military assistance provided by Washington.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Although the proposal remains in its early stages, it is considered one of the most significant initiatives introduced in Congress concerning the future of U.S. military assistance to Israel, reflecting an expanding debate within the United States about the nature of the relationship between the two countries in the years ahead.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/1696967782386-euw9BgPH4TbcoUoWrGCwxy1jRlEzJh.webp', false, false, 87, 344, TIMESTAMP '2026-06-04 17:21:43.863', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'FIFA Introduces New Rules for the 2026 World Cup', 'فيفا يفرض قواعد جديدة في مونديال 2026', 'fifa-newrules', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلن الاتحاد الدولي لكرة القدم (فيفا) اعتماد مجموعة من التعديلات التحكيمية الجديدة خلال كأس العالم 2026، بهدف تعزيز الانضباط وتسريع إيقاع المباريات وتحسين دقة القرارات التحكيمية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومن أبرز التعديلات الجديدة، إمكانية طرد أي لاعب يتعمد تغطية فمه أثناء التحدث إلى لاعب منافس خلال المشادات داخل الملعب، في إطار مكافحة الإساءات اللفظية والعنصرية التي يصعب رصدها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما أصبح بإمكان الحكم طرد أي لاعب يغادر أرض الملعب احتجاجاً أو غضباً من أحد القرارات التحكيمية، في خطوة تهدف إلى الحد من السلوكيات غير الرياضية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ما يتعلق بإهدار الوقت، سيطبق الحكام عدّاً تنازلياً مدته خمس ثوانٍ عند تنفيذ رميات التماس وضربات المرمى. وفي حال عدم التنفيذ ضمن المهلة المحددة، تُمنح الكرة للفريق المنافس، سواء عبر رمية تماس أو ركلة ركنية بحسب الحالة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وشملت التعديلات أيضاً إلزام اللاعبين المستبدلين بمغادرة أرض الملعب خلال عشر ثوانٍ فقط، وإلا سيتوجب على اللاعب البديل الانتظار دقيقة إضافية قبل الدخول.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "أما اللاعب المصاب الذي يحتاج إلى تدخل طبي داخل أرض الملعب، فسيُطلب منه البقاء خارج الملعب لمدة دقيقة قبل العودة إلى اللعب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما وسّع فيفا صلاحيات تقنية حكم الفيديو المساعد (VAR)، لتشمل مراجعة حالات البطاقة الصفراء الثانية، إضافة إلى بعض القرارات المتعلقة بالركنيات التي قد تُحتسب بشكل خاطئ.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "The governing body of world football, FIFA, has announced a set of new refereeing regulations for the 2026 World Cup aimed at improving discipline, increasing the pace of matches, and enhancing the accuracy of officiating decisions.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Among the most notable changes is the possibility of sending off any player who deliberately covers his mouth while speaking to an opposing player during on-field confrontations, as part of efforts to combat verbal abuse and racist remarks that are difficult to detect.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Referees will also be empowered to issue a red card to any player who leaves the field in protest or anger over a refereeing decision, in a move designed to reduce unsporting behavior.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "To combat time-wasting, officials will apply a five-second countdown for throw-ins and goal kicks. If the restart is not taken within the allotted time, possession will be awarded to the opposing team, either through a throw-in or a corner kick depending on the situation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The new rules also require substituted players to leave the field within ten seconds. Failure to do so will result in the incoming substitute having to wait an additional minute before entering the match.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In addition, an injured player who receives medical treatment on the field will be required to remain off the pitch for one minute before being allowed to return.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "FIFA has also expanded the powers of the Video Assistant Referee (VAR) system to include reviews of second-yellow-card incidents, as well as certain corner-kick decisions that may have been awarded incorrectly.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/324769-ktcIBhvnemaa9FW2xsbTR6hGWyECgg.jpg', false, false, 983, 2545, TIMESTAMP '2026-06-05 11:47:04.276', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'sport'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Official Exam Fate Nears Decision as Countdown Begins – Secondary Education League Puts Student Safety Above All Else!', 'مصير الامتحانات الرسمية سيُحسم وعدّ عكسي بدأ– رابطة التعليم الثانوي تضع سلامة الطلاب فوق كل اعتبار!', 'official-exams', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد رئيس رابطة التعليم الثانوي الرسمي جمال عمر أن سلامة الطلاب والأساتذة يجب أن تبقى الأولوية المطلقة في أي قرار يتعلق بالامتحانات الرسمية، مشدداً على أن أي استحقاق تربوي يفقد قيمته إذا غابت مقومات الأمان.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وأوضح عمر أن الامتحانات الرسمية تشكل محطة أساسية في المسار التعليمي للطلاب، إلا أن نجاحها يبقى مرتبطاً بقدرة الدولة على توفير ظروف آمنة ومناسبة لإجرائها، بعيداً عن أي مخاطر أو ضغوط قد تنعكس سلباً على الطلاب والكادر التعليمي.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وأشار إلى أن الرابطة تتابع التطورات الأمنية والتربوية عن كثب، انطلاقاً من مسؤوليتها تجاه الطلاب والأهالي الذين يعيشون حالة من القلق مع اقتراب موعد الامتحانات، مؤكداً أن مصلحة الطلاب تبقى فوق أي اعتبار آخر.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "كما شدد على ضرورة اعتماد مقاربة واقعية ومسؤولة تأخذ في الاعتبار هواجس الأهالي، ولا سيما في المناطق التي تشهد توترات أمنية متكررة، لافتاً إلى أن أي قرار بشأن الامتحانات يجب أن ينطلق أولاً من مبدأ حماية الإنسان.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وختم بالتأكيد أن الرابطة ستعلن موقفها النهائي بعد استكمال المشاورات، مشيراً إلى أن الأمن التربوي سيبقى المعيار الأساسي في أي قرار يُتخذ، حفاظاً على حق الطلاب بالتعليم وسلامتهم في آن واحد.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Jamal Omar, President of the Official Secondary Education Teachers’ League, stressed that the safety of students and teachers must remain the absolute priority in any decision related to official examinations, emphasizing that any educational milestone loses its value if adequate security and safety conditions are absent.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Omar explained that official examinations represent a fundamental stage in students’ academic journeys, but their success remains dependent on the state’s ability to provide safe and appropriate conditions for conducting them, free from risks or pressures that could negatively affect students and educational staff.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He noted that the league is closely monitoring both security and educational developments, given its responsibility toward students and parents who are experiencing growing concern as the examination period approaches. He stressed that students’ interests must take precedence over all other considerations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also emphasized the need for a realistic and responsible approach that takes into account the concerns of parents, particularly in areas experiencing recurring security tensions, pointing out that any decision regarding examinations must begin with the principle of protecting people first.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Omar concluded by stating that the league will announce its final position after completing consultations, stressing that educational security will remain the primary criterion guiding any decision, in order to safeguard both students’ right to education and their safety.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/Cover-Set-62-1024x512-q5iyt7JVfhHyGPKndD4owUG1UuAHO8.jpg', false, false, 272, 753, TIMESTAMP '2026-06-05 19:00:47.402', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT ' Al-Moqdad: Berri Was Surprised by the Agreement, and There Is No Direct Contact Between Hezbollah and Washington', 'المقداد: بري صُدم من الاتفاق ولا تواصل مباشر بين حزب الله وواشنطن', 'mokdad-berri-deal-66', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد عضو كتلة «الوفاء للمقاومة» النائب علي المقداد أن رئيس مجلس النواب نبيه بري تفاجأ بنتائج الاتفاق الأخير، مشيراً إلى أنه لم يكن يتوقع المآلات التي انتهى إليها حتى لو كانت هناك اتصالات أو وساطات سابقة مرتبطة به.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ما يتعلق بتصريحات الرئيس الأميركي دونالد ترامب حول وجود تواصل مع حزب الله، نفى المقداد وجود أي قنوات اتصال مباشرة مع الولايات المتحدة، مؤكداً أن الحزب لا يجري أي تواصل مباشر لا مع ترامب ولا مع أي مسؤول أميركي آخر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح أن الاتصالات تتم حصراً عبر وسطاء ودول تلعب أدواراً في نقل الرسائل وإدارة التواصل غير المباشر، لافتاً إلى أن دولاً مثل قطر والسعودية ومصر تضطلع بهذا الدور سواء مع الدولة اللبنانية أو عبر رئيس مجلس النواب نبيه بري.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Ali Al-Moqdad, a member of Hezbollah’s Loyalty to the Resistance bloc, stated that Nabih Berri was surprised by the outcome of the recent agreement, noting that he did not expect the developments that ultimately resulted from it, even if previous contacts or mediation efforts had been related to the process.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding statements by Donald Trump about the existence of communication with Hezbollah, Al-Moqdad denied that there are any direct channels of communication with the United States, stressing that the party does not engage in direct contact with Trump or any other American official.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He explained that communications take place exclusively through intermediaries and countries that play a role in conveying messages and managing indirect contacts. He noted that countries such as Qatar, Saudi Arabia, and Egypt perform this role, whether with the Lebanese state or through Speaker Nabih Berri.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/2-uLnBdaDZCSxmQAY740uYLSfqoyrGRR.webp', false, false, 3, 64, TIMESTAMP '2026-06-06 10:58:21.612', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Argentina Coach Reassures Fans: Will Messi Return Before the World Cup?', 'مدرب الأرجنتين يطمئن الجماهير: هل يعود ميسي قبل انطلاق كأس العالم؟', 'messiwc66-6', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد مدرب المنتخب الأرجنتيني ليونيل سكالوني أن النجم Lionel Messi يتعافى بشكل جيد من الإصابة العضلية التي تعرض لها مؤخراً، مشيراً إلى أن قائد المنتخب قد يشارك في إحدى المباراتين الوديتين الأخيرتين قبل انطلاق كأس العالم 2026.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأوضح سكالوني أن ميسي عاد للتدرب جزئياً مع المجموعة بعد فترة من العمل الفردي، مؤكداً أن حالته تتحسن بشكل ملحوظ وأن الجهاز الفني يشعر بارتياح أكبر حيال جاهزيته البدنية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وكان ميسي قد تعرض للإصابة خلال مشاركته مع Inter Miami CF في الدوري الأميركي، ما أثار تساؤلات حول قدرته على اللحاق باستعدادات المنتخب الأرجنتيني قبل البطولة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتخوض Argentina national football team مباراتين وديتين أمام Honduras national football team وIceland national football team قبل بدء مشوارها في المونديال، حيث أشار سكالوني إلى أن ميسي قد يحصل على بعض الدقائق خلال إحدى المباراتين.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما كشف المدرب الأرجنتيني عن موقف طريف جمعه بميسي عند إبلاغه باستدعائه إلى القائمة، إذ مازحه القائد بأنه سينتظر إعلان الأسماء رسمياً ليتأكد من وجوده ضمنها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ويستعد ميسي لخوض كأس العالم السادسة في مسيرته، بعدما قاد الأرجنتين إلى التتويج بلقب 2022 FIFA World Cup، في وقت يأمل فيه المنتخب الحفاظ على لقبه في النسخة المقبلة.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Argentina coach confirmed that star player Lionel Messi is recovering well from the muscle injury he recently suffered, indicating that the national team captain could feature in one of the final two friendly matches before the 2026 FIFA World Cup.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Argentina coach explained that Messi has resumed partial training with the squad after a period of individual work, stressing that his condition is improving significantly and that the coaching staff feels increasingly comfortable about his physical readiness.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Messi sustained the injury while playing for Inter Miami CF, raising questions about whether he would be able to join Argentina’s preparations ahead of the tournament.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Argentina national football team is scheduled to play friendlies against the Honduras national football team and the Iceland national football team before the World Cup begins, with the coach indicating that Messi could receive some playing time in one of those matches.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He also revealed a lighthearted exchange with Messi when informing him of his call-up, saying that the captain jokingly told him he would wait for the official squad announcement to make sure he had actually been selected.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Messi is preparing to participate in the sixth World Cup of his career after leading Argentina to victory at the 2022 FIFA World Cup, as the team aims to defend its title in the upcoming tournament.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/r1585095_1296x729_16-9-MSmXNzTEolNwjIjAIHs0GTrJxvgt3U.jpg', false, false, 29, 183, TIMESTAMP '2026-06-06 11:58:02.374', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'sport'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'As Objections Grow, Attention Turns to the Ministry of Education’s Next Move', 'مع تصاعد الاعتراضات... ترقب لقرار وزارة التربية', 'att-edu-min66-26', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نقلا عن موقع صدى الضاحية", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "أكدت مصادر متابعة أن وزيرة التربية قد تجد نفسها خلال الأيام المقبلة أمام خيار إلغاء الامتحانات الرسمية للشهادة الثانوية، في ظل الصعوبات المتزايدة التي تواجهها الوزارة لتأمين مراكز الامتحانات والكادر البشري والإداري اللازم لإجراء هذا الاستحقاق.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشارت المصادر إلى أن الجهود المبذولة لتنظيم الامتحانات تواجه تحديات لوجستية وأمنية متزايدة، بالتزامن مع تصاعد الاعتراضات والتحركات الطلابية الرافضة للآلية المعتمدة من قبل الوزارة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "في المقابل، لفتت مصادر تربوية إلى أن القطاع التعليمي في لبنان يعاني منذ سنوات من تداعيات الأزمات المتلاحقة التي بدأت عام 2019، ما انعكس سلباً على مستوى التعليم ومكانة الشهادة اللبنانية على الصعيدين الإقليمي والدولي.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكدت أن الحفاظ على قيمة الشهادة اللبنانية يتطلب معالجة شاملة للأزمة التربوية وإيجاد حلول تعيد الثقة بالقطاع التعليمي، محذرة من أن استمرار التراجع الحالي قد يؤدي إلى نتائج أكثر خطورة في المستقبل.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "المصدر: صدى الضاحية ", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Sources following the file have indicated that the Minister of Education may find herself in the coming days facing the option of canceling the official secondary school examinations, amid mounting difficulties in securing examination centers and the administrative and human resources required to conduct the exams.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The sources noted that efforts to organize the examinations are facing increasing logistical and security challenges, alongside growing student objections and protest movements rejecting the mechanism adopted by the ministry.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, educational sources pointed out that Lebanon’s education sector has been suffering for years from the consequences of successive crises that began in 2019, negatively affecting both educational standards and the reputation of the Lebanese diploma at the regional and international levels.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "They stressed that preserving the value of the Lebanese certificate requires a comprehensive approach to the educational crisis and the adoption of solutions capable of restoring confidence in the sector, warning that continued deterioration could lead to even more serious consequences in the future.", "type": "text"}]}, {"type": "paragraph"}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/E0F3186D-EFB5-40DC-A4C0-CCE7F2CBE685-aPhTvhjcHncpOZ5Ynt1oZhAyC4WYPo.jpg', false, false, 74, 246, TIMESTAMP '2026-06-06 19:53:28.542', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Qalibaf After the Strike on Beirut’s Southern Suburbs: “They Understand Only the Language of Force”', 'قاليباف بعد استهداف الضاحية: "لا يفهمون إلا لغة القوة"', 'qalibav-comment-6726', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "رفع رئيس مجلس الشورى الإيراني محمد باقر قاليباف سقف مواقفه تجاه الولايات المتحدة وإسرائيل، معتبراً أن التطورات الأخيرة في المنطقة تثبت أن الضغوط العسكرية لا تزال هي الخيار المعتمد بدلاً من الحوار والتفاهمات السياسية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار قاليباف إلى أن الجهات التي تتحدث عن التهدئة لا تلتزم بوقف إطلاق النار، معتبراً أن الخروقات المرتبطة بلبنان والحصار المفروض على إيران تؤكد أن هذه الأطراف \"لا تفهم إلا لغة القوة\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما اعتبر أن استمرار الضغوط على إيران، إلى جانب الدعم الأميركي لإسرائيل، قد يجعل المصالح والقواعد الأميركية والإسرائيلية في المنطقة عرضة للاستهداف، مؤكداً أن القوات المسلحة الإيرانية تمتلك الجهوزية الكاملة للتعامل مع أي تطورات أو تهديدات محتملة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التصريحات في ظل تصاعد التوتر بين إيران وإسرائيل والولايات المتحدة، وسط مخاوف متزايدة من توسع المواجهة الإقليمية وانعكاساتها على أمن المنطقة والملاحة الدولية", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Mohammad Bagher Ghalibaf raised the tone of his remarks toward the United States and Israel, arguing that recent developments in the region demonstrate that military pressure remains the preferred approach over dialogue and political understandings.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Qalibaf stated that parties calling for de-escalation are not adhering to ceasefire commitments, asserting that developments related to Lebanon and the sanctions imposed on Iran show that these actors “understand only the language of force.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He further argued that continued pressure on Iran, combined with American support for Israel, could make U.S. and Israeli interests and bases in the region vulnerable to targeting, emphasizing that Iran’s armed forces are fully prepared to deal with any potential developments or threats.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The remarks come amid rising tensions between Iran, Israel, and the United States, alongside growing concerns about a wider regional confrontation and its potential impact on regional security and international maritime routes.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/76171582_604-SCoshdbE3CgIAlDuSKyHmFwApvTsif.jpg', false, false, 9, 100, TIMESTAMP '2026-06-07 16:46:49.463', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The Enemy Erases Southern Lebanon’s Schools from the Map', 'العدو يمحو مدارس الجنوب من الخريطة', 'enemy-erases-schools', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "يصعب اليوم الحديث عن رقم نهائي للمؤسسات التعليمية الرسمية والخاصة التي دُمّرت بفعل العدوان الإسرائيلي، إذ تُضاف تباعاً مدارس وثانويات ومعاهد مهنية جديدة إلى لائحة الخسائر. لكنّ المؤكد، وفق ما تُظهِره الصور الجوية، أنّ عشرات المؤسسات دُمّرت بالكامل، ما يطرح أسئلة جدّية حول إمكان إعادة بنائها وعودتها إلى العمل في السنوات المقبلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي وقت لم تكن فيه المدارس قد تعافت بعد من آثار حرب 2024، ولم تُستكمل أعمال الترميم فيها، جاءت الجولة الأخيرة لتعيد عدداً كبيراً منها إلى نقطة الصفر، بل لتُزيل بعضها بالكامل. فقد مُحيَت تقريباً ثانوية مروحين من الخريطة بعد أن كانت قد تضرّرت سابقاً. وفي عيترون، تُظهِر الصور الجوية تحوّل الثانوية الرسمية من مبنى متضرّر إلى ركام كامل. وفي بنت جبيل، طاول التدمير الثانوية الرسمية والمعهد المهني، إلى جانب أضرار جسيمة أو دمار كامل لعدد من المؤسسات التربوية في بلدات الحافة الأمامية والمحاذية.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "ومع كل مدرسة تسقط أو تُدمّر، لا يضيع صفّ دراسي أو مختبر أو ملعب فحسب، بل جزء من ذاكرة المكان. لذلك يتحدّث المديرون عن معركة من نوع آخر عنوانها الحفاظ على المؤسسات التعليمية وعدم شطبها من السجلّ التربوي، حتى في حال تعذّر استقبال طلابها في المدى المنظور. غير أنّ هناك من يرى أيضاً أنّ مجرّد الحفاظ على الكيان هو قرار سياسي بامتياز.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي اجتماع تشاوري عقدته وزيرة التربية ريما كرامي أخيراً مع أكثر من 20 مديراً لمؤسسات متضرّرة، برزت هذه الهواجس بوضوح. ولم يقتصر النقاش على حجم الأضرار وكلفة إعادة البناء، بل تناول أيضاً مصير التعليم في هذه المدارس وإمكان استمرارها كمؤسسات مستقلة، بعدما فقد بعضها مبانيه وطلابه والبيئة السكانية التي كان يعتمد عليها.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتبرز هنا معضلة أساسية. ففي البلدات الأمامية التي تعرّضت لدمار واسع، مثل ميس الجبل وعيترون وبليدا وحولا والخيام وكفركلا والعديسة وغيرها، لا يبدو خيار استحداث مبانٍ بديلة للمؤسسات المُدمّرة واقعياً في الوقت الراهن، بحسب المديرين، إذ إنّ الأهالي والطلاب والأساتذة تشتّتوا في مناطق لبنانية مختلفة، ما يجعل إعادة تجميعهم في مكان واحد أمراً بالغ الصعوبة.", "type": "text"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "مديرو المدارس أمام معركة سياسية لعدم شطب المؤسسات التعليمية من السجلّ التربوي حتى في حال تعذّر استقبال طلابها", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "paragraph", "content": [{"text": "لذلك، يميل مدير ثانوية ميس الجبل الرسمية فرج بدران إلى الحفاظ على كيانات المدارس والثانويات عبر تسجيل الطلاب فيها، مع اعتماد التعليم عن بعد كخيار أساسي، وإتاحة المجال لهم لمتابعة الدراسة حضورياً في المدارس القريبة من أماكن نزوحهم، شرط بقائهم مُسجّلين في مدارسهم الأصلية، مع التشديد على ضرورة تأمين الحد الأدنى من مقوّمات هذا الخيار، ولا سيّما الإنترنت والأجهزة. وفيما تؤكّد وزيرة التربية، بحسب بدران، الحفاظ على كيانات المدارس وعدم شطبها، تبقى كل السيناريوات مرهونة بتطورات وقف إطلاق النار واتضاح صورة المرحلة المقبلة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "من جهتها، تقول مديرة ثانوية عيترون الرسمية زينب قعفراني إنّ ما يجري يشكّل حملة مُمنهجة تستهدف المؤسسات التعليمية، بما يهدّد وجودها ودورها ويؤدّي إلى محوها من الذاكرة الجماعية. وتشير إلى أنّ الواقع اليوم أكثر ضبابية من مرحلة ما بعد حرب 2024، حين عاد الأهالي سريعاً إلى قراهم واستعادت البلدات جزءاً من حياتها الطبيعية، ما سهّل إعادة تشغيل المدارس ولو جزئياً. أمّا اليوم، فإنّ حجم الدمار واتّساعه يفرضان أسئلة أكثر تعقيداً حول إمكان عودة السكان، وعدد الطلاب الذين سيعودون، وإمكانية إعادة تجميعهم ضمن مؤسسات تعليمية واحدة. وترى قعفراني أنّ المباني البديلة في بلدات مجاورة لا تستقطب الطلاب النازحين ولا حتى طلاب البلدات المضيفة، معتبرةً أنّ التعليم عن بعد لا يشكّل بديلاً ناجعاً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كذلك، يرى عدد من المديرين أنّ الحديث عن إعادة بناء المدارس في القرى الأمامية يبقى سابقاً لأوانه، ما دامت هذه البلدات تحتاج أولاً إلى إعادة إعمار منازلها وعودة سكانها. فالأولوية هي لاستعادة الحياة السكنية، لأنّ المدرسة لا يمكن أن تستعيد دورها من دون عودة القرية نفسها. أمّا في بلدات أخرى ما زال جزء من نسيجها السكني قائماً، مثل مجدل سلم وبرج قلاويه وقبريخا وغيرها، فتبدو الخيارات أكثر مرونة، سواء عبر غرف صفّية جاهزة أو مبانٍ مؤقّتة إلى حين استكمال إعادة الإعمار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "لكن مع اتّساع الدمار وتشتّت السكان وغياب صورة واضحة عن حجم العودة، لا تبدو الأزمة مجرّد أزمة أبنية مدرسية، بل أزمة تمسّ مستقبل التعليم الرسمي في المناطق الحدودية. فحين تُمحى المدارس من الخريطة، يصبح التحدّي أكبر من إعادة بناء الجدران، ليمتدّ إلى حماية الذاكرة التربوية للقرى، وضمان حقّ أبنائها في مدرسة يمكن أن يعودوا إليها يوماً ما.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "فاتن الحاج - الاخبار", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Schools Wiped Off the Map: Border Communities Fight to Preserve Their Educational Future", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Today, it is difficult to determine a final number of public and private educational institutions destroyed by Israeli attacks, as new schools, secondary schools, and vocational institutes continue to be added to the list of losses. What aerial imagery clearly shows, however, is that dozens of institutions have been completely destroyed, raising serious questions about the possibility of rebuilding them and restoring their operations in the coming years.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Many schools had not yet recovered from the damage caused by the 2024 war when the latest round of destruction pushed them back to square one—or erased them entirely. Marwahin Secondary School, already damaged previously, has been almost completely wiped off the map. In Aitaroun, aerial images show the official secondary school transformed from a damaged building into a pile of rubble. In Bint Jbeil, both the official secondary school and the vocational institute suffered severe destruction, alongside many other educational institutions in frontline and border villages.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For school administrators, every destroyed school represents more than the loss of classrooms, laboratories, or sports facilities—it is the loss of part of a community’s memory. As a result, many now describe their struggle as a battle to preserve educational institutions and prevent them from being removed from Lebanon’s educational registry, even if they cannot welcome students in the foreseeable future.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These concerns were highlighted during a recent consultative meeting between Education Minister Rima Karami and more than 20 directors of affected schools. Discussions extended beyond the scale of destruction and reconstruction costs to include the future of education in these institutions and whether they could continue to exist independently after losing their buildings, students, and local communities.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A major challenge exists in heavily damaged frontline villages such as Mays al-Jabal, Aitaroun, Blida, Houla, Khiam, Kfar Kila, and Adaisseh. School directors argue that creating alternative facilities is currently unrealistic because residents, students, and teachers have been dispersed across Lebanon, making it extremely difficult to regroup them in a single location.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The director of Mays al-Jabal Official Secondary School, Faraj Badran, advocates preserving the legal existence of schools by keeping students officially enrolled while relying on distance learning and allowing them to attend nearby schools in their areas of displacement. He stresses the need to provide internet access and electronic devices to support such a model.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meanwhile, Aitaroun Secondary School principal Zeinab Qaafarani described the destruction as a systematic campaign against educational institutions that threatens their very existence and role in society. She noted that the situation is even more uncertain than after the 2024 war, when residents returned relatively quickly and schools were partially reopened. Today, the scale of destruction raises far more complex questions about population return, student numbers, and the feasibility of re-establishing educational communities.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Many administrators believe that discussing reconstruction in frontline villages remains premature. They argue that rebuilding homes and enabling residents to return must come first, since schools cannot truly function without the return of the communities they serve. In other villages where parts of the residential fabric remain intact, such as Majdal Selm, Borj Qalaouiyeh, and Qabrikha, more flexible solutions—including temporary classrooms and prefabricated structures—may be possible until reconstruction is completed.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "As destruction expands, populations remain displaced, and uncertainty persists, the crisis is no longer merely about damaged school buildings. It has become a challenge to the future of public education in Lebanon’s border regions, where preserving educational memory and ensuring that future generations have schools to return to may prove just as important as rebuilding the walls themselves.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "Faten El Hajj - Al Akhbar", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/850603_0.jpeg-I8vwU6gnEC8DPVt6vSHonJ5wpkhMBt.webp', false, false, 237, 1013, TIMESTAMP '2026-06-09 15:16:23.022', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'general'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Insistence on Holding Exams Ignores the Reality of War and Displacement', 'الإصرار على الامتحانات يتجاهل واقع الحرب والنزوح', 'off-ex-real-1126', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "المرفأ- وكأنّ وزيرة التربية الدكتورة ريما كرامي لا تعيش في لبنان، لا تعلم جغرافيّته ولا مناطقه، ولا تتابع نشرات الأخبار اليوميّة والأخبار العاجلة عمّا يحصل من عدوان إسرائيلي واسع وقاسٍ على الجنوب.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "الدكتورة ريما كرامي تصرّ على إجراء الامتحانات الرسميّة غير آبهة بمعاناة عشرات آلاف الطلّاب النازحين من منازلهم ومناطقهم، والذين يصعب على أهاليهم التنقّل.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "الدكتورة ريما كرامي، علم \"المرفأ\" أنّها اتخذت قرارًا بإجراء الامتحانات الرسميّة دون التنسيق مع الجيش، وإعطائه لائحة بالمدارس المنوي استضافتها للامتحانات، وهو الأمر الذي ينطوي على مخاطرة كبيرة نتيجة العدوان المستمرّ، وكذلك وجود النازحين في عدد كبير من مدارس العاصمة وجبل لبنان.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "آخر إبداعات وزيرة \"الـLalaland\" أنّها رفضت طلب العديد من الجامعات إجراء الامتحانات حصرًا في فروع صيدا والنبطيّة وصور \"أونلاين\" وعن بُعد، كَون هذه المناطق تتعرّض لعدوان، وباتت أجزاء كبيرة منها مدمّرة.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "فالدكتورة ريما كرامي تريد للجامعة أن تجري الامتحانات في تلك المناطق حضوريًّا.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وعليه، يدعو \"المرفأ\" معالي الوزيرة كرامي، إلى نقل مكتبها من بيروت إلى النبطيّة، لتكون قدوةً لكلّ تلميذ قرّرت هي من تلقاء نفسها أنّ عليه المخاطرة بنفسه والذهاب نحو إجراء امتحانات أكثر ما تحتاجه هو الصفاء الذهني", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "According to Al-Marfaa, Education Minister  appears disconnected from the realities facing Lebanon, particularly the ongoing Israeli military campaign in the south and its impact on students and their families.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "The report criticizes Karami’s insistence on proceeding with official examinations despite the hardship facing tens of thousands of displaced students who have been forced from their homes and regions, while many families struggle with transportation and daily mobility.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "Al-Marfaa further claims that the minister decided to move forward with the examinations without coordinating with the Lebanese Army or providing a list of schools expected to host exam centers, describing this as a risky approach given the ongoing conflict and the fact that many schools in Beirut and Mount Lebanon are currently sheltering displaced people.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "The report also criticizes Karami’s refusal of requests from several universities to conduct examinations online in branches located in Sidon, Nabatieh, and Tyre, areas that continue to face military attacks and widespread destruction.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "According to Al-Marfaa, the minister insists that examinations in those areas be held in person.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "The publication concludes by arguing that asking students to attend exams under such circumstances ignores the realities of war and displacement, maintaining that examinations require a minimum level of safety, stability, and peace of mind to be conducted fairly.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}]}$c$::jsonb, 'https://daraj.media/wp-content/uploads/2022/06/Cover-2022-06-26T123302.192.jpg', false, false, 111, 419, TIMESTAMP '2026-06-10 10:17:58.385', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Israeli Company Accused of Targeting WhatsApp Users in Lebanon... WhatsApp Turns to the Courts', 'شركة إسرائيلية متهمة باستهداف مستخدمي واتساب في لبنان... وواتساب يلجأ إلى القضاء', 'isr-hack-lbwp-61-26', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلن تطبيق \"واتساب\"، المملوك من شركة \"ميتا\"، إعتزامه التقدم بطلبٍ إلى محكمة أميركية لاتخاذ إجراءات ضد شركة NSO Group الإسرائيلية، متهماً إياها بمواصلة محاولات استهداف المستخدمين عبر برنامج التجسس \"بيغاسوس\"، رغم صدور حكم قضائي دائم يمنعها من استخدام المنصة لنشر برمجياتها الخبيثة.وذكرت صحيفة \"فايننشال تايمز\" أن \"واتساب\" رصد استخدام بعض عملاء NSO أسلوباً جديداً يُعرف باسم \"One-Click\"، يعتمد على استدراج الضحية للنقر على رابطٍ يُرسل عبر رسالة نصية أو من خلال تطبيقات المراسلة، ما يتيح تنزيل برنامج التجسس على الجهاز المستهدف في الخلفية.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وبحسب الصحيفة، يُعد \"بيغاسوس\" من أكثر برامج التجسس إثارة للجدل، إذ يتيح الوصول إلى محتويات الهواتف الذكية ونقل البيانات والرسائل، بما في ذلك المعلومات الموجودة داخل تطبيقات مشفرة مثل \"واتساب\" و\"سيغنال\".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتأتي هذه التطورات بعد معركة قضائية طويلة انتهت العام الماضي بحكم لمصلحة \"واتساب\"، تضمن تعويضاً بقيمة 168 مليون دولار وحظراً دائماً على NSO يمنعها من استهداف مستخدمي المنصة.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "كما أشارت \"فايننشال تايمز\" إلى أن الولايات المتحدة أدرجت الشركة الإسرائيلية على قائمة القيود التجارية بعد العثور على برمجياتها في هواتف ديبلوماسيين أميركيين، فيما تتهم منظمات حقوقية الشركة باستهداف صحافيين ونشطاء ومعارضين سياسيين عبر برامج التجسس التي تطورها.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "WhatsApp, owned by Meta, has announced plans to ask a U.S. court to take action against Israeli cyber-intelligence firm NSO Group, accusing it of continuing attempts to target users through its Pegasus spyware despite a permanent court order banning the company from using the platform to distribute malicious software.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "According to the Financial Times, WhatsApp detected a new technique allegedly used by some NSO clients known as “One-Click”, which relies on tricking victims into clicking a link sent via text message or messaging applications, allowing spyware to be secretly installed on the targeted device.Pegasus is considered one of the world's most controversial spyware tools, capable of accessing smartphone contents and extracting data, messages, and communications, including information stored within encrypted applications such as WhatsApp and Signal.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "The latest developments follow a lengthy legal battle that ended last year with a ruling in WhatsApp’s favor, including $168 million in damages and a permanent injunction preventing NSO from targeting users of the platform.The Financial Times also reported that the United States placed NSO on its trade restrictions list after its spyware was found on the phones of American diplomats. Human rights organizations have likewise accused the company of targeting journalists, activists, and political dissidents through the surveillance technologies it develops.", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/IMG-20260610-WA0116-jngzb8s9fnJ6Q9pTs6jMygNzm445u6.jpg', false, false, 103, 616, TIMESTAMP '2026-06-10 13:54:04.354', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Who Is Protecting Israel Within the Lebanese Government?', 'من يحمي إسرائيل في الحكومة اللبنانية؟', 'lb-protect-isr-626', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نقلا عن المحطة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "رغم مرور أربعة أيام على استهداف آلية للجيش اللبناني على طريق كفرتبنيت - الخردلي في 1 حزيران يونيو ٢٠٢٦ ما أدى إلى استشهاد ضابطين وعسكري، لم تتقدم الدولة اللبنانية حتى الآن بأي شكوى إلى مجلس الأمن ضد إسرائيل.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "صمت يطرح أسئلة كبيرة حول موقف رئيس الجمهورية ورئيس الحكومة ووزير الخارجية، الذين لم يصدر عنهم أي موقف، ولم يتحركوا باتجاه محاسبة المعتدي، وكأن دماء العسكريين لا تستوجب حتى تقديم شكوى رسمية", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "وكانت المحطة» قد كشفت، نقلا عن مصادر في السراي الحكومي، أن رئيس الحكومة نواف سلام رفض سابقا تقديم شكوى ضد إسرائيل، مبررا ذلك بأن لبنان يخوض مفاوضات مع الجانب الإسرائيلي، متسائلاً: \" كيف يمكن تقديم شكوى ضدها في الوقت نفسه ؟ عيب ونحن عم نفاوضها \"", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "According to Al Mahatta", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "According to Al-Mahatta, despite four days having passed since the targeting of a Lebanese Army vehicle on the Kfar Tebnit–Khardali road on June 1, 2026, which resulted in the deaths of two officers and one soldier, the Lebanese state has yet to submit any complaint against Israel to the United Nations Security Council.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report says this silence raises major questions about the positions of the President of the Republic, the Prime Minister, and the Foreign Minister, none of whom have issued a public statement or taken steps toward holding the attacker accountable, as if the deaths of the servicemen do not warrant even a formal complaint.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Al-Mahatta also stated that it had previously revealed, citing sources at the Grand Serail, that Prime Minister Nawaf Salam had opposed filing a complaint against Israel, reportedly arguing that Lebanon is engaged in negotiations with the Israeli side and asking: “How can we file a complaint against it at the same time? It would be inappropriate while we are negotiating with it.”", "type": "text"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/c85d86c5-8cf1-4401-9f48-edaabf6e4be1_16x9_1200x676-BeU1tfukEJFJih466u5EUZLblC1BKi.jpeg', false, false, 5, 15, TIMESTAMP '2026-06-10 15:42:21.600', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'security'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT '$10,000 for Each Adviser at the Ministry of Education!', '10000 دولار لكل مستشار في وزارة التربية!', '1kadiveser-for-edumin', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "نقلا عن بيروت ريفيو", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "وزيرة التَّربيَّة الإصلاحيَّة مطالبة بالشَّفَّافيَّة والكشف عن حقيقة رواتب المستشارين الَّذين يلعبون دور مدراء الظِّلِّ في الوزارة.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": " ألا تخجل الوزيرة من النَّظر في أعين المعلِّمين في القطـ.ـاعين الرَّسميّ والخاصِّ عندما تناقشهم في حقوقهم وبدلاتهم، وتطالبهم بأن يعملوا أيَّامًا إضافيَّة، وتجلس بجانبها من تتقاضى بما يوازي رواتب 16 معلِّمًا لتنظِّر عليهم في العمل المهنيّ والمصلحة العامَّة؟", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "10000 دولار لكلِّ مستشار في وزارة التَّربيَّة!", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "* وزير الظِّلِّ المستشار عدنان الأمين: باحث تربويّ عريق، وله إنجازات أكاديميَّة مهمَّة، وهو بمثابة المرشد الرُّوحيّ لوزيرة التَّربيَّة ريما كرامي، وهو وزير الظِّلِّ، وهو يتابع الملفَّات الثَّقيلة؛ مثل ملفِّ إصلاح الجامعة اللَّبنانيَّة، وملفِّ المناهج التَّربويَّة، وملفَّات أخرى.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "* المستشارة الإداريَّة جورجيا الهاشم: مستشارة من دون أيِّ تاريخ إنجازات سابق، جلبها عماد الأشقر كمستشارة له أثناء تولِّيه بالتَّكليف المديريَّة العامَّة في عهد عباس الحلبيّ، وغنيّ عن التَّذكير بأنَّ الوزيرة تعتبر عماد الأشقر من الفاسدين في الوزارة. بالرَّغم من ذلك، توسَّع دورها في عهد الوزيرة الجديدة؛ فهي ليست موظَّفة في الوزارة وتطيع الوزيرة طاعة عمياء حفاظًا على مصالحها، وهي تتابع كلَّ ما تطلبه منها الوزيرة، حتَّى إنَّها تسيِّر لها العروض التَّقديَّميَّة أثناء عرض الوزيرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "* المستشار الماليّ ماهر الحسنية: المستشار الماليّ لوزيرة التَّربيَّة، أحضره الوزير الحلبيّ لإعداد منهجيَّة عمل موحَّدة للمانحين، وقد أنجزها بنجاح ثمَّ استبقته وزيرة التَّربيَّة للدَّور نفسه، حيث يتابع مهامَّه مع المانحين وتوحيد جهود التَّمويل.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "* المستشارة أمل شعبان: موظَّفة في وزارة التَّربيَّة، كانت تشغل منصب أمينة سرِّ لجان المعادلات، سُجنت في عهد الوزير الحلبيّ على خلفيَّة اتِّهامات في ملفِّ المعادلات مع الطُّلَّاب العراقيِّين، ثمَّ أُفرج عنها بكفالة، ورفض الوزير الحلبيّ إعادتها إلى مكانها بالرَّغم من كلِّ الضُّغوط السِّياسيَّة في حينها. وبالرَّغم من ذلك، فقد وضعتها الوزيرة إلى جانبها لتعاود الهيمنة على القرارات من دون توصيف رسميّ واضح.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "* المستشار القانونيّ فهمي كرامي: مستشار الوزيرة للشُّؤون القانونيَّة \"يلي مساقبة انو خيها\"، ولا تاريخ مهمًّا له في العمل التَّربويّ أو إنجاز يُذكر.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "* مستشار العلاقات الدُّوليَّة جوليان جلخ: مستشار الوزيرة للعلاقات الدُّوليَّة. لا تاريخ مهنيًّا حافلاً، \"لا فكاهة ولا مزية\" ولا دور حتَّى.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "رواتب المستشارين بالمقارنة مع رواتب المعلِّمين", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "رواتب 4 مستشارين فقط (عدنان الأمين، ماهر الحسنية، جورجيا الهاشم، وجوليان جلخ) تساوي 40.000 $، أي بمعدل 10 آلاف دولار للمستشار. وتدعي الوزيرة أنَّ فهمي كرامي لا يتقاضى راتبًا من الوزارة ولا من المنظَّمات الدُّوليَّة، بل يقوم بعمله معها بدافع الأخوَّة.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "إشارة إلى أنَّ المستشارَين الأساسيَّين هما من عهد الوزير الحلبيّ الَّذي تتَّهم الوزيرة عهده بالفساد.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "راتب المعلِّم الثَّانويّ هو 600 $ فقط، أي أنَّ راتب كلِّ مستشار يوازي راتب 16 معلِّمًا يعلِّمون 4 أيَّام في الأسبوع.", "type": "text"}]}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "المصدر: بيروت ريفيو ", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph"}, {"type": "paragraph", "content": [{"text": "According to Beirut Review", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "A report published by ", "type": "text"}, {"text": "Beirut Review", "type": "text", "marks": [{"type": "italic"}]}, {"text": " called on Education Minister  to provide greater transparency regarding the salaries and responsibilities of a number of advisers who, according to the report, play influential roles within the ministry.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "The report questioned how discussions about teachers’ salaries, benefits, and additional working days can take place while some advisers are allegedly receiving compensation that far exceeds the income of ordinary teachers.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "paragraph", "content": [{"text": "According to the publication, several advisers hold key responsibilities within the ministry:", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adnan Al-Amin", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is described as a veteran educational researcher who follows major files, including reform of the Lebanese University and curriculum development.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Georgia Al-Hashem", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is presented as an administrative adviser whose role reportedly expanded under the current minister.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Maher Al-Hassaniyeh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is said to oversee coordination with donors and funding-related matters.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Amal Shaaban", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is described as a ministry employee who has returned to a position of influence after previous legal proceedings related to the equivalency file.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fahmi Karami", "type": "text", "marks": [{"type": "bold"}]}, {"text": " serves as a legal adviser.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Julian Jalkh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is responsible for international relations.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The report claims that four advisers—Adnan Al-Amin, Maher Al-Hassaniyeh, Georgia Al-Hashem, and Julian Jalkh—receive a combined $40,000 per month, averaging approximately $10,000 each, although no official documentation was presented in the article to substantiate the figures.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It further contrasts these alleged salaries with those of secondary-school teachers, claiming that a teacher earns around $600 per month, and argues that the ministry should clarify the nature of advisers’ contracts, funding sources, responsibilities, and compensation.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The report concludes by calling for full disclosure regarding the advisers’ roles and remuneration, particularly at a time when the education sector continues to face financial and administrative challenges.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Source: Beirut Review", "type": "text"}, {"type": "hardBreak"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/IMG-20260612-WA0190%281%29-IPcX1beYapVzK4tsqnbx1Pr5MiPys3.jpg', false, false, 115, 328, TIMESTAMP '2026-06-12 16:05:25.087', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'economy'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'Araghchi reveals details of the anticipated agreement with Washington… & Lebanon is strongly represented', 'عراقجي يكشف تفاصيل الاتفاق المرتقب مع واشنطن… ولبنان حاضر بقوة', 'ir-lb-newagreem1226', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أعلن وزير الخارجية الإيراني Abbas Araghchi أن التفاهم المرتقب بين إيران والولايات المتحدة بات أقرب من أي وقت مضى، كاشفاً أن المراجعات النهائية للنص لا تزال جارية داخل المؤسسات الإيرانية، على أن يُعلن الاتفاق فور استكمال مراحله الأخيرة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأكد عراقجي أن الاتفاق، في حال إقراره، سيشمل ملفات متعددة أبرزها رفع العقوبات، والإفراج عن الأصول الإيرانية المجمدة، وإعادة الإعمار، إضافة إلى تعهد أميركي مكتوب باحترام سيادة إيران. كما أشار إلى أن الملف النووي أُرجئ إلى المرحلة الثانية من الاتفاق، بعدما رفضت طهران مطالب أميركية وصفتها بغير المقبولة.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي الشأن الإقليمي، شدد عراقجي على أن إنهاء الحرب يجب أن يشمل جميع الجبهات، بما فيها لبنان، مؤكداً أن إيران «لن تترك حزب الله وحيداً»، وأن أي تسوية نهائية يجب أن تتضمن انسحاب إسرائيل من الأراضي التي تحتلها في جنوب لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "واعتبر أن إيران خرجت منتصرة من المواجهة الأخيرة، مشيراً إلى أن أفضل وقت لإنهاء الحرب هو عندما يكون ميزان القوة في مصلحة بلاده، ومؤكداً أن الاتفاق المرتقب سيكرّس نتائج هذا الانتصار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما حذر من أن التهديدات العسكرية ضد إيران لم تنجح في تغيير مواقفها، مؤكداً أن طهران أبلغت الأطراف الأخرى بأنها مستعدة لأي مواجهة إذا فُرضت عليها الحرب.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي ملف الملاحة البحرية، أعلن عراقجي أن إدارة مضيق هرمز لن تعود إلى ما كانت عليه قبل الحرب، مشدداً على أن إيران وسلطنة عمان تمارسان السيادة على المضيق، وأن السفن ستدفع رسوماً مقابل الخدمات المقدمة فيه مستقبلاً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وأشار الوزير الإيراني إلى أن الاتفاق لا يزال يواجه معارضة من عدة جهات، وفي مقدمتها إسرائيل التي قال إنها تسعى إلى عرقلته وإفشاله، مؤكداً أن تفاصيله الكاملة ستُعرض على الرأي العام فور إقراره بشكل نهائي.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Iranian Foreign Minister Abbas Araghchi announced that a potential understanding between Iran and the United States is closer than ever, revealing that final reviews of the draft text are still underway within Iranian institutions before a formal announcement is made.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Araghchi stated that, if approved, the agreement would cover several key issues, including the lifting of sanctions, the release of frozen Iranian assets, reconstruction efforts, and a written U.S. commitment to respect Iran’s sovereignty. He also noted that the nuclear file has been postponed to a second phase of the agreement after Tehran rejected what it described as unacceptable American demands.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On regional issues, Araghchi stressed that ending the war must include all fronts, including Lebanon, asserting that Iran “will not leave Hezbollah alone” and that any final settlement must include an Israeli withdrawal from territories it occupies in southern Lebanon.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He argued that Iran emerged victorious from the recent confrontation, saying the best time to end a war is when the balance of power favors his country, and claiming that the expected agreement would consolidate the results of that victory.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Araghchi also warned that military threats against Iran had failed to alter Tehran’s positions, emphasizing that Iran had informed other parties that it is prepared for any confrontation should war be imposed upon it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Regarding maritime navigation, he declared that management of the Strait of Hormuz would not return to its pre-war framework, stressing that Iran and Oman exercise sovereignty over the strait and that ships would in the future pay fees for services provided there.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Iranian minister added that the agreement continues to face opposition from several parties, particularly Israel, which he accused of attempting to obstruct and derail the process, while pledging that full details would be made public once a final agreement is approved.", "type": "text"}]}]}$c$::jsonb, 'https://www.reuters.com/resizer/v2/O64D34LKXBOJ5DS425CXUEGRKE.jpg?auth=94d6562dd4e1190233a95802a3baa10abfc416548b5b612514f4db4414ed6028&width=1920&quality=80', false, false, 147, 368, TIMESTAMP '2026-06-12 20:32:26.866', CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'world'), (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a')
ON CONFLICT ("slug") DO NOTHING;

UPDATE "Article" SET "views" = 1, "clicks" = 13 WHERE "slug" = 'qassem-lb-speech-19626';

INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "isFeatured", "isDraft", "views", "clicks", "publishedAt", "updatedAt", "categoryId", "authorId")
SELECT 'The State Handed Over the Country Without Anything in Return... Here Is the Preliminary Text of the Framework Agreement Between Lebanon and Israel', 'الدولة سلمت البلاد من دون مقابل... إليكم النص المبدئي لاتفاق الإطار بين لبنان و اسرائيل', 'lebgov-isr-deal277', $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "‏ النص المبدئي لاتفاق الإطار بين لبنان واسرائيل: ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تلتزم إسرائيل ولبنان باتخاذ تدابير بحسن نية تعكس نوايا إيجابية بما في ذلك وقف جميع الأعمال العدائية والتعهد بالعمل على البحث عن الرفات وإعادتها والإفراج عن المحتجزين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تلتزم حكومة إسرائيل وحكومة لبنان بعملية متبادلة ومتدرجة وفق شروط واضحة تستعيد بموجبها القوات المسلحة اللبنانية سلطة الدولة الفعلية على كامل الأراضي اللبنانية وذلك بعد التحقق من نزع سلاح الجماعات المسلحة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تشدد حكومة إسرائيل على أن عملياتها العسكرية في لبنان هي حصراً نتيجة للهجمات والتهديدات والنوايا العدائية الصادرة عن الجماعات المسلحة غير التابعة للدولة ولا سيما حزب الله", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  تؤكد حكومة لبنان مجدداً التزامها الحازم وغير القابل للتراجع باستعادة وممارسة السيادة الكاملة على جميع أراضيها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  يلتزم لبنان والولايات المتحدة بمنع تدفق الأموال إلى أي كيان أو منظمة أو فرد مرتبط بالجماعات المسلحة غير التابعة للدولة واتخاذ التدابير القانونية المتاحة لحظر أنشطة أي كيان أو منظمة أو فرد من هذا النوع", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "‏ النص المبدئي لاتفاق الإطار بين لبنان واسرائيل: ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تلتزم إسرائيل ولبنان باتخاذ تدابير بحسن نية تعكس نوايا إيجابية بما في ذلك وقف جميع الأعمال العدائية والتعهد بالعمل على البحث عن الرفات وإعادتها والإفراج عن المحتجزين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تلتزم حكومة إسرائيل وحكومة لبنان بعملية متبادلة ومتدرجة وفق شروط واضحة تستعيد بموجبها القوات المسلحة اللبنانية سلطة الدولة الفعلية على كامل الأراضي اللبنانية وذلك بعد التحقق من نزع سلاح الجماعات المسلحة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تشدد حكومة إسرائيل على أن عملياتها العسكرية في لبنان هي حصراً نتيجة للهجمات والتهديدات والنوايا العدائية الصادرة عن الجماعات المسلحة غير التابعة للدولة ولا سيما حزب الله", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  تؤكد حكومة لبنان مجدداً التزامها الحازم وغير القابل للتراجع باستعادة وممارسة السيادة الكاملة على جميع أراضيها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  يلتزم لبنان والولايات المتحدة بمنع تدفق الأموال إلى أي كيان أو منظمة أو فرد مرتبط بالجماعات المسلحة غير التابعة للدولة واتخاذ التدابير القانونية المتاحة لحظر أنشطة أي كيان أو منظمة أو فرد من هذا النوع‏ النص المبدئي لاتفاق الإطار بين لبنان واسرائيل: ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تلتزم إسرائيل ولبنان باتخاذ تدابير بحسن نية تعكس نوايا إيجابية بما في ذلك وقف جميع الأعمال العدائية والتعهد بالعمل على البحث عن الرفات وإعادتها والإفراج عن المحتجزين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تلتزم حكومة إسرائيل وحكومة لبنان بعملية متبادلة ومتدرجة وفق شروط واضحة تستعيد بموجبها القوات المسلحة اللبنانية سلطة الدولة الفعلية على كامل الأراضي اللبنانية وذلك بعد التحقق من نزع سلاح الجماعات المسلحة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تشدد حكومة إسرائيل على أن عملياتها العسكرية في لبنان هي حصراً نتيجة للهجمات والتهديدات والنوايا العدائية الصادرة عن الجماعات المسلحة غير التابعة للدولة ولا سيما حزب الله", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  تؤكد حكومة لبنان مجدداً التزامها الحازم وغير القابل للتراجع باستعادة وممارسة السيادة الكاملة على جميع أراضيها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  يلتزم لبنان والولايات المتحدة بمنع تدفق الأموال إلى أي كيان أو منظمة أو فرد مرتبط بالجماعات المسلحة غير التابعة للدولة واتخاذ التدابير القانونية المتاحة لحظر أنشطة أي كيان أو منظمة أو فرد من هذا النوع‏ النص المبدئي لاتفاق الإطار بين لبنان واسرائيل: ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "تلتزم إسرائيل ولبنان باتخاذ تدابير بحسن نية تعكس نوايا إيجابية بما في ذلك وقف جميع الأعمال العدائية والتعهد بالعمل على البحث عن الرفات وإعادتها والإفراج عن المحتجزين", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تلتزم حكومة إسرائيل وحكومة لبنان بعملية متبادلة ومتدرجة وفق شروط واضحة تستعيد بموجبها القوات المسلحة اللبنانية سلطة الدولة الفعلية على كامل الأراضي اللبنانية وذلك بعد التحقق من نزع سلاح الجماعات المسلحة", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " تشدد حكومة إسرائيل على أن عملياتها العسكرية في لبنان هي حصراً نتيجة للهجمات والتهديدات والنوايا العدائية الصادرة عن الجماعات المسلحة غير التابعة للدولة ولا سيما حزب الله", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  تؤكد حكومة لبنان مجدداً التزامها الحازم وغير القابل للتراجع باستعادة وممارسة السيادة الكاملة على جميع أراضيها", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "  يلتزم لبنان والولايات المتحدة بمنع تدفق الأموال إلى أي كيان أو منظمة أو فرد مرتبط بالجماعات المسلحة غير التابعة للدولة واتخاذ التدابير القانونية المتاحة لحظر أنشطة أي كيان أو منظمة أو فرد من هذا النوع", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": " ", "type": "text"}, {"text": "Preliminary Text of the Framework Agreement Between", "type": "text", "marks": [{"type": "bold"}]}, {"text": "  ", "type": "text"}, {"text": "and", "type": "text", "marks": [{"type": "bold"}]}, {"text": " :", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": " Israel and Lebanon commit to taking measures in good faith that reflect positive intentions, including the cessation of all hostile acts, efforts to locate and return remains, and the release of detainees.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": " The Government of Israel and the Government of Lebanon commit to a reciprocal and gradual process under clear conditions through which the Lebanese Armed Forces will restore effective state authority over all Lebanese territory, following verification of the disarmament of armed groups.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": " The Government of Israel stresses that its military operations in Lebanon are solely the result of attacks, threats, and hostile intentions originating from non-state armed groups, particularly .", "type": "text"}]}, {"type": "paragraph", "content": [{"text": " The Government of Lebanon reaffirms its firm and irreversible commitment to restoring and exercising full sovereignty over all its territory.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}, {"text": "Lebanon and the  commit to preventing the flow of funds to any entity, organization, or individual linked to non-state armed groups, and to taking available legal measures to prohibit the activities of any such entity, organization, or individual.", "type": "text"}]}, {"type": "paragraph", "content": [{"type": "hardBreak"}]}]}$c$::jsonb, 'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/IMG-20260626-WA0114-Tn4m9ouvbQYyfP1j55YVvhEqQP4bcB.jpg', false, true, 0, 0, TIMESTAMP '2026-06-26 21:11:19.264', CURRENT_TIMESTAMP,
